//! `@MOAI:` / `@MX:` dual-read tag scanner (C2 #2178).
//!
//! Grammar v1 (unifies the two historical spellings found in the design corpus —
//! top §9 L1184 `@MOAI:REQ SPEC-X/REQ-007` (space form) and Core Brain
//! L3472-3473 `@MOAI:SPEC: SPEC-PAYMENT-001` (colon form); the conflict and the
//! "define schema + parser version before adding sub-lines" note are recorded in
//! review-group2, tag grammar section):
//!
//! ```text
//! line    := prefix? "@MOAI:" payload | prefix? "@MX:" payload
//! payload := KIND ( ":" SEGMENT )*           // SEGMENT = SUB or args part
//! KIND    := [A-Z][A-Z0-9_]*                 // uppercase, at least one char
//! ```
//!
//! A payload without `:` carries args only (`@MOAI:REQ SPEC-X/REQ-007`); each
//! additional `:` segment is a SUB when it is a bare uppercase run (`SPEC:REQ`),
//! otherwise the final segment is the free-text ARGS (`SPEC: args with spaces`).
//! The `@MX:` namespace parses with the same rules and normalizes into the same
//! node shape — mixed-namespace files are read in full and duplicates are
//! diagnosed, never rewritten (REQ-C2-01/02: this scanner is read-only; the
//! migration writer belongs to a later card).
//!
//! Parser version: every node and report carries `parser_version = 1`; new
//! sub-lines MUST bump it (Core Brain L3475).

use serde_json::{json, Value};
use std::{
    collections::BTreeMap,
    fs,
    path::{Path, PathBuf},
};

type Result<T> = std::result::Result<T, String>;

pub const PARSER_VERSION: u32 = 1;
const FILE_LIMIT: u64 = 262_144;
const WALK_DEPTH: usize = 16;
const WALK_FILES: usize = 512;

/// One normalized tag node (both namespaces land here).
#[derive(Clone, Debug)]
pub struct TagNode {
    pub namespace: &'static str,
    pub kind: String,
    pub sub: Option<String>,
    pub args: Option<String>,
    pub line: usize,
    pub raw: String,
}

/// A line that carries a marker but does not parse under grammar v1.
#[derive(Clone, Debug)]
pub struct InvalidTag {
    pub namespace: &'static str,
    pub line: usize,
    pub raw: String,
    pub reason: String,
}

struct Parsed {
    namespace: &'static str,
    kind: String,
    sub: Option<String>,
    args: Option<String>,
}

fn uppercase_run(s: &str) -> Option<&str> {
    let end = s
        .char_indices()
        .find(|(_, c)| !c.is_ascii_uppercase() && !c.is_ascii_digit() && *c != '_')
        .map(|(i, _)| i)
        .unwrap_or(s.len());
    if end > 0 {
        Some(&s[..end])
    } else {
        None
    }
}

/// Parses one marker payload under grammar v1. The payload is everything after
/// the `@MOAI:` / `@MX:` marker on the line. The form is decided by which delimiter
/// comes first (#2178: a space-form tag whose args contain a URL — `@MX:NOTE see
/// https://…` — must not be split on the URL's colons):
///
/// - space form (first whitespace before any colon): the kind is the bare run before
///   the whitespace and the args are everything after it (`@MX:NOTE see https://…`).
/// - colon form (first colon before any whitespace): the text before the colon is the
///   kind; of the rest, the first fragment is a SUB only when it is a bare uppercase
///   run (`@MOAI:SPEC:REQ`) — otherwise the whole rest is args, colons preserved
///   (`@MX:NOTE: [AUTO] …: …`, `@MX:SPEC: SPEC-PAYMENT-001`).
/// - neither delimiter: a bare KIND. Junk glued to the kind (`REQ-Thing /path`) and
///   empty segments (`SPEC::`) are invalid.
fn parse_payload(payload: &str) -> Result<(String, Option<String>, Option<String>)> {
    let first_space = payload.find(char::is_whitespace);
    let first_colon = payload.find(':');
    if let Some(space) = first_space {
        if first_colon.is_none_or(|colon| space < colon) {
            return space_form(payload, space);
        }
    }
    match first_colon {
        Some(colon) => colon_form(payload, colon),
        None => bare_kind(payload),
    }
}

fn space_form(payload: &str, space: usize) -> Result<(String, Option<String>, Option<String>)> {
    let kind = uppercase_run(&payload[..space]).unwrap_or("").to_string();
    if kind.len() != space {
        let shown = &payload[..space];
        return Err(format!(
            "kind must be an uppercase run ([A-Z][A-Z0-9_]*), found {shown:?}"
        ));
    }
    let args = payload[space..].trim();
    if args.is_empty() {
        Ok((kind, None, None))
    } else {
        Ok((kind, None, Some(args.to_string())))
    }
}

fn bare_kind(payload: &str) -> Result<(String, Option<String>, Option<String>)> {
    let kind = uppercase_run(payload).unwrap_or("").to_string();
    if kind.len() != payload.len() || kind.is_empty() {
        let shown = payload;
        return Err(format!(
            "kind must be an uppercase run ([A-Z][A-Z0-9_]*), found {shown:?}"
        ));
    }
    Ok((kind, None, None))
}

fn colon_form(payload: &str, colon: usize) -> Result<(String, Option<String>, Option<String>)> {
    let kind = uppercase_run(&payload[..colon]).unwrap_or("").to_string();
    if kind.len() != colon {
        let shown = &payload[..colon];
        return Err(format!(
            "kind must be an uppercase run ([A-Z][A-Z0-9_]*), found {shown:?}"
        ));
    }
    // The fragment after the colon is a SUB only when it is a bare uppercase run —
    // otherwise it (with every later colon preserved) is args (#2178: real tags carry
    // colons inside their args — `[AUTO] …`, URLs, `fan_in >= 3:`).
    let rest = &payload[colon + 1..];
    // The untrimmed first segment: its length is where the SUB ends inside `rest`, so
    // `KIND: SUB` and `KIND:  SUB:args` cut args after the SUB, not inside it.
    let raw = rest.split(':').next().unwrap_or("");
    let second = raw.trim();
    if second.is_empty() {
        return Err(format!("empty segment after kind {kind:?}"));
    }
    if let Some(sub) = uppercase_run(second) {
        if sub.len() == second.len() {
            let args = rest[raw.len()..].trim_start_matches(':').trim();
            if args.is_empty() {
                return Ok((kind, Some(sub.to_string()), None));
            }
            return Ok((kind, Some(sub.to_string()), Some(args.to_string())));
        }
    }
    Ok((kind, None, Some(rest.trim().to_string())))
}

fn parse_line(line: &str) -> Option<Result<Parsed>> {
    let marker = if let Some(pos) = line.find("@MOAI:") {
        let payload = line[pos + "@MOAI:".len()..].to_string();
        ("MOAI", payload)
    } else if let Some(pos) = line.find("@MX:") {
        let payload = line[pos + "@MX:".len()..].to_string();
        ("MX", payload)
    } else {
        return None;
    };
    Some(parse_payload(&marker.1).map(|(kind, sub, args)| Parsed {
        namespace: marker.0,
        kind,
        sub,
        args,
    }))
}

fn scan_file(path: &Path) -> Result<Value> {
    let bytes = fs::read(path).map_err(|_| "tag file read failed".to_string())?;
    if bytes.len() as u64 > FILE_LIMIT {
        return Err("tag file exceeds the size limit".into());
    }
    let text = String::from_utf8(bytes).map_err(|_| "tag file is not UTF-8".to_string())?;
    let mut nodes = Vec::new();
    let mut invalid = Vec::new();
    for (idx, line) in text.lines().enumerate() {
        if let Some(parsed) = parse_line(line) {
            match parsed {
                Ok(p) => nodes.push((idx + 1, line.to_string(), p)),
                Err(reason) => invalid.push((idx + 1, line.to_string(), reason)),
            }
        }
    }
    Ok(json!({
        "nodes": nodes.into_iter().map(|(line, raw, p)| json!({
            "namespace": p.namespace,
            "kind": p.kind,
            "sub": p.sub,
            "args": p.args,
            "line": line,
            "raw": raw,
            "parser_version": PARSER_VERSION,
        })).collect::<Vec<_>>(),
        "invalid": invalid.into_iter().map(|(line, raw, reason)| json!({
            "line": line, "raw": raw, "reason": reason,
        })).collect::<Vec<_>>(),
    }))
}

fn walk_files(root: &Path, out: &mut Vec<PathBuf>, depth: usize) -> Result<()> {
    if depth > WALK_DEPTH {
        return Err("tag scan nesting limit exceeded".into());
    }
    for entry in fs::read_dir(root).map_err(|_| "tag scan directory unavailable".to_string())? {
        let path = entry
            .map_err(|_| "tag scan entry unavailable".to_string())?
            .path();
        let meta =
            fs::symlink_metadata(&path).map_err(|_| "tag scan metadata unavailable".to_string())?;
        if meta.file_type().is_symlink() {
            continue; // links are skipped, never followed (read-only scan)
        }
        if meta.is_dir() {
            walk_files(&path, out, depth + 1)?;
        } else if meta.is_file() && meta.len() <= FILE_LIMIT {
            out.push(path);
        }
    }
    if out.len() > WALK_FILES {
        return Err("tag scan file limit exceeded".into());
    }
    Ok(())
}

/// Read-only dual-read scan (REQ-C2-01/02): reads both `@MOAI:` and `@MX:`
/// markers, normalizes them into one node shape, diagnoses duplicates (same
/// namespace+kind+sub seen more than once), and never writes. `path` may be a
/// file or a directory. Known limitation: `parse_line` reads only the FIRST
/// marker on a line — a single line carrying both `@MOAI:` and `@MX:` contributes
/// one node for the first marker, and the second is invisible to the scan.
pub fn scan_path(path: &Path) -> Result<Value> {
    let meta = fs::symlink_metadata(path).map_err(|_| "tag scan path unavailable".to_string())?;
    let mut reports = Vec::new();
    let paths: Vec<PathBuf> = if meta.is_dir() {
        let mut found = Vec::new();
        walk_files(path, &mut found, 0)?;
        found.sort();
        found
    } else if meta.is_file() {
        vec![path.to_path_buf()]
    } else {
        return Err("tag scan path is not a file or directory".into());
    };
    let mut total_nodes = 0usize;
    let mut total_invalid = 0usize;
    let mut duplicates: Vec<Value> = Vec::new();
    for file in &paths {
        let report = scan_file(file)?;
        let nodes = report["nodes"].as_array().cloned().unwrap_or_default();
        let invalid = report["invalid"].as_array().cloned().unwrap_or_default();
        total_nodes += nodes.len();
        total_invalid += invalid.len();

        // Duplicate diagnosis is per file (REQ-C2-01): the same kind+sub declared
        // in BOTH namespaces inside one file is the migration duplicate. The same
        // tag repeated across separate files is normal practice, not a duplicate.
        let mut per_file: BTreeMap<String, Vec<Value>> = BTreeMap::new();
        for node in &nodes {
            let key = format!(
                "{}|{}",
                node["kind"].as_str().unwrap_or(""),
                node["sub"].as_str().unwrap_or(""),
            );
            per_file.entry(key).or_default().push(node.clone());
        }
        let file_dups: Vec<Value> = per_file
            .iter()
            .filter(|(_, group)| {
                let namespaces: Vec<&str> = group
                    .iter()
                    .map(|n| n["namespace"].as_str().unwrap_or(""))
                    .collect();
                namespaces.contains(&"MOAI") && namespaces.contains(&"MX")
            })
            .map(|(key, group)| {
                json!({
                    "file": file.to_string_lossy(),
                    "key": key,
                    "namespaces": group.iter().map(|n| n["namespace"].clone()).collect::<Vec<_>>(),
                    "lines": group.iter().map(|n| n["line"].clone()).collect::<Vec<_>>(),
                })
            })
            .collect();
        if !file_dups.is_empty() {
            duplicates.extend(file_dups);
        }
        reports.push(json!({
            "path": file.to_string_lossy(),
            "nodes": nodes,
            "invalid": invalid,
        }));
    }
    Ok(json!({
        "parser_version": PARSER_VERSION,
        "files": reports,
        "file_count": reports.len(),
        "node_count": total_nodes,
        "invalid_count": total_invalid,
        "duplicates": duplicates,
        "duplicate_diagnosis_only": true,
        "modified": 0,
        "writes": false,
    }))
}

src/audit.rs.content:
//! Independent AUDIT and completion admission (Issue #2004, 05-D).
//!
//! `audit` is the auditor's own run: it observes the candidate in PROJECT (commit, tree digest,
//! workspace id, toolchain), re-runs the approved verification through 05-C, and hands
//! everything to `reduce`, a pure function that decides admission. Receipts that arrive as JSON
//! are self-reports and never count; only the receipt the auditor's own run produced does
//! (#2004 leader decision D1). Admission is `admitted` only when every required check passed on
//! a fresh runner receipt of exactly this candidate, the reviewer was independent, and no
//! reviewer opinion contradicts the evidence.

use crate::digest;
use crate::plan::{build_plan, current_revision, Decision};
use crate::run::{self, ProducerKind, Receipt, RunOutcome, RunRequest, Summary};
use crate::verify::{self, CheckResult, Toolchain};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::path::Path;

pub type Result<T> = std::result::Result<T, String>;

/// What the author presents for audit.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Candidate {
    pub commit: String,
    pub tree_digest: String,
    /// 01-A `identity` workspace id of the worktree the work was done in.
    pub workspace_id: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Finding {
    pub rule_id: String,
    pub severity: String,
    pub message: String,
}

/// The reviewer's free-text judgement: `pass` or `fail`. Never evidence by itself.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Opinion {
    pub verdict: String,
    pub summary: String,
}

/// Self-declared by the caller; recorded and judged by the table, not verified.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Reviewer {
    /// `claude`, `codex`, …
    pub host: String,
    /// Subagent or session identifier.
    pub identity: String,
    /// `fresh`, `fork`, `separate-session` or `same-session`.
    pub context_sharing: String,
    pub read_only: bool,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Waiver {
    /// `check:<index>` of a required check.
    pub gate: String,
    /// `quality`, or one of the never-waivable `security`, `secret`, `permission`.
    pub gate_class: String,
    pub reason: String,
    pub approver: String,
    pub scope: String,
    /// `YYYY-MM-DDTHH:MM:SSZ`.
    pub expires_at: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AuditInput {
    pub protocol_version: u32,
    pub request_id: String,
    pub candidate: Candidate,
    /// The 05-C request the auditor runs again.
    pub run: RunRequest,
    /// Indexes into the snapshot's verification commands that must pass.
    pub required_checks: Vec<usize>,
    /// Receipts the author produced; recorded as self-reports, never used for must-pass.
    #[serde(default)]
    pub self_reports: Vec<Value>,
    #[serde(default)]
    pub findings: Vec<Finding>,
    pub opinion: Option<Opinion>,
    pub reviewer: Reviewer,
    #[serde(default)]
    pub waivers_allowed: bool,
    #[serde(default)]
    pub waivers: Vec<Waiver>,
    /// `gh api repos/<o>/<r>/pulls/<n>` JSON when there is a PR; fetched by the caller.
    pub pr: Option<Value>,
    #[serde(default)]
    pub pr_lookup_failed: bool,
}

/// What the auditor saw in PROJECT itself.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Observed {
    pub commit: String,
    pub tree_digest: String,
    pub workspace_id: Option<String>,
    pub toolchain: Toolchain,
}

/// The 00-D verdict vocabulary.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Status {
    Passed,
    Failed,
    NotRun,
    Blocked,
    Stale,
    Unknown,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Admission {
    Admitted,
    Rejected,
    Held,
    Blocked,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum PrBinding {
    NotApplicable,
    Ok,
    Stale,
    Unknown,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct Independence {
    pub accepted: bool,
    pub limitation: Option<&'static str>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct MustPass {
    pub command_ref: usize,
    pub command: String,
    /// The original result; a waiver never rewrites it.
    pub status: Status,
    pub waived: bool,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct StaleReceipt {
    pub attempt_id: String,
    pub reasons: Vec<&'static str>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct WaiverRecord {
    #[serde(flatten)]
    pub waiver: Waiver,
    pub original: Option<Status>,
    /// `waived` or `refused`.
    pub outcome: &'static str,
    pub refusal: Option<&'static str>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct Verdict {
    pub request_id: String,
    pub status: Status,
    pub admission: Admission,
    pub reasons: Vec<&'static str>,
    pub candidate: Candidate,
    pub observed: Observed,
    pub reviewer: Reviewer,
    pub independence: Independence,
    pub pr_binding: PrBinding,
    pub run_decision: Decision,
    pub run_reasons: Vec<String>,
    pub must_pass: Vec<MustPass>,
    pub stale_receipts: Vec<StaleReceipt>,
    pub excluded_self_reports: Vec<String>,
    pub findings: Vec<Finding>,
    pub waivers: Vec<WaiverRecord>,
    pub receipt: Option<Receipt>,
}

/// Independence rules (#2004 leader decision H1, conservative until 02-B/02-C measure more).
/// A Claude subagent with a fresh context or any separate session is independent; a fork, and a
/// Codex subagent whose context inheritance is undocumented, proceed with a recorded limitation;
/// the same session, an unknown host or an unknown sharing value is not independent.
const INDEPENDENCE: [(&str, &str, Option<&str>); 6] = [
    ("claude", "fresh", None),
    ("claude", "separate-session", None),
    (
        "claude",
        "fork",
        Some("fork shares the parent conversation and the files it read"),
    ),
    ("codex", "separate-session", None),
    (
        "codex",
        "fresh",
        Some("codex subagent context inheritance is undocumented"),
    ),
    (
        "codex",
        "fork",
        Some("fork shares the parent conversation and the files it read"),
    ),
];

pub fn independence(r: &Reviewer) -> Independence {
    match INDEPENDENCE
        .iter()
        .find(|(h, s, _)| *h == r.host && *s == r.context_sharing)
    {
        Some(&(_, _, limitation)) => Independence {
            accepted: true,
            limitation:
                limitation
                    .or((!r.read_only)
                        .then_some("reviewer could write; an edit makes a new candidate")),
        },
        None => Independence {
            accepted: false,
            limitation: None,
        },
    }
}

/// The PR's `head.sha` against the audited commit; a failed lookup is `unknown`.
pub fn pr_binding(commit: &str, pr: Option<&Value>, lookup_failed: bool) -> PrBinding {
    if lookup_failed {
        return PrBinding::Unknown;
    }
    let Some(pr) = pr else {
        return PrBinding::NotApplicable;
    };
    match pr["head"]["sha"].as_str() {
        Some(sha) if sha == commit => PrBinding::Ok,
        Some(_) => PrBinding::Stale,
        None => PrBinding::Unknown,
    }
}

/// The auditor's own view of PROJECT.
pub fn observe(project: &Path) -> Result<Observed> {
    let identity = crate::identity::identity(project)?;
    Ok(Observed {
        commit: current_revision(project)?,
        tree_digest: crate::tree_digest(project, &run::TREE_EXCLUDES)?,
        workspace_id: identity["workspace_id"].as_str().map(String::from),
        toolchain: verify::toolchain(project),
    })
}

/// `YYYY-MM-DDTHH:MM:SSZ` now (civil-from-days, H. Hinnant), for waiver expiry.
pub fn utc_now() -> String {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| d.as_secs()) as i64;
    let (days, rem) = (secs.div_euclid(86_400), secs.rem_euclid(86_400));
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + i64::from(m <= 2);
    format!(
        "{y:04}-{m:02}-{d:02}T{:02}:{:02}:{:02}Z",
        rem / 3_600,
        rem % 3_600 / 60,
        rem % 60
    )
}

fn valid_timestamp(s: &str) -> bool {
    let b = s.as_bytes();
    b.len() == 20
        && b.iter().enumerate().all(|(i, c)| match i {
            4 | 7 => *c == b'-',
            10 => *c == b'T',
            13 | 16 => *c == b':',
            19 => *c == b'Z',
            _ => c.is_ascii_digit(),
        })
}

/// REQ-05D-01: identity, attempt and timestamps present.
fn receipt_well_formed(r: &Receipt) -> bool {
    !r.task_id.is_empty()
        && !r.attempt_id.is_empty()
        && r.checks.iter().all(|c| {
            c.result == CheckResult::NotRun
                || (c.started_unix_ms.is_some() && c.finished_unix_ms.is_some())
        })
}

/// REQ-05D-02: the receipt against the approved contracts and what the auditor observed.
fn receipt_stale_reasons(
    r: &Receipt,
    input: &AuditInput,
    observed: &Observed,
) -> Vec<&'static str> {
    let spec = &input.run.admission.spec;
    let spec_digest = spec
        .snapshot
        .as_ref()
        .map(|s| s.digest.clone())
        .unwrap_or_default();
    let plan_digest = build_plan(
        spec,
        &input.run.admission.tasks,
        &input.run.admission.expected_revision,
    )
    .plan_digest;
    let policy = spec.policy_revision.as_ref().map(|p| digest(p.as_bytes()));
    let mut out = Vec::new();
    if r.tree_digest != observed.tree_digest {
        out.push("tree-changed");
    }
    if r.spec_digest != spec_digest {
        out.push("spec-changed");
    }
    if r.plan_digest != plan_digest {
        out.push("plan-changed");
    }
    if r.policy_digest != policy {
        out.push("policy-changed");
    }
    if r.toolchain != observed.toolchain {
        out.push("toolchain-changed");
    }
    out
}

/// Decides admission. Pure: no files, no processes, no clock (`now` is passed in).
pub fn reduce(input: &AuditInput, observed: &Observed, outcome: &RunOutcome, now: &str) -> Verdict {
    let commands = &input.run.admission.spec.verification_commands;
    let independence = independence(&input.reviewer);
    let pr = pr_binding(
        &input.candidate.commit,
        input.pr.as_ref(),
        input.pr_lookup_failed,
    );

    let excluded_self_reports: Vec<String> = input
        .self_reports
        .iter()
        .map(|v| match run::ingest_self_report(v.clone()) {
            Ok(r) => r.attempt_id,
            Err(_) => "malformed".into(),
        })
        .collect();

    // Which receipt may count, and why another may not.
    let mut stale_receipts = Vec::new();
    let usable: Option<&Receipt> = match &outcome.receipt {
        Some(r) if r.producer.kind == ProducerKind::RunnerReceipt => {
            let reasons = receipt_stale_reasons(r, input, observed);
            if reasons.is_empty() {
                Some(r)
            } else {
                stale_receipts.push(StaleReceipt {
                    attempt_id: r.attempt_id.clone(),
                    reasons,
                });
                None
            }
        }
        _ => None,
    };
    let well_formed = usable.is_none_or(receipt_well_formed);
    let status_of = |i: usize| -> Status {
        match usable {
            Some(_) if !well_formed => Status::Unknown,
            Some(r) => match r
                .checks
                .iter()
                .find(|c| c.command_ref == i)
                .map(|c| c.result)
            {
                Some(CheckResult::Passed) => Status::Passed,
                Some(CheckResult::Failed) => Status::Failed,
                Some(CheckResult::NotRun) => Status::NotRun,
                None => Status::Unknown,
            },
            // A runner receipt was set aside as stale; anything else that is not one proves
            // nothing; no receipt at all means the run itself stopped.
            None => match &outcome.receipt {
                Some(r) if r.producer.kind == ProducerKind::RunnerReceipt => Status::Stale,
                Some(_) => Status::Unknown,
                None if outcome.decision == Decision::Stale => Status::Stale,
                None => Status::Blocked,
            },
        }
    };
    let mut must_pass: Vec<MustPass> = input
        .required_checks
        .iter()
        .map(|&i| MustPass {
            command_ref: i,
            command: commands.get(i).cloned().unwrap_or_default(),
            status: if i < commands.len() {
                status_of(i)
            } else {
                Status::Unknown
            },
            waived: false,
        })
        .collect();

    // Waivers: quality gates only, allowed by policy, not expired; the original stays.
    let waivers: Vec<WaiverRecord> = input
        .waivers
        .iter()
        .map(|w| {
            let target = w
                .gate
                .strip_prefix("check:")
                .and_then(|n| n.parse::<usize>().ok())
                .and_then(|n| must_pass.iter().position(|m| m.command_ref == n));
            let refusal = if !input.waivers_allowed {
                Some("waivers-not-allowed")
            } else if w.gate_class != "quality" {
                Some("gate-not-waivable")
            } else if !valid_timestamp(&w.expires_at) {
                Some("invalid-expiry")
            } else if w.expires_at.as_str() <= now {
                Some("expired")
            } else if target.is_none() {
                Some("unknown-gate")
            } else {
                None
            };
            let original = target.map(|t| must_pass[t].status);
            if let (None, Some(t)) = (refusal, target) {
                must_pass[t].waived = true;
            }
            WaiverRecord {
                waiver: w.clone(),
                original,
                outcome: if refusal.is_none() {
                    "waived"
                } else {
                    "refused"
                },
                refusal,
            }
        })
        .collect();

    let evidence_ok = !must_pass.is_empty()
        && must_pass
            .iter()
            .all(|m| m.status == Status::Passed || m.waived)
        && usable.is_some_and(|r| r.result != Summary::Unknown);
    let mut findings = input.findings.clone();
    let mut reasons: Vec<&'static str> = Vec::new();
    let worst = || {
        [
            Status::Failed,
            Status::Blocked,
            Status::Stale,
            Status::NotRun,
            Status::Unknown,
        ]
        .into_iter()
        .find(|s| must_pass.iter().any(|m| m.status == *s && !m.waived))
        .unwrap_or(Status::Unknown)
    };
    let (status, admission) = if !independence.accepted {
        reasons.push("independence-missing");
        (Status::Blocked, Admission::Blocked)
    } else if observed.workspace_id.is_none() {
        reasons.push("workspace-unknown");
        (Status::Unknown, Admission::Held)
    } else if observed.workspace_id.as_deref() != Some(input.candidate.workspace_id.as_str()) {
        reasons.push("foreign-workspace");
        (Status::Failed, Admission::Rejected)
    } else if observed.commit != input.candidate.commit
        || observed.tree_digest != input.candidate.tree_digest
    {
        reasons.push("candidate-changed");
        (Status::Stale, Admission::Rejected)
    } else if pr == PrBinding::Stale {
        reasons.push("pr-head-mismatch");
        (Status::Stale, Admission::Rejected)
    } else if pr == PrBinding::Unknown {
        reasons.push("pr-lookup-failed");
        (Status::Unknown, Admission::Held)
    } else if let Some(o) = input
        .opinion
        .as_ref()
        .filter(|o| (o.verdict == "pass") != evidence_ok)
    {
        reasons.push("opinion-conflicts-with-evidence");
        findings.push(Finding {
            rule_id: "opinion-conflicts-with-evidence".into(),
            severity: "high".into(),
            message: format!(
                "reviewer said {} while the evidence {}; the evidence decides and the verdict is held",
                o.verdict,
                if evidence_ok { "passes" } else { "does not pass" }
            ),
        });
        (Status::Unknown, Admission::Held)
    } else if usable.is_some_and(|r| r.result == Summary::Unknown) {
        reasons.push("oracle-changed");
        (Status::Unknown, Admission::Held)
    } else if !evidence_ok {
        reasons.push("must-pass-not-met");
        (worst(), Admission::Rejected)
    } else {
        (Status::Passed, Admission::Admitted)
    };

    Verdict {
        request_id: input.request_id.clone(),
        status,
        admission,
        reasons,
        candidate: input.candidate.clone(),
        observed: observed.clone(),
        reviewer: input.reviewer.clone(),
        independence,
        pr_binding: pr,
        run_decision: outcome.decision,
        run_reasons: outcome.reasons.clone(),
        must_pass,
        stale_receipts,
        excluded_self_reports,
        findings,
        waivers,
        receipt: outcome.receipt.clone(),
    }
}

/// The auditor's run: observe PROJECT, re-run the approved verification, reduce.
pub fn audit(project: &Path, input: &AuditInput) -> Result<Verdict> {
    if input.required_checks.is_empty() {
        return Err("invalid audit request: required_checks is empty".into());
    }
    let observed = observe(project)?;
    let outcome = run::run(project, &input.run, &observed.commit)?;
    Ok(reduce(input, &observed, &outcome, &utc_now()))
}

src/baseline.rs.content:
//! Read-only baseline inventory (Issue #1985, 00-A). Records the checkout state, a sha256
//! inventory of tracked and changed files, and a byte-level `.claude` comparison between the
//! Go baseline commit, its install template, and the current checkout's installed copy.
//!
//! The collector never writes: git is invoked with `--no-optional-locks` (no index refresh),
//! the Go baseline is read with `cat-file`/`ls-tree` only, blob ids are computed with
//! `hash-object` without `-w`, and the user home is checked for existence only (REQ-00A-08).
//! Output paths are repository-relative; absolute paths never reach the result (REQ-00A-09).
//! Classification is mechanical; meaning-level judgments stay with the design pages.
use serde_json::{json, Value};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    io::Write,
    path::{Path, PathBuf},
    process::{Command, Stdio},
    time::{SystemTime, UNIX_EPOCH},
};

type Result<T> = std::result::Result<T, String>;

/// Lane worktrees nest inside the primary checkout; they are not part of its state.
const EXCLUDED_PREFIXES: [&str; 3] = [".claude/worktrees/", ".moai-cli/worktrees/", ".worktrees/"];
const HOME_ENTRIES: [&str; 3] = [".claude", ".moai", ".agents"];
const TEMPLATE_PREFIX: &str = "internal/template/templates/";

fn git(dir: &Path, args: &[&str], stdin: Option<&[u8]>) -> Result<(i32, Vec<u8>)> {
    run_git(dir, args, stdin).map(|(code, out, _)| (code, out))
}
/// Runs git with a fixed argv. The caller's `GIT_DIR`, `GIT_WORK_TREE`, injected config and
/// discovery variables are removed and the locale is fixed (`identity::scrub_git_env`), so
/// PROJECT is the repository read (Issue #2054). Returns exit code, stdout and stderr; stderr
/// is only used to classify a failure.
fn run_git(dir: &Path, args: &[&str], stdin: Option<&[u8]>) -> Result<(i32, Vec<u8>, Vec<u8>)> {
    let mut cmd = Command::new("git");
    cmd.arg("--no-optional-locks").arg("-C").arg(dir).args(args);
    crate::identity::scrub_git_env(&mut cmd);
    let mut child = cmd
        .env("GIT_OPTIONAL_LOCKS", "0")
        .env("GIT_TERMINAL_PROMPT", "0")
        .stdin(if stdin.is_some() {
            Stdio::piped()
        } else {
            Stdio::null()
        })
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|_| "git unavailable")?;
    if let Some(bytes) = stdin {
        child
            .stdin
            .take()
            .ok_or("git stdin unavailable")?
            .write_all(bytes)
            .map_err(|_| "git stdin write failed")?;
    }
    let out = child.wait_with_output().map_err(|_| "git failed")?;
    Ok((out.status.code().unwrap_or(-1), out.stdout, out.stderr))
}
/// A failure other than "not a git repository" is `git failed: <path-free summary>`
/// (`git_failed`, as in #2033); "not a git repository" keeps `git <cmd> exited <code>`.
fn git_ok(dir: &Path, args: &[&str]) -> Result<Vec<u8>> {
    match run_git(dir, args, None)? {
        (0, out, _) => Ok(out),
        (code, _, err) => {
            let summary = crate::identity::failure_summary(&err);
            if err.is_empty() || summary.starts_with(crate::identity::NOT_A_REPOSITORY) {
                Err(format!("git {} exited {code}", args[0]))
            } else {
                Err(format!("git failed: {summary}"))
            }
        }
    }
}
fn text(bytes: Vec<u8>) -> Result<String> {
    String::from_utf8(bytes).map_err(|_| "non UTF-8 git output".into())
}
fn fields(bytes: &[u8]) -> Result<Vec<String>> {
    bytes
        .split(|b| *b == 0)
        .filter(|f| !f.is_empty())
        .map(|f| String::from_utf8(f.to_vec()).map_err(|_| "non UTF-8 path".into()))
        .collect()
}
fn excluded(path: &str) -> bool {
    excluded_by(path, &EXCLUDED_PREFIXES)
}
/// `rel` is excluded when it equals an entry (trailing `/` ignored) or lies under it.
fn excluded_by(rel: &str, excludes: &[&str]) -> bool {
    excludes.iter().any(|e| {
        let e = e.trim_end_matches('/');
        !e.is_empty() && (rel == e || rel.starts_with(&format!("{e}/")))
    })
}
fn hex40(s: &str) -> bool {
    s.len() == 40
        && s.bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

/// Working-tree bytes of a repository-relative path, without following symlinks.
/// Returns (kind, sha256 of file bytes or link target).
fn content(root: &Path, rel: &str) -> Result<(&'static str, Option<String>)> {
    let path = root.join(rel);
    let Ok(m) = fs::symlink_metadata(&path) else {
        return Ok(("missing", None));
    };
    if m.file_type().is_symlink() {
        let target = fs::read_link(&path).map_err(|_| "symlink unreadable")?;
        let raw = target.to_str().ok_or("non UTF-8 symlink target")?;
        return Ok(("symlink", Some(crate::digest(raw.as_bytes()))));
    }
    if m.is_file() {
        let bytes = fs::read(&path).map_err(|_| format!("unreadable file {rel}"))?;
        return Ok(("file", Some(crate::digest(&bytes))));
    }
    Ok((if m.is_dir() { "directory" } else { "special" }, None))
}

/// RFC 3339 UTC seconds from the system clock (civil-from-days, no external crate).
pub(crate) fn utc_now() -> String {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let (days, rem) = (secs.div_euclid(86400), secs.rem_euclid(86400));
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + i64::from(m <= 2);
    format!(
        "{y:04}-{m:02}-{d:02}T{:02}:{:02}:{:02}Z",
        rem / 3600,
        rem % 3600 / 60,
        rem % 60
    )
}

fn relativize(root: &Path, raw: &str) -> String {
    let p = fs::canonicalize(raw).unwrap_or_else(|_| PathBuf::from(raw));
    match p.strip_prefix(root) {
        Ok(r) if r.as_os_str().is_empty() => ".".into(),
        Ok(r) => r.to_string_lossy().into_owned(),
        Err(_) => "<outside-project>".into(),
    }
}

fn worktrees(root: &Path) -> Result<Vec<Value>> {
    let out = git_ok(root, &["worktree", "list", "--porcelain", "-z"])?;
    let mut rows = Vec::new();
    let mut cur: BTreeMap<String, Value> = BTreeMap::new();
    for field in out.split(|b| *b == 0) {
        if field.is_empty() {
            if !cur.is_empty() {
                rows.push(json!(std::mem::take(&mut cur)));
            }
            continue;
        }
        let f = String::from_utf8_lossy(field);
        let (key, val) = f.split_once(' ').unwrap_or((&f, ""));
        match key {
            "worktree" => cur.insert("path".into(), json!(relativize(root, val))),
            "HEAD" => cur.insert("head".into(), json!(val)),
            "branch" => cur.insert("branch".into(), json!(val)),
            // Lock and prune reasons are free text that may carry paths; keep the flag only.
            "detached" | "bare" | "locked" | "prunable" => cur.insert(key.into(), json!(true)),
            _ => None,
        };
    }
    if !cur.is_empty() {
        rows.push(json!(cur));
    }
    rows.sort_by_key(|r| r["path"].as_str().unwrap_or("").to_string());
    Ok(rows)
}

fn remote_heads(root: &Path) -> Value {
    match git(root, &["ls-remote", "--heads", "origin"], None) {
        Ok((0, out)) => {
            let mut heads: Vec<Value> = String::from_utf8_lossy(&out)
                .lines()
                .filter_map(|l| l.split_once('\t'))
                .map(|(sha, r)| json!({"ref": r, "sha": sha}))
                .collect();
            heads.sort_by_key(|h| h["ref"].as_str().unwrap_or("").to_string());
            json!({"status": "collected", "heads": heads})
        }
        // stderr is discarded: it can echo a remote URL carrying credentials.
        Ok((code, _)) => {
            json!({"status": "unavailable", "reason": format!("ls-remote exited {code}")})
        }
        Err(e) => json!({"status": "unavailable", "reason": e}),
    }
}

/// Parses `git status --porcelain=v2 -z --untracked-files=all`. Header lines (`#`) and
/// unknown record types are skipped: only v1 carries a documented stability guarantee.
fn changes(root: &Path, excluded_count: &mut usize) -> Result<Vec<Value>> {
    let out = git_ok(
        root,
        &["status", "--porcelain=v2", "-z", "--untracked-files=all"],
    )?;
    let recs = fields(&out)?;
    let mut rows = Vec::new();
    let mut i = 0;
    while i < recs.len() {
        let r = &recs[i];
        i += 1;
        let parts: Vec<&str> = r.splitn(11, ' ').collect();
        let (kind, xy, head, index, path, orig) = match parts[0] {
            "1" if parts.len() >= 9 => {
                let rest: Vec<&str> = r.splitn(9, ' ').collect();
                (
                    "ordinary",
                    rest[1],
                    rest[6],
                    rest[7],
                    rest[8].to_string(),
                    None,
                )
            }
            "2" if parts.len() >= 10 => {
                let rest: Vec<&str> = r.splitn(10, ' ').collect();
                let orig = recs.get(i).cloned();
                i += 1;
                (
                    "renamed",
                    rest[1],
                    rest[6],
                    rest[7],
                    rest[9].to_string(),
                    orig,
                )
            }
            "u" if parts.len() >= 11 => ("unmerged", parts[1], "", "", parts[10].to_string(), None),
            "?" => ("untracked", "??", "", "", r[2..].to_string(), None),
            _ => continue,
        };
        if excluded(&path) {
            *excluded_count += 1;
            continue;
        }
        let (file_kind, sha) = content(root, &path)?;
        let opt = |s: &str| {
            if hex40(s) && s != "0".repeat(40) {
                json!(s)
            } else {
                Value::Null
            }
        };
        rows.push(json!({
            "path": path, "status": kind, "xy": xy, "kind": file_kind, "sha256": sha,
            "object_head": opt(head), "object_index": opt(index), "orig_path": orig,
        }));
    }
    rows.sort_by_key(|r| r["path"].as_str().unwrap_or("").to_string());
    Ok(rows)
}

fn tracked(root: &Path) -> Result<Vec<Value>> {
    let out = git_ok(root, &["ls-files", "-s", "-z"])?;
    let mut seen = BTreeMap::new();
    for rec in fields(&out)? {
        let (meta, path) = rec.split_once('\t').ok_or("malformed ls-files record")?;
        let m: Vec<&str> = meta.split(' ').collect();
        if m.len() != 3 || seen.contains_key(path) {
            continue;
        }
        let (kind, sha) = if m[0] == "160000" {
            ("gitlink", None)
        } else {
            content(root, path)?
        };
        seen.insert(
            path.to_string(),
            json!({"path": path, "mode": m[0], "object": m[1], "kind": kind, "sha256": sha}),
        );
    }
    Ok(seen.into_values().collect())
}

/// Blob ids of active files, computed without writing objects.
fn blob_ids(root: &Path, files: &[(String, &'static str)]) -> Result<BTreeMap<String, String>> {
    let mut ids = BTreeMap::new();
    let regular: Vec<&String> = files
        .iter()
        .filter(|f| f.1 == "file")
        .map(|f| &f.0)
        .collect();
    if !regular.is_empty() {
        let list: String = regular.iter().map(|p| format!("{p}\n")).collect();
        let (code, out) = git(
            root,
            &["hash-object", "--no-filters", "--stdin-paths"],
            Some(list.as_bytes()),
        )?;
        let out = text(out)?;
        let lines: Vec<&str> = out.lines().collect();
        if code != 0 || lines.len() != regular.len() {
            return Err("hash-object failed".into());
        }
        for (p, id) in regular.iter().zip(lines) {
            ids.insert((*p).clone(), id.to_string());
        }
    }
    for (p, _) in files.iter().filter(|f| f.1 == "symlink") {
        let target = fs::read_link(root.join(p)).map_err(|_| "symlink unreadable")?;
        let raw = target.to_str().ok_or("non UTF-8 symlink target")?;
        let (code, out) = git(
            root,
            &["hash-object", "--no-filters", "--stdin"],
            Some(raw.as_bytes()),
        )?;
        if code != 0 {
            return Err("hash-object failed".into());
        }
        ids.insert(p.clone(), text(out)?.trim().to_string());
    }
    Ok(ids)
}

/// Lists regular files and symlinks under `dir` (paths relative to `root`, symlinks never
/// followed). Entries matching `excludes` are skipped and their files counted in `skipped`;
/// special files are refused.
fn walk(
    root: &Path,
    dir: &Path,
    excludes: &[&str],
    out: &mut Vec<(String, &'static str)>,
    skipped: &mut usize,
) -> Result<()> {
    let Ok(entries) = fs::read_dir(dir) else {
        return Ok(());
    };
    for entry in entries {
        let path = entry.map_err(|_| "directory entry unavailable")?.path();
        let rel = path
            .strip_prefix(root)
            .map_err(|_| "path outside root")?
            .to_str()
            .ok_or("non UTF-8 path")?
            .to_string();
        let m = fs::symlink_metadata(&path).map_err(|_| "metadata unavailable")?;
        if excluded_by(&rel, excludes) {
            *skipped += if m.is_dir() { count_files(&path) } else { 1 };
        } else if m.is_dir() {
            walk(root, &path, excludes, out, skipped)?;
        } else if m.file_type().is_symlink() {
            out.push((rel, "symlink"));
        } else if m.is_file() {
            out.push((rel, "file"));
        } else {
            return Err(format!("special file refused: {rel}"));
        }
    }
    Ok(())
}

// @MX:ANCHOR tree digest owned by 00-A (#1985); 05-C #2003 and 07-D #2011 call it, never re-implement.
/// Content digest of the file tree under `root` (format `moai-tree-v1`). Paths are relative,
/// `/`-separated, UTF-8 and sorted bytewise; each entry is framed as kind byte (`f` file,
/// `l` symlink), u64 big-endian path length, path, u64 big-endian content length, content
/// (file bytes, or the link target for a symlink, which is never followed). Empty directories
/// do not contribute. `excludes` are root-relative paths; an entry equal to or under one is
/// left out. Special files are refused. Returns `sha256:<64 lowercase hex>`.
pub fn tree_digest(root: &Path, excludes: &[&str]) -> Result<String> {
    use sha2::{Digest, Sha256};
    let mut files = Vec::new();
    walk(root, root, excludes, &mut files, &mut 0)?;
    files.sort();
    let mut h = Sha256::new();
    h.update(b"moai-tree-v1\0");
    for (rel, kind) in files {
        let path = root.join(&rel);
        let (tag, bytes) = if kind == "symlink" {
            let t = fs::read_link(&path).map_err(|_| "symlink unreadable")?;
            (
                b'l',
                t.to_str()
                    .ok_or("non UTF-8 symlink target")?
                    .as_bytes()
                    .to_vec(),
            )
        } else {
            (
                b'f',
                fs::read(&path).map_err(|_| format!("unreadable file {rel}"))?,
            )
        };
        let name = rel.replace(std::path::MAIN_SEPARATOR, "/");
        h.update([tag]);
        h.update((name.len() as u64).to_be_bytes());
        h.update(name.as_bytes());
        h.update((bytes.len() as u64).to_be_bytes());
        h.update(&bytes);
    }
    Ok(format!("sha256:{:x}", h.finalize()))
}
fn count_files(dir: &Path) -> usize {
    fs::read_dir(dir)
        .map(|es| {
            es.filter_map(|e| e.ok())
                .map(|e| match fs::symlink_metadata(e.path()) {
                    Ok(m) if m.is_dir() => count_files(&e.path()),
                    Ok(_) => 1,
                    Err(_) => 0,
                })
                .sum()
        })
        .unwrap_or(0)
}

fn scope(path: &str) -> &'static str {
    let name = path.rsplit('/').next().unwrap_or(path);
    if name.contains(".local.") || name.ends_with(".local") {
        "private"
    } else {
        "shared"
    }
}

fn claude_diff(
    root: &Path,
    commit: Option<&str>,
    go_repo: Option<&Path>,
    tracked_paths: &BTreeSet<String>,
) -> Result<Value> {
    let rules = json!({
        "key": "path relative to the .claude directory of each set",
        "class": "baseline-only|template-only|active-only when present in one set; identical when present in two or more sets with one blob id; differing otherwise",
        "tracking": "current checkout: tracked (ls-files), ignored (check-ignore), untracked, or absent",
        "origin": "generated when the template set holds the path, else source",
        "scope": "private when the file name contains .local. or ends with .local, else shared",
        "excluded": EXCLUDED_PREFIXES,
    });
    let Some(commit) = commit else {
        return Ok(
            json!({"status": "not_collected", "reason": "no --go-baseline-commit", "rules": rules}),
        );
    };
    if !hex40(commit) {
        return Err("go baseline commit must be 40 lowercase hex".into());
    }
    let spec = format!("{commit}^{{commit}}");
    let has = |dir: &Path| matches!(git(dir, &["cat-file", "-e", &spec], None), Ok((0, _)));
    let (repo, source): (PathBuf, &str) = if has(root) {
        (root.to_path_buf(), "project")
    } else if let Some(g) = go_repo.filter(|g| has(g)) {
        (g.to_path_buf(), "go-repo")
    } else {
        return Ok(
            json!({"status": "commit_not_found", "go_baseline_commit": commit, "rules": rules}),
        );
    };
    let tree = git_ok(
        &repo,
        &[
            "ls-tree",
            "-r",
            "-z",
            commit,
            "--",
            ".claude",
            "internal/template/templates",
        ],
    )?;
    let mut baseline = BTreeMap::new();
    let mut template = BTreeMap::new();
    let mut roots = BTreeSet::new();
    for rec in fields(&tree)? {
        let (meta, path) = rec.split_once('\t').ok_or("malformed ls-tree record")?;
        let object = meta
            .split(' ')
            .nth(2)
            .ok_or("malformed ls-tree record")?
            .to_string();
        if let Some(rel) = path.strip_prefix(".claude/") {
            baseline.insert(rel.to_string(), object);
        } else if let Some(rest) = path.strip_prefix(TEMPLATE_PREFIX) {
            let (troot, rel) = if let Some(rel) = rest.strip_prefix(".claude/") {
                ("", rel)
            } else if let Some(at) = rest.find("/.claude/") {
                (&rest[..at], &rest[at + 9..])
            } else {
                continue;
            };
            roots.insert(troot.to_string());
            template.insert(rel.to_string(), object);
        }
    }
    if roots.len() > 1 {
        return Ok(json!({"status": "multiple_template_roots", "roots": roots, "rules": rules}));
    }
    let mut active_files = Vec::new();
    let mut skipped = 0;
    walk(
        root,
        &root.join(".claude"),
        &EXCLUDED_PREFIXES,
        &mut active_files,
        &mut skipped,
    )?;
    let active_tree_digest = tree_digest(&root.join(".claude"), &["worktrees/"])?;
    let ids = blob_ids(root, &active_files)?;
    let mut active = BTreeMap::new();
    for (p, kind) in &active_files {
        let rel = p.strip_prefix(".claude/").unwrap_or(p).to_string();
        let (_, sha) = content(root, p)?;
        active.insert(rel, (ids.get(p).cloned(), sha, *kind));
    }
    let active_list: String = active.keys().map(|k| format!(".claude/{k}\0")).collect();
    let ignored: BTreeSet<String> = match git(
        root,
        &["check-ignore", "-z", "--stdin"],
        Some(active_list.as_bytes()),
    )? {
        (0 | 1, out) => fields(&out)?.into_iter().collect(),
        (code, _) => return Err(format!("git check-ignore exited {code}")),
    };
    let keys: BTreeSet<&String> = baseline
        .keys()
        .chain(template.keys())
        .chain(active.keys())
        .collect();
    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    let mut rows = Vec::new();
    for k in keys {
        let b = baseline.get(k);
        let t = template.get(k);
        let a = active.get(k);
        let ids: Vec<Option<&String>> = vec![b, t, a.map(|a| a.0.as_ref()).unwrap_or(None)];
        let present = [b.is_some(), t.is_some(), a.is_some()];
        let n = present.iter().filter(|p| **p).count();
        let class = match (n, present) {
            (1, [true, _, _]) => "baseline-only",
            (1, [_, true, _]) => "template-only",
            (1, _) => "active-only",
            _ => {
                let distinct: BTreeSet<Option<&String>> = ids
                    .iter()
                    .zip(present)
                    .filter(|(_, p)| *p)
                    .map(|(i, _)| *i)
                    .collect();
                if distinct.len() == 1 && !distinct.contains(&None) {
                    "identical"
                } else {
                    "differing"
                }
            }
        };
        *counts.entry(class).or_default() += 1;
        let full = format!(".claude/{k}");
        let tracking = if a.is_none() {
            "absent"
        } else if tracked_paths.contains(&full) {
            "tracked"
        } else if ignored.contains(&full) {
            "ignored"
        } else {
            "untracked"
        };
        rows.push(json!({
            "path": k, "class": class,
            "baseline": b, "template": t,
            "active": a.map(|(id, sha, kind)| json!({"object": id, "sha256": sha, "kind": kind})),
            "tracking": tracking,
            "origin": if t.is_some() { "generated" } else { "source" },
            "scope": scope(k),
        }));
    }
    let total = rows.len();
    Ok(json!({
        "status": "collected", "go_baseline_commit": commit, "source": source,
        "template_root": roots.iter().next().map(|r| format!("{TEMPLATE_PREFIX}{r}")),
        "rules": rules, "counts": counts, "total": total,
        "set_sizes": {"baseline": baseline.len(), "template": template.len(), "active": active.len()},
        "excluded_active_files": skipped,
        "active_tree_digest": active_tree_digest,
        "active_tree_digest_excludes": ["worktrees/"],
        "rows": rows,
    }))
}

/// Collects the read-only baseline for `project`. Returns
/// `{schema_version, collected_at, baseline, inventory, claude_diff, checksums}`.
pub fn inventory(project: &Path, go_commit: Option<&str>, go_repo: Option<&Path>) -> Result<Value> {
    let collected_at = utc_now();
    let top = text(git_ok(project, &["rev-parse", "--show-toplevel"])?)?;
    let root = fs::canonicalize(top.trim()).map_err(|_| "project root unavailable")?;
    let head = text(git_ok(&root, &["rev-parse", "HEAD"])?)?
        .trim()
        .to_string();
    if !hex40(&head) {
        return Err("HEAD is not a 40 hex commit".into());
    }
    let branch = text(git_ok(&root, &["branch", "--show-current"])?)?
        .trim()
        .to_string();
    let home = std::env::var_os("HOME").map(PathBuf::from);
    let home_rows: Vec<Value> = HOME_ENTRIES
        .iter()
        .map(|e| {
            let exists = home
                .as_ref()
                .map(|h| fs::symlink_metadata(h.join(e)).is_ok());
            json!({"path": format!("~/{e}"), "exists": exists})
        })
        .collect();
    let files = tracked(&root)?;
    let tracked_paths: BTreeSet<String> = files
        .iter()
        .filter_map(|f| f["path"].as_str().map(String::from))
        .collect();
    let mut excluded_changes = 0;
    let changed = changes(&root, &mut excluded_changes)?;
    let mut sums = BTreeMap::new();
    // shasum-format lines cannot carry these paths unescaped; they stay in `files`/`changes`
    // and are listed here so the omission is visible rather than silent.
    let mut unrepresentable = BTreeSet::new();
    for f in files.iter().chain(changed.iter()) {
        if let (Some(p), Some(s), Some("file")) =
            (f["path"].as_str(), f["sha256"].as_str(), f["kind"].as_str())
        {
            if p.contains('\n') || p.contains('\\') {
                unrepresentable.insert(p.to_string());
            } else {
                sums.insert(p.to_string(), s[7..].to_string());
            }
        }
    }
    let checksums: String = sums.iter().map(|(p, h)| format!("{h}  {p}\n")).collect();
    let mut diff = claude_diff(&root, go_commit, go_repo, &tracked_paths)?;
    diff["schema_version"] = json!(1);
    diff["collected_at"] = json!(collected_at);
    diff["head_sha"] = json!(head);
    let count = |s: &str| changed.iter().filter(|c| c["status"] == s).count();
    let measurements = json!([
        {"name": "tracked_files", "command": "git ls-files -s -z", "value": files.len()},
        {"name": "changed_tracked", "command": "git status --porcelain=v2 -z --untracked-files=all", "value": changed.len() - count("untracked")},
        {"name": "untracked_files", "command": "git status --porcelain=v2 -z --untracked-files=all", "value": count("untracked")},
        {"name": "checksum_rows", "command": "sha256 of regular files among tracked and changed rows", "value": sums.len()},
    ]);
    Ok(json!({
        "schema_version": 1,
        "collected_at": collected_at,
        "baseline": {
            "schema_version": 1, "collected_at": collected_at,
            "head_sha": head, "branch": if branch.is_empty() { Value::Null } else { json!(branch) },
            "worktrees": worktrees(&root)?,
            "remote_heads": remote_heads(&root),
            "home": home_rows,
            "path_rule": "paths are relative to the project root; worktrees outside it read <outside-project>; home entries are ~-relative and recorded as existence only",
        },
        "inventory": {
            "schema_version": 1, "collected_at": collected_at, "head_sha": head,
            "files": files, "changes": changed,
            "excluded_prefixes": EXCLUDED_PREFIXES, "excluded_changes": excluded_changes,
            "checksum_unrepresentable": unrepresentable,
            "measurements": measurements,
            "measured_at": "collected_at",
        },
        "claude_diff": diff,
        "checksums": checksums,
    }))
}

src/claim.rs.content:
//! Claim journal (① single-host) and Issue comment claim (⑤ cross-host, eventual)
//! (Issue #2005, 06-A; P08 decision 2026-11-08: ⑤ comment claim is primary, ① the
//! same-host serializer).
//!
//! ① One clone keeps one journal. All worktrees of a clone resolve the same common dir
//! through [`crate::identity`], so the journal lives at `<common dir>/.moai-cli/claims/`:
//! `journal.log` (append-only, one JSON line per event, fsync — the authority),
//! `<task_key>.json` (the current record, temp + fsync + rename — a human-readable cache),
//! and `.lock` (an advisory `File::try_lock` target). A second process that finds the lock
//! held gets `busy` at once and waits never (REQ-06A-05); the waiting policy is the caller's.
//! The lock serialises same-host claimants only: anything that bypasses `moai-cli` is not
//! serialised, which is why a claim that never went through the journal is invalid by
//! definition (RC1 reading of the advisory-lock boundary).
//!
//! ⑤ A claiming lane posts exactly one Issue comment
//! `moai-claim: session=<id> epoch=<n> lease_until=<utc>` (after the journal check) and
//! records the returned comment id in the record. When live claim comments collide, the
//! smallest comment id wins and the loser stops writing and gets `already_owned`
//! (REQ-06A-13). A winning comment with the caller's own session value is adopted only when
//! this journal recorded posting that comment id; otherwise the outcome is `uncertain` and
//! nothing is written, because a same-named live session may own it (#2165, REQ-AM-04).
//! The token `Moai-Claim: <issue>#<comment-id>` is carried in the branch
//! name (suffix `c<issue>-<id>`), in every commit trailer and in the PR body
//! (REQ-06A-14); [`verify_claim_token`] is the leader's read-side check (REQ-06A-15).
//! An expired lease is never taken over automatically: the outcome names the operator
//! (06-B) instead (REQ-06A-16).
//!
//! Lease (rc.2 #2166, decisions 00:5x 2026-11-09): an absent `lease_until` defaults to
//! now + [`DEFAULT_LEASE`] (4h); an explicit value wins. Expiry is only shown
//! (`claim-show` `expired: true`) and never moves ownership.
//!
//! HOLD (reported, never decided here): the heartbeat numbers (P08/P11); the journal location
//! is an interim derivation under the git common dir until P09/01-B fixes the state-root
//! map; takeover after expiry is 06-B's operator procedure.
use crate::digest;
use crate::forge::policy::{format_utc, next_link, parse_utc, Clock};
use crate::forge::transport::{HttpRequest, Transport};
use crate::forge::{Client, ForgeError};
use crate::identity;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{
    fs::{self, OpenOptions},
    io::Write,
    path::{Path, PathBuf},
    process::{Command, Stdio},
};

type Result<T> = std::result::Result<T, String>;

pub const SCHEMA_VERSION: u32 = 1;
/// Default lease in seconds when a request carries no `lease_until` (#2166, 4h).
pub const DEFAULT_LEASE: i64 = 4 * 60 * 60;
/// Safety bound for the comment-list pagination, aligned with forge's `max_pages`.
const CLAIM_MAX_PAGES: u32 = 50;
/// The states in which a record holds the claim (plan §8). A record in any other state
/// (`unclaimed`, `integrated`, `cancelled`) does not block a new acquire.
pub const ACTIVE_STATES: &[&str] = &[
    "assigned",
    "running",
    "verifying",
    "pr_ready",
    "in_review",
    "blocked",
    "handoff_pending",
    "uncertain",
];

// @MX:NOTE: The journal root is derived from git's common dir (`<clone>/.git/.moai-cli/claims`)
// so every worktree of one clone shares one journal and git status stays clean. HOLD: the final
// state-root map belongs to P09 / 01-B (#1989); 06-B must migrate records if the location moves.
/// One clone keeps one journal; the common dir is the clone boundary (01-A), so all worktrees
/// resolve the same root and git never lists the files.
pub fn journal_root(project: &Path) -> Result<PathBuf> {
    let id = identity::identity(project)?;
    if id["identity_status"].as_str() != Some("ok") {
        return Err(format!(
            "claim journal requires a git repository; identity_status was {}",
            id["identity_status"].as_str().unwrap_or("unknown")
        ));
    }
    let common = id["clone_anchor"]
        .as_str()
        .ok_or("claim journal requires a git repository")?;
    Ok(Path::new(common).join(".moai-cli").join("claims"))
}

// ---- Request and record ----

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct TaskRef {
    pub provider: String,
    pub host: String,
    /// Display data for the API URL; the key is `(provider, host, repository_id, issue_id)`.
    pub owner: String,
    pub repo: String,
    pub repository_id: i64,
    pub issue_id: i64,
    pub issue_number: i64,
}

impl TaskRef {
    /// Every field is required today; an optional field added later gets its default here,
    /// so call sites stay unchanged (#2256).
    pub fn new(
        provider: impl Into<String>,
        host: impl Into<String>,
        owner: impl Into<String>,
        repo: impl Into<String>,
        repository_id: i64,
        issue_id: i64,
        issue_number: i64,
    ) -> Self {
        TaskRef {
            provider: provider.into(),
            host: host.into(),
            owner: owner.into(),
            repo: repo.into(),
            repository_id,
            issue_id,
            issue_number,
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct Owner {
    /// `session`, `leader`, `operator`, `local-process`, `remote-task`, `ci` (bounded free
    /// form). `local-process` is the only kind 06-B probes for liveness.
    pub kind: String,
    pub id: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub host_id: Option<String>,
    /// 06-B additive: the OS pid of a `local-process` owner, recorded at claim time so a
    /// later handoff can probe liveness (REQ-06B-02). Old records deserialize unchanged.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pid: Option<u32>,
    /// 06-B additive: the process start time (`ps -o lstart=` under `LC_ALL=C`); comparing
    /// it guards against pid reuse. Recorded with `pid`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub process_start: Option<String>,
}

impl Owner {
    /// An owner with no host id, pid or process start (#2256).
    pub fn new(kind: impl Into<String>, id: impl Into<String>) -> Self {
        Owner {
            kind: kind.into(),
            id: id.into(),
            host_id: None,
            pid: None,
            process_start: None,
        }
    }

    pub fn host_id(mut self, host_id: impl Into<String>) -> Self {
        self.host_id = Some(host_id.into());
        self
    }

    pub fn pid(mut self, pid: u32) -> Self {
        self.pid = Some(pid);
        self
    }

    pub fn process_start(mut self, process_start: impl Into<String>) -> Self {
        self.process_start = Some(process_start.into());
        self
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct SpecRef {
    pub id: String,
    pub revision: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub digest: Option<String>,
}

/// `claim-acquire` stdin (typed JSON, unknown keys rejected).
#[derive(Clone, Debug, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct ClaimRequest {
    pub schema_version: u32,
    pub task_ref: TaskRef,
    pub logical_key: String,
    pub owner: Owner,
    /// #2169 additive: GitHub assignee — display projection only (REQ-B2-01), recorded
    /// verbatim; the claim never writes it to GitHub (REQ-06A-08).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub assignee: Option<String>,
    /// #2169 additive: the host session identifier of the executing session.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub provider_session: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub attempt: Option<u64>,
    /// The exact base commit the attempt is bound to (40 lowercase hex).
    pub base_revision: String,
    pub write_scope: Vec<String>,
    pub spec_ref: SpecRef,
    /// RFC3339 `YYYY-MM-DDTHH:MM:SSZ`. Absent or empty: now + [`DEFAULT_LEASE`] at acquire
    /// (#2166); an explicit value wins.
    #[serde(default)]
    pub lease_until: String,
    /// Recorded as intents in `effects[]` only; never executed by this Issue (REQ-06A-08).
    #[serde(default)]
    pub projection_intents: Vec<Value>,
    /// WHEN given and not the epoch the journal would hand out, the request is rejected as
    /// stale (AC-06A-2).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expected_epoch: Option<u64>,
}

impl ClaimRequest {
    /// The required fields; every optional field takes the value serde gives an absent key,
    /// so a built request equals the parsed one (#2256).
    pub fn new(
        schema_version: u32,
        task_ref: TaskRef,
        logical_key: impl Into<String>,
        owner: Owner,
        base_revision: impl Into<String>,
        write_scope: Vec<String>,
        spec_ref: SpecRef,
    ) -> Self {
        ClaimRequest {
            schema_version,
            task_ref,
            logical_key: logical_key.into(),
            owner,
            assignee: None,
            provider_session: None,
            attempt: None,
            base_revision: base_revision.into(),
            write_scope,
            spec_ref,
            lease_until: String::new(),
            projection_intents: Vec::new(),
            expected_epoch: None,
        }
    }

    pub fn assignee(mut self, assignee: impl Into<String>) -> Self {
        self.assignee = Some(assignee.into());
        self
    }

    pub fn provider_session(mut self, provider_session: impl Into<String>) -> Self {
        self.provider_session = Some(provider_session.into());
        self
    }

    pub fn attempt(mut self, attempt: u64) -> Self {
        self.attempt = Some(attempt);
        self
    }

    pub fn lease_until(mut self, lease_until: impl Into<String>) -> Self {
        self.lease_until = lease_until.into();
        self
    }

    pub fn projection_intents(mut self, projection_intents: Vec<Value>) -> Self {
        self.projection_intents = projection_intents;
        self
    }

    pub fn expected_epoch(mut self, expected_epoch: u64) -> Self {
        self.expected_epoch = Some(expected_epoch);
        self
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct WorktreeId {
    pub common_dir: String,
    pub git_dir: String,
    pub path: String,
    /// Full 40-hex HEAD of the work tree at claim time.
    pub head: String,
    /// 06-B/2107 additive: the branch name the claim works on (checked against
    /// `pulls?head=<owner>:<branch>` when reconciling a pr_create effect). Old records
    /// deserialize unchanged; `None` falls back to the full pull-list scan.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub branch: Option<String>,
}

impl WorktreeId {
    /// A work tree identity with no branch (#2256).
    pub fn new(
        common_dir: impl Into<String>,
        git_dir: impl Into<String>,
        path: impl Into<String>,
        head: impl Into<String>,
    ) -> Self {
        WorktreeId {
            common_dir: common_dir.into(),
            git_dir: git_dir.into(),
            path: path.into(),
            head: head.into(),
            branch: None,
        }
    }

    pub fn branch(mut self, branch: impl Into<String>) -> Self {
        self.branch = Some(branch.into());
        self
    }
}

/// One claim record (REQ-06A-01). `comment_id`/`claim_token` are the ⑤ fencing token
/// (REQ-06A-12); `claim_token` is the exact `Moai-Claim: <issue>#<comment-id>` string.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct ClaimRecord {
    pub schema_version: u32,
    pub task_ref: TaskRef,
    pub task_key: String,
    pub logical_key: String,
    /// The execution owner — the only one of the four ownership fields the acquire path
    /// compares with the winning claim comment's session (REQ-B2-01). Exclusivity itself
    /// comes from that comment and the journal record, never from a field value alone.
    pub owner: Owner,
    /// #2169 additive: GitHub assignee of the issue — display projection only, never
    /// consulted by the journal or any gate (REQ-06A-08: a claim never writes it).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub assignee: Option<String>,
    /// #2169 additive: the host session identifier of the executing session.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub provider_session: Option<String>,
    /// #2169 additive: the leader-side integration gate identifier (who owns the
    /// integration gate for this claim). Set by the integration flow, not by acquire.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub integration_owner: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub attempt: Option<u64>,
    pub epoch: u64,
    pub base_revision: String,
    pub worktree: WorktreeId,
    pub write_scope: Vec<String>,
    pub spec_ref: SpecRef,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub comment_id: Option<i64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub claim_token: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lease_until: Option<String>,
    pub state: String,
    #[serde(default)]
    pub effects: Vec<Value>,
    pub last_observed_at: String,
}

/// One `journal.log` line. Public so tests and 06-B tooling can read the authority file.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct JournalEvent {
    pub event: String,
    pub record: ClaimRecord,
}

/// sha256(provider|host|repository_id|issue_id), first 16 hex chars — path-safe (plan step 4).
pub fn task_key(t: &TaskRef) -> String {
    let s = format!(
        "{}|{}|{}|{}",
        t.provider, t.host, t.repository_id, t.issue_id
    );
    digest(s.as_bytes())[7..23].to_string()
}

pub fn claim_token(issue_number: i64, comment_id: i64) -> String {
    format!("Moai-Claim: {issue_number}#{comment_id}")
}

/// Branch-name encoding of the token (REQ-06A-14); branches cannot carry `#`.
pub fn claim_branch_suffix(issue_number: i64, comment_id: i64) -> String {
    format!("c{issue_number}-{comment_id}")
}

/// Whether `state` holds the claim (blocks a new acquire). `handed_off` (06-B) is not
/// active: the handoff closes the record and the next acquire writes the new epoch.
pub fn is_active(state: &str) -> bool {
    ACTIVE_STATES.contains(&state)
}

fn is_live(lease_until: &str, now: i64) -> bool {
    parse_utc(lease_until).is_some_and(|t| t > now)
}

pub fn is_key(s: &str) -> bool {
    s.len() == 16
        && s.bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

fn bounded(s: &str, max: usize) -> bool {
    !s.is_empty() && s.len() <= max && !s.chars().any(char::is_control)
}

fn valid_github_name(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 100
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"-_.".contains(&b))
        && s != "."
        && s != ".."
}

fn validate_request(req: &ClaimRequest) -> Result<()> {
    if req.schema_version != SCHEMA_VERSION {
        return Err("unsupported request schema_version".into());
    }
    let t = &req.task_ref;
    if t.provider != "github" || t.host != "github.com" {
        return Err("claim task_ref must be provider github host github.com in RC1".into());
    }
    if !valid_github_name(&t.owner) || !valid_github_name(&t.repo) {
        return Err("claim task_ref owner and repo must be GitHub names".into());
    }
    if t.repository_id <= 0 || t.issue_id <= 0 || t.issue_number <= 0 {
        return Err("claim task_ref ids must be positive".into());
    }
    if !bounded(&req.logical_key, 100) {
        return Err("logical_key must be a bounded string without control characters".into());
    }
    if !bounded(&req.owner.kind, 32) || !bounded(&req.owner.id, 128) {
        return Err("owner kind and id must be bounded strings without control characters".into());
    }
    if req.owner.host_id.as_ref().is_some_and(|h| !bounded(h, 128)) {
        return Err("owner host_id must be a bounded string without control characters".into());
    }
    let hex = |s: &str| {
        s.len() == 40
            && s.bytes()
                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
    };
    if !hex(&req.base_revision) {
        return Err("base_revision must be a 40 lowercase hex commit".into());
    }
    if req.write_scope.len() > 32 || req.write_scope.iter().any(|s| !bounded(s, 256)) {
        return Err("write_scope must be a bounded list of short entries".into());
    }
    if !bounded(&req.spec_ref.id, 128) || !bounded(&req.spec_ref.revision, 128) {
        return Err(
            "spec_ref id and revision must be bounded strings without control characters".into(),
        );
    }
    if let Some(d) = &req.spec_ref.digest {
        let ok = d.len() == 71
            && d.starts_with("sha256:")
            && d[7..]
                .bytes()
                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b));
        if !ok {
            return Err("spec_ref digest must be sha256:<64 hex digits>".into());
        }
    }
    if parse_utc(&req.lease_until).is_none() {
        return Err("lease_until must be YYYY-MM-DDTHH:MM:SSZ".into());
    }
    if req.projection_intents.len() > 32 {
        return Err("projection_intents must be a bounded list (32)".into());
    }
    Ok(())
}

// ---- Worktree identity (01-A reuse + a minimal HEAD read) ----

fn git_head(work_tree: &str) -> Result<String> {
    let mut cmd = Command::new("git");
    cmd.arg("--no-optional-locks")
        .arg("-C")
        .arg(work_tree)
        .arg("rev-parse")
        .arg("HEAD");
    // The shared git-environment scrub (Issue #2043) — the same hygiene as `identity`.
    identity::scrub_git_env(&mut cmd);
    let out = cmd
        .env("GIT_OPTIONAL_LOCKS", "0")
        .stdin(Stdio::null())
        .stderr(Stdio::piped())
        .output()
        .map_err(|_| "git unavailable")?;
    if !out.status.success() {
        let stderr = String::from_utf8_lossy(&out.stderr);
        let raw = stderr.lines().next().unwrap_or("").trim();
        let line = raw
            .strip_prefix("fatal:")
            .or_else(|| raw.strip_prefix("error:"))
            .unwrap_or(raw)
            .trim();
        let cut = line.find(['\'', '"', '/', '\\']).unwrap_or(line.len());
        let summary: String = line[..cut].trim_end().chars().take(160).collect();
        let summary = if summary.is_empty() {
            "git rev-parse failed"
        } else {
            &summary
        };
        return Err(format!("git failed: {summary}"));
    }
    let s = String::from_utf8(out.stdout)
        .map_err(|_| "non UTF-8 git output")?
        .trim()
        .to_string();
    let lower_hex = s
        .bytes()
        .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b));
    if s.len() == 40 && lower_hex {
        Ok(s)
    } else {
        Err("HEAD is not a 40 hex commit".into())
    }
}

/// The checked-out branch of the work tree at claim time (#2126) — the name a later
/// pr_create reconcile can query with `pulls?head=<owner>:<branch>`. `None` on a
/// detached HEAD (git answers `HEAD`) or anything that is not a plain branch name;
/// reconcile then falls back to the full pull-list scan.
fn git_branch(work_tree: &str) -> Result<Option<String>> {
    let mut cmd = Command::new("git");
    cmd.arg("--no-optional-locks")
        .arg("-C")
        .arg(work_tree)
        .arg("rev-parse")
        .arg("--abbrev-ref")
        .arg("HEAD");
    identity::scrub_git_env(&mut cmd);
    let out = cmd
        .env("GIT_OPTIONAL_LOCKS", "0")
        .stdin(Stdio::null())
        .stderr(Stdio::piped())
        .output()
        .map_err(|_| "git unavailable".to_string())?;
    if !out.status.success() {
        // The HEAD read already classified any real git failure; a missing branch name
        // is not one — the claim still records, reconcile just loses the shortcut.
        return Ok(None);
    }
    let s = String::from_utf8(out.stdout)
        .map_err(|_| "non UTF-8 git output")?
        .trim()
        .to_string();
    let plain = !s.is_empty()
        && s != "HEAD"
        && s.len() <= 200
        && !s.chars().any(|c| c.is_control() || c.is_whitespace());
    if plain {
        Ok(Some(s))
    } else {
        Ok(None)
    }
}

pub(crate) fn worktree_id(identity: &Value) -> Result<WorktreeId> {
    let path = identity["work_tree"]
        .as_str()
        .ok_or("claim journal requires a git work tree")?;
    // Same evaluation order as the former literal, so the first failing source wins as before.
    let common_dir = identity["clone_anchor"]
        .as_str()
        .ok_or("claim journal requires a git repository")?;
    let git_dir = identity["workspace_git_dir"]
        .as_str()
        .ok_or("claim journal requires a git repository")?;
    let mut id = WorktreeId::new(common_dir, git_dir, path, git_head(path)?);
    id.branch = git_branch(path)?;
    Ok(id)
}

// ---- Comment claim (⑤) ----

/// One parsed `moai-claim:` line; `comment_id` is attached by the reader.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ClaimComment {
    pub comment_id: i64,
    pub session: String,
    pub epoch: u64,
    pub lease_until: String,
}

/// Parses the canonical claim line wherever it stands in a comment body.
pub fn parse_claim_line(body: &str) -> Option<ClaimComment> {
    for line in body.lines() {
        let Some(rest) = line.trim().strip_prefix("moai-claim:") else {
            continue;
        };
        let (mut session, mut epoch, mut lease) = (None, None, None);
        for tok in rest.split_whitespace() {
            if let Some(v) = tok.strip_prefix("session=") {
                session = Some(v.to_string());
            } else if let Some(v) = tok.strip_prefix("epoch=") {
                epoch = v.parse().ok();
            } else if let Some(v) = tok.strip_prefix("lease_until=") {
                lease = Some(v.to_string());
            }
        }
        if let (Some(session), Some(epoch), Some(lease_until)) = (session, epoch, lease) {
            return Some(ClaimComment {
                comment_id: 0,
                session,
                epoch,
                lease_until,
            });
        }
    }
    None
}

/// REQ-06A-13: among live claims the smallest comment id wins.
pub fn resolve_winner(live: &[ClaimComment]) -> Option<ClaimComment> {
    live.iter().min_by_key(|c| c.comment_id).cloned()
}

fn err_transport(message: impl Into<String>) -> ForgeError {
    ForgeError {
        kind: "transport",
        message: format!("gh transport: {}", message.into()),
        retryable: true,
    }
}

/// Fields of a claim comment line (#2255, REQ-A9-02). The first three are the RC1 line and
/// stay first, so every reader of the RC1 form keeps working; the rest are appended tokens.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ClaimFields {
    /// Session id of the claimant; `unverified` when the poster could not confirm it.
    pub session: String,
    pub epoch: u64,
    pub lease_until: String,
    /// Lane label (`agent-1`, ...), when known.
    pub lane: Option<String>,
    pub issue: Option<i64>,
    pub branch: Option<String>,
    /// UTC time the line was written (`YYYY-MM-DDTHH:MM:SSZ`).
    pub at: Option<String>,
    /// True when another session (the leader) posted the line on the claimant's behalf.
    pub relay: bool,
}

/// The one claim-line generator: acquire, queue-next and a relaying leader all render
/// through it, and `claim_verify::classify_comment` parses what it writes.
pub fn render_claim_line(f: &ClaimFields) -> String {
    let mut line = format!(
        "moai-claim: session={} epoch={} lease_until={}",
        f.session, f.epoch, f.lease_until
    );
    if let Some(lane) = &f.lane {
        line.push_str(&format!(" lane={lane}"));
    }
    if let Some(issue) = f.issue {
        line.push_str(&format!(" issue={issue}"));
    }
    if let Some(branch) = &f.branch {
        line.push_str(&format!(" branch={branch}"));
    }
    if let Some(at) = &f.at {
        line.push_str(&format!(" at={at}"));
    }
    // Absent means not relayed, so a line with no extra fields is the RC1 line byte for byte.
    if f.relay {
        line.push_str(" relay=true");
    }
    line
}

/// Reads every comment of the issue through the read path (GET only) and returns the
/// parsed claim comments of all pages.
fn read_claims<T: Transport, C: Clock>(
    client: &Client<'_, T, C>,
    t: &TaskRef,
) -> std::result::Result<Vec<ClaimComment>, ForgeError> {
    let mut url = Some(format!(
        "https://api.github.com/repos/{}/{}/issues/{}/comments?per_page=100",
        t.owner, t.repo, t.issue_number
    ));
    let mut claims = Vec::new();
    let mut pages = 0;
    while let Some(u) = url {
        pages += 1;
        if pages > CLAIM_MAX_PAGES {
            return Err(ForgeError {
                kind: "invalid_input",
                message: "claim comment page limit exceeded (50)".into(),
                retryable: false,
            });
        }
        let resp = client.get(&u, None)?;
        let arr = resp
            .body
            .as_ref()
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        for c in &arr {
            let (Some(id), Some(body)) = (c["id"].as_i64(), c["body"].as_str()) else {
                continue;
            };
            if let Some(mut line) = parse_claim_line(body) {
                line.comment_id = id;
                claims.push(line);
            }
        }
        url = resp.header("link").and_then(|l| next_link(Some(l)));
    }
    Ok(claims)
}

/// The one allowed GitHub write of a claim (REQ-06A-12): exactly one comment POST.
fn post_claim<T: Transport, C: Clock>(
    client: &Client<'_, T, C>,
    t: &TaskRef,
    line: &str,
) -> std::result::Result<i64, ForgeError> {
    let url = format!(
        "https://api.github.com/repos/{}/{}/issues/{}/comments",
        t.owner, t.repo, t.issue_number
    );
    let req = HttpRequest::new("POST", url).with_body(json!({"body": line}));
    let resp = client.send_with_backoff(&req)?;
    if !(200..300).contains(&resp.status) {
        return Err(if resp.status == 404 {
            ForgeError {
                kind: "not_found",
                message: "forge resource not found or not visible to this account (404)".into(),
                retryable: false,
            }
        } else {
            err_transport(format!("claim comment POST returned HTTP {}", resp.status))
        });
    }
    resp.body
        .as_ref()
        .and_then(|b| b["id"].as_i64())
        .ok_or_else(|| err_transport("claim comment response carried no id"))
}

// ---- Journal I/O ----

fn refuse_symlink(path: &Path) -> Result<()> {
    if fs::symlink_metadata(path)
        .map(|m| m.file_type().is_symlink())
        .unwrap_or(false)
    {
        return Err("journal path is a symlink; refused".into());
    }
    Ok(())
}

/// The journal handle. `lock: None` is the read-only view (`show`): it creates nothing.
#[derive(Debug)]
pub struct Journal {
    dir: PathBuf,
    lock: Option<fs::File>,
}

impl Journal {
    /// Read-only view; never creates a file or directory.
    pub fn open_read(root: &Path) -> Result<Journal> {
        refuse_symlink(root)?;
        Ok(Journal {
            dir: root.to_path_buf(),
            lock: None,
        })
    }

    /// Opens (creating directories and `.lock`) for a writing command; [`Journal::try_lock`]
    /// follows. Symlinked paths are refused (REQ-06A-07); a symlink swap between the check and
    /// the open is a documented residual risk of the advisory local model.
    pub fn open(root: &Path) -> Result<Journal> {
        refuse_symlink(root)?;
        if root.exists() && !root.is_dir() {
            return Err("journal path is not a directory".into());
        }
        fs::create_dir_all(root).map_err(|_| "journal directory unavailable".to_string())?;
        let lock_path = root.join(".lock");
        refuse_symlink(&lock_path)?;
        let lock = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(&lock_path)
            .map_err(|_| "journal lock unavailable".to_string())?;
        Ok(Journal {
            dir: root.to_path_buf(),
            lock: Some(lock),
        })
    }

    /// REQ-06A-05: never waits. `Ok(true)` holds the lock until the handle drops;
    /// `Ok(false)` is `busy` — the waiting policy is the caller's.
    pub fn try_lock(&self) -> Result<bool> {
        match self.lock.as_ref().map(|f| f.try_lock()) {
            Some(Ok(())) => Ok(true),
            Some(Err(std::fs::TryLockError::WouldBlock)) => Ok(false),
            Some(Err(std::fs::TryLockError::Error(_))) => Err("journal lock unavailable".into()),
            None => Err("journal was opened read-only; lock needs Journal::open".into()),
        }
    }

    /// Every complete line; a trailing partial line (no newline) is dropped — the
    /// "last complete line" rule of the design. A corrupt complete line is an error.
    pub fn read_events(&self) -> Result<Vec<JournalEvent>> {
        let path = self.dir.join("journal.log");
        refuse_symlink(&path)?;
        let bytes = match fs::read(&path) {
            Ok(b) => b,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
            Err(_) => return Err("claim journal read failed".into()),
        };
        let text = String::from_utf8(bytes).map_err(|_| "claim journal read failed".to_string())?;
        let segs: Vec<&str> = text.split('\n').collect();
        // The last element is "" after a final newline, or a partial line without one;
        // it is never a complete record, so it is dropped either way.
        let complete = &segs[..segs.len().saturating_sub(1)];
        let mut out = Vec::new();
        for (i, seg) in complete.iter().enumerate() {
            if seg.trim().is_empty() {
                continue;
            }
            match serde_json::from_str::<JournalEvent>(seg) {
                Ok(ev) => out.push(ev),
                Err(_) => return Err(format!("claim journal read failed at line {}", i + 1)),
            }
        }
        Ok(out)
    }

    /// Commits one journal event: the append (authority, fsync) lands first, then the
    /// record file (cache) is replaced atomically. The single write surface for every
    /// consumer that records effects, handoffs or transitions on a record (06-B and later;
    /// tests seed journals through it).
    pub fn commit(&self, event: &str, record: &ClaimRecord) -> Result<()> {
        append_event(&self.dir, event, record)?;
        write_record_file(&self.dir, record)
    }
}

fn append_event(dir: &Path, event: &str, record: &ClaimRecord) -> Result<()> {
    let path = dir.join("journal.log");
    refuse_symlink(&path)?;
    let mut f = OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
        .map_err(|_| "claim journal write failed".to_string())?;
    let ev = JournalEvent {
        event: event.to_string(),
        record: record.clone(),
    };
    let mut line = serde_json::to_string(&ev).map_err(|_| "encode failed".to_string())?;
    line.push('\n');
    f.write_all(line.as_bytes())
        .and_then(|_| f.sync_all())
        .map_err(|_| "claim journal write failed".to_string())
}

/// Temp file + fsync + rename (REQ-06A-04). Crash semantics: `journal.log` is appended and
/// fsynced FIRST, so the authority always carries the newer of the two writes.
fn write_record_file(dir: &Path, record: &ClaimRecord) -> Result<()> {
    let path = dir.join(format!("{}.json", record.task_key));
    refuse_symlink(&path)?;
    let tmp = dir.join(format!(
        "{}.json.tmp-{}",
        record.task_key,
        std::process::id()
    ));
    let bytes = serde_json::to_vec_pretty(record).map_err(|_| "encode failed".to_string())?;
    let mut f = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&tmp)
        .map_err(|_| "claim journal write failed".to_string())?;
    let write = f.write_all(&bytes).and_then(|_| f.sync_all());
    if write.is_err() {
        let _ = fs::remove_file(&tmp);
        return Err("claim journal write failed".into());
    }
    match fs::rename(&tmp, &path) {
        Ok(()) => Ok(()),
        Err(_) => {
            let _ = fs::remove_file(&tmp);
            Err("claim record replace failed".into())
        }
    }
}

// ---- Filesystem honesty (REQ-06A-07) ----

/// Best-effort filesystem type of the journal directory. macOS `stat -f %T` and coreutils
/// `stat -f -c %T` are both tried; when neither answers, the honest fallback says so.
fn fs_kind_note(dir: &Path) -> String {
    let arg_sets: [&[&str]; 2] = [&["-f", "%T"], &["-f", "-c", "%T"]];
    for args in arg_sets {
        let out = Command::new("stat")
            .args(args)
            .arg(dir)
            .env("LC_ALL", "C")
            .stdin(Stdio::null())
            .stderr(Stdio::piped())
            .output();
        if let Ok(out) = out {
            if out.status.success() {
                if let Ok(s) = String::from_utf8(out.stdout) {
                    return fs_note(&s.trim().to_ascii_lowercase());
                }
            }
        }
    }
    "journal filesystem type unknown; atomicity and locking are guaranteed only on local filesystems".into()
}

fn fs_note(kind: &str) -> String {
    let network = ["nfs", "cifs", "smb", "afp", "webdav", "9p", "fuse"]
        .iter()
        .any(|k| kind.contains(k));
    if network {
        format!("journal path is on network filesystem '{kind}'; atomicity and advisory locking are not guaranteed")
    } else {
        format!("journal filesystem '{kind}'; locking is advisory and local")
    }
}

// ---- Operations ----

#[derive(Debug)]
pub struct AcquireOutcome {
    pub outcome: &'static str,
    pub record: Option<ClaimRecord>,
    pub foreign_owner: Option<Value>,
    pub notes: Vec<String>,
}

fn scope_of(outcome: &str, record: Option<&ClaimRecord>) -> &'static str {
    // REQ-06A-11: a claim decided by a comment is cross-host (eventually); the journal-only
    // paths are single-host by construction.
    match outcome {
        "claimed" => "cross-host-eventual",
        "already_owned" => {
            if record.is_none() {
                // lost to another host's live comment
                "cross-host-eventual"
            } else {
                "single-host"
            }
        }
        // The winner is unresolved on the comment ledger, which is the cross-host layer.
        "uncertain" => "cross-host-eventual",
        _ => "single-host",
    }
}

impl AcquireOutcome {
    pub(crate) fn to_json(&self) -> Value {
        json!({
            "outcome": self.outcome,
            "record": self.record.as_ref().map(|r| json!(r)).unwrap_or(Value::Null),
            "foreign_owner": self.foreign_owner.clone().unwrap_or(Value::Null),
            "coordination_scope": scope_of(self.outcome, self.record.as_ref()),
            "cross_host_atomic": false,
            "notes": self.notes,
        })
    }
}

/// The acquire body; the caller holds the journal lock. Journal owner check first
/// (REQ-06A-03), then the comment claim (REQ-06A-12), then the journal append.
pub fn acquire<T: Transport, C: Clock>(
    journal: &Journal,
    req: &ClaimRequest,
    worktree: WorktreeId,
    client: &Client<'_, T, C>,
    clock: &C,
) -> Result<AcquireOutcome> {
    let now = clock.now();
    // #2166: an absent lease becomes now + DEFAULT_LEASE; an explicit one is kept as is.
    let filled;
    let req = if req.lease_until.is_empty() {
        filled = ClaimRequest {
            lease_until: format_utc(now + DEFAULT_LEASE),
            ..req.clone()
        };
        &filled
    } else {
        req
    };
    validate_request(req)?;
    let key = task_key(&req.task_ref);
    let events = journal.read_events()?;
    let mine: Vec<&ClaimRecord> = events
        .iter()
        .filter(|e| e.record.task_key == key)
        .map(|e| &e.record)
        .collect();
    if let Some(&existing) = mine.last() {
        if is_active(&existing.state) {
            // Never changed, never taken over (REQ-06A-03, REQ-06A-16).
            let expired = existing
                .lease_until
                .as_deref()
                .is_some_and(|l| !is_live(l, now));
            return Ok(if expired {
                AcquireOutcome {
                    outcome: "expired",
                    record: Some(existing.clone()),
                    foreign_owner: None,
                    notes: vec![
                        "the active record's lease has expired; takeover needs operator approval (06-B)".into(),
                    ],
                }
            } else {
                AcquireOutcome {
                    outcome: "already_owned",
                    record: Some(existing.clone()),
                    foreign_owner: None,
                    notes: vec![],
                }
            });
        }
    }
    let epoch = mine.iter().map(|r| r.epoch).max().unwrap_or(0) + 1;
    if let Some(want) = req.expected_epoch {
        if want != epoch {
            return Err(format!(
                "conflict in claim journal: stale epoch {want}; journal epoch would be {epoch}"
            ));
        }
    }
    // ⑤: read before posting; a live foreign claim wins by the smaller comment id.
    let claims = read_claims(client, &req.task_ref).map_err(String::from)?;
    let live: Vec<ClaimComment> = claims
        .into_iter()
        .filter(|c| is_live(&c.lease_until, now))
        .collect();
    let adopted;
    let comment_id = match resolve_winner(&live) {
        Some(winner) if winner.session != req.owner.id => {
            return Ok(AcquireOutcome {
                outcome: "already_owned",
                record: None,
                foreign_owner: Some(json!({
                    "session": winner.session, "epoch": winner.epoch,
                    "comment_id": winner.comment_id, "lease_until": winner.lease_until,
                })),
                notes: vec![
                    "a live claim comment with a smaller comment id is the winner; nothing was written".into(),
                ],
            });
        }
        // The winner carries our session value. A comment body proves nothing about who
        // posted it (every lane shares one forge account), so it is adopted only when this
        // journal recorded posting that very comment; otherwise a same-named live session
        // may own it (#2165 REQ-A6-01, REQ-AM-04).
        Some(winner) if !mine.iter().any(|r| r.comment_id == Some(winner.comment_id)) => {
            return Ok(AcquireOutcome {
                outcome: "uncertain",
                record: None,
                foreign_owner: Some(json!({
                    "session": winner.session, "epoch": winner.epoch,
                    "comment_id": winner.comment_id, "lease_until": winner.lease_until,
                })),
                notes: vec![format!(
                    "the winning live claim comment (id {}) carries this session value but this \
                     clone's journal has no record of posting it; it was not adopted — another \
                     live session may share the name (REQ-AM-04); nothing was written",
                    winner.comment_id
                )],
            });
        }
        Some(winner) => {
            adopted = true;
            winner.comment_id
        }
        None => {
            adopted = false;
            post_claim(
                client,
                &req.task_ref,
                // The acquire line stays the RC1 line byte for byte (#2255 AC-3): the issue is
                // the URL's, and the comment's own created_at is the server's time.
                &render_claim_line(&ClaimFields {
                    session: req.owner.id.clone(),
                    epoch,
                    lease_until: req.lease_until.clone(),
                    ..Default::default()
                }),
            )
            .map_err(String::from)?
        }
    };
    // The POST does not settle a cross-host race: another claimant can pass the same
    // pre-check and post between our GET and our POST (REQ-06A-13). The re-read decides —
    // the smallest live comment id wins. A loser keeps its posted comment (it is inert
    // under the rule, and deleting it is no authorized claim write) but records nothing.
    let comment_id = if adopted {
        comment_id
    } else {
        match read_claims(client, &req.task_ref) {
            Err(e) => {
                return Ok(AcquireOutcome {
                    outcome: "uncertain",
                    record: None,
                    foreign_owner: None,
                    notes: vec![format!(
                        "the comment was posted (id {comment_id}) but the re-read failed ({}); \
                             no journal record was written and the winner is unresolved — \
                             re-check with claim-show and the issue comments",
                        e.message
                    )],
                });
            }
            Ok(claims2) => {
                let live2: Vec<ClaimComment> = claims2
                    .into_iter()
                    .filter(|c| is_live(&c.lease_until, now))
                    .collect();
                // Our own POST returned an id, so the comment exists; if the re-read does
                // not show it, the list cannot be trusted to judge the winner.
                let Some(ours) = live2.iter().find(|c| c.comment_id == comment_id) else {
                    return Ok(AcquireOutcome {
                        outcome: "uncertain",
                        record: None,
                        foreign_owner: None,
                        notes: vec![format!(
                            "the comment was posted (id {comment_id}) but the re-read does not \
                             show it; without read-your-writes visibility the winner cannot be \
                             judged — no journal record was written, re-check with claim-show"
                        )],
                    });
                };
                match resolve_winner(&live2) {
                    Some(winner) if winner.comment_id != ours.comment_id => {
                        return Ok(AcquireOutcome {
                            outcome: "already_owned",
                            record: None,
                            foreign_owner: Some(json!({
                                "session": winner.session, "epoch": winner.epoch,
                                "comment_id": winner.comment_id, "lease_until": winner.lease_until,
                            })),
                            notes: vec![format!(
                                "a concurrent claimant posted the smaller live comment id {winner_id}; \
                                 our posted comment id {mine} remains on the issue and is inert under \
                                 the smallest-live-id rule; no journal record was written",
                                winner_id = winner.comment_id,
                                mine = comment_id,
                            )],
                        });
                    }
                    _ => comment_id,
                }
            }
        }
    };
    let token = claim_token(req.task_ref.issue_number, comment_id);
    let mut effects = req.projection_intents.clone();
    effects.push(json!({
        "kind": if adopted { "comment_adopted" } else { "comment_posted" },
        "comment_id": comment_id,
    }));
    let record = ClaimRecord {
        schema_version: SCHEMA_VERSION,
        task_ref: req.task_ref.clone(),
        task_key: key.clone(),
        logical_key: req.logical_key.clone(),
        owner: req.owner.clone(),
        assignee: req.assignee.clone(),
        provider_session: req.provider_session.clone(),
        // REQ-B2-01: the integration owner is the leader gate's identity — the acquire
        // path never sets it; the integration flow (leader) records it later.
        integration_owner: None,
        attempt: req.attempt,
        epoch,
        base_revision: req.base_revision.clone(),
        worktree,
        write_scope: req.write_scope.clone(),
        spec_ref: req.spec_ref.clone(),
        comment_id: Some(comment_id),
        claim_token: Some(token),
        lease_until: Some(req.lease_until.clone()),
        state: "assigned".into(),
        effects,
        last_observed_at: format_utc(now),
    };
    // The append (authority) lands before the record file (cache).
    append_event(&journal.dir, "acquire", &record)?;
    write_record_file(&journal.dir, &record)?;
    let mut notes = vec![
        "the journal lock is advisory: processes that bypass moai-cli are not serialized".into(),
        fs_kind_note(&journal.dir),
    ];
    if adopted {
        notes.push(
            "a live claim comment of this session already existed and was adopted; no comment was posted".into(),
        );
    }
    Ok(AcquireOutcome {
        outcome: "claimed",
        record: Some(record),
        foreign_owner: None,
        notes,
    })
}

/// `claim-release`: closes the active record as `cancelled` (REQ-06A-16 takeover stays with
/// the operator). A stale epoch is a conflict (AC-06A-2).
pub fn release<C: Clock>(
    journal: &Journal,
    key: &str,
    epoch: u64,
    reason: &str,
    clock: &C,
) -> Result<AcquireOutcome> {
    if !is_key(key) {
        return Err("task must be a 16 hex character claim key".into());
    }
    let events = journal.read_events()?;
    let existing = events
        .iter()
        .rfind(|e| e.record.task_key == key)
        .map(|e| e.record.clone());
    let Some(rec) = existing else {
        return Ok(AcquireOutcome {
            outcome: "unclaimed",
            record: None,
            foreign_owner: None,
            notes: vec!["no record exists for this task key".into()],
        });
    };
    if !is_active(&rec.state) {
        return Ok(AcquireOutcome {
            outcome: "unclaimed",
            record: Some(rec),
            foreign_owner: None,
            notes: vec!["the record is not in an active state".into()],
        });
    }
    if rec.epoch != epoch {
        return Err(format!(
            "conflict in claim journal: stale epoch {epoch}; current record epoch is {}",
            rec.epoch
        ));
    }
    let now = clock.now();
    let mut new = rec.clone();
    new.state = "cancelled".into();
    new.last_observed_at = format_utc(now);
    new.effects
        .push(json!({"kind": "release", "reason": reason}));
    append_event(&journal.dir, "release", &new)?;
    write_record_file(&journal.dir, &new)?;
    Ok(AcquireOutcome {
        outcome: "released",
        record: Some(new),
        foreign_owner: None,
        notes: vec![],
    })
}

/// `show` plus `expired` against `now` (#2166): true only for an active record whose lease
/// has passed. Display only — ownership never moves on expiry (REQ-A7-02). Byte-identical
/// when repeated at the same `now`; no lock, no write.
pub fn show_at(root: &Path, key: &str, now: i64) -> Result<Value> {
    let mut v = show(root, key)?;
    let expired = v["record"]["state"].as_str().is_some_and(is_active)
        && v["record"]["lease_until"]
            .as_str()
            .is_some_and(|l| !is_live(l, now));
    v["expired"] = json!(expired);
    Ok(v)
}

/// `claim-show`: byte-identical when repeated (REQ-06A-10) — no lock, no write, no clock.
pub fn show(root: &Path, key: &str) -> Result<Value> {
    if !is_key(key) {
        return Err("task must be a 16 hex character claim key".into());
    }
    let journal = Journal::open_read(root)?;
    let events = journal.read_events()?;
    let record = events
        .iter()
        .rfind(|e| e.record.task_key == key)
        .map(|e| e.record.clone());
    let outcome = if record.is_some() {
        "held"
    } else {
        "unclaimed"
    };
    let scope = match &record {
        Some(r) if r.comment_id.is_some() => "cross-host-eventual",
        _ => "single-host",
    };
    Ok(json!({
        "outcome": outcome,
        "record": record.map(|r| json!(r)).unwrap_or(Value::Null),
        "coordination_scope": scope,
        "cross_host_atomic": false,
    }))
}

// ---- Leader-side token verification (REQ-06A-15) ----

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CommitCarrier {
    pub sha: String,
    /// The `Moai-Claim:` trailer text exactly as the commit carries it.
    pub moai_claim_trailer: Option<String>,
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct TokenCarriers {
    /// The PR head branch name; `None` fails the verdict (it is always knowable to the leader).
    pub branch: Option<String>,
    pub commits: Vec<CommitCarrier>,
    pub pr_body: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TokenVerdict {
    pub pass: bool,
    pub reasons: Vec<String>,
}

/// Checks that branch name, every commit trailer and the PR body carry exactly the winner's
/// token (REQ-06A-14/15, AC-06A-9/12). Any absent or different token is a reason; a different
/// token is a fencing violation, not a near-miss.
pub fn verify_claim_token(
    issue_number: i64,
    comment_id: i64,
    carriers: &TokenCarriers,
) -> TokenVerdict {
    let token = claim_token(issue_number, comment_id);
    let suffix = claim_branch_suffix(issue_number, comment_id);
    let mut reasons = Vec::new();
    match &carriers.branch {
        Some(b) if b.contains(&suffix) => {}
        Some(_) => reasons.push(format!(
            "branch name does not carry the claim token suffix {suffix}"
        )),
        None => reasons.push("branch name missing from carriers".into()),
    }
    if carriers.commits.is_empty() {
        reasons.push("no commits supplied".into());
    }
    for c in &carriers.commits {
        match &c.moai_claim_trailer {
            Some(t) if t == &token => {}
            Some(t) => reasons.push(format!(
                "commit {} carries a different claim token ({t})",
                c.sha
            )),
            None => reasons.push(format!("commit {} carries no Moai-Claim trailer", c.sha)),
        }
    }
    if !carriers.pr_body.contains(&token) {
        reasons.push("PR body does not carry the claim token".into());
    }
    TokenVerdict {
        pass: reasons.is_empty(),
        reasons,
    }
}

// ---- CLI entries (`main` wraps the results in the 01-C envelope) ----

/// CLI acquire: identity + worktree, journal open + try_lock (busy never waits), then
/// [`acquire`]. The transport and clock come from the caller like `forge_read_cli`.
pub fn acquire_cli<T: Transport, C: Clock>(
    project: &Path,
    req: ClaimRequest,
    transport: &T,
    clock: &C,
) -> Result<Value> {
    let root = journal_root(project)?;
    let id = identity::identity(project)?;
    let worktree = worktree_id(&id)?;
    let journal = Journal::open(&root)?;
    if !journal.try_lock()? {
        return Ok(json!({
            "outcome": "busy",
            "record": Value::Null,
            "foreign_owner": Value::Null,
            "coordination_scope": "single-host",
            "cross_host_atomic": false,
            "notes": ["another process holds the journal lock; retry policy is the caller's (REQ-06A-05)"],
        }));
    }
    let client = Client::new(transport, clock, Default::default(), Default::default());
    let out = acquire(&journal, &req, worktree, &client, clock)?;
    Ok(out.to_json())
}

pub fn show_cli(project: &Path, key: &str) -> Result<Value> {
    let root = journal_root(project)?;
    show_at(&root, key, crate::forge::policy::SystemClock.now())
}

pub fn release_cli<C: Clock>(
    project: &Path,
    key: &str,
    epoch: u64,
    reason: &str,
    clock: &C,
) -> Result<Value> {
    let root = journal_root(project)?;
    let journal = Journal::open(&root)?;
    if !journal.try_lock()? {
        return Ok(json!({
            "outcome": "busy",
            "record": Value::Null,
            "foreign_owner": Value::Null,
            "coordination_scope": "single-host",
            "cross_host_atomic": false,
            "notes": ["another process holds the journal lock; retry policy is the caller's (REQ-06A-05)"],
        }));
    }
    let out = release(&journal, key, epoch, reason, clock)?;
    Ok(out.to_json())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::contract;

    fn task_ref() -> TaskRef {
        TaskRef::new("github", "github.com", "acme", "widgets", 101, 7001, 7)
    }

    #[test]
    fn task_key_is_stable_and_id_distinct() {
        let a = task_ref();
        // Display names are not key material: a renamed owner keeps the key.
        let mut renamed = task_ref();
        renamed.owner = "other".to_string();
        assert_eq!(task_key(&a), task_key(&renamed));
        let mut other_repo = task_ref();
        other_repo.repository_id = 202;
        assert_ne!(task_key(&a), task_key(&other_repo));
        let key = task_key(&a);
        assert_eq!(key.len(), 16);
        assert!(key
            .bytes()
            .all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
    }

    #[test]
    fn token_shapes_are_canonical() {
        assert_eq!(claim_token(2005, 6720575543), "Moai-Claim: 2005#6720575543");
        assert_eq!(claim_branch_suffix(2005, 6720575543), "c2005-6720575543");
    }

    #[test]
    fn claim_line_parses_from_prose() {
        let body = "leader relay post\n\nmoai-claim: session=agent-6-742cb6 epoch=1 lease_until=2026-11-08T13:47:52Z";
        let c = parse_claim_line(body).unwrap();
        assert_eq!(c.session, "agent-6-742cb6");
        assert_eq!(c.epoch, 1);
        assert_eq!(c.lease_until, "2026-11-08T13:47:52Z");
        assert!(parse_claim_line("no claim here").is_none());
        assert!(parse_claim_line("moai-claim: session=x epoch=oops lease_until=y").is_none());
    }

    #[test]
    fn winner_is_the_smallest_live_comment_id() {
        let c = |id: i64, session: &str, lease: &str| ClaimComment {
            comment_id: id,
            session: session.into(),
            epoch: 1,
            lease_until: lease.into(),
        };
        let now = 1000;
        let live: Vec<ClaimComment> = [
            c(200, "b", "1970-01-01T00:16:40Z"),
            c(100, "a", "1970-01-01T00:30:00Z"),
        ]
        .into_iter()
        .filter(|x| is_live(&x.lease_until, now))
        .collect();
        assert_eq!(resolve_winner(&live).unwrap().comment_id, 100);
        // An expired comment (lease 1970-01-01T00:16:39Z) is not live.
        assert!(!is_live("1970-01-01T00:16:39Z", now));
        assert_eq!(resolve_winner(&[]), None);
    }

    fn carriers(branch: Option<&str>, trailers: &[Option<&str>], pr_body: &str) -> TokenCarriers {
        TokenCarriers {
            branch: branch.map(str::to_string),
            commits: trailers
                .iter()
                .enumerate()
                .map(|(i, t)| CommitCarrier {
                    sha: format!("{i:040}"),
                    moai_claim_trailer: t.map(str::to_string),
                })
                .collect(),
            pr_body: pr_body.into(),
        }
    }

    #[test]
    fn token_verification_passes_only_when_all_three_carry_it() {
        let token = claim_token(2005, 42);
        let good = carriers(
            Some("issue/2005-06-A-c2005-42"),
            &[Some(&token), Some(&token)],
            &format!("Refs #2005\n{token}"),
        );
        assert!(verify_claim_token(2005, 42, &good).pass);

        let v = verify_claim_token(2005, 42, &carriers(None, &[Some(&token)], &token));
        assert!(!v.pass);
        assert!(v.reasons[0].contains("branch name missing"));

        let v = verify_claim_token(
            2005,
            42,
            &carriers(Some("plain-branch"), &[Some(&token)], &token),
        );
        assert!(!v.pass && v.reasons[0].contains("suffix"));

        let v = verify_claim_token(
            2005,
            42,
            &carriers(Some("issue/2005-06-A-c2005-42"), &[None], &token),
        );
        assert!(!v.pass && v.reasons[0].contains("no Moai-Claim trailer"));

        let v = verify_claim_token(
            2005,
            42,
            &carriers(
                Some("issue/2005-06-A-c2005-42"),
                &[Some("Moai-Claim: 2005#7")],
                &token,
            ),
        );
        assert!(!v.pass && v.reasons[0].contains("different claim token"));

        let v = verify_claim_token(
            2005,
            42,
            &carriers(
                Some("issue/2005-06-A-c2005-42"),
                &[Some(&token)],
                "no token here",
            ),
        );
        assert!(!v.pass && v.reasons[0].contains("PR body"));
    }

    #[test]
    fn fs_note_warns_only_on_network_filesystems() {
        let local = fs_note("apfs");
        assert!(local.contains("advisory") && !local.contains("not guaranteed"));
        let nfs = fs_note("nfs");
        assert!(nfs.contains("not guaranteed") && nfs.contains("nfs"));
