//! Flow control (A13 #2279): WIP caps, the integration-gate verdict, and the read
//! side of flow metrics. Everything here is GET-only — status posting, merging and
//! ruleset changes stay with the leader flow (decision 06:02, 2026-11-09).
//!
//! GitHub is read through the injected forge transport; tests replay recorded JSON.
//! gh call count is minimised: the open-PR list, the PR, the commit list and the two
//! compare calls are the only reads a verdict performs.
use crate::forge::transport::Transport;
use crate::forge::Client;
use serde_json::{json, Value};

type Result<T> = std::result::Result<T, String>;

pub const SCHEMA_VERSION: u32 = 1;
/// The config key names (the numbers themselves are user-specified defaults, not
/// measured baselines — the issue requires them marked as such).
pub const CAP_LANE: &str = "lane_open_pr_cap";
pub const CAP_TOTAL: &str = "total_open_pr_cap";
/// Defaults are the user-approved values (2026-11-09 06:02Z decision: 1 audit-
/// pending PR per lane, 8 total open) — not measured baselines.
pub const DEFAULT_LANE_CAP: u64 = 1;
pub const DEFAULT_TOTAL_CAP: u64 = 8;

fn api(owner: &str, repo: &str, tail: &str) -> String {
    format!("https://api.github.com/repos/{owner}/{repo}/{tail}")
}

/// One open pull request as the WIP check sees it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct OpenPr {
    pub number: i64,
    pub head_ref: String,
    pub author: String,
    pub draft: bool,
}

/// One commit of a PR as the gate verdict sees it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PrCommit {
    pub sha: String,
    pub parents: usize,
    pub message: String,
}

/// Marker forms that count as a claim line (06:02: lane-authored commits and the PR
/// body must carry `Moai-Claim: <issue>#<comment-id>`).
fn has_claim_line(text: &str) -> bool {
    text.contains("Moai-Claim: ")
}

fn fetch_open_pulls<T: Transport, C: crate::forge::policy::Clock>(
    client: &Client<'_, T, C>,
    owner: &str,
    repo: &str,
) -> Result<Vec<OpenPr>> {
    let mut out = Vec::new();
    let mut url = Some(api(owner, repo, "pulls?state=open&per_page=100"));
    let mut pages = 0;
    while let Some(u) = url {
        pages += 1;
        if pages > 10 {
            return Err("flow open pull list page limit exceeded (10)".to_string());
        }
        let resp = client.get(&u, None)?;
        let arr = resp
            .body
            .as_ref()
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        for p in &arr {
            out.push(OpenPr {
                number: p["number"].as_i64().unwrap_or(0),
                head_ref: p["head"]["ref"].as_str().unwrap_or_default().into(),
                author: p["user"]["login"].as_str().unwrap_or_default().into(),
                draft: p["draft"].as_bool().unwrap_or(false),
            });
        }
        url = resp
            .header("link")
            .and_then(|l| crate::forge::policy::next_link(Some(l)));
    }
    Ok(out)
}

fn fetch_pr<T: Transport, C: crate::forge::policy::Clock>(
    client: &Client<'_, T, C>,
    owner: &str,
    repo: &str,
    number: i64,
) -> Result<Value> {
    let resp = client.get(&api(owner, repo, &format!("pulls/{number}")), None)?;
    resp.body
        .clone()
        .ok_or_else(|| "pr response carried no body".to_string())
}

fn fetch_base_tip<T: Transport, C: crate::forge::policy::Clock>(
    client: &Client<'_, T, C>,
    owner: &str,
    repo: &str,
    base_ref: &str,
) -> Result<String> {
    let resp = client.get(&api(owner, repo, &format!("commits/{base_ref}")), None)?;
    resp.body
        .as_ref()
        .and_then(|b| b["sha"].as_str().map(str::to_string))
        .ok_or_else(|| "base branch response carried no sha".to_string())
}

/// ahead_by: how many commits `head` is ahead of `base` (0 when base is not an
/// ancestor — the compare endpoint reports diverged with both counts).
fn fetch_compare<T: Transport, C: crate::forge::policy::Clock>(
    client: &Client<'_, T, C>,
    owner: &str,
    repo: &str,
    base: &str,
    head: &str,
) -> Result<(u64, u64, Vec<String>)> {
    let resp = client.get(&api(owner, repo, &format!("compare/{base}...{head}")), None)?;
    let body = resp.body.clone().unwrap_or(Value::Null);
    let ahead = body["ahead_by"].as_u64().unwrap_or(u64::MAX);
    let behind = body["behind_by"].as_u64().unwrap_or(u64::MAX);
    let files: Vec<String> = body["files"]
        .as_array()
        .cloned()
        .unwrap_or_default()
        .iter()
        .filter_map(|f| f["filename"].as_str().map(str::to_string))
        .collect();
    Ok((ahead, behind, files))
}

fn fetch_pr_commits<T: Transport, C: crate::forge::policy::Clock>(
    client: &Client<'_, T, C>,
    owner: &str,
    repo: &str,
    number: i64,
) -> Result<Vec<PrCommit>> {
    let mut out = Vec::new();
    let mut url = Some(api(
        owner,
        repo,
        &format!("pulls/{number}/commits?per_page=100"),
    ));
    let mut pages = 0;
    while let Some(u) = url {
        pages += 1;
        if pages > 10 {
            return Err("flow pr commit page limit exceeded (10)".to_string());
        }
        let resp = client.get(&u, None)?;
        let arr = resp
            .body
            .as_ref()
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        for c in &arr {
            out.push(PrCommit {
                sha: c["sha"].as_str().unwrap_or_default().to_string(),
                parents: c["parents"].as_array().map(|a| a.len()).unwrap_or(0),
                message: c["commit"]["message"]
                    .as_str()
                    .unwrap_or_default()
                    .to_string(),
            });
        }
        url = resp
            .header("link")
            .and_then(|l| crate::forge::policy::next_link(Some(l)));
    }
    Ok(out)
}

fn fetch_commit_status<T: Transport, C: crate::forge::policy::Clock>(
    client: &Client<'_, T, C>,
    owner: &str,
    repo: &str,
    sha: &str,
) -> Result<String> {
    let resp = client.get(&api(owner, repo, &format!("commits/{sha}/status")), None)?;
    resp.body
        .as_ref()
        .and_then(|b| b["state"].as_str().map(str::to_string))
        .ok_or_else(|| "commit status response carried no state".to_string())
}

// ---- WIP cap (assignment-refusal signal; the refusal itself is the leader's act) ----

fn count_by_author(prs: &[OpenPr], author: &str) -> u64 {
    prs.iter().filter(|p| p.author == author).count() as u64
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct WipVerdict {
    pub lane: String,
    pub lane_open: u64,
    pub total_open: u64,
    pub lane_cap: u64,
    pub total_cap: u64,
    pub exceeded: bool,
}

/// WIP cap check (read-only): one open-PR list call, then the lane count and the
/// total are compared with the caps. `exceeded` is the assignment-refusal signal.
pub fn wip_check<T: Transport, C: crate::forge::policy::Clock>(
    client: &Client<'_, T, C>,
    owner: &str,
    repo: &str,
    lane: &str,
    lane_cap: u64,
    total_cap: u64,
) -> Result<WipVerdict> {
    let prs = fetch_open_pulls(client, owner, repo)?;
    let lane_open = count_by_author(&prs, lane);
    let total_open = prs.len() as u64;
    Ok(WipVerdict {
        lane: lane.to_string(),
        lane_open,
        total_open,
        lane_cap,
        total_cap,
        exceeded: lane_open >= lane_cap || total_open >= total_cap,
    })
}

pub fn wip_check_json<T: Transport, C: crate::forge::policy::Clock>(
    client: &Client<'_, T, C>,
    owner: &str,
    repo: &str,
    lane: &str,
    lane_cap: u64,
    total_cap: u64,
) -> Result<Value> {
    let v = wip_check(client, owner, repo, lane, lane_cap, total_cap)?;
    Ok(json!({
        "schema_version": SCHEMA_VERSION,
        "lane": v.lane,
        "lane_open": v.lane_open,
        "total_open": v.total_open,
        "lane_cap": v.lane_cap,
        "total_cap": v.total_cap,
        "exceeded": v.exceeded,
        "verdict": if v.exceeded { "refuse_assignment" } else { "allow" },
        "writes": false,
    }))
}

// ---- integration gate verdict (06:02 rules, read-only) ----

/// One gate check with its outcome.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GateCheck {
    pub check: &'static str,
    pub pass: bool,
    pub detail: String,
}

/// The integration gate verdict (verdict only — status posting and merging stay on
/// the leader path). Checks:
/// tip containment (behind = update-branch needed), files changed since the audited
/// head (advisory count), claim lines on lane-authored non-merge commits, the PR
/// body claim line, the CI commit status, and a head re-read.
pub fn gate_verdict<T: Transport, C: crate::forge::policy::Clock>(
    client: &Client<'_, T, C>,
    owner: &str,
    repo: &str,
    number: i64,
    audit_head: &str,
    base_ref: &str,
) -> Result<Value> {
    let pr = fetch_pr(client, owner, repo, number)?;
    let head = pr["head"]["sha"]
        .as_str()
        .ok_or_else(|| "pr response carried no head sha".to_string())?
        .to_string();
    let body = pr["body"].as_str().unwrap_or_default().to_string();

    let tip = fetch_base_tip(client, owner, repo, base_ref)?;
    let (ahead_by, _behind, _files) = fetch_compare(client, owner, repo, &tip, &head)?;
    let tip_contained = ahead_by > 0 || tip == head;
    let checks0 = GateCheck {
        check: "tip_contained",
        pass: tip_contained,
        detail: format!("tip {tip} ahead_by {ahead_by}"),
    };

    let changed_since_audit = head != audit_head;
    let (audit_ahead, _b2, changed_files) = if changed_since_audit {
        fetch_compare(client, owner, repo, audit_head, &head)?
    } else {
        (0u64, 0u64, Vec::new())
    };
    let checks1 = GateCheck {
        check: "changed_since_audit",
        pass: !changed_since_audit || changed_files.is_empty(),
        detail: format!(
            "audit {audit_head} vs head: {} file(s) differ",
            changed_files.len()
        ),
    };
    let _ = audit_ahead;

    // Claim lines: lane-authored (non-merge) commits must each carry one; merge
    // commits are records and are exempt (06:02).
    let commits = fetch_pr_commits(client, owner, repo, number)?;
    let no_claim: Vec<String> = commits
        .iter()
        .filter(|c| c.parents <= 1 && !has_claim_line(&c.message))
        .map(|c| c.sha.clone())
        .collect();
    let checks2 = GateCheck {
        check: "commit_claim_lines",
        pass: no_claim.is_empty(),
        detail: format!(
            "{} lane commit(s) checked; missing claim: {}",
            commits.len(),
            if no_claim.is_empty() {
                "none".into()
            } else {
                no_claim.join(", ")
            }
        ),
    };

    let body_claim = has_claim_line(&body);
    let checks3 = GateCheck {
        check: "pr_body_claim",
        pass: body_claim,
        detail: if body_claim {
            "claim line present".into()
        } else {
            "PR body carries no Moai-Claim line".into()
        },
    };

    let (ci_state, ci_ok) = fetch_commit_status(client, owner, repo, &head)
        .map(|s| {
            let ok = s == "success";
            (s.clone(), ok)
        })
        .unwrap_or_else(|_e| ("unknown".into(), false));
    let _ = ci_ok;
    let checks4 = GateCheck {
        check: "ci_status",
        pass: ci_state == "success",
        detail: format!("commit status: {ci_state}"),
    };

    let pr_again = fetch_pr(client, owner, repo, number)?;
    let head_stable = pr_again["head"]["sha"].as_str() == Some(head.as_str());
    let checks5 = GateCheck {
        check: "head_recheck",
        pass: head_stable,
        detail: format!("head {head} re-read"),
    };

    let all = [checks0, checks1, checks2, checks3, checks4, checks5];
    let pass = all.iter().all(|c| c.pass);
    let verdict = if pass { "ok" } else { "blocked" };
    let reasons: Vec<String> = all
        .iter()
        .filter(|c| !c.pass)
        .map(|c| format!("{}: {}", c.check, c.detail))
        .collect();
    Ok(json!({
        "schema_version": SCHEMA_VERSION,
        "pr": number,
        "head": head,
        "audit_head": audit_head,
        "tip": tip,
        "changed_since_audit": changed_since_audit,
        "changed_files": changed_files,
        "checks": all.iter().map(|c| json!({
            "check": c.check, "pass": c.pass, "detail": c.detail,
        })).collect::<Vec<_>>(),
        "verdict": verdict,
        "reasons": reasons,
        "writes": false,
    }))
}

src/forge/audit_status.rs.content:
//! The `moai/audit` commit status, posted by an audit-only GitHub App when its token is set
//! (#2173, B6; decisions 01:1x(11-09) "Forge permissions and fallback").
//!
//! `forge-audit-status` posts one status on an exact head SHA and reads it back once:
//!
//! - The context is the constant `moai/audit`, the context the integration ruleset requires.
//!   It is never caller-settable; another context would be a different check.
//! - WHEN `MOAI_AUDIT_APP_TOKEN` is set, its value is handed to gh as `GH_TOKEN` in the child's
//!   environment only, and the description carries `source=app`. Otherwise gh's own (shared
//!   account) authentication posts it, the description carries `source=shared-account`, and a
//!   warning says the source is not pinned (REQ-B6-01). Only the variable name is ever output.
//! - Pinning the source is a ruleset setting (the required check's expected source app) and
//!   App registration, installation and token minting are operator steps (keep-set); none of
//!   them is done here.
//!
//! The POST is a write: it needs a permission reference, like `forge-report`. A status is
//! idempotent per (sha, context), so no outbox marker is kept; the read-back GET reports what
//! GitHub shows, or `uncertain`.
use super::policy::Clock;
use super::transport::{GhTransport, HttpRequest, Transport};
use super::{Client, Config, ForgeError, API, SCHEMA_VERSION};
use serde::Deserialize;
use serde_json::{json, Value};
use std::collections::BTreeMap;
use std::path::Path;

pub const CONTEXT: &str = "moai/audit";
/// The only place the App token is read from. Its value is never logged or stored.
pub const APP_TOKEN_VAR: &str = "MOAI_AUDIT_APP_TOKEN";
/// GitHub truncates longer status descriptions.
const DESCRIPTION_MAX: usize = 140;
const STATES: [&str; 4] = ["success", "failure", "error", "pending"];

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AuditStatusRequest {
    pub schema_version: u32,
    pub owner: String,
    pub repo: String,
    pub sha: String,
    pub state: String,
    /// The verdict comment (`https://github.com/...`).
    pub target_url: String,
    #[serde(default)]
    pub description: String,
}

fn valid_name(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 100
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"-_.".contains(&b))
        && s != "."
        && s != ".."
}

fn validate(req: &AuditStatusRequest, permission: &str) -> Result<(), ForgeError> {
    if ["", "null", "placeholder"].contains(&permission.trim())
        || permission.len() > 128
        || permission.chars().any(char::is_control)
    {
        return Err(ForgeError::of(
            "permission_reference_missing",
            "permission reference required",
        ));
    }
    if req.schema_version != SCHEMA_VERSION {
        return Err(ForgeError::of(
            "unsupported_protocol_version",
            "unsupported request schema_version",
        ));
    }
    if !valid_name(&req.owner) || !valid_name(&req.repo) {
        return Err(ForgeError::invalid("owner and repo must be GitHub names"));
    }
    let hex = req.sha.len() == 40
        && req
            .sha
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b));
    if !hex {
        return Err(ForgeError::invalid("sha must be a 40 lowercase hex commit"));
    }
    if !STATES.contains(&req.state.as_str()) {
        return Err(ForgeError::invalid(
            "state must be success, failure, error or pending",
        ));
    }
    if !req.target_url.starts_with("https://github.com/")
        || req.target_url.len() > 512
        || req.target_url.chars().any(|c| c.is_control() || c == ' ')
    {
        return Err(ForgeError::invalid(
            "target_url must be an https://github.com/ link",
        ));
    }
    if req.description.chars().any(char::is_control) {
        return Err(ForgeError::invalid(
            "description must be one line without control characters",
        ));
    }
    Ok(())
}

/// The description sent: the caller's text plus the source marker, within GitHub's limit.
fn description(text: &str, source: &str) -> Result<String, ForgeError> {
    let marker = format!("source={source}");
    let full = if text.is_empty() {
        marker
    } else {
        format!("{text} · {marker}")
    };
    if full.chars().count() > DESCRIPTION_MAX {
        return Err(ForgeError::invalid(format!(
            "description must be at most {DESCRIPTION_MAX} characters with the source marker"
        )));
    }
    Ok(full)
}

/// Posts and reads back. `app` says whether the transport carries the App token.
pub fn post<T: Transport, C: Clock>(
    req: &AuditStatusRequest,
    permission: &str,
    app: bool,
    transport: &T,
    clock: &C,
) -> Result<Value, ForgeError> {
    validate(req, permission)?;
    let (source, token_source) = if app {
        ("app", "app")
    } else {
        ("shared-account", "shared_account")
    };
    let desc = description(&req.description, source)?;
    let client = Client::new(transport, clock, Config::default(), BTreeMap::new());
    let (o, r, sha) = (&req.owner, &req.repo, &req.sha);
    let post =
        HttpRequest::new("POST", format!("{API}/repos/{o}/{r}/statuses/{sha}")).with_body(json!({
            "state": req.state, "target_url": req.target_url,
            "description": desc, "context": CONTEXT,
        }));
    let resp = client.send_with_backoff(&post)?;
    if resp.status != 201 {
        return Err(ForgeError::transport(format!(
            "status POST returned HTTP {}",
            resp.status
        )));
    }
    // Read back: the newest `moai/audit` entry on that sha, or uncertain.
    let observed = match client.get(
        &format!("{API}/repos/{o}/{r}/commits/{sha}/statuses?per_page=100"),
        None,
    ) {
        Ok(back) => back
            .body
            .as_ref()
            .and_then(Value::as_array)
            .and_then(|a| a.iter().find(|s| s["context"] == CONTEXT))
            .map(|s| json!({"state": s["state"], "description": s["description"]}))
            .unwrap_or_else(|| json!("uncertain")),
        Err(_) => json!("uncertain"),
    };
    let mut warnings = Vec::new();
    if !app {
        warnings.push(format!(
            "status source is not pinned: posted by the shared account ({APP_TOKEN_VAR} not set)"
        ));
    }
    Ok(json!({
        "schema_version": SCHEMA_VERSION,
        "sha": sha,
        "context": CONTEXT,
        "state": req.state,
        "description": desc,
        "token_source": token_source,
        "token_variable": APP_TOKEN_VAR,
        "observed": observed,
        "warnings": warnings,
        "notes": [
            "pinning the source is the ruleset's expected-source app for the required check; operator keep-set, not done here"
        ],
    }))
}

/// CLI entry (`forge.audit_status`): reads the App token from the environment by name.
pub fn audit_status_cli<C: Clock>(
    project: &Path,
    req: AuditStatusRequest,
    permission: &str,
    mut transport: GhTransport,
    clock: &C,
) -> Result<Value, String> {
    if !project.is_dir() {
        return Err(ForgeError::invalid("project must be a directory").into());
    }
    let token = std::env::var(APP_TOKEN_VAR)
        .ok()
        .filter(|t| !t.trim().is_empty());
    let app = token.is_some();
    transport.gh_token = token;
    Ok(post(&req, permission, app, &transport, clock)?)
}

