//! Project-specific file generation: plan read-only, apply with the merged 3-way
//! decision and receipts (Issue #1997, 03-C).
//!
//! The AGENTS.md managed section, the personal file opt-in and the `.gitignore`
//! section are the existing agents machinery: `generation` derives an
//! `AgentsRequest`, calls the public `agents_plan` for its read-only judgment and
//! the `agents_apply` engine for its publication (receipts, baseline recovery, manifest
//! write included) through the crate-internal `agents_apply_amended` hook, so the
//! generation state joins the one manifest publish (#2114). `src/agents.rs` is 01-B
//! #1989's; its public API and behavior are unchanged; the
//! generation-specific files — portable project workflows under
//! `.moai-cli/workflows/<id>/`, native role files `.claude/agents/<role>.md` and
//! `.codex/agents/<role>.toml`, and skill projections `.claude/skills/<id>/SKILL.md`
//! (`.agents/skills/…`) — are planned and published in this module through the public
//! 01-B apply engine (`decide`, `publish_exclusive`/`publish_replace`,
//! `save_before_bytes`, `Receipt`). Baselines of generation files live in the same
//! `generation.json` `owned_files` list, recorded with an additive `kind` field
//! (`workflow`, `native-role`, `skill-projection`; #2109) plus a `section_id` tag of
//! the shape `generation:<kind>:…` kept so manifests written before the kind field
//! stay readable (agents.rs's `OwnedFile` rejects unknown fields, and its own writes
//! leave `kind` unset).
//!
//! The delegation is stale-safe: `generation_apply` first re-plans the whole
//! generation request and refuses any drift, then re-plans the agents portion and
//! hands `agents_apply` its own freshly computed digest — a plan that passed the
//! outer check passes the inner one unchanged.
//!
//! Boundaries: `.claude/settings.json` and `.codex/config.toml` merges stay out
//! (HOLD-2 A, owner 02-B #1992) — Codex role files carry only `name`, `description`
//! and `developer_instructions`, never the keys that widen parent permissions.
//! Markdown merging stays at managed-section granularity (HOLD-1 A; the diff3 study
//! shows line-level merging has no general non-conflict guarantee). The subcommand
//! names are `generation-plan`/`generation-apply` (HOLD-3 A). External skill content
//! is never copied: a projection references a `reviewed` source with an attribution
//! line, and a source whose license is not reviewed blocks every file that cites it
//! (REQ-03C-08).

use crate::agents::{
    agents_apply_amended_for, agents_plan_for, AgentsPlan, AgentsRequest, FilePlan,
};
use crate::apply::{
    decide, new_request_id, publish_exclusive, publish_replace, read_opt, root_of,
    save_before_bytes, Decision, Receipt,
};
use crate::{digest, read_profile, PROJECT_STATE_DIR};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{fs, path::Path};

type Result<T> = std::result::Result<T, String>;

const MANIFEST: &str = ".moai-cli/manifests/generation.json";
const SOURCES_MANIFEST: &str = ".moai-cli/manifests/sources.json";
const MAX_ROLES: usize = 16;
const MAX_PROJECTIONS: usize = 16;
/// Generated text stays short: Codex reads the whole AGENTS.md chain within 32 KiB
/// by default, and the managed section must leave room for user content.
const PURPOSE_LIMIT: usize = 500;

/// Skill names follow the Agent Skills specification (same rule as 03-B).
fn valid_skill_name(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 64
        && s.bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
        && !s.starts_with('-')
        && !s.ends_with('-')
        && !s.contains("--")
}

fn valid_revision(s: &str) -> bool {
    s.len() == 40
        && s.bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

/// REQ-03C-07: no rendered string may carry managed-marker tokens or a frontmatter
/// delimiter line, and role purposes must stay single-line short.
fn render_safe(s: &str) -> Result<()> {
    let lower = s.to_ascii_lowercase();
    if lower.contains("<!--")
        || lower.contains("-->")
        || lower.contains("moai:managed:")
        || s.lines().any(|l| l.trim() == "---")
    {
        return Err("rendered value contains managed-marker or frontmatter syntax; refused".into());
    }
    Ok(())
}

fn bounded_purpose(s: &str) -> bool {
    !s.trim().is_empty() && s.len() <= PURPOSE_LIMIT && !s.contains('\n')
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct NativeRole {
    pub role_id: String,
    /// claude | codex
    pub host: String,
    pub purpose: String,
    #[serde(default)]
    pub read_only_intent: bool,
    /// Claude-only allowed-tools list (Codex files never carry tool keys).
    #[serde(default)]
    pub tools: Vec<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SkillProjection {
    /// Installed skill name; also the projected directory name (REQ-03C-09).
    pub id: String,
    /// `source_url` of an entry in `.moai-cli/manifests/sources.json`.
    pub source_url: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resolved_revision: Option<String>,
    /// claude | codex (default: claude)
    #[serde(default)]
    pub host_targets: Vec<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GenerationRequest {
    pub protocol_version: u32,
    /// en | ko (feeds the delegated agents rendering too).
    pub language: String,
    /// Repo-relative directory that must exist (agents_plan contract).
    pub workflow_reference: String,
    /// none | ignored | tracked (the personal-file opt-in, passed through).
    pub local_file: String,
    /// Portable workflow id; the generated directory name.
    pub workflow_id: String,
    #[serde(default)]
    pub native_roles: Vec<NativeRole>,
    #[serde(default)]
    pub skill_projections: Vec<SkillProjection>,
}

/// One planned file. The agents portion carries the `agents.rs` fields it produced;
/// generation files add their `source_refs` and kind tag.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GenerationFilePlan {
    pub path: String,
    /// create | merge | append | unchanged | conflict
    pub action: String,
    pub tracked_by_default: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expected_sha256: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub baseline_sha256: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub rendered_sha256: Option<String>,
    #[serde(default)]
    pub source_refs: Vec<String>,
    /// agents:<section> | generation:workflow:<id> |
    /// generation:native-role:<host>:<role> | generation:skill-projection:<host>:<id>
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub kind: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GenerationPlan {
    pub protocol_version: u32,
    pub request: GenerationRequest,
    pub target_binding: String,
    pub files: Vec<GenerationFilePlan>,
    /// Pass-through of the agents host_notes (CLAUDE.md family) plus generation
    /// warnings (read-only-intent, license gate).
    pub host_notes: Vec<String>,
    pub warnings: Vec<String>,
    pub plan_digest: String,
}

fn validate(r: &GenerationRequest) -> Result<()> {
    if r.protocol_version != 1
        || !(r.language == "en" || r.language == "ko")
        || !["none", "ignored", "tracked"].contains(&r.local_file.as_str())
        || !valid_skill_name(&r.workflow_id)
        || r.workflow_reference.trim().is_empty()
        || r.workflow_reference.len() > 256
        || r.native_roles.len() > MAX_ROLES
        || r.skill_projections.len() > MAX_PROJECTIONS
    {
        return Err("invalid generation request; no values were logged".into());
    }
    for role in &r.native_roles {
        if !valid_skill_name(&role.role_id)
            || !(role.host == "claude" || role.host == "codex")
            || !bounded_purpose(&role.purpose)
            || role.tools.len() > 32
            || !role
                .tools
                .iter()
                .all(|t| !t.is_empty() && t.len() <= 128 && !t.contains(char::is_whitespace))
        {
            return Err("invalid generation request; no values were logged".into());
        }
    }
    for p in &r.skill_projections {
        if !valid_skill_name(&p.id)
            || p.source_url.trim().is_empty()
            || p.source_url.len() > 2048
            || p.resolved_revision
                .as_ref()
                .is_some_and(|rev| !valid_revision(rev))
            || p.host_targets.iter().any(|h| h != "claude" && h != "codex")
        {
            return Err("invalid generation request; no values were logged".into());
        }
    }
    for role in &r.native_roles {
        render_safe(&role.purpose)?;
        render_safe(&role.role_id)?;
    }
    render_safe(&r.workflow_id)?;
    Ok(())
}

/// Reads `generation.json` as a Value. agents.rs owns the typed schema; the
/// generation side only rewrites keys the schema already knows.
fn manifest_value(root: &Path) -> Result<Value> {
    let path = root.join(MANIFEST);
    match fs::metadata(&path) {
        Ok(m) if !m.is_file() || m.len() > 262_144 => {
            Err("target is not a bounded regular file".into())
        }
        Ok(_) => {
            let bytes = fs::read(&path).map_err(|_| "target read failed".to_string())?;
            serde_json::from_slice(&bytes)
                .map_err(|_| "generation manifest unreadable; inspect before generating".into())
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(Value::Null),
        Err(_) => Err("target metadata unavailable".into()),
    }
}

/// The recorded baseline digest of one generation file, from the manifest's
/// `owned_files` (entries tagged with a `generation:` section id).
fn generation_baseline(manifest: &Value, path: &str) -> Option<String> {
    manifest
        .get("owned_files")
        .and_then(Value::as_array)
        .and_then(|list| {
            list.iter()
                .find(|f| f.get("path").and_then(Value::as_str) == Some(path))
                .and_then(|f| f.get("baseline_sha256"))
                .and_then(Value::as_str)
                .map(str::to_string)
        })
}

/// License gate (REQ-03C-08): the source entry in `sources.json` must carry
/// `license.status: reviewed` for anything to reference it. Returns the attribution
/// pair (resolved revision, license note) when reviewed.
fn source_reviewed(root: &Path, source_url: &str) -> Result<Option<(String, String)>> {
    let path = root.join(SOURCES_MANIFEST);
    let bytes = match fs::read(&path) {
        Ok(b) => b,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(_) => return Err("target read failed".into()),
    };
    let manifest: Value = serde_json::from_slice(&bytes)
        .map_err(|_| "sources manifest unreadable; inspect before generating".to_string())?;
    for s in manifest
        .get("sources")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
    {
        if s.get("source_url").and_then(Value::as_str) == Some(source_url) {
            let status = s
                .get("license")
                .and_then(|l| l.get("status"))
                .and_then(Value::as_str)
                .unwrap_or("unknown");
            if status != "reviewed" {
                return Ok(None);
            }
            let revision = s
                .get("resolved_revision")
                .and_then(Value::as_str)
                .unwrap_or("unpinned");
            let license = s
                .get("license")
                .and_then(|l| l.get("spdx"))
                .and_then(Value::as_str)
                .or_else(|| {
                    s.get("license")
                        .and_then(|l| l.get("evidence"))
                        .and_then(Value::as_str)
                })
                .unwrap_or("evidence recorded");
            return Ok(Some((revision.to_string(), license.to_string())));
        }
    }
    Ok(None)
}

fn toml_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04X}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn render_workflow_skill(workflow_id: &str, language: &str) -> String {
    if language == "ko" {
        format!("# {id} 워크플로\n\n이 프로젝트 전용 워크플로입니다. 절차와 판단 기준은 `references/workflow.md`에 정리합니다.\n",
            id = workflow_id)
    } else {
        format!("# {id} workflow\n\nA project-specific workflow. Procedures and judgment notes live in `references/workflow.md`.\n",
            id = workflow_id)
    }
}

fn render_workflow_reference(workflow_id: &str, language: &str) -> String {
    if language == "ko" {
        format!("# {id} 절차\n\n1. 대상과 범위를 확인한다.\n2. 검증 가능한 완료 조건을 먼저 정의한다.\n3. 결과와 증거를 기록한다.\n",
            id = workflow_id)
    } else {
        format!("# {id} procedure\n\n1. Confirm the target and scope.\n2. Define a verifiable done condition first.\n3. Record the result and the evidence.\n",
            id = workflow_id)
    }
}

fn render_claude_role(role: &NativeRole) -> String {
    let tools = if role.tools.is_empty() {
        String::new()
    } else {
        format!("tools: {}\n", role.tools.join(", "))
    };
    format!(
        "---\nname: {id}\ndescription: {purpose}\n{tools}---\n\n{purpose}\n",
        id = role.role_id,
        purpose = role.purpose,
        tools = tools,
    )
}

fn render_codex_role(role: &NativeRole) -> String {
    format!(
        "name = {name}\ndescription = {desc}\ndeveloper_instructions = {instr}\n",
        name = toml_string(&role.role_id),
        desc = toml_string(&role.purpose),
        instr = toml_string(&role.purpose),
    )
}

fn render_projection_skill(
    projection: &SkillProjection,
    language: &str,
    source: &(String, String),
) -> Result<String> {
    let attribution = format!(
        "source: {} @ {} (license: {})",
        projection.source_url, source.0, source.1
    );
    render_safe(&attribution)?;
    let body = if language == "ko" {
        format!("# {id} 참조\n\n이 파일은 외부 skill을 복제하지 않고 참조만 기록합니다.\n{attribution}\n",
            id = projection.id)
    } else {
        format!("# {id} reference\n\nThis file references an external skill without copying it.\n{attribution}\n",
            id = projection.id)
    };
    Ok(format!(
        "---\nname: {id}\ndescription: {desc}\n---\n\n{body}",
        id = projection.id,
        desc = if language == "ko" {
            "외부 skill 참조 기록"
        } else {
            "external skill reference record"
        },
    ))
}

fn plan_digest(p: &GenerationPlan) -> String {
    digest(
        &serde_json::to_vec(&(
            p.protocol_version,
            &p.request,
            &p.target_binding,
            &p.files,
            &p.host_notes,
            &p.warnings,
        ))
        .expect("typed plan"),
    )
}

fn file_from_agents(f: &FilePlan) -> GenerationFilePlan {
    GenerationFilePlan {
        path: f.path.clone(),
        action: f.action.clone(),
        tracked_by_default: f.tracked_by_default,
        expected_sha256: f.expected_sha256.clone(),
        baseline_sha256: f.baseline_sha256.clone(),
        rendered_sha256: f.rendered_sha256.clone(),
        source_refs: Vec::new(),
        kind: Some(format!(
            "agents:{}",
            f.section_id.clone().unwrap_or_else(|| "personal".into())
        )),
        detail: f.detail.clone(),
    }
}

fn three_way_action(
    baseline: Option<&str>,
    current_digest: Option<&str>,
    rendered_digest: &str,
) -> &'static str {
    match decide(baseline, current_digest, Some(rendered_digest)) {
        Decision::KeepCurrent => "unchanged",
        Decision::Apply => "merge",
        Decision::Conflict => "conflict",
    }
}

/// The create/merge refinement of an Apply decision: no current bytes means create.
fn is_create(current: Option<&Vec<u8>>) -> bool {
    current.is_none()
}

/// `generation-plan`: the read-only judgment (REQ-03C-01). The agents portion is the
/// public `agents_plan`; nothing is written.
/// Canonical `workflow_reference` form: exactly one trailing slash. The recorded
/// configuration and the existing golden AGENTS.md renders carry the slash, and
/// `agents.rs` (untouched here) embeds the value verbatim — so the two spellings of
/// one meaning are normalized to the slash-terminated form before planning (Issue
/// #2095). A canonical request renders byte-identically to before.
fn normalize_workflow_reference(raw: &str) -> String {
    format!("{}/", raw.trim_end_matches('/'))
}

/// The canonical `workflow_reference` names a directory this request's own apply writes:
/// `.moai-cli/workflows/` or `.moai-cli/workflows/<workflow_id>/` (#2274, REQ-1). Only then
/// may the agents plan skip its "directory exists" check; any other reference keeps it.
fn reference_is_own_output(request: &GenerationRequest) -> bool {
    let base = format!("{PROJECT_STATE_DIR}/workflows/");
    request.workflow_reference == base
        || request.workflow_reference == format!("{base}{}/", request.workflow_id)
}

pub fn generation_plan(root: &Path, request: GenerationRequest) -> Result<GenerationPlan> {
    let mut request = request;
    request.workflow_reference = normalize_workflow_reference(&request.workflow_reference);
    validate(&request)?;
    let root = root
        .canonicalize()
        .map_err(|_| "project directory unavailable")?;
    let agents_request = AgentsRequest {
        protocol_version: 1,
        language: request.language.clone(),
        workflow_reference: request.workflow_reference.clone(),
        local_file: request.local_file.clone(),
    };
    let agents = agents_plan_for(&root, agents_request, reference_is_own_output(&request))?;
    let manifest = manifest_value(&root)?;
    let mut files: Vec<GenerationFilePlan> = agents.files.iter().map(file_from_agents).collect();
    let mut warnings: Vec<String> = agents.warnings.clone();
    let host_notes: Vec<String> = agents.host_notes.clone();

    // Portable workflow (REQ-03C-01: one workflow per request).
    let workflow_rel = format!(
        "{PROJECT_STATE_DIR}/workflows/{}/SKILL.md",
        request.workflow_id
    );
    let workflow_ref_rel = format!(
        "{PROJECT_STATE_DIR}/workflows/{}/references/workflow.md",
        request.workflow_id
    );
    let rendered_skill = render_workflow_skill(&request.workflow_id, &request.language);
    let rendered_ref = render_workflow_reference(&request.workflow_id, &request.language);
    for (rel, rendered) in [
        (&workflow_rel, rendered_skill),
        (&workflow_ref_rel, rendered_ref),
    ] {
        let current = fs::read(root.join(rel)).ok();
        let baseline = generation_baseline(&manifest, rel);
        let rendered_digest = digest(rendered.as_bytes());
        let action = three_way_action(
            baseline.as_deref(),
            current.as_deref().map(digest).as_deref(),
            &rendered_digest,
        );
        let action = if action == "merge" && is_create(current.as_ref()) {
            "create"
        } else {
            action
        };
        files.push(GenerationFilePlan {
            path: rel.into(),
            action: action.into(),
            tracked_by_default: true,
            expected_sha256: current.as_deref().map(digest),
            baseline_sha256: baseline,
            rendered_sha256: Some(rendered_digest),
            source_refs: Vec::new(),
            kind: Some(format!("generation:workflow:{}", request.workflow_id)),
            detail: None,
        });
    }

    // Native roles (REQ-03C-05/06): nothing under .claude/agents/ or .codex/agents/
    // is planned when the request lists no roles.
    for role in &request.native_roles {
        let (rel, rendered) = match role.host.as_str() {
            "claude" => (
                format!(".claude/agents/{}.md", role.role_id),
                render_claude_role(role),
            ),
            _ => (
                format!(".codex/agents/{}.toml", role.role_id),
                render_codex_role(role),
            ),
        };
        if role.host == "codex" && role.read_only_intent {
            warnings.push(
                "read_only_intent is guidance; a Codex agent file cannot create a sandbox".into(),
            );
        }
        let current = fs::read(root.join(&rel)).ok();
        let baseline = generation_baseline(&manifest, &rel);
        let rendered_digest = digest(rendered.as_bytes());
        let action = three_way_action(
            baseline.as_deref(),
            current.as_deref().map(digest).as_deref(),
            &rendered_digest,
        );
        let action = if action == "merge" && is_create(current.as_ref()) {
            "create"
        } else {
            action
        };
        files.push(GenerationFilePlan {
            path: rel,
            action: action.into(),
            tracked_by_default: false,
            expected_sha256: current.as_deref().map(digest),
            baseline_sha256: baseline,
            rendered_sha256: Some(rendered_digest),
            source_refs: Vec::new(),
            kind: Some(format!(
                "generation:native-role:{}:{}",
                role.host, role.role_id
            )),
            detail: None,
        });
    }

    // Skill projections (REQ-03C-08/09): license gate first, attribution rendered.
    for p in &request.skill_projections {
        let hosts: Vec<String> = if p.host_targets.is_empty() {
            vec!["claude".into()]
        } else {
            p.host_targets.clone()
        };
        let Some(source) = source_reviewed(&root, &p.source_url)? else {
            warnings.push(format!(
                "source {} is not license-reviewed; projection {} is not planned",
                p.source_url, p.id
            ));
            continue;
        };
        let rendered = render_projection_skill(p, &request.language, &source)?;
        let rendered_digest = digest(rendered.as_bytes());
        for host in &hosts {
            let rel = match host.as_str() {
                "codex" => format!(".agents/skills/{}/SKILL.md", p.id),
                _ => format!(".claude/skills/{}/SKILL.md", p.id),
            };
            let dest_dir = root
                .join(&rel)
                .parent()
                .expect("projection parent")
                .to_path_buf();
            let current = fs::read(root.join(&rel)).ok();
            let baseline = generation_baseline(&manifest, &rel);
            // REQ-03C-09: an existing skill directory without a recorded baseline is
            // a conflict — MoAI never claims a directory it did not project before.
            let unclaimed = baseline.is_none()
                && (current.is_some() || fs::symlink_metadata(&dest_dir).is_ok());
            let action = if unclaimed {
                "conflict"
            } else {
                let decided = three_way_action(
                    baseline.as_deref(),
                    current.as_deref().map(digest).as_deref(),
                    &rendered_digest,
                );
                if decided == "merge" && is_create(current.as_ref()) {
                    "create"
                } else {
                    decided
                }
            };
            files.push(GenerationFilePlan {
                path: rel,
                action: action.into(),
                tracked_by_default: false,
                expected_sha256: current.as_deref().map(digest),
                baseline_sha256: baseline,
                rendered_sha256: Some(rendered_digest.clone()),
                source_refs: vec![p.source_url.clone()],
                kind: Some(format!("generation:skill-projection:{}:{}", host, p.id)),
                detail: unclaimed
                    .then_some("existing skill directory without a manifest baseline".to_string()),
            });
        }
    }

    let binding = digest(root.to_str().ok_or("non UTF-8 project path")?.as_bytes());
    let mut plan = GenerationPlan {
        protocol_version: 1,
        request,
        target_binding: binding,
        files,
        host_notes,
        warnings,
        plan_digest: String::new(),
    };
    plan.plan_digest = plan_digest(&plan);
    Ok(plan)
}

/// Recovers the rendered text for one generation file from the plan request.
fn rendered_text_for(root: &Path, p: &GenerationPlan, f: &GenerationFilePlan) -> Result<String> {
    let kind = f.kind.as_deref().unwrap_or("");
    if let Some(_id) = kind.strip_prefix("generation:workflow:") {
        if f.path.ends_with("SKILL.md") {
            return Ok(render_workflow_skill(
                &p.request.workflow_id,
                &p.request.language,
            ));
        }
        return Ok(render_workflow_reference(
            &p.request.workflow_id,
            &p.request.language,
        ));
    }
    if let Some(rest) = kind.strip_prefix("generation:native-role:") {
        let Some((host, role_id)) = rest.split_once(':') else {
            return Err("unknown planned path".into());
        };
        let role = p
            .request
            .native_roles
            .iter()
            .find(|r| r.role_id == role_id && r.host == host)
            .ok_or("unknown planned path")?;
        return match host {
            "claude" => Ok(render_claude_role(role)),
            _ => Ok(render_codex_role(role)),
        };
    }
    if let Some(rest) = kind.strip_prefix("generation:skill-projection:") {
        let Some((host, id)) = rest.split_once(':') else {
            return Err("unknown planned path".into());
        };
        let projection = p
            .request
            .skill_projections
            .iter()
            .find(|sp| sp.id == id)
            .ok_or("unknown planned path")?;
        let hosts: Vec<String> = if projection.host_targets.is_empty() {
            vec!["claude".into()]
        } else {
            projection.host_targets.clone()
        };
        if !hosts.iter().any(|h| h == host) {
            return Err("unknown planned path".into());
        }
        let source =
            source_reviewed(root, &projection.source_url)?.ok_or("unknown planned path")?;
        return render_projection_skill(projection, &p.request.language, &source);
    }
    Err("unknown planned path".into())
}

/// `generation-apply` (REQ-03C-03/04/11): re-plans the whole request and refuses any
/// drift, applies the agents portion through the `agents_apply` engine with its own
/// freshly computed digest, publishes the generation files with the 01-B engine from
/// its hook, and records the generation baselines plus `workflow_id`,
/// `interview_revision` and `profile_sha256` in the one `generation.json` publish that
/// comes last (#2114). A mid-sequence failure reports `partial apply` with what landed
/// and leaves the previous manifest in place.
pub fn generation_apply(
    root: &Path,
    p: GenerationPlan,
    confirmed: &str,
    permission: &str,
) -> Result<Value> {
    if ["", "null", "placeholder"].contains(&permission.trim())
        || permission.len() > 128
        || permission.chars().any(char::is_control)
    {
        return Err("permission reference required".into());
    }
    // Same canonical form at the apply entry: an old plan recorded before #2095 with
    // the raw spelling then fails the digest re-check and must re-preview.
    let mut p = p;
    p.request.workflow_reference = normalize_workflow_reference(&p.request.workflow_reference);
    let current = generation_plan(root, p.request.clone())?;
    if p.protocol_version != 1
        || confirmed != p.plan_digest
        || plan_digest(&p) != p.plan_digest
        || current.plan_digest != p.plan_digest
    {
        return Err("stale or altered plan; re-preview required".into());
    }
    if let Some(f) = p.files.iter().find(|f| f.action == "conflict") {
        return Err(format!(
            "conflict in {}: {}; nothing applied",
            f.path,
            f.detail.as_deref().unwrap_or("review required")
        ));
    }
    let root = root_of(root)?;

    // 1. The agents portion: AGENTS.md managed section, personal opt-in, .gitignore,
    //    and the single manifest publish agents.rs owns. The freshly re-planned digest is the
    //    inner confirmation; the outer generation check already refused drift.
    let agents_request = AgentsRequest {
        protocol_version: 1,
        language: p.request.language.clone(),
        workflow_reference: p.request.workflow_reference.clone(),
        local_file: p.request.local_file.clone(),
    };
    let own_output = reference_is_own_output(&p.request);
    let agents_plan: AgentsPlan = agents_plan_for(&root, agents_request.clone(), own_output)?;
    // 2 and 3 run inside the agents hook, after the agents files and before the one
    //    manifest publish (#2114): a failure here leaves the previous manifest intact.
    let request_id = new_request_id("generation.apply", &p.plan_digest);
    let (profile, profile_bytes) = read_profile(&root)?;
    let mut files_created: Vec<String> = Vec::new();
    let mut files_merged: Vec<String> = Vec::new();
    // Lives past the hook: it reads `complete` only after the manifest publish (#2119).
    let mut receipt = Receipt::new(&request_id, "generation.apply", &root);
    let mut hook = |root: &Path, manifest: &mut Value| -> Result<()> {
        // 2. The generation files, through the 01-B engine with a receipt.
        for f in &p.files {
            let Some(kind) = &f.kind else {
                continue;
            };
            if !kind.starts_with("generation:") || f.path == MANIFEST {
                continue;
            }
            if f.action == "unchanged" {
                continue;
            }
            let rendered_text = rendered_text_for(root, &p, f)?;
            let bytes = rendered_text.into_bytes();
            let path_abs = root.join(&f.path);
            let before = read_opt(&path_abs)?;
            let fail = |receipt: &Receipt, message: String| -> String {
                match receipt.save(root) {
                    Ok(()) => message,
                    Err(se) => format!("{message}; receipt not recorded: {se}"),
                }
            };
            if before.as_deref().map(digest).as_deref() != f.expected_sha256.as_deref() {
                receipt.entry(
                    &f.path,
                    &f.action,
                    before.as_deref().map(digest).as_deref(),
                    None,
                    false,
                    Some("target changed since plan".into()),
                );
                receipt.status = "partial".into();
                return Err(fail(
                    &receipt,
                    format!(
                        "partial apply: applied [{}]; failed at {}: target changed since plan",
                        files_created.join(", "),
                        f.path
                    ),
                ));
            }
            if let Some(b) = before.as_deref() {
                if let Err(e) = save_before_bytes(root, &request_id, &f.path, b) {
                    receipt.entry(
                        &f.path,
                        &f.action,
                        before.as_deref().map(digest).as_deref(),
                        None,
                        false,
                        Some(e.clone()),
                    );
                    receipt.status = "partial".into();
                    return Err(fail(
                        &receipt,
                        format!(
                            "partial apply: applied [{}]; failed at {}: {e}",
                            files_created.join(", "),
                            f.path
                        ),
                    ));
                }
            }
            let publish = if before.is_none() {
                publish_exclusive(&path_abs, &bytes)
            } else {
                publish_replace(&path_abs, before.as_deref(), &bytes)
            };
            if let Err(e) = publish {
                receipt.entry(
                    &f.path,
                    &f.action,
                    before.as_deref().map(digest).as_deref(),
                    None,
                    false,
                    Some(e.clone()),
                );
                receipt.status = "partial".into();
                return Err(fail(
                    &receipt,
                    format!(
                        "partial apply: applied [{}]; failed at {}: {e}",
                        files_created.join(", "),
                        f.path
                    ),
                ));
            }
            receipt.entry(
                &f.path,
                &f.action,
                before.as_deref().map(digest).as_deref(),
                Some(&digest(&bytes)),
                true,
                None,
            );
            if before.is_none() {
                files_created.push(f.path.clone());
            } else {
                files_merged.push(f.path.clone());
            }
        }

        // 3. The manifest: record generation baselines and the profile linkage on the
        //    value agents_apply is about to publish. Only keys the agents.rs schema
        //    already knows are touched (agents_apply re-decodes the typed schema).
        if let Some(map) = manifest.as_object_mut() {
            let list = map
                .entry("owned_files")
                .or_insert_with(|| json!([]))
                .as_array_mut()
                .expect("owned_files array");
            list.retain(|f| {
                let path = f.get("path").and_then(Value::as_str).unwrap_or("");
                !p.files.iter().any(|pf| {
                    pf.kind
                        .as_deref()
                        .is_some_and(|k| k.starts_with("generation:"))
                        && pf.path == path
                })
            });
            for f in &p.files {
                let Some(kind) = &f.kind else {
                    continue;
                };
                if !kind.starts_with("generation:") || f.action == "conflict" {
                    continue;
                }
                let Some(rendered) = &f.rendered_sha256 else {
                    continue;
                };
                list.push(json!({
                    "path": f.path,
                    // The bare kind (#2109) is the primary discriminator; the
                    // generation:… section_id tag stays for readers of manifests
                    // written before the kind field existed.
                    "kind": kind.strip_prefix("generation:").and_then(|rest| {
                        rest.split(':').next()
                    }),
                    "section_id": kind,
                    "baseline_sha256": rendered,
                }));
            }
            map.insert("workflow_id".into(), json!(p.request.workflow_id));
            map.insert(
                "interview_revision".into(),
                json!(profile.interview_revision),
            );
            map.insert("profile_sha256".into(), json!(digest(&profile_bytes)));
        }
        // The manifest entry itself is recorded in the agents.apply receipt, which keeps
        // the pre-apply manifest bytes for recovery. Saved as `partial` here: the
        // manifest publish is still ahead.
        receipt
            .save(root)
            .map_err(|e| format!("published files but the receipt was not recorded: {e}"))
    };
    let agents_result = agents_apply_amended_for(
        &root,
        agents_plan.clone(),
        &agents_plan.plan_digest,
        permission,
        own_output,
        &mut hook,
    )?;
    receipt.status = "complete".into();
    receipt
        .save(&root)
        .map_err(|e| format!("published files but the receipt was not recorded: {e}"))?;
    let agents_applied: Vec<String> = agents_result
        .get("applied")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|v| v.as_str().map(str::to_string))
        .filter(|path| path != MANIFEST)
        .collect();
    let mut all_created = agents_applied.clone();
    all_created.extend(files_created.iter().cloned());
    Ok(json!({
        "state": "applied",
        "files_created": all_created,
        "files_merged": files_merged,
        "host_loaded": false,
        "execution_verified": false,
        "receipt": request_id,
    }))
}

src/github_templates.rs.content:
//! GitHub templates for a generated project (Issue #2013, 08-B).
//!
//! The verified development copies under `.github/` were added (never moved) as
//! `templates/github/`; this module embeds those bytes and plans and applies them into a
//! project with the 01-B 3-way engine (`decide`, `publish_exclusive`/`publish_replace`,
//! `save_before_bytes`, `Receipt`).
//!
//! Decisions (leader, under the user's "lift only the HOLD" rule, recorded on #2013):
//! - template bytes are embedded in the binary with `include_str!` (①A, as generation.rs
//!   renders its files from strings in the binary);
//! - Rust handles byte parity and the 3-way only; form structure is checked by the Python
//!   static tests (②A: no YAML crate, Cargo.toml keeps its dependencies);
//! - `config.yml` is not a template (③B: the development copy has none).
//!
//! Generation is opted in by the profile key `github_issues` (Issue #2106) or by the
//! request flag of the same name; an explicit request flag wins over the profile, and a
//! folder that merely exists never triggers it (REQ-08B-04).
//! Baselines live in their own manifest `.moai-cli/manifests/github.json` with the
//! `owned_files[].baseline_sha256` shape of `generation.json`: that file's writers are
//! private to agents.rs and generation.rs, so 08-B adds no third writer to it.
//! Files are planned whole (`managed_scope: whole-file`): a user file at a target path
//! without a baseline is a conflict and is never overwritten; other files under
//! `.github/` (user Markdown templates, `config.yml`) are listed as preserved and never
//! touched. GitHub renders forms only from the default branch, so nothing here reports
//! rendering as verified (REQ-08B-10).
use crate::apply::{
    decide, new_request_id, publish_exclusive, publish_replace, read_opt, root_of,
    save_before_bytes, target, Decision, Receipt,
};
use crate::digest;
use crate::spec::{Canonical, SortedKeys};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{fs, path::Path};

type Result<T> = std::result::Result<T, String>;

pub const MANIFEST: &str = ".moai-cli/manifests/github.json";
/// Marker of an unresolved template variable (`placeholder_pattern` in
/// `templates/github/manifest.json`).
pub const PLACEHOLDER: &str = "{{";

/// `(target path, embedded bytes)` of every template, in manifest order.
pub const TEMPLATES: &[(&str, &str)] = &[
    (
        ".github/ISSUE_TEMPLATE/moai-feature.yml",
        include_str!("../templates/github/ISSUE_TEMPLATE/moai-feature.yml"),
    ),
    (
        ".github/ISSUE_TEMPLATE/moai-bugfix.yml",
        include_str!("../templates/github/ISSUE_TEMPLATE/moai-bugfix.yml"),
    ),
    (
        ".github/ISSUE_TEMPLATE/moai-investigation.yml",
        include_str!("../templates/github/ISSUE_TEMPLATE/moai-investigation.yml"),
    ),
    (
        ".github/moai/labels.yml",
        include_str!("../templates/github/labels.yml"),
    ),
];

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GithubRequest {
    pub protocol_version: u32,
    /// Explicit opt-in for this run. When absent, the profile's `github_issues` decides;
    /// when present, it wins over the profile.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub github_issues: Option<bool>,
}

/// Resolves the opt-in: the request flag first, then the profile key. A missing profile
/// or key means not opted in; an unreadable profile is an error, never a guess.
fn opted_in(root: &Path, request: &GithubRequest) -> Result<(bool, String)> {
    if let Some(flag) = request.github_issues {
        return Ok((flag, format!("opt-in from request.github_issues = {flag}")));
    }
    let profile_path = root.join(crate::PROJECT_STATE_DIR).join("project.yaml");
    if read_opt(&profile_path)?.is_none() {
        return Ok((
            false,
            "opt-in: request.github_issues absent and no project profile".into(),
        ));
    }
    let (profile, _) = crate::profile::read_profile(root)?;
    Ok(match profile.github_issues {
        Some(flag) => (flag, format!("opt-in from profile github_issues = {flag}")),
        None => (
            false,
            "opt-in: request.github_issues and profile github_issues both absent".into(),
        ),
    })
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct GithubFilePlan {
    pub path: String,
    /// create | merge | unchanged | conflict
    pub action: String,
    pub expected_sha256: Option<String>,
    pub baseline_sha256: Option<String>,
    pub rendered_sha256: String,
    /// True when the file already equals the rendering but no baseline is recorded
    /// (an interrupted apply): the next apply records it instead of reporting a conflict.
    pub adopt_baseline: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GithubPlan {
    pub protocol_version: u32,
    pub request: GithubRequest,
    pub files: Vec<GithubFilePlan>,
    /// Existing `.github/` files this plan does not own; they are left as they are.
    pub preserved: Vec<String>,
    pub notes: Vec<String>,
    pub plan_digest: String,
}

/// Paths of an unresolved placeholder among `templates` (REQ-08B-08).
pub fn unresolved(templates: &[(&str, &str)]) -> Vec<String> {
    templates
        .iter()
        .filter(|(_, text)| text.contains(PLACEHOLDER))
        .map(|(path, _)| path.to_string())
        .collect()
}

fn manifest_baselines(root: &Path) -> Result<Vec<(String, String)>> {
    let Some(bytes) = read_opt(&root.join(MANIFEST))? else {
        return Ok(Vec::new());
    };
    let v: Value = serde_json::from_slice(&bytes)
        .map_err(|_| "github manifest unreadable; inspect before generating".to_string())?;
    Ok(v["owned_files"]
        .as_array()
        .map(|a| {
            a.iter()
                .filter_map(|f| {
                    Some((
                        f["path"].as_str()?.to_string(),
                        f["baseline_sha256"].as_str()?.to_string(),
                    ))
                })
                .collect()
        })
        .unwrap_or_default())
}

fn preserved(root: &Path) -> Vec<String> {
    let mut out = Vec::new();
    let mut stack = vec![root.join(".github")];
    while let Some(dir) = stack.pop() {
        let Ok(entries) = fs::read_dir(&dir) else {
            continue;
        };
        for e in entries.flatten() {
            let path = e.path();
            if path.is_dir() {
                stack.push(path);
            } else if let Ok(rel) = path.strip_prefix(root) {
                let rel = rel.to_string_lossy().replace('\\', "/");
                if !TEMPLATES.iter().any(|(t, _)| *t == rel) {
                    out.push(rel);
                }
            }
        }
    }
    out.sort();
    out
}

fn plan_digest(p: &GithubPlan) -> String {
    let mut v = serde_json::to_value(p).expect("plan serializes");
    v["plan_digest"] = Value::Null;
    digest(&SortedKeys.bytes(&v))
}

/// `github-plan`: read-only.
pub fn github_plan(root: &Path, request: GithubRequest) -> Result<GithubPlan> {
    if request.protocol_version != 1 {
        return Err("unsupported protocol_version; supported: 1".into());
    }
    let root = root_of(root)?;
    let mut files = Vec::new();
    let mut notes = Vec::new();
    let (enabled, source) = opted_in(&root, &request)?;
    if !enabled {
        notes.push("not generated: not opted in; an existing .github/ never opts in".into());
    } else {
        let baselines = manifest_baselines(&root)?;
        for (rel, text) in TEMPLATES {
            let current = read_opt(&target(&root, rel)?)?;
            let current_digest = current.as_deref().map(digest);
            let baseline = baselines
                .iter()
                .find(|(p, _)| p == rel)
                .map(|(_, d)| d.clone());
            let rendered = digest(text.as_bytes());
            let (action, detail) = match decide(
                baseline.as_deref(),
                current_digest.as_deref(),
                Some(&rendered),
            ) {
                Decision::KeepCurrent => ("unchanged", None),
                Decision::Apply if current.is_none() => ("create", None),
                Decision::Apply => ("merge", None),
                Decision::Conflict if baseline.is_none() => (
                    "conflict",
                    Some("an existing file has no recorded baseline; it is kept".to_string()),
                ),
                Decision::Conflict => (
                    "conflict",
                    Some("the file changed since the last apply; it is kept".to_string()),
                ),
            };
            let adopt = action == "unchanged" && baseline.is_none();
            files.push(GithubFilePlan {
                path: rel.to_string(),
                action: action.into(),
                expected_sha256: current_digest,
                baseline_sha256: baseline,
                rendered_sha256: rendered,
                adopt_baseline: adopt,
                detail,
            });
        }
        notes.push(
            "GitHub reads Issue forms only from the default branch; rendering is not_run".into(),
        );
    }
    notes.push(source);
    let mut plan = GithubPlan {
        protocol_version: 1,
        request,
        files,
        preserved: preserved(&root),
        notes,
        plan_digest: String::new(),
    };
    plan.plan_digest = plan_digest(&plan);
    Ok(plan)
}

/// `github-apply`: publish the approved plan, then record baselines. A failure after a
/// file and before the manifest leaves files equal to the rendering, which the next plan
/// adopts as baselines (REQ-08B-07).
pub fn github_apply(
    root: &Path,
    p: GithubPlan,
    confirmed: &str,
    permission: &str,
) -> Result<Value> {
    if ["", "null", "placeholder"].contains(&permission.trim())
        || permission.len() > 128
        || permission.chars().any(char::is_control)
    {
        return Err("permission reference required".into());
    }
    let current = github_plan(root, p.request.clone())?;
    if p.protocol_version != 1
        || confirmed != p.plan_digest
        || plan_digest(&p) != p.plan_digest
        || current.plan_digest != p.plan_digest
    {
        return Err("stale or altered plan; re-preview required".into());
    }
    if let Some(f) = p.files.iter().find(|f| f.action == "conflict") {
        return Err(format!(
            "conflict in {}: {}; nothing applied",
            f.path,
            f.detail.as_deref().unwrap_or("review required")
        ));
    }
    if let Some(path) = unresolved(TEMPLATES).first() {
        return Err(format!(
            "conflict in {path}: unresolved template placeholder; nothing applied"
        ));
    }
    let root = root_of(root)?;
    let request_id = new_request_id("github.apply", &p.plan_digest);
    let mut receipt = Receipt::new(&request_id, "github.apply", &root);
    let mut written: Vec<String> = Vec::new();
    for f in p
        .files
        .iter()
        .filter(|f| f.action == "create" || f.action == "merge")
    {
        let text = TEMPLATES
            .iter()
            .find(|(t, _)| *t == f.path)
            .map(|(_, text)| *text)
            .ok_or("rendered output missing")?;
        let path = target(&root, &f.path)?;
        let before = read_opt(&path)?;
        let before_digest = before.as_deref().map(digest);
        let failed = |receipt: &mut Receipt, e: String| -> String {
            receipt.entry(
                &f.path,
                &f.action,
                before_digest.as_deref(),
                None,
                false,
                Some(e.clone()),
            );
            receipt.status = "partial".into();
            let saved = receipt.save(&root);
            let message = format!(
                "partial apply: applied [{}]; failed at {}: {e}",
                written.join(", "),
                f.path
            );
            match saved {
                Ok(()) => message,
                Err(se) => format!("{message}; receipt not recorded: {se}"),
            }
        };
        if before_digest != f.expected_sha256 {
            return Err(failed(&mut receipt, "target changed since plan".into()));
        }
        if let Some(b) = before.as_deref() {
            save_before_bytes(&root, &request_id, &f.path, b)
                .map_err(|e| failed(&mut receipt, e))?;
        }
        let publish = match before.as_deref() {
            None => publish_exclusive(&path, text.as_bytes()),
            Some(b) => publish_replace(&path, Some(b), text.as_bytes()),
        };
        publish.map_err(|e| failed(&mut receipt, e))?;
        receipt.entry(
            &f.path,
            &f.action,
            before_digest.as_deref(),
            Some(&f.rendered_sha256),
            true,
            None,
        );
        receipt.save(&root)?;
        written.push(f.path.clone());
    }
    // Baselines last: every planned file that is now equal to its rendering.
    let manifest_path = target(&root, MANIFEST)?;
    let before = read_opt(&manifest_path)?;
    let owned: Vec<Value> = p
        .files
        .iter()
        .map(|f| json!({"path": f.path, "baseline_sha256": f.rendered_sha256}))
        .collect();
    let mut manifest = json!({"schema_version": 1, "template_set": "github", "owned_files": owned});
    if p.files.is_empty() {
        manifest = match &before {
            Some(b) => serde_json::from_slice(b).map_err(|_| "github manifest unreadable")?,
            None => Value::Null,
        };
    }
    let mut adopted = Vec::new();
    if !manifest.is_null() {
        let mut out = serde_json::to_vec_pretty(&manifest).map_err(|_| "encode failed")?;
        out.push(b'\n');
        if before.as_deref() != Some(out.as_slice()) {
            if let Some(b) = before.as_deref() {
                save_before_bytes(&root, &request_id, MANIFEST, b)?;
            }
            match before.as_deref() {
                None => publish_exclusive(&manifest_path, &out),
                Some(b) => publish_replace(&manifest_path, Some(b), &out),
            }
            .map_err(|e| {
                format!(
                    "partial apply: applied [{}]; failed at {MANIFEST}: {e}",
                    written.join(", ")
                )
            })?;
            receipt.entry(
                MANIFEST,
                if before.is_none() { "create" } else { "merge" },
                before.as_deref().map(digest).as_deref(),
                Some(&digest(&out)),
                true,
                None,
            );
        }
        adopted = p
            .files
            .iter()
            .filter(|f| f.adopt_baseline)
            .map(|f| f.path.clone())
            .collect();
    }
    // A run that published nothing leaves no receipt behind (second run: diff 0).
    let request_id = if receipt.entries.is_empty() {
        None
    } else {
        receipt.status = "complete".into();
        receipt.save(&root)?;
        Some(request_id)
    };
    Ok(json!({
        "request_id": request_id,
        "written": written,
        "adopted_baselines": adopted,
        "unchanged": p.files.iter().filter(|f| f.action == "unchanged").map(|f| f.path.clone()).collect::<Vec<_>>(),
        "preserved": p.preserved,
        "manifest": MANIFEST,
        "rendering": "not_run: GitHub reads Issue forms only from the default branch",
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn placeholder_scan_finds_unresolved_markers() {
        assert!(unresolved(TEMPLATES).is_empty());
        assert_eq!(
            unresolved(&[("a.yml", "name: {{project}}"), ("b.yml", "ok")]),
            vec!["a.yml".to_string()]
        );
    }
}

src/handoff.rs.content:
//! Stalled-claim re-inspection and explicit handoff (06-B #2006).
//!
//! 06-A records who owns a task; this module answers what happened when that owner
//! stopped. Everything here runs after a human decision (the leader's explicit
//! `claim-handoff` request IS the approval): nothing decides "the writer is dead" from a
//! timeout, a heartbeat or silence — the lease has no numbers by user decision (P08 (a)),
//! so expiry and takeover are always named, never automatic.
//!
//! - [`claim_handoff`] reads the record, probes the previous owner's liveness **only** for
//!   a `local-process` owner on the same host (REQ-06B-02), refuses an alive or
//!   indeterminate owner without `--force-explicit` + a reason (REQ-06B-03), preserves the
//!   previous worktree as evidence with read-only git only (REQ-06B-04), and closes the
//!   record as `handed_off` naming `to_epoch` (REQ-06B-05). The epoch+1 record itself is
//!   written by the next `claim-acquire` (the journal hands out max+1, so it is exactly
//!   `to_epoch`) — the closure fences everything below it.
//! - [`effect_intend`] / [`effect_confirm`] record an external write before and after it is
//!   sent (REQ-06B-06), reusing the 07-B outbox operation-id and `moai:op` marker formats.
//!   An intent below the record's current epoch is rejected as `stale_epoch` and kept only
//!   as a diagnostic (REQ-06B-08).
//! - [`effects_reconcile`] queries the remote with the stable marker for every `uncertain`
//!   effect and moves it to `confirmed` (found) or `not_performed` (confirmed absent); it
//!   never re-creates anything (REQ-06B-07). A rate-limited probe changes no state until
//!   retry-after (REQ-06B-09).
//!
//! Results are classified `passed|failed|blocked|uncertain|not_run` in the output `verdict`
//! field; anything not probed is never reported as success (REQ-06B-10).
use crate::claim::{is_active, is_key, ClaimRecord, Journal, JournalEvent, TaskRef};
use crate::forge::outbox::{op_id, op_marker, parse_op_markers};
use crate::forge::policy::{format_utc, next_link, Clock};
use crate::forge::transport::Transport;
use crate::forge::{Client, ForgeError};
use crate::{digest, identity};
use serde_json::{json, Value};
use std::{
    cell::{Cell, RefCell},
    path::Path,
    process::{Command, Stdio},
};

type Result<T> = std::result::Result<T, String>;

/// The state a handoff closes the previous record with (REQ-06B-05). Not an active state:
/// the closure releases the claim and the next acquire writes the new epoch.
pub const HANDOFF_STATE: &str = "handed_off";

/// Marker prefix written into external artifacts so a reconcile can find them again
/// (07-B convention: the full marker is `<!-- moai:op <operation>:<project>:<local>:<n> -->`).
pub const MARKER_PREFIX: &str = "moai:op ";

fn now_of<C: Clock>(clock: &C) -> String {
    format_utc(clock.now())
}

fn current_record<'a>(events: &'a [JournalEvent], key: &str) -> Option<&'a ClaimRecord> {
    events
        .iter()
        .rev()
        .find(|e| e.record.task_key == key)
        .map(|e| &e.record)
}

fn next_epoch(events: &[JournalEvent], key: &str) -> u64 {
    events
        .iter()
        .filter(|e| e.record.task_key == key)
        .map(|e| e.record.epoch)
        .max()
        .unwrap_or(0)
        + 1
}

// ---- liveness (REQ-06B-02) ----

/// Probes one recorded `local-process` owner. `ps -p <pid> -o lstart=` answers both
/// existence and start time under `LC_ALL=C`; a differing start time means the pid was
/// reused by another process. No `kill`, no crate, no reading of any other host.
pub fn probe_liveness(pid: Option<u32>, expected_start: Option<&str>) -> (String, Value) {
    let Some(pid) = pid else {
        return (
            "indeterminate".into(),
            json!({"reason": "no pid recorded", "pid": Value::Null}),
        );
    };
    let out = Command::new("ps")
        .args(["-p", &pid.to_string(), "-o", "lstart="])
        .env("LC_ALL", "C")
        .stdin(Stdio::null())
        .stderr(Stdio::piped())
        .output();
    let Ok(out) = out else {
        return (
            "indeterminate".into(),
            json!({"pid": pid, "reason": "ps unavailable"}),
        );
    };
    if !out.status.success() {
        return (
            "dead".into(),
            json!({"pid": pid, "reason": "no such process"}),
        );
    }
    let start = String::from_utf8_lossy(&out.stdout).trim().to_string();
    if start.is_empty() {
        return (
            "indeterminate".into(),
            json!({"pid": pid, "reason": "start time unavailable"}),
        );
    }
    match expected_start {
        Some(expected) if expected == start => {
            ("alive".into(), json!({"pid": pid, "start": start}))
        }
        Some(expected) => (
            "dead".into(),
            json!({"pid": pid, "observed_start": start, "recorded_start": expected, "reason": "pid reused"}),
        ),
        None => (
            "indeterminate".into(),
            json!({"pid": pid, "observed_start": start, "reason": "no recorded start time"}),
        ),
    }
}

// ---- worktree evidence (REQ-06B-04) ----

/// Read-only git evidence of the previous worktree. Only `status`, `rev-parse` and
/// `stash list` run — no `reset`, no `checkout --`, no `stash`, no `clean`, no
/// `worktree remove` (REQ-06B-04; the checklist reviews this).
fn collect_evidence(worktree_path: &str) -> Value {
    let dir = Path::new(worktree_path);
    if !dir.is_dir() {
        return json!({
            "status": "unavailable",
            "note": "the previous worktree path is missing; dirty changes cannot be inspected and the new owner starts fresh",
        });
    }
    let git_read = |args: &[&str]| -> String {
        let mut cmd = Command::new("git");
        cmd.arg("--no-optional-locks").arg("-C").arg(dir).args(args);
        identity::scrub_git_env(&mut cmd);
        let out = cmd
            .env("GIT_OPTIONAL_LOCKS", "0")
            .stdin(Stdio::null())
            .stderr(Stdio::piped())
            .output();
        match out {
            Ok(o) if o.status.success() => String::from_utf8_lossy(&o.stdout).into_owned(),
            _ => String::new(),
        }
    };
    json!({
        "status": "collected",
        "status_v2_z": git_read(&["status", "--porcelain=v2", "-z"]),
        "head": git_read(&["rev-parse", "HEAD"]).trim().to_string(),
        "stash_list": git_read(&["stash", "list"]),
    })
}

// ---- handoff (REQ-06B-01..05) ----

/// The leader's explicit handoff. Every refusal and every probe result is recorded; the
/// only state-changing refusals are `stale_request` (an error, nothing written) and the
/// `handoff_pending` marking for an alive or indeterminate owner.
#[allow(clippy::too_many_arguments)]
pub fn claim_handoff<C: Clock>(
    journal: &Journal,
    key: &str,
    from_epoch: u64,
    reason: &str,
    force_explicit: bool,
    host_id: Option<&str>,
    clock: &C,
) -> Result<Value> {
    if !is_key(key) {
        return Err("task must be a 16 hex character claim key".into());
    }
    if reason.trim().is_empty() || reason.len() > 256 || reason.chars().any(char::is_control) {
        return Err("reason must be a bounded string without control characters".into());
    }
    let events = journal.read_events()?;
    let Some(current) = current_record(&events, key) else {
        return Ok(json!({
            "outcome": "unclaimed", "verdict": "not_run", "record": Value::Null,
            "liveness": Value::Null, "notes": ["no record exists for this task key"],
        }));
    };
    // REQ-06B-01: the request must name the epoch it saw — checked before anything else,
    // a closed record still has a current epoch and a late request is a stale one.
    if from_epoch != current.epoch {
        return Err(format!(
            "conflict in claim handoff: stale_request {from_epoch}; current record epoch is {}",
            current.epoch
        ));
    }
    if !is_active(&current.state) {
        return Ok(json!({
            "outcome": "unclaimed", "verdict": "not_run", "record": json!(current),
            "liveness": Value::Null,
            "notes": [format!("the record is not in an active state ({})", current.state)],
        }));
    }
    // REQ-06B-02: probe only a local-process owner on the same host.
    let probeable = current.owner.kind == "local-process"
        && current.owner.host_id.is_some()
        && current.owner.host_id.as_deref() == host_id;
    let (liveness, liveness_evidence) = if probeable {
        let (result, evidence) =
            probe_liveness(current.owner.pid, current.owner.process_start.as_deref());
        (result, Some(evidence))
    } else {
        ("not_applicable".to_string(), None)
    };
    let now = now_of(clock);
    let mut effects = current.effects.clone();
    effects.push(json!({
        "kind": "liveness", "result": liveness, "evidence": liveness_evidence, "at": now,
    }));
    // REQ-06B-03: an alive or indeterminate owner needs the explicit flag; silence,
    // timeouts and heartbeats never decide a takeover.
    if (liveness == "alive" || liveness == "indeterminate") && !force_explicit {
        let mut pending = current.clone();
        pending.state = "handoff_pending".into();
        pending.effects = effects;
        pending.last_observed_at = now.clone();
        journal.commit("handoff_pending", &pending)?;
        return Ok(json!({
            "outcome": "handoff_pending", "verdict": "blocked", "record": json!(pending),
            "liveness": liveness,
            "notes": ["an alive or indeterminate owner needs --force-explicit with a reason; no automatic takeover (REQ-06B-03)"],
        }));
    }
    // REQ-06B-04: preserve the previous worktree as evidence; read-only git only.
    let evidence = collect_evidence(&current.worktree.path);
    effects.push(json!({"kind": "worktree_evidence", "evidence": evidence, "at": now}));
    // REQ-06B-05: the worktree lock is an intent only — executing it is the caller's
    // approval scope, never this command.
    effects.push(json!({
        "kind": "worktree_lock_intent",
        "command": format!("git worktree lock --reason \"handoff from epoch {}\"", current.epoch),
        "state": "intended",
        "note": "recorded as an intent; never executed here",
        "at": now,
    }));
    let to_epoch = next_epoch(&events, key);
    let mut closed = current.clone();
    closed.state = HANDOFF_STATE.into();
    closed.last_observed_at = now.clone();
    closed.effects = effects;
    closed.effects.push(json!({
        "kind": "handoff", "to_epoch": to_epoch, "reason": reason, "at": now,
    }));
    journal.commit("handoff", &closed)?;
    Ok(json!({
        "outcome": "handed_off", "verdict": "passed", "record": json!(closed),
        "liveness": liveness, "to_epoch": to_epoch,
        "notes": ["the next claim-acquire writes the to_epoch record; publish intents below to_epoch are fenced (REQ-06B-08)"],
    }))
}

// ---- effects: intend / confirm (REQ-06B-06, REQ-06B-08) ----

/// One publish effect in the record's `effects[]`: `{"kind": <publish kind>,
/// "operation_id", "intent_digest", "state": intended|confirmed|uncertain|not_performed,
/// "epoch", "marker", "response_id"?, "observed_state"?}`. Bookkeeping entries
/// (liveness, worktree_evidence, worktree_lock_intent, stale_result, handoff) carry no
/// operation_id and are never touched here.
fn publish_effect<'a>(record: &'a ClaimRecord, operation_id: &str) -> Option<(usize, &'a Value)> {
    record
        .effects
        .iter()
        .enumerate()
        .find(|(_, e)| e["operation_id"].as_str() == Some(operation_id))
}

#[allow(clippy::too_many_arguments)]
pub fn effect_intend<C: Clock>(
    journal: &Journal,
    key: &str,
    epoch: u64,
    operation: &str,
    project_id: &str,
    local_id: &str,
    attempt: u32,
    kind: &str,
    payload: &[u8],
    clock: &C,
) -> Result<Value> {
    if !is_key(key) {
        return Err("task must be a 16 hex character claim key".into());
    }
    if !bounded_kind(kind) {
        return Err("kind must be a bounded string without control characters".into());
    }
    // The 07-B formats: both fail on non-portable parts.
    let operation_id = op_id(operation, project_id, local_id, attempt).map_err(String::from)?;
    let marker = op_marker(operation, project_id, local_id, attempt);
    let events = journal.read_events()?;
    let Some(current) = current_record(&events, key) else {
        return Err("unknown task key; no claim record exists".into());
    };
    // REQ-06B-08: the intent names the epoch it believes it is publishing under.
    if epoch < current.epoch {
        let now = now_of(clock);
        let mut diag = current.clone();
        diag.last_observed_at = now.clone();
        diag.effects.push(json!({
            "kind": "stale_result",
            "request": {"operation": operation, "project_id": project_id, "local_id": local_id,
                        "attempt": attempt, "publish_kind": kind, "epoch": epoch},
            "at": now,
        }));
        journal.commit("stale_result", &diag)?;
        return Err(format!(
            "conflict in claim journal: stale_epoch {epoch}; current record epoch is {}",
            current.epoch
        ));
    }
    if !is_active(&current.state) {
        return Err(format!(
            "conflict in claim journal: the record is not active ({});
             publish intents attach to an active epoch",
            current.state
        ));
    }
    // draft-ietf-httpapi-idempotency-key semantics, borrowed locally (never sent to
    // GitHub): the same key with the same payload is the same intent, a different payload
    // under the same key is a conflict.
    let intent_digest = digest(payload);
    if let Some((_, existing)) = publish_effect(current, &operation_id) {
        if existing["intent_digest"] == json!(intent_digest) {
            return Ok(json!({
                "outcome": "intended", "verdict": "passed",
                "operation_id": operation_id, "marker": existing["marker"],
                "intent_digest": intent_digest, "epoch": epoch, "state": existing["state"],
                "notes": ["the same key and payload were already intended; nothing changed"],
            }));
        }
        return Err(format!(
            "conflict in claim journal: operation_id {operation_id} is already recorded with a different payload"
        ));
    }
    let now = now_of(clock);
    let mut record = current.clone();
    record.last_observed_at = now.clone();
    record.effects.push(json!({
        "kind": kind,
        "operation_id": operation_id,
        "intent_digest": intent_digest,
        "state": "intended",
        "epoch": epoch,
        "marker": marker,
        "at": now,
    }));
    journal.commit("effect_intend", &record)?;
    Ok(json!({
        "outcome": "intended", "verdict": "passed",
        "operation_id": operation_id, "marker": marker,
        "intent_digest": intent_digest, "epoch": epoch, "state": "intended",
    }))
}

fn bounded_kind(s: &str) -> bool {
    !s.is_empty() && s.len() <= 64 && !s.chars().any(char::is_control)
}

/// Confirms an intended effect after the external write returned, or marks it `uncertain`
/// when the write was interrupted (REQ-06B-06). One confirm per intent.
pub fn effect_confirm<C: Clock>(
    journal: &Journal,
    key: &str,
    operation_id: &str,
    response_id: &str,
    observed_state: &str,
    clock: &C,
) -> Result<Value> {
    if !is_key(key) {
        return Err("task must be a 16 hex character claim key".into());
    }
    if response_id.len() > 256 || response_id.chars().any(char::is_control) {
        return Err("response_id must be a bounded string without control characters".into());
    }
    if !bounded_kind(observed_state) {
        return Err("observed_state must be a bounded string without control characters".into());
    }
    let events = journal.read_events()?;
    let Some(current) = current_record(&events, key) else {
        return Err("unknown task key; no claim record exists".into());
    };
    let Some((index, effect)) = publish_effect(current, operation_id) else {
        return Err(format!(
            "unknown operation_id {operation_id}; nothing was intended under it"
        ));
    };
    if effect["state"] != json!("intended") {
        return Err(format!(
            "conflict in claim journal: operation_id {operation_id} is already {}",
            effect["state"]
        ));
    }
    let now = now_of(clock);
    let mut record = current.clone();
    record.last_observed_at = now.clone();
    let mut updated = effect.clone();
    let outcome = if observed_state == "uncertain" {
        updated["state"] = json!("uncertain");
        "uncertain"
    } else {
        updated["state"] = json!("confirmed");
        updated["response_id"] = json!(response_id);
        updated["observed_state"] = json!(observed_state);
        "confirmed"
    };
    updated["at"] = json!(now);
    record.effects[index] = updated;
    journal.commit("effect_confirm", &record)?;
    Ok(json!({
        "outcome": outcome, "verdict": "passed",
        "operation_id": operation_id, "state": record.effects[index]["state"],
        "response_id": if outcome == "confirmed" { json!(response_id) } else { Value::Null },
    }))
}

// ---- reconcile (REQ-06B-07, REQ-06B-09, REQ-06B-10) ----

/// What one probe said about one uncertain effect.
#[derive(Debug, PartialEq, Eq)]
enum Probe {
    Found {
        remote_id: String,
    },
    Absent,
    /// Rate limited; `retry_after_s` carries what the probe reported.
    Limited {
        retry_after_s: Option<u64>,
    },
    /// The built-in comment lookup cannot judge this kind (#2099): a pr_create (or any
    /// unknown) marker lives in the PR body, not in a comment, and absence in comments is
    /// NOT a confirmed absence. State stays untouched; --remote-probe judges it.
    Unjudgeable,
    /// The probe could not answer; the effect stays uncertain.
    Failed {
        why: String,
    },
}

/// Reads every comment of the issue (GET only) once — the built-in probe matches all
/// uncertain markers against this single pass, minimizing re-reads (GitHub best
/// practices). `--remote-probe` replaces it in tests and for non-comment kinds.
fn fetch_comments<T: Transport, C: Clock>(
    client: &Client<'_, T, C>,
    t: &TaskRef,
) -> std::result::Result<Vec<(i64, String)>, ForgeError> {
    let mut url = Some(format!(
        "https://api.github.com/repos/{}/{}/issues/{}/comments?per_page=100",
        t.owner, t.repo, t.issue_number
    ));
    let mut comments = Vec::new();
    let mut pages = 0;
    while let Some(u) = url {
        pages += 1;
        if pages > 50 {
            return Err(ForgeError {
                kind: "invalid_input",
                message: "reconcile comment page limit exceeded (50)".into(),
                retryable: false,
            });
        }
        let resp = client.get(&u, None)?;
        let arr = resp
            .body
            .as_ref()
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        for c in &arr {
            if let (Some(id), Some(body)) = (c["id"].as_i64(), c["body"].as_str()) {
                comments.push((id, body.to_string()));
            }
        }
        url = resp.header("link").and_then(|l| next_link(Some(l)));
    }
    Ok(comments)
}

/// Reads every pull request of the repository — `state=all` (#2116: a merged or closed
/// PR carrying the marker is still evidence of creation; scanning only open PRs would
/// report a false absence) — and matches the uncertain markers against this single pass
/// (#2107). A PR list item carries `number` and `body`. The page cap stays: a scan that
/// could not see every page must NOT be read as a confirmed absence, so the caller turns
/// the error into an uncertain effect.
fn fetch_pulls<T: Transport, C: Clock>(
    client: &Client<'_, T, C>,
    t: &TaskRef,
    head: Option<&str>,
) -> std::result::Result<Vec<(i64, String)>, ForgeError> {
    let mut url = Some(match head {
        // #2126: the narrow query for the claim's own branch — usually one page. The
        // value is percent-encoded (#2133): git allows branch names with `#` `&` `+`
        // `%` and non-ASCII bytes, and a raw one would truncate or inject parameters.
        Some(b) => format!(
            "https://api.github.com/repos/{}/{}/pulls?head={}&state=all&per_page=100",
            t.owner,
            t.repo,
            encode_query_component(b)
        ),
        None => format!(
            "https://api.github.com/repos/{}/{}/pulls?state=all&per_page=100",
            t.owner, t.repo
        ),
    });
    let mut pulls = Vec::new();
    let mut pages = 0;
    while let Some(u) = url {
        pages += 1;
        if pages > 50 {
            return Err(ForgeError {
                kind: "invalid_input",
                message: "reconcile pull page limit exceeded (50)".into(),
                retryable: false,
            });
        }
        let resp = client.get(&u, None)?;
        let arr = resp
            .body
            .as_ref()
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        for p in &arr {
            if let (Some(number), Some(body)) = (p["number"].as_i64(), p["body"].as_str()) {
                pulls.push((number, body.to_string()));
            }
        }
        url = resp.header("link").and_then(|l| next_link(Some(l)));
    }
    Ok(pulls)
}

fn run_probe_command(cmd: &str, marker: &str) -> Probe {
    let out = Command::new(cmd)
        .arg(marker)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output();
    let Ok(out) = out else {
        return Probe::Failed {
            why: format!("probe {cmd} cannot be started"),
        };
    };
    let stdout = String::from_utf8_lossy(&out.stdout).trim().to_string();
    match out.status.code() {
        Some(0) => match serde_json::from_str::<Value>(&stdout) {
            Ok(mut v) => match v["remote_id"].take() {
                Value::String(s) if !s.is_empty() => Probe::Found { remote_id: s },
                Value::Number(n) => Probe::Found {
                    remote_id: n.to_string(),
                },
                _ => Probe::Failed {
                    why: "exit 0 without a remote_id".into(),
                },
            },
            Err(_) => Probe::Failed {
                why: "exit 0 with a non-JSON body".into(),
            },
        },
        Some(4) => Probe::Absent,
        Some(5) => Probe::Limited {
            retry_after_s: stdout.parse().ok(),
        },
        code => Probe::Failed {
            why: format!("probe exited {code:?}"),
        },
    }
}

/// The remote lookup the built-in probe can run for a kind (`#2101` gate, extended by
/// #2107): a comment-borne kind is judged from Issue comments, a pr_create marker lives
/// in the PR body and is judged from the pull list, and an unknown kind stays
/// unjudgeable — the conservative default (#2099). A pr_create with a known branch tries
/// the narrow `pulls?head=` query first and only falls back to the full scan when that
/// answers empty (#2126).
fn builtin_lookup(kind: &str) -> Option<&'static str> {
    match kind {
        "comment_post" => Some("comments"),
        "pr_create" => Some("pulls"),
        _ => None,
    }
}

/// The recorded branch the head query may use: plain, bounded, no control or whitespace
/// characters. Anything else (a detached HEAD recorded `None`) keeps the full-scan path.
/// Percent-encodes a query value the RFC 3986 way, with a deliberately smaller safe set
/// than the query grammar allows: unreserved characters (ALPHA / DIGIT / `-` / `.` /
/// `_` / `~`) plus the structural `:` (owner:branch) and `/` (slash branches) stay raw;
/// everything else becomes %XX (uppercase hex over UTF-8 bytes). The grammar would let
/// sub-delims like `&` `+` `=` through raw, but conventional query parsing splits on
/// `&` and decodes `+` as a space — exactly the #2133 hazard list — so they are encoded.
fn encode_query_component(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' | b':' | b'/' => {
                out.push(byte as char)
            }
            _ => out.push_str(&format!("%{byte:02X}")),
        }
    }
    out
}

fn head_branch(branch: Option<&str>) -> Option<&str> {
    branch.filter(|s| {
        !s.is_empty() && s.len() <= 200 && !s.chars().any(|c| c.is_control() || c.is_whitespace())
    })
}

/// Whether a remote body carries the marker. The artifact may spell the operation marker
/// `moai:op` or `moai-op` — compare the parsed identity (operation, project, local id,
/// attempt), not the literal text (#2099); an unparseable marker falls back to literal.
fn marker_matches(body: &str, marker: &str) -> bool {
    match parse_op_markers(marker).first() {
        Some(want) => parse_op_markers(body).iter().any(|m| {
            m.operation == want.operation
                && m.project_id == want.project_id
                && m.local_id == want.local_id
                && m.attempt == want.attempt
        }),
        None => body.contains(marker),
    }
}

/// Reconciles every `uncertain` publish effect against the remote. Reads only — the
/// function has no write path at all, so nothing is ever re-created (REQ-06B-07). The
/// journal is written once, only when at least one effect moved; a rate-limited probe
/// leaves every state unchanged (REQ-06B-09).
pub fn effects_reconcile<T: Transport, C: Clock>(
    journal: &Journal,
    key: &str,
    remote_probe: Option<&str>,
    transport: &T,
    clock: &C,
) -> Result<Value> {
    if !is_key(key) {
        return Err("task must be a 16 hex character claim key".into());
    }
    let events = journal.read_events()?;
    let Some(current) = current_record(&events, key).cloned() else {
        return Err("unknown task key; no claim record exists".into());
    };
    let uncertain: Vec<usize> = current
        .effects
        .iter()
        .enumerate()
        .filter(|(_, e)| e["state"] == json!("uncertain") && e["operation_id"].is_string())
        .map(|(i, _)| i)
        .collect();
    if uncertain.is_empty() {
        return Ok(json!({
            "outcome": "reconciled", "verdict": "not_run", "transitions": [],
            "notes": ["no uncertain effects to reconcile; nothing was probed and nothing written"],
        }));
    }
    let mut record = current.clone();
    let mut transitions = Vec::new();
    let mut retry_after = Vec::new();
    let blocked = Cell::new(false);
    let mut failed = 0;
    let mut left_unjudgeable = false;
    // The built-in probe fetches each remote source lazily, at most once: comments for
    // comment-borne kinds, the narrow `pulls?head=<owner>:<branch>` query for a pr_create
    // whose record knows its branch (#2126), and the full pull-list scan only when the
    // head query answered empty or no branch is known (#2107/#2116 semantics). Kinds with
    // no built-in lookup are never fetched for and never judged (#2099).
    let needs = |source: &str| {
        remote_probe.is_none()
            && uncertain.iter().any(|&i| {
                builtin_lookup(current.effects[i]["kind"].as_str().unwrap_or_default())
                    == Some(source)
            })
    };
    let branch = head_branch(record.worktree.branch.as_deref());
    let client = Client::new(transport, clock, Default::default(), Default::default());
    type Items = std::result::Result<Vec<(i64, String)>, ForgeError>;
    let fetched: RefCell<std::collections::BTreeMap<&'static str, Items>> =
        RefCell::new(Default::default());
    // Fetches one source on first use; `None` when the source has no effects to serve.
    let ensure = |source: &'static str| -> Option<Items> {
        if !fetched.borrow().contains_key(source) {
            let needed = match source {
                "head" => branch.is_some() && needs("pulls"),
                _ => needs(source),
            };
            if !needed {
                return None;
            }
            let r = match source {
                "comments" => fetch_comments(&client, &record.task_ref),
                "head" => fetch_pulls(
                    &client,
                    &record.task_ref,
                    Some(&format!(
                        "{}:{}",
                        record.task_ref.owner,
                        branch.expect("needs_head implies a known branch")
                    )),
                ),
                _ => fetch_pulls(&client, &record.task_ref, None),
            };
            if let Err(e) = &r {
                if e.kind == "blocked" {
                    blocked.set(true);
                }
            }
            fetched.borrow_mut().insert(source, r);
        }
        fetched.borrow().get(source).cloned()
    };
    // The full pull-list scan with #2116 semantics: one match confirms, zero is a
    // confirmed absence, more than one is ambiguous.
    let full_scan = |marker: &str| -> Probe {
        match ensure("pulls") {
            None => Probe::Unjudgeable,
            Some(Err(e)) if e.kind == "blocked" => Probe::Limited {
                retry_after_s: None,
            },
            Some(Err(e)) => Probe::Failed {
                why: e.message.clone(),
            },
            Some(Ok(items)) => {
                let matches: Vec<&(i64, String)> = items
                    .iter()
                    .filter(|(_, body)| marker_matches(body, marker))
                    .collect();
                match matches.len() {
                    1 => Probe::Found {
                        remote_id: matches[0].0.to_string(),
                    },
                    0 => Probe::Absent,
                    _ => Probe::Failed {
                        why: format!(
                            "{n} remote artifacts carry the same operation marker; the winner \
                             is ambiguous",
                            n = matches.len()
                        ),
                    },
                }
            }
        }
    };
    for &i in uncertain.iter() {
        let effect = current.effects[i].clone();
        let marker = effect["marker"].as_str().unwrap_or_default().to_string();
        let operation_id = effect["operation_id"]
            .as_str()
            .unwrap_or_default()
            .to_string();
        let kind = effect["kind"].as_str().unwrap_or_default().to_string();
        let verdict = match remote_probe {
            Some(cmd) => run_probe_command(cmd, &marker),
            None => match builtin_lookup(&kind) {
                None => Probe::Unjudgeable,
                Some("pulls") => {
                    // #2126: the narrow head query first when the branch is known — a hit
                    // confirms with zero full-list GETs, an empty answer falls back to the
                    // full scan, a failed or ambiguous lookup stays uncertain.
                    let head_probe = if branch.is_some() {
                        match ensure("head") {
                            Some(Ok(items)) => {
                                let m: Vec<&(i64, String)> = items
                                    .iter()
                                    .filter(|(_, body)| marker_matches(body, &marker))
                                    .collect();
                                match m.len() {
                                    1 => Some(Probe::Found {
                                        remote_id: m[0].0.to_string(),
                                    }),
                                    0 => None, // fall back to the full scan
                                    _ => Some(Probe::Failed {
                                        why: format!(
                                            "{n} pull requests on the branch carry the same \
                                             operation marker; ambiguous",
                                            n = m.len()
                                        ),
                                    }),
                                }
                            }
                            Some(Err(e)) if e.kind == "blocked" => Some(Probe::Limited {
                                retry_after_s: None,
                            }),
                            Some(Err(e)) => Some(Probe::Failed {
                                why: e.message.clone(),
                            }),
                            None => None,
                        }
                    } else {
                        None
                    };
                    head_probe.unwrap_or_else(|| full_scan(&marker))
                }
                Some(_) => match ensure("comments") {
                    None => Probe::Unjudgeable,
                    Some(Err(e)) if e.kind == "blocked" => Probe::Limited {
                        retry_after_s: None,
                    },
                    Some(Err(e)) => Probe::Failed {
                        why: e.message.clone(),
                    },
                    Some(Ok(items)) => {
                        let matches: Vec<&(i64, String)> = items
                            .iter()
                            .filter(|(_, body)| marker_matches(body, &marker))
                            .collect();
                        match matches.len() {
                            1 => Probe::Found {
                                remote_id: matches[0].0.to_string(),
                            },
                            0 => Probe::Absent,
                            _ => Probe::Failed {
                                why: format!(
                                    "{n} remote artifacts carry the same operation marker; the \
                                     winner is ambiguous",
                                    n = matches.len()
                                ),
                            },
                        }
                    }
                },
            },
        };
        match verdict {
            Probe::Found { remote_id } => {
                let mut updated = effect.clone();
                updated["state"] = json!("confirmed");
                updated["response_id"] = json!(remote_id.clone());
                updated["observed_state"] = json!("marker found on the remote");
                updated["at"] = json!(now_of(clock));
                record.effects[i] = updated.clone();
                transitions.push(json!({
                    "operation_id": operation_id, "from": "uncertain",
                    "to": "confirmed", "response_id": remote_id,
                }));
            }
            Probe::Absent => {
                let mut updated = effect.clone();
                updated["state"] = json!("not_performed");
                updated["observed_state"] = json!("marker confirmed absent");
                updated["at"] = json!(now_of(clock));
                record.effects[i] = updated.clone();
                transitions.push(json!({
                    "operation_id": operation_id, "from": "uncertain", "to": "not_performed",
                }));
            }
            Probe::Limited { retry_after_s } => {
                blocked.set(true);
                if let Some(s) = retry_after_s {
                    retry_after.push(s);
                }
                transitions.push(json!({
                    "operation_id": operation_id, "from": "uncertain", "to": "uncertain",
                    "why": "rate limited; state unchanged until retry-after (REQ-06B-09)",
                }));
            }
            Probe::Unjudgeable => {
                left_unjudgeable = true;
                transitions.push(json!({
                    "operation_id": operation_id, "from": "uncertain", "to": "uncertain",
                    "why": format!(
                        "the built-in probe reads Issue comments only and cannot judge kind \
                         {kind}; pass --remote-probe (REQ-06B-07)"
                    ),
                }));
            }
            Probe::Failed { why } => {
                failed += 1;
                transitions.push(json!({
                    "operation_id": operation_id, "from": "uncertain", "to": "uncertain",
                    "why": format!("probe failed: {why}"),
                }));
            }
        }
    }
    // One event only when something actually moved; a second identical run writes nothing.
    let moved = transitions.iter().any(|t| t["to"] != json!("uncertain"));
    if moved {
        record.last_observed_at = now_of(clock);
        journal.commit("effects_reconcile", &record)?;
    }
    let judged = transitions
        .iter()
        .filter(|t| t["to"] == json!("confirmed") || t["to"] == json!("not_performed"))
        .count();
    let verdict = if left_unjudgeable && judged == 0 && failed == 0 && !blocked.get() {
        "not_run"
    } else if left_unjudgeable || blocked.get() {
        "blocked"
    } else if failed > 0 {
        "uncertain"
    } else {
        "passed"
    };
    let mut notes = Vec::new();
    if left_unjudgeable {
        notes.push(
            "some effects cannot be judged from Issue comments; pass --remote-probe to judge \
             them (REQ-06B-07, #2099)"
                .into(),
        );
    }
    if blocked.get() {
        notes.push(
            "a probe was rate limited; effects keep their state until retry-after (REQ-06B-09)"
                .into(),
        );
    }
    if !retry_after.is_empty() {
        notes.push(format!(
            "retry_after_s reported by the probe: {:?}",
            retry_after
        ));
    }
    Ok(json!({
        "outcome": "reconciled", "verdict": verdict,
        "transitions": transitions, "notes": notes,
    }))
}

/// The `moai:op` markers found in a remote body, re-exported for callers that parse
/// comment bodies directly (the parse itself is 07-B's `parse_op_markers`).
pub fn markers_in(body: &str) -> Vec<crate::forge::outbox::OpMarker> {
    parse_op_markers(body)
}

// ---- CLI entries (`main` wraps the results in the 01-C envelope) ----

fn open_journal(project: &Path) -> Result<Journal> {
    let root = crate::claim::journal_root(project)?;
    let journal = Journal::open(&root)?;
    if !journal.try_lock()? {
        return Err("conflict in claim journal: another process holds the journal lock; the waiting policy is the caller's (REQ-06A-05)".into());
    }
    Ok(journal)
}

pub fn claim_handoff_cli<C: Clock>(
    project: &Path,
    key: &str,
    from_epoch: u64,
    reason: &str,
    force_explicit: bool,
    host_id: Option<&str>,
    clock: &C,
) -> Result<Value> {
    let journal = open_journal(project)?;
    claim_handoff(
        &journal,
        key,
        from_epoch,
        reason,
        force_explicit,
        host_id,
        clock,
    )
}

#[allow(clippy::too_many_arguments)]
pub fn effect_intend_cli<C: Clock>(
    project: &Path,
    key: &str,
    epoch: u64,
    operation: &str,
    project_id: &str,
    local_id: &str,
    attempt: u32,
    kind: &str,
    payload: &[u8],
    clock: &C,
) -> Result<Value> {
    let journal = open_journal(project)?;
    effect_intend(
        &journal, key, epoch, operation, project_id, local_id, attempt, kind, payload, clock,
    )
}

pub fn effect_confirm_cli<C: Clock>(
    project: &Path,
    key: &str,
    operation_id: &str,
    response_id: &str,
    observed_state: &str,
    clock: &C,
) -> Result<Value> {
    let journal = open_journal(project)?;
    effect_confirm(
        &journal,
        key,
        operation_id,
        response_id,
        observed_state,
        clock,
    )
}

pub fn effects_reconcile_cli<T: Transport, C: Clock>(
    project: &Path,
    key: &str,
    remote_probe: Option<&str>,
    transport: &T,
    clock: &C,
) -> Result<Value> {
    let journal = open_journal(project)?;
    effects_reconcile(&journal, key, remote_probe, transport, clock)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// AC-1 (#2133): the unreserved set plus `:` and `/` stays raw; the query hazards —
    /// `#` (truncates), `&` (parameter injection), `+` (decodes as space), `=` `%`
    /// and non-ASCII — become uppercase %XX over UTF-8 bytes.
    #[test]
    fn query_component_encoding_follows_rfc3986_safe_set() {
        assert_eq!(
            encode_query_component("acme:plain-branch/with/slashes"),
            "acme:plain-branch/with/slashes"
        );
        assert_eq!(
            encode_query_component("hotfix/r+2026#v2&w=1"),
            "hotfix/r%2B2026%23v2%26w%3D1"
        );
        assert_eq!(encode_query_component("100%"), "100%25");
        assert_eq!(encode_query_component("a b"), "a%20b");
        assert_eq!(encode_query_component("release~1.rc"), "release~1.rc");
        // Non-ASCII encodes to UTF-8 %XX bytes only — no raw byte above 0x7F survives.
        let encoded = encode_query_component("브랜치");
        assert!(encoded.starts_with("%EB%B8%8C"));
        assert!(encoded
            .bytes()
            .all(|b| b.is_ascii() && (b.is_ascii_alphanumeric() || b == b'%')));
    }
}

