//! PLAN and task DAG admission (Issue #2002, 05-B).
//!
//! A plan orders the tasks of an approved 05-A snapshot and decides, before RUN, whether the
//! work may start: `ready`, `stale` (something it was approved or pinned against changed) or
//! `blocked` (something it needs is missing). The decision is recomputed from its inputs every
//! time; nothing is stored, and execution is always reported as `not_run`.

use crate::digest;
use crate::spec::{content_digest, Canonical, Execution, Outcome, SortedKeys, SpecDocument};
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::{BTreeMap, BTreeSet};
use std::path::Path;
use std::process::Command;

pub type Result<T> = std::result::Result<T, String>;

/// Verification kinds that count as an executable verifier for an acceptance criterion.
const VERIFIER_KINDS: [&str; 4] = ["command", "test", "property", "manual-review"];

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Task {
    pub id: String,
    #[serde(default)]
    pub depends_on: Vec<String>,
    /// Repository-relative paths the task writes.
    #[serde(default)]
    pub write_paths: Vec<String>,
    /// Acceptance criteria of the snapshot this task is verified against.
    #[serde(default)]
    pub verifier_refs: Vec<String>,
    /// Host the task needs, if any; compared with the session's capabilities.
    pub host: Option<String>,
}

/// An approval record. It names what was approved; it never grants host permissions.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Approval {
    pub id: String,
    /// Opaque; owner and epoch fields belong to 06-A.
    pub approver: String,
    pub basis: String,
    pub snapshot_reference: String,
    pub snapshot_digest: String,
    pub allowed_actions: Vec<String>,
    pub revoked: bool,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AdmissionRequest {
    pub protocol_version: u32,
    pub spec: SpecDocument,
    pub tasks: Vec<Task>,
    pub approval: Approval,
    /// Commit id the plan was pinned to (`HEAD^{commit}` at plan time).
    pub expected_revision: String,
    /// Hosts this session can run tasks on.
    #[serde(default)]
    pub capabilities: Vec<String>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct Dangling {
    pub from: String,
    pub to: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct Blocked {
    pub task: String,
    pub reason: &'static str,
    pub suggestion: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct Conflict {
    pub tasks: [String; 2],
    pub paths: Vec<String>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct Plan {
    pub spec_ref: Option<String>,
    pub snapshot_digest: Option<String>,
    pub expected_revision: String,
    /// Topological order (Kahn, ties broken by id); empty when there is a cycle.
    pub order: Vec<String>,
    /// Strongly connected components that form a cycle (Tarjan), each sorted by id.
    pub cycles: Vec<Vec<String>>,
    pub structure: Outcome,
    pub duplicate_ids: Vec<String>,
    pub dangling: Vec<Dangling>,
    pub blocked: Vec<Blocked>,
    /// Task pairs whose write paths overlap with no dependency between them.
    pub parallel_conflicts: Vec<Conflict>,
    pub execution: Execution,
    pub plan_digest: String,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Decision {
    Ready,
    Stale,
    Blocked,
}

/// What 05-C receives for a task admitted to RUN.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct PinnedContract {
    pub spec_ref: String,
    pub plan_digest: String,
    pub task_id: String,
    pub expected_revision: String,
    pub scope: Vec<String>,
    pub approval_ref: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct AdmissionDecision {
    pub decision: Decision,
    pub reasons: Vec<&'static str>,
    pub expected_revision: String,
    pub current_revision: String,
    pub plan: Plan,
    /// One entry per task in order, only when the decision is `ready`.
    pub pinned: Vec<PinnedContract>,
}

fn normalize(path: &str) -> String {
    let mut p = path.trim();
    while let Some(rest) = p.strip_prefix("./") {
        p = rest;
    }
    p.trim_end_matches('/').to_string()
}

// @MX:DEBT: [AUTO] write-scope overlap by path-string prefix; the interface belongs to 06-C #2007
// @MX:CEILING: repository-relative paths; symlinks and case-insensitive filesystems are not seen
// @MX:UPGRADE: replace with the 06-C write_scope interface once it lands
fn paths_overlap(a: &str, b: &str) -> bool {
    a == b || b.starts_with(&format!("{a}/")) || a.starts_with(&format!("{b}/"))
}

/// Tarjan's strongly connected components over `deps` (task -> its dependencies).
fn cycles(deps: &BTreeMap<&str, BTreeSet<&str>>) -> Vec<Vec<String>> {
    struct State<'a> {
        index: BTreeMap<&'a str, usize>,
        low: BTreeMap<&'a str, usize>,
        stack: Vec<&'a str>,
        on_stack: BTreeSet<&'a str>,
        found: Vec<Vec<String>>,
    }
    fn visit<'a>(v: &'a str, deps: &BTreeMap<&'a str, BTreeSet<&'a str>>, s: &mut State<'a>) {
        let i = s.index.len();
        s.index.insert(v, i);
        s.low.insert(v, i);
        s.stack.push(v);
        s.on_stack.insert(v);
        for &w in &deps[v] {
            if !s.index.contains_key(w) {
                visit(w, deps, s);
                let lw = s.low[w];
                let lv = s.low.get_mut(v).expect("visited");
                *lv = (*lv).min(lw);
            } else if s.on_stack.contains(w) {
                let iw = s.index[w];
                let lv = s.low.get_mut(v).expect("visited");
                *lv = (*lv).min(iw);
            }
        }
        if s.low[v] == s.index[v] {
            let mut scc = Vec::new();
            while let Some(w) = s.stack.pop() {
                s.on_stack.remove(w);
                scc.push(w.to_string());
                if w == v {
                    break;
                }
            }
            if scc.len() > 1 || deps[v].contains(v) {
                scc.sort();
                s.found.push(scc);
            }
        }
    }
    let mut s = State {
        index: BTreeMap::new(),
        low: BTreeMap::new(),
        stack: Vec::new(),
        on_stack: BTreeSet::new(),
        found: Vec::new(),
    };
    for &v in deps.keys() {
        if !s.index.contains_key(v) {
            visit(v, deps, &mut s);
        }
    }
    s.found.sort();
    s.found
}

/// Kahn's algorithm with a sorted ready set, so equal inputs give equal orders.
fn order(deps: &BTreeMap<&str, BTreeSet<&str>>) -> Option<Vec<String>> {
    let mut indegree: BTreeMap<&str, usize> = deps.iter().map(|(k, d)| (*k, d.len())).collect();
    let mut dependents: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for (task, ds) in deps {
        for d in ds {
            dependents.entry(d).or_default().push(task);
        }
    }
    let mut ready: BTreeSet<&str> = indegree
        .iter()
        .filter(|(_, n)| **n == 0)
        .map(|(k, _)| *k)
        .collect();
    let mut out = Vec::new();
    while let Some(t) = ready.pop_first() {
        out.push(t.to_string());
        for d in dependents.get(t).into_iter().flatten() {
            let n = indegree.get_mut(d).expect("known task");
            *n -= 1;
            if *n == 0 {
                ready.insert(d);
            }
        }
    }
    (out.len() == deps.len()).then_some(out)
}

/// Every task reachable through `depends_on` from `start`.
fn ancestors<'a>(start: &'a str, deps: &BTreeMap<&'a str, BTreeSet<&'a str>>) -> BTreeSet<&'a str> {
    let mut seen = BTreeSet::new();
    let mut todo: Vec<&str> = deps[start].iter().copied().collect();
    while let Some(t) = todo.pop() {
        if seen.insert(t) {
            todo.extend(deps[t].iter().copied());
        }
    }
    seen
}

/// Builds the plan for the snapshot's tasks. Pure: no files, no git, no clock.
pub fn build_plan(spec: &SpecDocument, tasks: &[Task], expected_revision: &str) -> Plan {
    let mut sorted: Vec<&Task> = tasks.iter().collect();
    sorted.sort_by(|a, b| a.id.cmp(&b.id));
    let mut duplicate_ids: Vec<String> = sorted
        .windows(2)
        .filter(|w| w[0].id == w[1].id)
        .map(|w| w[0].id.clone())
        .collect();
    duplicate_ids.dedup();
    sorted.dedup_by(|a, b| a.id == b.id);
    let by_id: BTreeMap<&str, &Task> = sorted.iter().map(|t| (t.id.as_str(), *t)).collect();

    let mut dangling = Vec::new();
    let mut deps: BTreeMap<&str, BTreeSet<&str>> = BTreeMap::new();
    for t in &sorted {
        let entry = deps.entry(t.id.as_str()).or_default();
        for d in &t.depends_on {
            match by_id.get_key_value(d.as_str()) {
                Some((k, _)) => {
                    entry.insert(k);
                }
                None => dangling.push(Dangling {
                    from: t.id.clone(),
                    to: d.clone(),
                }),
            }
        }
    }

    let criteria: BTreeMap<&str, &crate::spec::Acceptance> =
        spec.acceptance.iter().map(|a| (a.id.as_str(), a)).collect();
    let mut blocked = Vec::new();
    for t in &sorted {
        let mut has_verifier = !t.verifier_refs.is_empty();
        for r in &t.verifier_refs {
            match criteria.get(r.as_str()) {
                None => {
                    dangling.push(Dangling {
                        from: t.id.clone(),
                        to: r.clone(),
                    });
                    has_verifier = false;
                }
                Some(ac) => {
                    let v = &ac.verification;
                    if !VERIFIER_KINDS.contains(&v.kind.as_str()) || v.selector.trim().is_empty() {
                        has_verifier = false;
                    }
                }
            }
        }
        if !has_verifier {
            blocked.push(Blocked {
                task: t.id.clone(),
                reason: "verifier-missing",
                suggestion: format!(
                    "add a task before {} that secures a verifier (command, test, property or manual review) for its acceptance criteria",
                    t.id
                ),
            });
        }
    }

    let order = order(&deps);
    let cycles = if order.is_some() {
        Vec::new()
    } else {
        cycles(&deps)
    };

    let mut parallel_conflicts = Vec::new();
    let reach: BTreeMap<&str, BTreeSet<&str>> =
        deps.keys().map(|k| (*k, ancestors(k, &deps))).collect();
    for (i, a) in sorted.iter().enumerate() {
        for b in &sorted[i + 1..] {
            if reach[a.id.as_str()].contains(b.id.as_str())
                || reach[b.id.as_str()].contains(a.id.as_str())
            {
                continue;
            }
            let mut paths = BTreeSet::new();
            for pa in a.write_paths.iter().map(|p| normalize(p)) {
                for pb in b.write_paths.iter().map(|p| normalize(p)) {
                    if paths_overlap(&pa, &pb) {
                        paths.insert(pa.clone());
                        paths.insert(pb);
                    }
                }
            }
            if !paths.is_empty() {
                parallel_conflicts.push(Conflict {
                    tasks: [a.id.clone(), b.id.clone()],
                    paths: paths.into_iter().collect(),
                });
            }
        }
    }

    let spec_ref = spec.snapshot.as_ref().map(|s| s.reference.clone());
    let snapshot_digest = spec.snapshot.as_ref().map(|s| s.digest.clone());
    let plan_digest = digest(&SortedKeys.bytes(&json!({
        "spec_ref": spec_ref,
        "snapshot_digest": snapshot_digest,
        "expected_revision": expected_revision,
        "tasks": sorted,
    })));
    Plan {
        spec_ref,
        snapshot_digest,
        expected_revision: expected_revision.into(),
        order: order.unwrap_or_default(),
        cycles,
        structure: if duplicate_ids.is_empty() && dangling.is_empty() {
            Outcome::Passed
        } else {
            Outcome::Failed
        },
        duplicate_ids,
        dangling,
        blocked,
        parallel_conflicts,
        execution: Execution::NotRun,
        plan_digest,
    }
}

/// Re-reads everything the approval and the pin rest on and decides. `current_revision` is
/// the repository's `HEAD^{commit}` now (see [`current_revision`]).
pub fn admit(req: &AdmissionRequest, current_revision: &str) -> AdmissionDecision {
    let plan = build_plan(&req.spec, &req.tasks, &req.expected_revision);
    let mut stale: Vec<&'static str> = Vec::new();
    let mut blocked: Vec<&'static str> = Vec::new();
    match (&req.spec.snapshot, req.spec.status.as_str()) {
        (Some(snap), "approved") => {
            if snap.digest != content_digest(&req.spec, &SortedKeys) {
                stale.push("snapshot-digest-mismatch");
            }
            if req.approval.snapshot_reference != snap.reference {
                stale.push("approval-reference-mismatch");
            }
            if req.approval.snapshot_digest != snap.digest {
                stale.push("approval-snapshot-mismatch");
            }
        }
        _ => blocked.push("not-approved"),
    }
    if req.expected_revision != current_revision {
        stale.push("expected-revision-mismatch");
    }
    if req.approval.revoked {
        blocked.push("approval-revoked");
    }
    if !req.approval.allowed_actions.iter().any(|a| a == "run") {
        blocked.push("approval-scope");
    }
    if !plan.cycles.is_empty() {
        blocked.push("cycle");
    }
    if !plan.duplicate_ids.is_empty() {
        blocked.push("duplicate-task-id");
    }
    if !plan.dangling.is_empty() {
        blocked.push("dangling-dependency");
    }
    if !plan.blocked.is_empty() {
        blocked.push("verifier-missing");
    }
    let missing_host = req
        .tasks
        .iter()
        .filter_map(|t| t.host.as_ref())
        .any(|h| !req.capabilities.contains(h));
    if missing_host {
        blocked.push("capability-missing");
    }
    let decision = match (stale.is_empty(), blocked.is_empty()) {
        (false, _) => Decision::Stale,
        (true, false) => Decision::Blocked,
        (true, true) => Decision::Ready,
    };
    let pinned = if decision == Decision::Ready {
        let by_id: BTreeMap<&str, &Task> = req.tasks.iter().map(|t| (t.id.as_str(), t)).collect();
        plan.order
            .iter()
            .map(|id| PinnedContract {
                spec_ref: plan.spec_ref.clone().unwrap_or_default(),
                plan_digest: plan.plan_digest.clone(),
                task_id: id.clone(),
                expected_revision: req.expected_revision.clone(),
                scope: by_id[id.as_str()]
                    .write_paths
                    .iter()
                    .map(|p| normalize(p))
                    .collect(),
                approval_ref: req.approval.id.clone(),
            })
            .collect()
    } else {
        Vec::new()
    };
    stale.extend(blocked);
    AdmissionDecision {
        decision,
        reasons: stale,
        expected_revision: req.expected_revision.clone(),
        current_revision: current_revision.into(),
        plan,
        pinned,
    }
}

/// `git rev-parse --verify --end-of-options HEAD^{commit}` in `project`, run with an argv
/// array (no shell) and the same environment cleaning as `identity`, so `GIT_DIR` and related
/// caller variables cannot point it at another repository (Issue #2043). A missing
/// repository or commit is an error, never a guessed revision; any other git failure is
/// `git failed: <path-free summary>` (`git_failed`, as in #2033).
pub fn current_revision(project: &Path) -> Result<String> {
    let mut cmd = Command::new("git");
    cmd.arg("-C").arg(project).args([
        "rev-parse",
        "--verify",
        "--quiet",
        "--end-of-options",
        "HEAD^{commit}",
    ]);
    crate::identity::scrub_git_env(&mut cmd);
    let out = cmd
        .stdin(std::process::Stdio::null())
        .output()
        .map_err(|_| "git unavailable")?;
    if !out.status.success() {
        // `--quiet` keeps a missing commit silent; "not a git repository" is still printed.
        let quiet = String::from_utf8_lossy(&out.stderr).trim().is_empty();
        let summary = crate::identity::failure_summary(&out.stderr);
        if quiet || summary.starts_with(crate::identity::NOT_A_REPOSITORY) {
            return Err(format!(
                "git rev-parse exited {}",
                out.status.code().unwrap_or(-1)
            ));
        }
        return Err(format!("git failed: {summary}"));
    }
    let rev = String::from_utf8(out.stdout).map_err(|_| "non UTF-8 git output")?;
    let rev = rev.trim();
    let hex = rev
        .bytes()
        .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b));
    if !(hex && (rev.len() == 40 || rev.len() == 64)) {
        return Err("git did not report a commit id".into());
    }
    Ok(rev.to_string())
}

src/pr_link.rs.content:
//! PR body for a claim (Issue #2007, 06-C; REQ-06C-07..11, 13).
//!
//! `pr-body-render` fixes the evidence a PR is judged by: `Refs #<n>`, the Issue URL,
//! logical key, SPEC reference, exact base and candidate SHAs, epoch, the claim token, the
//! checks from VERIFY receipts (05-C #2003), the independent review slot and the not_run list.
//! It never writes a closing keyword: GitHub reads them only on PRs into the default branch,
//! and the leader judges completion (REQ-06C-07/08). The layout follows
//! `.github/pull_request_template.md`; that template is applied by GitHub only on the default
//! branch, so `v2026.11.0` PRs pass this output to `gh pr create --body-file`.
//!
//! The body ends with an operation marker in the form `forge::outbox::parse_op_markers`
//! reads (`<!-- moai-op pr_create:<repository_id>:<task_key>:<epoch> -->`, r33), the lookup
//! key for 06-B's reconcile (REQ-06C-09). [`render_and_record`] records the matching 06-B
//! `effect-intend{kind: pr_create}` (same operation, project, local id and attempt, so
//! `parse_op_markers` reads both markers as one operation) when the record came from the
//! journal. Rendering is not opening: the record moves to `pr_ready` only at the PR's ACK
//! (REQ-06C-11, "PR opening and ACK"), through [`confirm_and_record`] (`pr-confirm`), which confirms
//! the intent with 06-B's `effect_confirm` — or takes an effect a reconcile already
//! confirmed — and never goes further than `pr_ready`. An `uncertain` ACK leaves the state
//! alone; `effects-reconcile` resolves it first.
use crate::claim::{claim_token, ClaimRecord};
use crate::digest;
use crate::forge::policy::Clock;
use crate::run::Receipt;
use crate::verify::CheckResult;
use crate::worktree::{
    commit_update, is_sha, not_written, open_locked_journal, RECORD_UPDATE_OWNER,
};
use serde_json::{json, Value};

type Result<T> = std::result::Result<T, String>;

/// Every GitHub closing keyword; none may appear in a rendered body.
const CLOSING_KEYWORDS: &[&str] = &[
    "close", "closes", "closed", "fix", "fixes", "fixed", "resolve", "resolves", "resolved",
];

pub struct RenderInput<'a> {
    pub base_branch: &'a str,
    pub default_branch: &'a str,
    pub base_sha: &'a str,
    pub candidate_sha: &'a str,
    pub allow_close: bool,
    pub not_run: &'a [String],
    pub review_link: Option<&'a str>,
    /// Extra bullets for the remaining-gap section.
    pub gaps: &'a [String],
    /// `(status, path)` from `git diff --name-status <base>...<candidate>`.
    pub changes: &'a [(String, String)],
}

/// Closing keywords found in `text`, as ASCII words (any case).
pub fn closing_keywords(text: &str) -> Vec<String> {
    text.split(|c: char| !c.is_ascii_alphabetic())
        .map(|w| w.to_ascii_lowercase())
        .filter(|w| CLOSING_KEYWORDS.contains(&w.as_str()))
        .collect()
}

fn cell(s: &str) -> String {
    s.replace('|', "\\|").replace('\n', " ")
}

pub fn operation_id(rec: &ClaimRecord) -> String {
    format!(
        "pr_create:{}:{}:{}",
        rec.task_ref.repository_id, rec.task_key, rec.epoch
    )
}

pub fn render(rec: &ClaimRecord, receipts: &[Receipt], input: &RenderInput) -> Result<Value> {
    for (name, sha) in [
        ("base_sha", input.base_sha),
        ("candidate_sha", input.candidate_sha),
    ] {
        if !is_sha(sha) {
            return Err(format!("invalid {name}: must be 40 lowercase hex"));
        }
    }
    let t = &rec.task_ref;
    let n = t.issue_number;
    let url = format!("https://github.com/{}/{}/issues/{n}", t.owner, t.repo);
    let token = rec
        .comment_id
        .map(|id| format!("`{}`", claim_token(n, id)))
        .unwrap_or_else(|| "없음 (claim 댓글 id가 record에 없다)".into());
    let spec_digest = rec.spec_ref.digest.as_deref().unwrap_or("null");

    let mut rows = Vec::new();
    let mut not_run: Vec<String> = Vec::new();
    for r in receipts {
        for c in &r.checks {
            let exit = match (c.result, c.exit_code) {
                (CheckResult::NotRun, _) => "not_run".to_string(),
                (_, Some(code)) => code.to_string(),
                (_, None) => "none".to_string(),
            };
            let result = serde_json::to_value(c.result)
                .ok()
                .and_then(|v| v.as_str().map(String::from))
                .unwrap_or_default();
            let tests = match (c.tests_passed, c.tests_failed) {
                (Some(p), Some(f)) => format!(" · {p} passed / {f} failed"),
                _ => String::new(),
            };
            rows.push(format!(
                "| `{}` | {exit} | {result}{tests} (receipt {}) |",
                cell(&c.command),
                cell(&r.attempt_id)
            ));
            if c.result == CheckResult::NotRun {
                not_run.push(format!("`{}` (receipt {})", c.command, r.attempt_id));
            }
        }
    }
    if rows.is_empty() {
        rows.push("| (receipt 없음) | not_run | 검사 receipt가 입력되지 않았다 |".into());
    }
    not_run.extend(input.not_run.iter().cloned());
    let not_run_lines = if not_run.is_empty() {
        "- not_run: 없음".to_string()
    } else {
        not_run
            .iter()
            .map(|s| format!("- not_run: {s}"))
            .collect::<Vec<_>>()
            .join("\n")
    };
    let change_rows = if input.changes.is_empty() {
        "| (변경 없음) | base와 candidate 사이에 바뀐 경로가 없다 |".to_string()
    } else {
        input
            .changes
            .iter()
            .map(|(status, path)| format!("| `{}` | {} |", cell(path), cell(status)))
            .collect::<Vec<_>>()
            .join("\n")
    };
    let gap_lines: String = input.gaps.iter().map(|g| format!("- {g}\n")).collect();
    let review = input
        .review_link
        .unwrap_or("<대기: 독립 review 판정 뒤 채운다>");
    let op = operation_id(rec);
    let marker = format!("<!-- moai-op {op} -->");

    let body = format!(
        "Refs #{n}\n\n\
## 대상과 claim\n\n\
- 대상 Issue: #{n} ({lk}) · {url}\n\
- logical_key: `{lk}`\n\
- claim 토큰: {token}\n\
- epoch: {epoch}\n\
- base: `{base_branch}` @ `{base}`\n\
- candidate head: `{head}` (exact SHA, 독립 review가 본 SHA와 같아야 한다)\n\
- SPEC: `{sid}` · revision `{srev}` · digest `{spec_digest}`\n\n\
## 변경\n\n\
| 경로 | git 상태 |\n\
| --- | --- |\n\
{change_rows}\n\n\
## 실행한 검사와 exit\n\n\
| 명령 | exit | 요약 |\n\
| --- | --- | --- |\n\
{rows}\n\n\
## 독립 review\n\n\
- 판정: <대기> · 본 SHA: `{head}`\n\
- 판정 댓글 링크: {review}\n\n\
## not_run / blocked\n\n\
{not_run_lines}\n\n\
## 남은 gap과 위험\n\n\
- PR 개설은 완료가 아니다. 통합과 Issue 종료는 리더가 판정한다.\n\
- reconcile: not_run (렌더는 effect intent만 기록한다. 조회는 `effects-reconcile`이 uncertain effect에만 한다)\n\
{gap_lines}\n\
{marker}\n",
        lk = rec.logical_key,
        epoch = rec.epoch,
        base_branch = input.base_branch,
        base = input.base_sha,
        head = input.candidate_sha,
        sid = rec.spec_ref.id,
        srev = rec.spec_ref.revision,
        rows = rows.join("\n"),
    );
    let found = closing_keywords(&body);
    if !found.is_empty() {
        return Err(format!(
            "conflict in PR body: closing keyword {} would be rendered; nothing written",
            found.join(", ")
        ));
    }
    let mut warnings = Vec::new();
    if input.allow_close {
        warnings.push(if input.base_branch != input.default_branch {
            format!(
                "closing keywords are read only on PRs into the default branch ({}); none were rendered",
                input.default_branch
            )
        } else {
            "closing keywords are never rendered; the leader closes the Issue".to_string()
        });
    }
    Ok(json!({
        "body": body,
        "body_digest": digest(body.as_bytes()),
        "closing_keywords": 0,
        "operation_id": op,
        "marker": marker,
        "reconcile": "not_run: effects-reconcile probes only an uncertain effect",
        "warnings": warnings,
        "record_update_request": {
            "task_key": rec.task_key,
            "epoch": rec.epoch,
            "state": "pr_ready",
            "at": "the pr_create ACK (pr-confirm), not the render",
        },
        "record_update_owner": RECORD_UPDATE_OWNER,
    }))
}

/// The intent payload: what is being created, not the body text, so a re-render after a
/// new commit is the same intent (06-B rejects a different payload under one key).
fn intent_payload(rec: &ClaimRecord, base_branch: &str) -> Vec<u8> {
    json!({
        "operation": "pr_create",
        "task_key": rec.task_key,
        "epoch": rec.epoch,
        "issue_number": rec.task_ref.issue_number,
        "base_branch": base_branch,
    })
    .to_string()
    .into_bytes()
}

/// [`render`] plus the record write (REQ-06C-09): the 06-B `pr_create` intent only; the
/// state stays as it is until the ACK ([`confirm_and_record`]). A record from a file is
/// rendered only; nothing is written for it.
pub fn render_and_record<C: Clock>(
    project: &std::path::Path,
    rec: &ClaimRecord,
    from_journal: bool,
    receipts: &[Receipt],
    input: &RenderInput,
    clock: &C,
) -> Result<Value> {
    let journal = if from_journal {
        Some(open_locked_journal(project)?)
    } else {
        None
    };
    let mut out = render(rec, receipts, input)?;
    let Some(journal) = journal else {
        out["record_update"] = not_written();
        out["effect_intent"] = Value::Null;
        return Ok(out);
    };
    let epoch = u32::try_from(rec.epoch).map_err(|_| "epoch out of range for an operation id")?;
    let intent = crate::handoff::effect_intend(
        &journal,
        &rec.task_key,
        rec.epoch,
        "pr_create",
        &rec.task_ref.repository_id.to_string(),
        &rec.task_key,
        epoch,
        "pr_create",
        &intent_payload(rec, input.base_branch),
        clock,
    )?;
    out["effect_intent"] = json!({
        "operation_id": intent["operation_id"],
        "marker": intent["marker"],
        "state": intent["state"],
        "intent_digest": intent["intent_digest"],
    });
    out["record_update"] = json!({
        "applied": intent["notes"].is_null(),
        "event": "effect_intend",
        "state": "unchanged until the pr_create ACK (pr-confirm)",
    });
    Ok(out)
}

/// `pr-confirm` (REQ-06C-11): the PR was opened and its ACK observed. An `intended`
/// `pr_create` effect is confirmed through 06-B's `effect_confirm` (`uncertain` when the
/// answer was lost); a `confirmed` effect — the reconcile case — is taken as is. Only a
/// confirmed effect moves the record to `pr_ready`.
pub fn confirm_and_record<C: Clock>(
    project: &std::path::Path,
    key: &str,
    operation_id: &str,
    response_id: &str,
    observed_state: &str,
    clock: &C,
) -> Result<Value> {
    let journal = open_locked_journal(project)?;
    let current = journal
        .read_events()?
        .into_iter()
        .rev()
        .find(|e| e.record.task_key == key)
        .map(|e| e.record)
        .ok_or("claim record not found for task")?;
    let effect = current
        .effects
        .iter()
        .find(|e| e["operation_id"] == operation_id && e["kind"] == "pr_create")
        .cloned()
        .ok_or_else(|| {
            format!("unknown operation_id {operation_id}; no pr_create was intended under it")
        })?;
    let confirm = if effect["state"] == "intended" {
        crate::handoff::effect_confirm(
            &journal,
            key,
            operation_id,
            response_id,
            observed_state,
            clock,
        )?
    } else {
        Value::Null
    };
    let state = if confirm.is_null() {
        effect["state"].clone()
    } else {
        confirm["state"].clone()
    };
    let record_update = if state == "confirmed" {
        commit_update(&journal, key, current.epoch, "pr_ready", clock, |r| {
            r.state = "pr_ready".into()
        })?
    } else {
        json!({
            "applied": false,
            "reason": format!("the pr_create effect is {state}; pr_ready waits for a confirmed ACK"),
        })
    };
    Ok(json!({
        "operation_id": operation_id,
        "effect_confirm": confirm,
        "effect_state": state,
        "record_update": record_update,
    }))
}

src/profile.rs.content:
//! Project profile (`.moai-cli/project.yaml`) and its key-level reconfigure delta
//! (Issue #1995, 03-A).
//!
//! Schema v2 keeps the seven v1 keys and adds `interview_revision` and `decisions`,
//! each bounded and run through the same portable filter as the v1 values. A plan
//! decides per key with a baseline/current/desired three-way table. The baseline is
//! the profile `project-apply` last wrote, recorded in
//! `.moai-cli/manifests/profile-baseline.json`; the generation manifest records only
//! the digest, and updating it stays 03-C's job. A file without a recoverable baseline
//! is treated as user-edited throughout: any key except the MoAI-owned
//! `schema_version` lands on a conflict when the input would change it, and nothing is
//! written. General YAML (comments, anchors, block style) keeps the v1
//! behaviour: edits are refused with "existing YAML requires preservation review"
//! until the lossless-editing HOLD is decided.

use crate::{digest, PROJECT_STATE_DIR, SECRET_SHAPES};
use serde::{Deserialize, Serialize};
use serde_json::{json, Map, Value};
use std::{
    fs,
    path::{Path, PathBuf},
};

type Result<T> = std::result::Result<T, String>;
const LIMIT: u64 = 65536;
/// `decisions` stays small by design (a few interview outcomes, not a transcript).
const DECISION_ITEM_LIMIT: usize = 32;
const DECISION_STRING_LIMIT: usize = 256;
const REVISION_LIMIT: usize = 128;
/// Keys owned by the profile schema, as `(key, additive)`: the delta covers exactly these, in
/// this order, and `read_profile` keeps exactly these. An additive key (added after the first
/// profile release) absent from desired, current and baseline is left out of the delta, so a
/// profile without it plans exactly as before the key existed. A length-free slice, so two
/// branches that each add a key merge without a silent length clash (PR #2044). Adding a key
/// touches this table, the `Profile` field and `validate` (#2254).
const PROFILE_KEYS: &[(&str, bool)] = &[
    ("schema_version", false),
    ("project_id", false),
    ("purpose", false),
    ("tools", false),
    ("development_methods", false),
    ("hosts", false),
    ("package_pin", false),
    ("interview_revision", false),
    ("decisions", false),
    ("github_issues", true),
    ("leader", true),
    ("context_max_bytes", true),
    ("archive_grace_days", true),
];

fn managed_keys() -> impl Iterator<Item = &'static str> {
    PROFILE_KEYS.iter().map(|&(key, _)| key)
}

/// Leader supervision settings (rc.2 A3 #2161/#2162, user decision D-2 2026-11-09).
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct LeaderSettings {
    /// Seconds between leader PR checks. A user-chosen value (default 300 when absent),
    /// not a measured one; the tick itself never sleeps — scheduling is the caller's.
    pub pr_check_interval_secs: u64,
}

/// One interview decision recorded under `decisions` (REQ-03A-01). `source` says where
/// the value came from: `repo` (repository convention), `user` (stated in the
/// interview) or `default` (MoAI fallback the user accepted).
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct DecisionRecord {
    pub id: String,
    pub topic: String,
    pub value: String,
    pub source: String,
    pub scope: String,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Profile {
    pub schema_version: u32,
    pub project_id: String,
    pub purpose: String,
    pub tools: Vec<String>,
    pub development_methods: Vec<String>,
    pub hosts: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub package_pin: Option<String>,
    /// Interview revision label linking the profile to one interview run; 03-C's
    /// generation apply surfaces it in the generation manifest.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub interview_revision: Option<String>,
    /// Interview decisions 03-B consumes as its candidate-selection basis. Bounded and
    /// portable-filtered; the interview transcript itself never enters the profile.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub decisions: Vec<DecisionRecord>,
    /// The project chose GitHub Issues, so `github-plan` generates the GitHub templates
    /// when its request carries no explicit flag (Issue #2106, REQ-08B-04). Absent means
    /// no choice was recorded; a profile written before this key reads unchanged.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub github_issues: Option<bool>,
    /// Leader supervision settings (#2162). Absent means the default interval; a profile
    /// written before this key reads unchanged.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub leader: Option<LeaderSettings>,
    /// Byte budget `context-bundle` uses when a request names no `max_bytes` (#2184,
    /// REQ-C8-01). Absent means the built-in 256 KiB default; a profile written before this
    /// key reads unchanged.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub context_max_bytes: Option<u64>,
    /// SPEC auto-archive inactivity window in days (#2187, REQ-D1-01). Absent means
    /// the built-in 90-day default (design §12, Go-inherited); a profile written
    /// before this key reads unchanged.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub archive_grace_days: Option<u64>,
}

/// Key-level reconfigure delta of a plan (REQ-03A-02). Keys are sorted in every list so
/// the plan digest is order-stable; every managed key lands in exactly one list (except
/// `github_issues` and `leader` while absent everywhere, which land in none), and
/// conflict keys (REQ-03A-03) appear only in `conflict`.
#[derive(Clone, Debug, Default, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Delta {
    #[serde(default)]
    pub added: Vec<String>,
    #[serde(default)]
    pub changed: Vec<String>,
    #[serde(default)]
    pub removed: Vec<String>,
    #[serde(default)]
    pub unchanged: Vec<String>,
    #[serde(default)]
    pub conflict: Vec<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Plan {
    pub protocol_version: u32,
    pub profile: Profile,
    pub expected_sha256: Option<String>,
    pub target_binding: String,
    /// create | update | unchanged | conflict
    pub action: String,
    pub delta: Delta,
    pub plan_digest: String,
}

/// What `project-apply` last wrote, read back as the reconfigure baseline. Anything
/// unreadable, foreign or malformed means "no baseline": the three-way table then
/// treats every key as user-edited, and the plan lands on a conservative conflict.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct BaselineRecord {
    schema_version: u32,
    profile_digest: String,
    profile: Value,
}

fn valid_digest(s: &str) -> bool {
    s.len() == 71
        && s.starts_with("sha256:")
        && s[7..]
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}
fn portable(s: &str) -> bool {
    let lower = s.to_ascii_lowercase();
    !s.trim().is_empty()
        && s.len() <= 2048
        && !s.chars().any(char::is_control)
        && !["/", "\\", "~/", ":\\"]
            .iter()
            .chain(SECRET_SHAPES.iter())
            .any(|x| lower.contains(x))
}
fn portable_id(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 80
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_')
}
fn bounded_decision_string(s: &str) -> bool {
    !s.is_empty() && s.len() <= DECISION_STRING_LIMIT && portable(s)
}

/// Accepts both schema versions so v1 files stay readable (fields default); a plan
/// input must be v2, which `plan` checks separately (REQ-03A-08).
fn validate(p: &Profile) -> Result<()> {
    if p.leader
        .as_ref()
        .is_some_and(|l| l.pr_check_interval_secs == 0)
    {
        return Err("leader pr_check_interval_secs must be a positive number".into());
    }
    let decisions_ok = p.decisions.len() <= DECISION_ITEM_LIMIT
        && p.decisions.iter().all(|d| {
            ["repo", "user", "default"].contains(&d.source.as_str())
                && portable_id(&d.id)
                && bounded_decision_string(&d.topic)
                && bounded_decision_string(&d.value)
                && bounded_decision_string(&d.scope)
        });
    if (p.schema_version != 1 && p.schema_version != 2)
        || !portable_id(&p.project_id)
        || !portable(&p.purpose)
        || p.tools.is_empty()
        || p.development_methods.is_empty()
        || p.hosts.is_empty()
        || p.tools.len() > 32
        || p.development_methods.len() > 32
        || p.hosts.len() > 2
        || !p
            .tools
            .iter()
            .chain(&p.development_methods)
            .all(|s| portable(s))
        || !p.hosts.iter().all(|s| s == "claude" || s == "codex")
        || p.package_pin.as_ref().is_some_and(|s| !valid_digest(s))
        || p.interview_revision
            .as_ref()
            .is_some_and(|s| !portable(s) || s.len() > REVISION_LIMIT)
        || !decisions_ok
        || p.context_max_bytes == Some(0)
        || p.archive_grace_days == Some(0)
    {
        return Err("invalid or nonportable profile; no values were logged".into());
    }
    Ok(())
}

/// Resolves a path under `.moai-cli/` and refuses symlinks on the state directory or
/// the path itself.
fn state_path(root: &Path, rel: &str) -> Result<PathBuf> {
    let root = root
        .canonicalize()
        .map_err(|_| "project directory unavailable")?;
    if !root.is_dir() {
        return Err("project must be a directory".into());
    }
    let dir = root.join(PROJECT_STATE_DIR);
    let full = dir.join(rel);
    for path in [&dir, &full] {
        match fs::symlink_metadata(path) {
            Ok(meta) if meta.file_type().is_symlink() => {
                return Err("symlink target refused".into())
            }
            Ok(_) => (),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => (),
            Err(_) => return Err("target metadata unavailable".into()),
        }
    }
    Ok(full)
}
fn target(root: &Path) -> Result<PathBuf> {
    state_path(root, "project.yaml")
}
fn baseline_path(root: &Path) -> Result<PathBuf> {
    state_path(root, "manifests/profile-baseline.json")
}
pub(crate) fn read(path: &Path) -> Result<Option<Vec<u8>>> {
    match fs::metadata(path) {
        Ok(m) if !m.is_file() || m.len() > LIMIT => {
            Err("target is not a bounded regular file".into())
        }
        Ok(_) => fs::read(path)
            .map(Some)
            .map_err(|_| "target read failed".into()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(_) => Err("target metadata unavailable".into()),
    }
}
fn read_baseline(root: &Path) -> Result<Option<Value>> {
    let Ok(Some(bytes)) = read(&baseline_path(root)?) else {
        return Ok(None);
    };
    let Ok(record) = serde_json::from_slice::<BaselineRecord>(&bytes) else {
        return Ok(None);
    };
    if record.schema_version != 1
        || !valid_digest(&record.profile_digest)
        || !record.profile.is_object()
    {
        return Ok(None);
    }
    Ok(Some(record.profile))
}

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
enum KeyDecision {
    KeepCurrent,
    Apply,
    Conflict,
}

/// The baseline/current/desired table from `agents.rs decide()`. The 01-B refactor
/// (#1989) landed a shared `apply::decide`, but it compares digests; this table keeps
/// the same semantics for JSON key values, mirrored on purpose. Missing values are
/// distinct from present values, and drift away from the baseline is never overwritten
/// (REQ-03A-03).
fn decide(
    baseline: Option<&Value>,
    current: Option<&Value>,
    desired: Option<&Value>,
) -> KeyDecision {
    if current == desired || desired == baseline {
        KeyDecision::KeepCurrent
    } else if current == baseline {
        KeyDecision::Apply
    } else {
        KeyDecision::Conflict
    }
}

fn compute_delta(baseline: Option<&Value>, current: Option<&Value>, desired: &Value) -> Delta {
    let empty = Map::new();
    let desired_map = desired.as_object().unwrap_or(&empty);
    let current_map = current.and_then(Value::as_object);
    let baseline_map = baseline.and_then(Value::as_object);
    let mut delta = Delta::default();
    for &(key, additive) in PROFILE_KEYS {
        let d = desired_map.get(key);
        let c = current_map.and_then(|m| m.get(key));
        let b = baseline_map.and_then(|m| m.get(key));
        // An additive key absent from desired, current and baseline is left out of the delta.
        if additive && d.is_none() && c.is_none() && b.is_none() {
            continue;
        }
        // schema_version is MoAI-owned schema state, never user content (leader decision
        // on the #2052 audit): a v1 file upgrades to v2 even without a baseline, while
        // every other key keeps the conservative no-baseline conflict.
        let decision = if key == "schema_version" {
            if c == d {
                KeyDecision::KeepCurrent
            } else {
                KeyDecision::Apply
            }
        } else {
            decide(b, c, d)
        };
        match decision {
            KeyDecision::KeepCurrent => delta.unchanged.push(key.into()),
            KeyDecision::Apply => match (c.is_some(), d.is_some()) {
                (false, true) => delta.added.push(key.into()),
                (true, false) => delta.removed.push(key.into()),
                _ => delta.changed.push(key.into()),
            },
            KeyDecision::Conflict => delta.conflict.push(key.into()),
        }
    }
    for list in [
        &mut delta.added,
        &mut delta.changed,
        &mut delta.removed,
        &mut delta.unchanged,
        &mut delta.conflict,
    ] {
        list.sort();
    }
    delta
}

fn plan_digest(p: &Plan) -> String {
    digest(
        &serde_json::to_vec(&(
            p.protocol_version,
            &p.profile,
            &p.expected_sha256,
            &p.target_binding,
            &p.action,
            &p.delta,
        ))
        .expect("typed plan"),
    )
}
pub fn plan(root: &Path, profile: Profile) -> Result<Plan> {
    validate(&profile)?;
    if profile.schema_version != 2 {
        return Err("invalid or nonportable profile; no values were logged".into());
    }
    let old = read(&target(root)?)?;
    let current = match &old {
        None => None,
        Some(bytes) => {
            // JSON is a YAML 1.2 subset. General YAML and comments are preserved by refusing edits (REQ-03A-04).
            let value: Value = serde_json::from_slice(bytes)
                .map_err(|_| "existing YAML requires preservation review")?;
            if !value.is_object() {
                return Err("invalid profile object".into());
            }
            Some(value)
        }
    };
    let baseline = read_baseline(root)?;
    let desired = serde_json::to_value(&profile).expect("typed profile");
    let delta = compute_delta(baseline.as_ref(), current.as_ref(), &desired);
    let action = if !delta.conflict.is_empty() {
        "conflict"
    } else if old.is_none() {
        "create"
    } else if delta.added.is_empty() && delta.changed.is_empty() && delta.removed.is_empty() {
        "unchanged"
    } else {
        "update"
    };
    let binding = digest(
        target(root)?
            .to_str()
            .ok_or("non UTF-8 project path")?
            .as_bytes(),
    );
    let mut p = Plan {
        protocol_version: 1,
        profile,
        target_binding: binding,
        expected_sha256: old.as_deref().map(digest),
        action: action.into(),
        delta,
        plan_digest: String::new(),
    };
    p.plan_digest = plan_digest(&p);
    Ok(p)
}

/// Rebuilds the profile object for an `update`: applied keys take the desired value,
/// user-preserved keys and unknown user keys stay byte-for-byte as they are.
/// `serde_json` runs with `preserve_order` (Issue #1992, leader RC1 decision H1 = B),
/// so existing keys keep their file order and keys `delta.added` appends them at the
/// end of the object.
fn splice_update(current: &[u8], desired: &Value, delta: &Delta) -> Result<Vec<u8>> {
    let mut value: Value = serde_json::from_slice(current)
        .map_err(|_| "existing YAML requires preservation review")?;
    let map = value.as_object_mut().ok_or("invalid profile object")?;
    let desired_map = desired.as_object().ok_or("invalid profile object")?;
    for key in delta.added.iter().chain(&delta.changed) {
        let v = desired_map.get(key).ok_or("invalid profile object")?;
        map.insert(key.clone(), v.clone());
    }
    for key in &delta.removed {
        map.remove(key);
    }
    let mut out = serde_json::to_vec_pretty(&value).map_err(|_| "encode failed")?;
    out.push(b'\n');
    Ok(out)
}

/// Publishes `after` through the 01-B apply engine (#2071): a replace when the plan saw
/// bytes, an exclusive create when it saw none. The plan's bytes are checked here first,
/// so a change since the preview keeps its stale-plan message; the engine re-checks after
/// staging.
fn write_replace(path: &Path, before: Option<&[u8]>, after: &[u8]) -> Result<()> {
    if read(path)?.as_deref() != before {
        return Err("target changed since plan; re-preview required".into());
    }
    match before {
        Some(_) => crate::apply::publish_replace(path, before, after),
        None => crate::apply::publish_exclusive(path, after),
    }
}

fn write_baseline(
    root: &Path,
    bytes: &[u8],
    profile_value: &Value,
) -> Result<(Option<String>, String)> {
    let record = json!({
        "schema_version": 1,
        "profile_digest": digest(bytes),
        "profile": profile_value,
    });
    let mut out = serde_json::to_vec_pretty(&record).map_err(|_| "encode failed")?;
    out.push(b'\n');
    let path = baseline_path(root)?;
    fs::create_dir_all(path.parent().expect("baseline parent"))
        .map_err(|_| "project state directory unavailable")?;
    let before = read(&path)?;
    let before_digest = before.as_deref().map(digest);
    write_replace(&path, before.as_deref(), &out)?;
    Ok((before_digest, digest(&out)))
}

pub fn apply(root: &Path, p: Plan, confirmed: &str, permission: &str) -> Result<Value> {
    // Caller authorization remains host-owned; this reference is not an authorization verifier.
    if ["", "null", "placeholder"].contains(&permission.trim())
        || permission.len() > 128
        || permission.chars().any(char::is_control)
    {
        return Err("permission reference required".into());
    }
    let current_plan = plan(root, p.profile.clone())?;
    if p.protocol_version != 1
        || confirmed != p.plan_digest
        || plan_digest(&p) != p.plan_digest
        || current_plan.plan_digest != p.plan_digest
    {
        return Err("stale or altered plan; re-preview required".into());
    }
    let target_rel = format!("{PROJECT_STATE_DIR}/project.yaml");
    let baseline_rel = format!("{PROJECT_STATE_DIR}/manifests/profile-baseline.json");
    if p.action == "conflict" {
        // REQ-03A-03: the user-edited keys are named, never their values; nothing is
        // written. REQ-01B-01 mirrored: the refused outcome is recorded so 04-C recovery
        // tooling can see why nothing was applied.
        let request_id = crate::apply::new_request_id("project.apply", &p.plan_digest);
        let mut receipt = crate::apply::Receipt::new(&request_id, "project.apply", root);
        receipt.entry(
            &target_rel,
            "conflict",
            p.expected_sha256.as_deref(),
            None,
            false,
            Some(format!(
                "user-edited keys ({}) preserved",
                p.delta.conflict.join(", ")
            )),
        );
        receipt.status = "refused".into();
        let mut message = format!(
            "conflict in project.yaml: user-edited keys ({}) preserved; nothing applied",
            p.delta.conflict.join(", ")
        );
        if let Err(e) = receipt.save(root) {
            message.push_str(&format!("; receipt not recorded: {e}"));
        }
        return Err(message);
    }
    let request_id = crate::apply::new_request_id("project.apply", &p.plan_digest);
    let mut receipt = crate::apply::Receipt::new(&request_id, "project.apply", root);
    if p.action == "unchanged" {
        // REQ-01B-10: a re-run writes nothing; the receipt records zero publishes.
        let bytes = read(&target(root)?)?.unwrap_or_default();
        receipt.entry(
            &target_rel,
            "unchanged",
            Some(&digest(&bytes)),
            Some(&digest(&bytes)),
            false,
            None,
        );
        receipt.status = "complete".into();
        receipt
            .save(root)
            .map_err(|e| format!("receipt not recorded: {e}"))?;
        return Ok(json!({
            "state": "unchanged",
            "profile_digest": digest(&bytes),
            "interview_revision": p.profile.interview_revision,
            "host_verified": false,
            "receipt": request_id
        }));
    }
    let desired = serde_json::to_value(&p.profile).expect("typed profile");
    let (bytes, state) = match p.action.as_str() {
        "create" => {
            let mut bytes = serde_json::to_vec_pretty(&p.profile).expect("typed profile");
            bytes.push(b'\n');
            (bytes, "created")
        }
        "update" => {
            // REQ-03A-05: replace only when the file still hashes to the plan's expectation.
            let current =
                read(&target(root)?)?.ok_or("stale or altered plan; re-preview required")?;
            if Some(digest(&current)) != p.expected_sha256 {
                return Err("stale or altered plan; re-preview required".into());
            }
            (splice_update(&current, &desired, &p.delta)?, "updated")
        }
        _ => return Err("unknown plan action; re-preview required".into()),
    };
    let path = target(root)?;
    fs::create_dir_all(path.parent().expect("target parent"))
        .map_err(|_| "project state directory unavailable")?;
    let path = target(root)?;
    let before = read(&path)?;
    let before_digest = before.as_deref().map(digest);
    // REQ-01B-08: keep the before bytes before publishing so recovery can restore
    // content; a created file needs no backup (recovery removes it).
    if let Some(b) = before.as_deref() {
        if let Err(e) = crate::apply::save_before_bytes(root, &request_id, &target_rel, b) {
            receipt.entry(
                &target_rel,
                &p.action,
                before_digest.as_deref(),
                None,
                false,
                Some(e.clone()),
            );
            receipt.status = "partial".into();
            let message = format!("backup of {target_rel} before publish failed: {e}");
            return Err(match receipt.save(root) {
                Ok(()) => message,
                Err(se) => format!("{message}; receipt not recorded: {se}"),
            });
        }
    }
    if let Err(e) = write_replace(&path, before.as_deref(), &bytes) {
        receipt.entry(
            &target_rel,
            &p.action,
            before_digest.as_deref(),
            None,
            false,
            Some(e.clone()),
        );
        receipt.status = "partial".into();
        return Err(match receipt.save(root) {
            Ok(()) => e,
            Err(se) => format!("{e}; receipt not recorded: {se}"),
        });
    }
    receipt.entry(
        &target_rel,
        &p.action,
        before_digest.as_deref(),
        Some(&digest(&bytes)),
        true,
        None,
    );
    // The baseline record lives under manifests/ and coexists with the 01-B receipt
    // store under receipts/. REQ-01B-08 mirrored for the record itself: a replaced
    // baseline keeps its before bytes, so recovery restores the whole pre-update state
    // instead of stopping halfway between project.yaml and the baseline.
    let baseline_before_bytes = read(&baseline_path(root)?).ok().flatten();
    if let Some(b) = baseline_before_bytes.as_deref() {
        if let Err(e) = crate::apply::save_before_bytes(root, &request_id, &baseline_rel, b) {
            receipt.entry(&baseline_rel, "replace", None, None, false, Some(e.clone()));
            receipt.status = "partial".into();
            let message = format!(
                "partial apply: applied [project.yaml]; failed at {baseline_rel} backup: {e}"
            );
            return Err(match receipt.save(root) {
                Ok(()) => message,
                Err(se) => format!("{message}; receipt not recorded: {se}"),
            });
        }
    }
    match write_baseline(root, &bytes, &desired) {
        Ok((baseline_before_digest, after_baseline)) => {
            receipt.entry(
                &baseline_rel,
                if baseline_before_digest.is_some() {
                    "replace"
                } else {
                    "create"
                },
                baseline_before_digest.as_deref(),
                Some(&after_baseline),
                true,
                None,
            );
            receipt.status = "complete".into();
        }
        Err(e) => {
            receipt.entry(&baseline_rel, "create", None, None, false, Some(e.clone()));
            receipt.status = "partial".into();
            let message =
                format!("partial apply: applied [project.yaml]; failed at {baseline_rel}: {e}");
            return Err(match receipt.save(root) {
                Ok(()) => message,
                Err(se) => format!("{message}; receipt not recorded: {se}"),
            });
        }
    }
    if let Err(e) = receipt.save(root) {
        return Err(format!(
            "published {target_rel} but its receipt was not recorded: {e}"
        ));
    }
    Ok(json!({
        "state": state,
        "profile_digest": digest(&bytes),
        "interview_revision": p.profile.interview_revision,
        "host_verified": false,
        "receipt": request_id,
        "next_actions": ["update profile_sha256 and interview_revision in .moai-cli/manifests/generation.json through the 03-C generation apply; project.apply does not write the manifest"]
    }))
}

/// Reads the existing profile, keeping only known keys. Unknown user keys are left in the
/// file untouched; the raw bytes are returned so callers can bind to the exact revision.
pub fn read_profile(root: &Path) -> Result<(Profile, Vec<u8>)> {
    let bytes = read(&target(root)?)?.ok_or("project profile missing")?;
    let value: Value =
        serde_json::from_slice(&bytes).map_err(|_| "existing YAML requires preservation review")?;
    let map = value.as_object().ok_or("invalid profile object")?;
    if map.get("package_pin").is_some_and(Value::is_null) {
        return Err("explicit null pin is invalid".into());
    }
    let filtered: serde_json::Map<String, Value> = map
        .iter()
        .filter(|(k, _)| managed_keys().any(|m| m == k.as_str()))
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    let profile: Profile =
        serde_json::from_value(Value::Object(filtered)).map_err(|_| "invalid profile")?;
    validate(&profile)?;
    Ok((profile, bytes))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn record(id: &str, value: &str, source: &str) -> DecisionRecord {
        DecisionRecord {
            id: id.into(),
            topic: "tools".into(),
            value: value.into(),
            source: source.into(),
            scope: "project".into(),
        }
    }

    fn v2() -> Profile {
        Profile {
            schema_version: 2,
            project_id: "demo".into(),
            purpose: "Build a small editor".into(),
            tools: vec!["Rust".into()],
            development_methods: vec!["TDD".into()],
            hosts: vec!["claude".into()],
            package_pin: None,
            interview_revision: Some("r1".into()),
            decisions: vec![record("d1", "Rust", "user")],
            github_issues: None,
            leader: None,
            context_max_bytes: None,
            archive_grace_days: None,
        }
    }

    /// `PROFILE_KEYS` lists exactly the `Profile` fields, and the additive ones are exactly
    /// the fields a v2 profile may omit (#2254: the table replaced three hand-kept lists).
    #[test]
    fn profile_keys_match_the_profile_fields() {
        let full = Profile {
            package_pin: Some("pin".into()),
            github_issues: Some(true),
            leader: Some(LeaderSettings {
                pr_check_interval_secs: 300,
            }),
            context_max_bytes: Some(1),
            archive_grace_days: Some(7),
            ..v2()
        };
        let fields: Vec<String> = serde_json::to_value(&full)
            .unwrap()
            .as_object()
            .unwrap()
            .keys()
            .cloned()
            .collect();
        let mut keys: Vec<String> = managed_keys().map(String::from).collect();
        let mut sorted = fields.clone();
        sorted.sort();
        keys.sort();
        assert_eq!(keys, sorted);
        let additive: Vec<&str> = PROFILE_KEYS
            .iter()
            .filter(|(_, a)| *a)
            .map(|(k, _)| *k)
            .collect();
        assert_eq!(
            additive,
            [
                "github_issues",
                "leader",
                "context_max_bytes",
                "archive_grace_days"
            ]
        );
    }

    /// `read_profile` keeps the `PROFILE_KEYS` and leaves a user's own key out, so the
    /// strict `Profile` still reads a file that carries one.
    #[test]
    fn read_profile_skips_keys_outside_the_table() {
        let tmp = tempfile::tempdir().unwrap();
        let mut file = serde_json::to_value(v2()).unwrap();
        file["my_own_key"] = json!("kept in the file");
        let path = tmp.path().join(PROJECT_STATE_DIR).join("project.yaml");
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(&path, serde_json::to_vec(&file).unwrap()).unwrap();
        let (profile, bytes) = read_profile(tmp.path()).unwrap();
        assert_eq!(profile.project_id, "demo");
        assert!(String::from_utf8(bytes).unwrap().contains("my_own_key"));
    }

    #[test]
    fn key_decisions_mirror_the_agents_table() {
        let v = |s: &str| Value::String(s.into());
        assert_eq!(decide(None, None, Some(&v("new"))), KeyDecision::Apply);
        assert_eq!(
            decide(Some(&v("old")), Some(&v("old")), Some(&v("new"))),
            KeyDecision::Apply
        );
        // A user edit away from the baseline wins over an input that agrees with the baseline.
        assert_eq!(
            decide(Some(&v("old")), Some(&v("user")), Some(&v("old"))),
            KeyDecision::KeepCurrent
        );
        assert_eq!(
            decide(Some(&v("old")), Some(&v("new")), Some(&v("new"))),
            KeyDecision::KeepCurrent
        );
        // Without a baseline every pending change is a conflict (conservative).
        assert_eq!(
            decide(None, Some(&v("user")), Some(&v("new"))),
            KeyDecision::Conflict
        );
        assert_eq!(
            decide(Some(&v("old")), Some(&v("user")), Some(&v("new"))),
            KeyDecision::Conflict
        );
        assert_eq!(
            decide(Some(&v("old")), None, Some(&v("new"))),
            KeyDecision::Conflict
        );
        assert_eq!(
            decide(Some(&v("old")), Some(&v("old")), None),
            KeyDecision::Apply
        );
    }

    #[test]
    fn v1_and_v2_profiles_validate_but_v1_files_stay_readable() {
