//! Project-unit `moai` skill copy (Issue #2242, EP-I / P04 HOLD).
//!
//! 04-B `update.rs` copies the `moai` skill package into the HOME skill
//! folders only; project-level copies (`.claude/skills/moai`,
//! `.agents/skills/moai` inside a project) are the P04 HOLD. This module
//! designs and exercises plan/apply/revert for those project copies with two
//! hard limits:
//!
//! - REQ-I5-01: every operation carries `opt_in` and refuses before touching
//!   anything unless it is `true`. The default is off: nothing is written
//!   without the explicit flag, and a mutation that ignores the flag fails
//!   the tests (#2226).
//! - The P04 HOLD is NOT released here: the project root and home are
//!   caller-supplied parameters, so tests run in temporary directories and
//!   real HOME paths are never defaults. Applying to the developer's actual
//!   project/home stays blocked until the HOLD is released.
//!
//! Reading order (AC-2): when both the home copy and the project copy
//! exist, the project copy is what a session in that project reads — Claude
//! documents project skills taking precedence over personal ones and Codex
//! walks from the working directory up toward `$HOME/.agents/skills`, so
//! the nearest copy wins. Both copies stay independent per host (independent
//! copy per host; symlinks refused — design textonly §4 L166). The plan reports
//! the duplication instead of guessing.
//!
//! Rollback (AC-1 revert): apply stores the before bytes of every
//! replaced folder under `<project>/.moai-cli/project-skill-rollback/
//! <request-id>/before/<host>/` plus a receipt JSON; revert restores from
//! that record (a created folder is removed, a replaced folder is restored
//! byte for byte).

use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{
    fs,
    path::{Path, PathBuf},
};

type Result<T> = std::result::Result<T, String>;

pub const PROJECT_SKILL_SCHEMA_VERSION: u32 = 1;
/// The reading-order note carried on duplicated pairs (AC-2).
pub const READING_ORDER_NOTE: &str =
    "project copy takes precedence over the home copy for sessions in this project (host-documented discovery order)";

fn opt_in_error() -> String {
    "explicit opt-in required; nothing written".into()
}

fn host_folder(host: &str) -> Result<&'static str> {
    match host {
        "claude" => Ok(".claude/skills"),
        "codex" => Ok(".agents/skills"),
        other => Err(format!("unknown host {other}; supported: claude, codex")),
    }
}

/// Plan/apply/revert request (#2242). The project root and home are
/// caller-supplied so tests run in temporary directories; nothing defaults
/// to the real HOME.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ProjectSkillRequest {
    pub protocol_version: u32,
    /// REQ-I5-01: must be true or every operation refuses before any write.
    pub opt_in: bool,
    /// Caller-supplied project root (tests pass a temporary directory).
    pub project_root: PathBuf,
    /// Caller-supplied home root; omitted means the home state is not scanned.
    pub home: Option<PathBuf>,
    /// claude | codex — which host folders to plan or copy.
    pub hosts: Vec<String>,
    /// Staged `moai` skill package source directory (caller-owned).
    pub source_dir: PathBuf,
}

/// One planned copy with the reading-order context (AC-2).
#[derive(Clone, Debug, Serialize)]
pub struct ProjectSkillEntry {
    pub host: String,
    /// Project skill folder, e.g. `.claude/skills/moai`.
    pub path: String,
    /// create | unchanged | replace
    pub action: String,
    /// Staged package digest.
    pub source_sha256: String,
    /// Current project copy digest (None when absent).
    pub current_sha256: Option<String>,
    /// Home copy digest (None when absent or home not scanned).
    pub home_sha256: Option<String>,
    /// True when both the home and project copies exist.
    pub duplicated_with_home: bool,
    pub reading_order_note: String,
}

#[derive(Clone, Debug, Serialize)]
pub struct ProjectSkillPlan {
    pub protocol_version: u32,
    pub opt_in: bool,
    pub package_digest: String,
    pub entries: Vec<ProjectSkillEntry>,
    pub warnings: Vec<String>,
}

fn project_skill_dir(root: &Path, host: &str) -> Result<PathBuf> {
    Ok(root.join(host_folder(host)?).join("moai"))
}

fn validate(req: &ProjectSkillRequest) -> Result<()> {
    if req.protocol_version != PROJECT_SKILL_SCHEMA_VERSION {
        return Err("unsupported protocol_version; supported: 1".into());
    }
    if req.hosts.is_empty() || req.hosts.len() > 2 {
        return Err("hosts must list one or two entries of claude, codex".into());
    }
    if !req.hosts.iter().all(|h| host_folder(h).is_ok()) {
        return Err("unknown host in hosts; supported: claude, codex".into());
    }
    if req.source_dir.as_os_str().is_empty() {
        return Err("source directory missing".into());
    }
    Ok(())
}

/// Digest of an installed `moai` skill directory (None when absent). The
/// staged-package digest rules apply, so both sides of the comparison use
/// the same algorithm.
fn installed_digest(dir: &Path) -> Result<Option<String>> {
    if !dir.is_dir() {
        return Ok(None);
    }
    let staged = crate::update::stage_package(dir)?;
    Ok(Some(staged.digest))
}

/// `project-skill-plan` (#2242 AC-1): read-only judgment per requested host —
/// the project copy digest, the home copy digest (reading-order report only),
/// and the action (create | unchanged | replace) against the staged package.
/// Writes nothing.
pub fn project_skill_plan(req: &ProjectSkillRequest) -> Result<ProjectSkillPlan> {
    validate(req)?;
    let staged = crate::update::stage_package(&req.source_dir)?;
    let mut entries = Vec::new();
    let mut warnings = Vec::new();
    for host in &req.hosts {
        let folder = host_folder(host)?;
        let project_dir = project_skill_dir(&req.project_root, host)?;
        let project_digest = installed_digest(&project_dir)?;
        let action = match project_digest.as_deref() {
            None => "create",
            Some(d) if d == staged.digest => "unchanged",
            Some(_) => "replace",
        };
        let mut home_sha256 = None;
        let mut duplicated = false;
        let mut note = String::new();
        if let Some(home) = &req.home {
            let home_digest = installed_digest(&project_skill_dir(home, host)?)?;
            duplicated = home_digest.is_some() && project_digest.is_some();
            if duplicated {
                note = READING_ORDER_NOTE.into();
            }
            home_sha256 = home_digest;
        }
        entries.push(ProjectSkillEntry {
            host: host.clone(),
            path: format!("{folder}/moai"),
            action: action.into(),
            source_sha256: staged.digest.clone(),
            current_sha256: project_digest,
            home_sha256,
            duplicated_with_home: duplicated,
            reading_order_note: note,
        });
        if duplicated {
            warnings.push(format!(
                "both the home and project copies exist for {host}; the project copy takes precedence for sessions in this project"
            ));
        }
    }
    Ok(ProjectSkillPlan {
        protocol_version: PROJECT_SKILL_SCHEMA_VERSION,
        opt_in: req.opt_in,
        package_digest: staged.digest,
        entries,
        warnings,
    })
}

/// Copies the staged skill tree into `dest` with the same refusals the
/// digest applies (symlink/special/size), through a temp directory and an
/// atomic rename: the destination is replaced whole or not at all. The
/// destination must not exist when called (the caller decides create vs
/// replace). Returns the number of files copied.
fn copy_tree_into_vacant(src: &Path, dest: &Path) -> Result<usize> {
    let parent = dest.parent().ok_or("destination parent unavailable")?;
    fs::create_dir_all(parent).map_err(|_| "destination directory unavailable".to_string())?;
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let temp = parent.join(format!(
        ".moai-skillcopy-{}-{nanos}.tmp",
        std::process::id()
    ));
    fs::create_dir(&temp).map_err(|_| "temporary directory refused".to_string())?;
    let mut count = 0usize;
    let copy_result = copy_tree(src, &temp, 0, &mut count);
    if let Err(e) = copy_result {
        let _ = fs::remove_dir_all(&temp);
        return Err(e);
    }
    match fs::rename(&temp, dest) {
        Ok(()) => Ok(count),
        Err(_) => {
            let _ = fs::remove_dir_all(&temp);
            Err("conflict in skill copy: existing_skill".into())
        }
    }
}

fn copy_tree(src: &Path, dest: &Path, depth: usize, count: &mut usize) -> Result<()> {
    if depth > 16 {
        return Err("skill tree nesting limit exceeded".into());
    }
    fs::create_dir_all(dest).map_err(|_| "destination directory unavailable".to_string())?;
    for entry in fs::read_dir(src).map_err(|_| "source directory unavailable".to_string())? {
        let entry = entry.map_err(|_| "source directory unavailable".to_string())?;
        let meta = fs::symlink_metadata(entry.path())
            .map_err(|_| "source metadata unavailable".to_string())?;
        if meta.file_type().is_symlink() {
            return Err("package symlink refused".into());
        }
        if meta.is_dir() {
            copy_tree(
                &entry.path(),
                &dest.join(entry.file_name()),
                depth + 1,
                count,
            )?;
        } else if meta.is_file() {
            if meta.len() > 262_144 {
                return Err("package file exceeds the size limit".into());
            }
            fs::copy(entry.path(), dest.join(entry.file_name()))
                .map_err(|_| "destination write failed".to_string())?;
            *count += 1;
        } else {
            return Err("package special file refused".into());
        }
    }
    Ok(())
}

/// One applied copy with what revert needs (AC-1 revert): the action
/// taken, the before digest, and the backup directory holding the pre-apply
/// bytes for `replace` (a `create` is reverted by removing the directory).
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AppliedCopy {
    pub host: String,
    pub path: String,
    /// create | replace | unchanged
    pub action: String,
    pub before_sha256: Option<String>,
    pub after_sha256: Option<String>,
    /// Rollback-relative backup dir for `replace` (None otherwise).
    pub backup_dir: Option<String>,
    pub files_copied: usize,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ProjectSkillApplyReceipt {
    pub schema_version: u32,
    pub request_id: String,
    pub package_digest: String,
    pub applied: Vec<AppliedCopy>,
    /// complete | partial — partial names what landed before the failure.
    pub status: String,
}

/// Revert request (#2242 AC-1 revert): names the persisted rollback
/// receipt to undo.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ProjectSkillRevertRequest {
    pub protocol_version: u32,
    pub project_root: PathBuf,
    /// The request_id from the apply receipt.
    pub request_id: String,
}

fn rollback_root(project_root: &Path) -> PathBuf {
    project_root.join(".moai-cli/project-skill-rollback")
}

/// `project-skill-apply` (#2242, REQ-I5-01 gate): re-plans, refuses without
/// `opt_in` before any write, refuses when the plan changed since preview,
/// then copies each requested host folder (backup → remove → rename for
/// `replace`) and persists the rollback receipt under
/// `<project>/.moai-cli/project-skill-rollback/<request_id>/receipt.json`.
pub fn project_skill_apply(req: &ProjectSkillRequest) -> Result<ProjectSkillApplyReceipt> {
    if !req.opt_in {
        // REQ-I5-01: the default is off — refuse before any write.
        return Err(opt_in_error());
    }
    validate(req)?;
    let plan = project_skill_plan(req)?;
    let root = req
        .project_root
        .canonicalize()
        .map_err(|_| "project directory unavailable".to_string())?;
    let staged = crate::update::stage_package(&req.source_dir)?;
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let request_id = format!("project-skill-{}-{nanos}", &staged.digest[..12]);
    let rollback_dir = rollback_root(&root).join(&request_id);
    fs::create_dir_all(&rollback_dir).map_err(|_| "rollback directory unavailable".to_string())?;

    let mut applied: Vec<AppliedCopy> = Vec::new();
    let step_failed =
        |applied: &[AppliedCopy], rollback_dir: &Path, host: &str, e: &str| -> String {
            // REQ-01B-06 style: persist what landed (status partial) so revert
            // can undo it; if even the receipt cannot be written, say so.
            let receipt = ProjectSkillApplyReceipt {
                schema_version: PROJECT_SKILL_SCHEMA_VERSION,
                request_id: String::new(),
                package_digest: String::new(),
                applied: applied.to_vec(),
                status: "partial".into(),
            };
            let receipt = serde_json::to_vec_pretty(&receipt)
                .map(|mut b| {
                    b.push(b'\n');
                    b
                })
                .unwrap_or_default();
            let receipt_path = rollback_dir.join("receipt.json");
            let note = match fs::write(&receipt_path, &receipt) {
                Ok(()) => format!("rollback receipt {}", rollback_dir.display()),
                Err(se) => format!("receipt not recorded: {se}"),
            };
            format!(
                "partial apply: applied [{}]; failed at {host}: {e}; {note}",
                applied
                    .iter()
                    .map(|a| a.host.as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            )
        };

    for entry in &plan.entries {
        let folder = host_folder(&entry.host)?;
        let dest = project_skill_dir(&root, &entry.host)?;
        match entry.action.as_str() {
            "unchanged" => {
                applied.push(AppliedCopy {
                    host: entry.host.clone(),
                    path: format!("{folder}/moai"),
                    action: "unchanged".into(),
                    before_sha256: entry.current_sha256.clone(),
                    after_sha256: Some(staged.digest.clone()),
                    backup_dir: None,
                    files_copied: 0,
                });
            }
            "create" => match copy_tree_into_vacant(&req.source_dir, &dest) {
                Ok(count) => {
                    applied.push(AppliedCopy {
                        host: entry.host.clone(),
                        path: format!("{folder}/moai"),
                        action: "create".into(),
                        before_sha256: None,
                        after_sha256: Some(staged.digest.clone()),
                        backup_dir: None,
                        files_copied: count,
                    });
                }
                Err(e) => {
                    applied.push(AppliedCopy {
                        host: entry.host.clone(),
                        path: format!("{folder}/moai"),
                        action: "create".into(),
                        before_sha256: None,
                        after_sha256: None,
                        backup_dir: None,
                        files_copied: 0,
                    });
                    return Err(step_failed(&applied, &rollback_dir, &entry.host, &e));
                }
            },
            _ => {
                // replace: keep the before bytes for revert, move the old tree
                // aside atomically, then rename the staged tree in.
                let backup_rel = format!("before/{folder}");
                let backup_abs = rollback_dir.join(&backup_rel);
                fs::create_dir_all(&backup_abs)
                    .map_err(|_| "rollback backup directory unavailable".to_string())?;
                let mut backup_count = 0usize;
                let backup_result = copy_tree(&dest, &backup_abs, 0, &mut backup_count);
                if let Err(e) = backup_result {
                    return Err(step_failed(
                        &applied,
                        &rollback_dir,
                        &entry.host,
                        &format!("rollback backup failed: {e}"),
                    ));
                }
                let replaced_dir = rollback_dir.join(format!("replaced/{folder}"));
                fs::create_dir_all(replaced_dir.parent().expect("replaced parent"))
                    .map_err(|_| "rollback replaced directory unavailable".to_string())?;
                fs::rename(&dest, &replaced_dir)
                    .map_err(|_| "existing skill directory move failed".to_string())?;
                match copy_tree_into_vacant(&req.source_dir, &dest) {
                    Ok(count) => {
                        applied.push(AppliedCopy {
                            host: entry.host.clone(),
                            path: format!("{folder}/moai"),
                            action: "replace".into(),
                            before_sha256: entry.current_sha256.clone(),
                            after_sha256: Some(staged.digest.clone()),
                            backup_dir: Some(backup_rel.clone()),
                            files_copied: count,
                        });
                    }
                    Err(e) => {
                        // Roll the move back: the old tree returns to its place.
                        let _ = fs::remove_dir_all(&dest);
                        let _ = fs::rename(&replaced_dir, &dest);
                        return Err(step_failed(&applied, &rollback_dir, &entry.host, &e));
                    }
                }
            }
        }
    }

    let receipt = ProjectSkillApplyReceipt {
        schema_version: PROJECT_SKILL_SCHEMA_VERSION,
        request_id: request_id.clone(),
        package_digest: staged.digest,
        applied: applied.clone(),
        status: "complete".to_string(),
    };
    let receipt_path = rollback_dir.join("receipt.json");
    let bytes = serde_json::to_vec_pretty(&receipt).map_err(|_| "encode failed".to_string())?;
    fs::write(&receipt_path, bytes).map_err(|_| "receipt write failed".to_string())?;
    Ok(receipt)
}

/// `project-skill-revert` (#2242 AC-1 revert): restores what one apply
/// changed — a created folder is removed, a replaced folder is restored
/// byte for byte from the rollback backup. Reads only the persisted
/// receipt; executes only local file moves.
pub fn project_skill_revert(req: &ProjectSkillRevertRequest) -> Result<Value> {
    if req.protocol_version != PROJECT_SKILL_SCHEMA_VERSION {
        return Err("unsupported protocol_version; supported: 1".into());
    }
    let project_root = req.project_root.clone();
    let request_id = req.request_id.clone();
    if request_id.is_empty()
        || request_id.contains("..")
        || request_id.contains('/')
        || request_id.contains('\\')
    {
        return Err("invalid request id; refused".into());
    }
    let root = project_root
        .canonicalize()
        .map_err(|_| "project directory unavailable".to_string())?;
    let rollback_dir = rollback_root(&root).join(request_id.as_str());
    let receipt_path = rollback_dir.join("receipt.json");
    let bytes = fs::read(&receipt_path)
        .map_err(|_| "receipt not found; inspect the rollback directory".to_string())?;
    let receipt: ProjectSkillApplyReceipt = serde_json::from_slice(&bytes)
        .map_err(|_| "receipt unreadable; inspect the rollback directory".to_string())?;
    let mut reverted = Vec::new();
    for a in receipt.applied.iter().rev() {
        let dest = project_skill_dir(&root, &a.host)?;
        match a.action.as_str() {
            "create" => {
                if dest.is_dir() {
                    fs::remove_dir_all(&dest).map_err(|_| "revert remove failed".to_string())?;
                    reverted.push(format!("{} (created, removed)", a.host));
                }
            }
            "replace" => {
                let backup_abs = rollback_dir.join(
                    a.backup_dir
                        .as_deref()
                        .ok_or("receipt backup missing; inspect the rollback directory")?,
                );
                if !backup_abs.is_dir() {
                    return Err("receipt backup missing; inspect the rollback directory".into());
                }
                let trash = rollback_dir.join(format!("post-revert/{}", a.host));
                fs::create_dir_all(&trash).map_err(|_| "revert staging unavailable".to_string())?;
                // Move the applied tree aside, then move the backup tree back.
                fs::rename(&dest, trash.join("applied"))
                    .map_err(|_| "revert move failed".to_string())?;
                fs::rename(&backup_abs, &dest).map_err(|_| "revert restore failed".to_string())?;
                reverted.push(format!("{} (replaced, restored)", a.host));
            }
            "unchanged" => {}
            other => return Err(format!("unknown action {other} in the receipt")),
        }
    }
    Ok(json!({
        "state": "reverted",
        "request_id": request_id.clone(),
        "reverted": reverted,
        "network": "none",
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn request(
        project: &Path,
        home: Option<&Path>,
        source: &Path,
        opt_in: bool,
    ) -> ProjectSkillRequest {
        ProjectSkillRequest {
            protocol_version: PROJECT_SKILL_SCHEMA_VERSION,
            opt_in,
            project_root: project.to_path_buf(),
            home: home.map(|h| h.to_path_buf()),
            hosts: vec!["claude".into()],
            source_dir: source.to_path_buf(),
        }
    }

    fn write_source(dir: &Path) {
        fs::create_dir_all(dir.join("references")).unwrap();
        fs::write(
            dir.join("SKILL.md"),
            b"---\nname: moai\ndescription: fixture\n---\n",
        )
        .unwrap();
        fs::write(dir.join("references/a.md"), b"a").unwrap();
    }

    #[test]
    fn opt_in_off_writes_nothing_and_apply_revert_round_trip() {
        let project = tempfile::TempDir::new().unwrap();
        let home = tempfile::TempDir::new().unwrap();
        let source = tempfile::TempDir::new().unwrap();
        write_source(source.path());
        let req = request(project.path(), Some(home.path()), source.path(), false);

        // Plan is read-only even with opt-in off.
        let plan = project_skill_plan(&req).unwrap();
        assert_eq!(plan.entries.len(), 1);
        assert_eq!(plan.entries[0].action, "create");

        // REQ-I5-01: apply without opt-in refuses before any write.
        let err = project_skill_apply(&req).unwrap_err();
        assert_eq!(err, opt_in_error());
        assert!(
            !project.path().join(".claude/skills/moai").exists(),
            "nothing may be written without opt-in"
        );

        // The reverted-and-opted-in flow creates the copy.
        let mut opted = req.clone();
        opted.opt_in = true;
        let plan = project_skill_plan(&opted).unwrap();
        assert_eq!(plan.entries[0].action, "create");
        let receipt = project_skill_apply(&opted).unwrap();
        assert_eq!(receipt.status, "complete");
        assert!(project.path().join(".claude/skills/moai/SKILL.md").exists());

        // Replace with changed source, then revert restores the first copy.
        let source2 = tempfile::TempDir::new().unwrap();
        write_source(source2.path());
        fs::write(
            source2.path().join("SKILL.md"),
            b"---\nname: moai\ndescription: v2\n---\n",
        )
        .unwrap();
        let req2 = request(project.path(), Some(home.path()), source2.path(), true);
        let plan2 = project_skill_plan(&req2).unwrap();
        assert_eq!(plan2.entries[0].action, "replace");
        let applied2 = project_skill_apply(&req2).unwrap();
        assert_eq!(applied2.status, "complete");
        let replaced =
            fs::read_to_string(project.path().join(".claude/skills/moai/SKILL.md")).unwrap();
        assert!(replaced.contains("v2"));

        let revert_req = ProjectSkillRevertRequest {
            protocol_version: PROJECT_SKILL_SCHEMA_VERSION,
            project_root: project.path().to_path_buf(),
            request_id: applied2.request_id.clone(),
        };
        let reverted = project_skill_revert(&revert_req).unwrap();
        assert_eq!(reverted["state"], json!("reverted"));
        let restored =
            fs::read_to_string(project.path().join(".claude/skills/moai/SKILL.md")).unwrap();
        assert!(restored.contains("fixture"));
    }

    #[test]
    fn unknown_host_and_missing_home_are_typed_errors() {
        let root = tempfile::TempDir::new().unwrap();
        let source = tempfile::TempDir::new().unwrap();
        write_source(source.path());
        let mut req = request(root.path(), None, source.path(), true);
        req.hosts = vec!["zcode".into()];
        assert!(project_skill_plan(&req).is_err());
        req.hosts = vec!["claude".into()];
        // apply without home: home reporting is skipped, apply still works.
        assert!(project_skill_apply(&req).is_ok());
    }
}

src/queue.rs.content:
//! Agent self-claim queue: `queue-next` (rc.2 A2 #2161; SPEC
//! `docs/design-review/autonomy-modes-spec.md` §3 steps 1-6).
//!
//! One call re-reads the open Issues of the repository (the remote is the source of truth,
//! user decision D-4), keeps the cards of one milestone, drops pull requests, epics (title
//! `][EP-`) and cards whose `Blocked-By:` line names an Issue that is still open, orders the
//! rest by parent epic (`상위: #N`) and number, and claims the first one it can through
//! 06-A's [`crate::claim::acquire`] under one journal lock for the whole run.
//!
//! - `already_owned` against a live foreign claim → the card is recorded in `lost_to` and the
//!   next candidate is tried. The loser writes nothing to the journal (`claim.rs`, unchanged).
//! - `claimed` → stop. `uncertain` → stop: the comment is posted and this session may be the
//!   winner (SPEC §4 item 4), so no further candidate is touched. `expired`, or an active
//!   record of this session, → stop and return it.
//! - Projection (SPEC §3 step 6) is recorded as intents only. RC1 does not apply state labels
//!   (`.github/moai/labels.yml`, "state lives in the report comment"), and the owned report
//!   comment belongs to `forge-report` with its own gates, so both are `not_run` here.
//!
//! - A candidate whose comments already carry any `moai-claim:` line — live or expired —
//!   is left out before acquire and recorded in `skipped` with `claimed_by` and `expired`
//!   (REQ-A2-01 "only Issues without a claim comment", REQ-A2-02 / REQ-A7-02 "no automatic
//!   takeover"): nothing is posted to it. The one exception is a card this journal already
//!   holds an active record for, which acquire returns unchanged.
//!
//! Not handled here: a local assignments file is not read (the remote is authoritative);
//! live GitHub runs are not part of the tests (fixtures only).
use crate::claim::{
    acquire, is_active, journal_root, parse_claim_line, task_key, worktree_id, ClaimComment,
    ClaimRequest, Journal, Owner, SpecRef, TaskRef,
};
use crate::forge::policy::{next_link, parse_utc, Clock};
use crate::forge::transport::Transport;
use crate::forge::Client;
use crate::identity;
use serde::Deserialize;
use serde_json::{json, Value};
use std::collections::BTreeSet;
use std::path::Path;

type Result<T> = std::result::Result<T, String>;

const API: &str = "https://api.github.com";
/// Same safety bound as the claim comment pagination.
const MAX_PAGES: u32 = 50;

/// The caller-supplied part of every claim request; `queue-next` fills `task_ref` and
/// `logical_key` per candidate and defaults nothing else.
#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ClaimTemplate {
    pub owner: Owner,
    pub base_revision: String,
    pub write_scope: Vec<String>,
    pub spec_ref: SpecRef,
    pub lease_until: String,
}

/// `queue-next` stdin (typed JSON, unknown keys rejected).
#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct QueueRequest {
    pub schema_version: u32,
    pub owner: String,
    pub repo: String,
    /// Milestone number whose cards are candidates.
    pub milestone: i64,
    pub claim: ClaimTemplate,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Candidate {
    pub number: i64,
    pub id: i64,
    pub logical_key: String,
    pub parent: Option<i64>,
}

/// Issue numbers named on lines that start with `prefix` (`#123` tokens only).
fn refs_on(body: &str, prefix: &str) -> Vec<i64> {
    body.lines()
        .filter_map(|l| l.trim().strip_prefix(prefix))
        .flat_map(|rest| {
            rest.split('#')
                .skip(1)
                .filter_map(|t| {
                    let digits: String = t.chars().take_while(char::is_ascii_digit).collect();
                    digits.parse().ok()
                })
                .collect::<Vec<i64>>()
        })
        .collect()
}

/// The second bracket of `[rc.2][A2] …` → `A2`; otherwise `issue-<n>`.
fn logical_key(title: &str, number: i64) -> String {
    let brackets: Vec<&str> = title
        .split('[')
        .skip(1)
        .filter_map(|s| s.split_once(']').map(|(k, _)| k.trim()))
        .collect();
    match brackets.get(1) {
        Some(k) if !k.is_empty() && k.len() <= 100 && !k.chars().any(char::is_control) => {
            (*k).to_string()
        }
        _ => format!("issue-{number}"),
    }
}

/// Splits the open Issues into ordered candidates and the cards left out (with a reason).
/// `issues` are GitHub issue objects of every open Issue of the repository, so a blocker in
/// another milestone still counts as open.
pub fn select(issues: &[Value], milestone: i64) -> (Vec<Candidate>, Vec<Value>) {
    let open: BTreeSet<i64> = issues.iter().filter_map(|i| i["number"].as_i64()).collect();
    let mut picked = Vec::new();
    let mut skipped = Vec::new();
    for i in issues {
        let (Some(number), Some(id)) = (i["number"].as_i64(), i["id"].as_i64()) else {
            continue;
        };
        if i["milestone"]["number"].as_i64() != Some(milestone) {
            continue;
        }
        let title = i["title"].as_str().unwrap_or_default();
        let body = i["body"].as_str().unwrap_or_default();
        let reason = if i.get("pull_request").is_some_and(|p| !p.is_null()) {
            Some(json!("pull_request"))
        } else if title.contains("][EP-") {
            Some(json!("epic"))
        } else {
            let open_blockers: Vec<i64> = refs_on(body, "Blocked-By:")
                .into_iter()
                .filter(|n| open.contains(n) && *n != number)
                .collect();
            (!open_blockers.is_empty()).then(|| json!({"blocked_by": open_blockers}))
        };
        match reason {
            Some(r) => skipped.push(json!({"issue": number, "reason": r})),
            None => picked.push(Candidate {
                number,
                id,
                logical_key: logical_key(title, number),
                parent: refs_on(body, "상위:").first().copied(),
            }),
        }
    }
    picked.sort_by_key(|c| (c.parent.unwrap_or(i64::MAX), c.number));
    (picked, skipped)
}

fn get_json<T: Transport, C: Clock>(
    client: &Client<'_, T, C>,
    url: &str,
) -> Result<(Value, Option<String>)> {
    let resp = client.get(url, None).map_err(String::from)?;
    let next = next_link(resp.header("link"));
    Ok((resp.body.unwrap_or(Value::Null), next))
}

/// Every open Issue object of the repository (GET only, `Link` pagination).
fn read_open_issues<T: Transport, C: Clock>(
    client: &Client<'_, T, C>,
    owner: &str,
    repo: &str,
) -> Result<Vec<Value>> {
    let mut url = Some(format!(
        "{API}/repos/{owner}/{repo}/issues?state=open&per_page=100"
    ));
    let mut out = Vec::new();
    let mut pages = 0;
    while let Some(u) = url {
        pages += 1;
        if pages > MAX_PAGES {
            return Err("queue issue page limit exceeded (50)".into());
        }
        let (body, next) = get_json(client, &u)?;
        out.extend(body.as_array().cloned().unwrap_or_default());
        url = next;
    }
    Ok(out)
}

/// Every `moai-claim:` comment of one Issue (GET only, `Link` pagination).
fn read_claim_comments<T: Transport, C: Clock>(
    client: &Client<'_, T, C>,
    owner: &str,
    repo: &str,
    number: i64,
) -> Result<Vec<ClaimComment>> {
    let mut url = Some(format!(
        "{API}/repos/{owner}/{repo}/issues/{number}/comments?per_page=100"
    ));
    let mut out = Vec::new();
    let mut closed = Vec::new();
    let mut pages = 0;
    while let Some(u) = url {
        pages += 1;
        if pages > MAX_PAGES {
            return Err("queue claim comment page limit exceeded (50)".into());
        }
        let (body, next) = get_json(client, &u)?;
        for c in body.as_array().cloned().unwrap_or_default() {
            let (Some(id), Some(text)) = (c["id"].as_i64(), c["body"].as_str()) else {
                continue;
            };
            if let Some(mut line) = parse_claim_line(text) {
                line.comment_id = id;
                out.push(line);
            }
            // #2255: a claim closed by a release or handoff line no longer holds the card.
            match crate::claim_verify::classify_comment(text) {
                crate::claim_verify::CommentKind::Release { target }
                | crate::claim_verify::CommentKind::Handoff { target, .. } => closed.push(target),
                _ => {}
            }
        }
        url = next;
    }
    out.retain(|c| !closed.contains(&c.comment_id));
    Ok(out)
}

/// The `skipped` entry of a card that already carries claim comments: the smallest live
/// comment id if one is live, otherwise the smallest comment id (expired).
fn claimed_entry(number: i64, claims: &[ClaimComment], now: i64) -> Option<Value> {
    let live = |c: &ClaimComment| parse_utc(&c.lease_until).is_some_and(|t| t > now);
    let first = claims
        .iter()
        .filter(|c| live(c))
        .min_by_key(|c| c.comment_id)
        .or_else(|| claims.iter().min_by_key(|c| c.comment_id))?;
    Some(json!({
        "issue": number,
        "reason": "claimed",
        "claimed_by": first.session,
        "comment_id": first.comment_id,
        "lease_until": first.lease_until,
        "expired": !live(first),
    }))
}

fn validate(req: &QueueRequest) -> Result<()> {
    if req.schema_version != 1 {
        return Err("unsupported request schema_version".into());
    }
    if req.milestone <= 0 {
        return Err("queue milestone must be a positive number".into());
    }
    Ok(())
}

/// The run: read, select, then claim the first candidate that can be claimed. The caller
/// holds the journal lock for the whole run.
pub fn next<T: Transport, C: Clock>(
    journal: &Journal,
    req: &QueueRequest,
    worktree: crate::claim::WorktreeId,
    client: &Client<'_, T, C>,
    clock: &C,
) -> Result<Value> {
    validate(req)?;
    let (repo, _) = get_json(client, &format!("{API}/repos/{}/{}", req.owner, req.repo))?;
    let repository_id = repo["id"]
        .as_i64()
        .ok_or("gh transport: repository response carried no id")?;
    let issues = read_open_issues(client, &req.owner, &req.repo)?;
    let (candidates, mut skipped) = select(&issues, req.milestone);
    let events = journal.read_events()?;
    let projection = json!({
        "label": {"state": "not_run", "reason": "RC1 does not apply state labels (.github/moai/labels.yml)"},
        "status_line": {"state": "not_run", "reason": "the owned report comment is forge-report's, behind its own gates"},
    });
    let mut lost_to = Vec::new();
    for c in &candidates {
        // #2169 display projections (assignee, provider_session) stay empty: queue-next's
        // request carries neither, and they never decide ownership (REQ-B2-01). The
        // constructor leaves them and expected_epoch/attempt unset (#2256).
        let claim = ClaimRequest::new(
            1,
            TaskRef::new(
                "github",
                "github.com",
                req.owner.clone(),
                req.repo.clone(),
                repository_id,
                c.id,
                c.number,
            ),
            c.logical_key.clone(),
            req.claim.owner.clone(),
            req.claim.base_revision.clone(),
            req.claim.write_scope.clone(),
            req.claim.spec_ref.clone(),
        )
        .lease_until(req.claim.lease_until.clone())
        .projection_intents(vec![
            json!({"kind": "projection_intent", "target": "label", "action": "not_run"}),
            json!({"kind": "projection_intent", "target": "status_line", "action": "not_run"}),
        ]);
        // REQ-A2-01/02: a card that already carries a claim comment (live or expired) is
        // not a candidate, unless this journal holds an active record for it.
        let key = task_key(&claim.task_ref);
        let own_active = events
            .iter()
            .rev()
            .find(|e| e.record.task_key == key)
            .is_some_and(|e| is_active(&e.record.state));
        if !own_active {
            let claims = read_claim_comments(client, &req.owner, &req.repo, c.number)?;
            if let Some(entry) = claimed_entry(c.number, &claims, clock.now()) {
                skipped.push(entry);
                continue;
            }
        }
        let out = acquire(journal, &claim, worktree.clone(), client, clock)?;
        let foreign = out.foreign_owner.clone();
        if out.outcome == "already_owned" {
            if let Some(f) = foreign {
                // A live foreign claim wins (smallest comment id); nothing was written here.
                lost_to.push(json!({"issue": c.number, "comment_id": f["comment_id"]}));
                continue;
            }
        }
        let mut v = out.to_json();
        v["issue"] = json!(c.number);
        v["lost_to"] = json!(lost_to);
        v["skipped"] = json!(skipped);
        v["projection"] = if out.outcome == "claimed" {
            projection
        } else {
            Value::Null
        };
        return Ok(v);
    }
    let outcome = if candidates.is_empty() {
        "idle"
    } else {
        "exhausted"
    };
    Ok(json!({
        "outcome": outcome,
        "issue": Value::Null,
        "record": Value::Null,
        "foreign_owner": Value::Null,
        "coordination_scope": "cross-host-eventual",
        "cross_host_atomic": false,
        "lost_to": lost_to,
        "skipped": skipped,
        "projection": Value::Null,
        "notes": [if candidates.is_empty() {
            "no candidate: record the idle line once and stop (SPEC §3 step 2)"
        } else {
            "every candidate already carries a claim comment or is owned by a live foreign claim"
        }],
    }))
}

/// CLI: identity + worktree, journal open + one lock for the whole run (busy never waits).
pub fn next_cli<T: Transport, C: Clock>(
    project: &Path,
    req: QueueRequest,
    transport: &T,
    clock: &C,
) -> Result<Value> {
    let root = journal_root(project)?;
    let id = identity::identity(project)?;
    let worktree = worktree_id(&id)?;
    let journal = Journal::open(&root)?;
    if !journal.try_lock()? {
        return Ok(json!({
            "outcome": "busy",
            "issue": Value::Null,
            "record": Value::Null,
            "foreign_owner": Value::Null,
            "coordination_scope": "single-host",
            "cross_host_atomic": false,
            "lost_to": [],
            "skipped": [],
            "projection": Value::Null,
            "notes": ["another process holds the journal lock; retry policy is the caller's (REQ-06A-05)"],
        }));
    }
    let client = Client::new(transport, clock, Default::default(), Default::default());
    next(&journal, &req, worktree, &client, clock)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn issue(number: i64, title: &str, body: &str, milestone: i64) -> Value {
        json!({"number": number, "id": number * 10, "title": title, "body": body,
               "milestone": {"number": milestone}})
    }

    #[test]
    fn selection_drops_prs_epics_blocked_and_orders_by_parent() {
        let issues = vec![
            issue(10, "[rc.2][EP-A] epic", "", 3),
            issue(12, "[rc.2][A2] two", "상위: #10\nBlocked-By: #11", 3),
            issue(11, "[rc.2][A1] one", "상위: #10\nBlocked-By: 없음", 3),
            issue(21, "[rc.2][B1] b", "상위: #20\nBlocked-By: #999", 3),
            issue(13, "[rc.2][A3] three", "상위: #10", 3),
            issue(30, "[rc.2][X] other milestone", "", 4),
            json!({"number": 14, "id": 140, "title": "pr", "body": "", "milestone": {"number": 3},
                   "pull_request": {"url": "x"}}),
        ];
        let (picked, skipped) = select(&issues, 3);
        let order: Vec<i64> = picked.iter().map(|c| c.number).collect();
        // #999 is not open, so #21 is not blocked; parent #10 sorts before #20.
        assert_eq!(order, vec![11, 13, 21]);
        assert_eq!(picked[0].logical_key, "A1");
        assert_eq!(picked[0].parent, Some(10));
        let reasons: Vec<(i64, Value)> = skipped
            .iter()
            .map(|s| (s["issue"].as_i64().unwrap(), s["reason"].clone()))
            .collect();
        assert!(reasons.contains(&(10, json!("epic"))));
        assert!(reasons.contains(&(12, json!({"blocked_by": [11]}))));
        assert!(reasons.contains(&(14, json!("pull_request"))));
        assert!(
            !reasons.iter().any(|(n, _)| *n == 30),
            "other milestones are not listed"
        );
    }

    #[test]
    fn logical_key_falls_back_to_issue_number() {
        assert_eq!(logical_key("[rc.2][A2] x", 7), "A2");
        assert_eq!(logical_key("plain title", 7), "issue-7");
        assert_eq!(logical_key("[only] one", 7), "issue-7");
    }

    /// #2255: a claim closed by a release or handoff line no longer counts, so the card can
    /// be a candidate again; an open claim still does.
    #[test]
    fn released_claims_do_not_hold_the_card() {
        use crate::forge::transport::{Exchange, HttpRequest, HttpResponse, RecordedTransport};
        struct Fixed;
        impl Clock for Fixed {
            fn now(&self) -> i64 {
                0
            }
            fn sleep(&self, _: u64) {}
        }
        let lease = "2026-11-09T09:00:00Z";
        let page = |body: Value| Exchange {
            request: HttpRequest::new(
                "GET",
                format!("{API}/repos/acme/widgets/issues/7/comments?per_page=100"),
            ),
            response: HttpResponse::new(200).with_body(body),
        };
        let claim = |id: i64, s: &str| json!({"id": id, "body": format!("moai-claim: session={s} epoch=1 lease_until={lease}")});
        let t = RecordedTransport::new(vec![
            page(json!([
                claim(100, "a"),
                {"id": 150, "body": crate::claim_verify::render_release_line(100, "leader")},
            ])),
            page(json!([
                claim(100, "a"),
                {"id": 150, "body": crate::claim_verify::render_handoff_line(100, "b", "leader")},
                claim(200, "b"),
            ])),
        ]);
        let client = Client::new(&t, &Fixed, Default::default(), Default::default());
        assert!(read_claim_comments(&client, "acme", "widgets", 7)
            .unwrap()
            .is_empty());
        let open = read_claim_comments(&client, "acme", "widgets", 7).unwrap();
        assert_eq!(open.iter().map(|c| c.comment_id).collect::<Vec<_>>(), [200]);
    }
}

src/recovery.rs.content:
//! UPDATE partial-failure recovery (Issue #2000, 04-C).
//!
//! 04-B leaves a host whose apply failed with a `pending` receipt that lists this request's
//! files (`before_sha256`/`after_sha256`) and keeps the pre-apply ownership manifest.
//! `recovery-plan` reads every host receipt and classifies each file of a pending host by
//! its CURRENT bytes (never by the receipt's `published` flag: a crash between a rename and
//! the receipt save leaves `published: false` on a file that already carries `after`):
//!
//! - `matches_after`: this request's change, revertible — a created file (`before` none) is
//!   removed; a replaced file is restored from its known-good copy
//!   `~/.moai-cli/installations/<id>/hosts/<host>/known-good/<sha256 hex>` (REQ-04C-03),
//!   and without that copy the file is `conflict` (`no_known_good`) instead;
//! - `matches_before`: never applied, nothing to do;
//! - `conflict`: anything else (a user edit, a symlink) — preserved;
//! - `missing`: the file is gone — preserved, reported.
//!
//! The plan writes nothing. `recovery-apply` recomputes it, refuses another digest, and for
//! each revertible file re-reads the bytes right before the remove/replace (REQ-04C-02).
//! A committed or recovered host is never written. A host with nothing left to resolve is
//! marked `recovered`; one with conflicts stays `pending`. A failure part way stops there,
//! records what was reverted beside the receipt and never retries (REQ-04C-07).
//!
//! Leader RC1 decisions (2026-11-08, recorded on #2000): recovery is triggered only by these
//! two explicit commands (P06 = A); the known-good location is the REQ-04C-03 path (P09).
//! 04-B stores the known-good copies and the receipt's `version_before` (#2089/#2091); a
//! receipt written before that, or a first apply, has neither, so a replaced file is then
//! `conflict(no_known_good)` and `version_before` is null with its reason.
// @MX:DEBT [P09 retention] Known-good copies have no retention period and no GC in RC1.
// UPGRADE when P09 retention is decided: prune copies no committed/pending receipt names.

use crate::apply::{publish_replace, read_opt, relative_ok};
use crate::contract::PROTOCOL_VERSION;
use crate::update::{
    current_install_id, host_receipt_path, load_host_receipt, now_rfc3339, projection_root,
    save_host_receipt, sha256_hex, HostReceipt, FILE_LIMIT, HOSTS,
};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{
    fs,
    path::{Path, PathBuf},
};

type Result<T> = std::result::Result<T, String>;

const RECOVERY_SCHEMA_VERSION: u32 = 1;

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct RecoveryFile {
    pub path: String,
    /// matches_before | matches_after | conflict | missing
    pub class: String,
    /// For `conflict`: `no_known_good` | `user_changed` | `symlink` | `not_a_regular_file`.
    pub reason: Option<String>,
    /// remove | restore | none
    pub action: String,
    pub before_sha256: Option<String>,
    pub after_sha256: Option<String>,
    pub current_sha256: Option<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct RecoveryHost {
    pub host: String,
    /// none (no receipt) | pending | committed | recovered | blocked
    pub receipt_status: String,
    pub blocked_reason: Option<String>,
    pub package_version: Option<String>,
    /// The receipt's `version_before` (#2091): the version the failed apply replaced.
    pub version_before: Option<String>,
    pub files: Vec<RecoveryFile>,
}

/// Why `version_before` is null, or null when it is known (REQ-04C-06).
fn version_before_basis(h: &RecoveryHost) -> Value {
    match (&h.version_before, h.receipt_status.as_str()) {
        (Some(_), _) => Value::Null,
        (None, "none") => json!("no host receipt"),
        (None, "blocked") => json!("host receipt unreadable or refused"),
        (None, _) => json!(
            "not recorded: a first apply on this host, or a receipt written before version_before existed (#2091)"
        ),
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct RecoveryPlan {
    pub schema_version: u32,
    pub protocol_version: u32,
    pub home: String,
    pub install_id: String,
    pub hosts: Vec<RecoveryHost>,
    pub plan_digest: String,
}

/// `hosts/<host>/known-good/<hex>` beside the host receipt.
fn known_good_path(home: &Path, install_id: &str, host: &str, sha: &str) -> Result<PathBuf> {
    let receipt = host_receipt_path(home, install_id, host, false)?;
    let hex = sha.strip_prefix("sha256:").unwrap_or(sha);
    if hex.len() != 64 || !hex.bytes().all(|b| b.is_ascii_hexdigit()) {
        return Err("invalid host receipt digest".into());
    }
    let dir = receipt
        .parent()
        .ok_or("host receipt directory unavailable")?;
    Ok(dir.join(host).join("known-good").join(hex))
}

/// The known-good bytes for `sha`, only if they are a bounded regular file (no symlink in
/// the store) whose digest is exactly `sha`.
fn known_good(home: &Path, install_id: &str, host: &str, sha: &str) -> Result<Option<Vec<u8>>> {
    let path = known_good_path(home, install_id, host, sha)?;
    let mut cursor = path.as_path();
    let stop = home.join(crate::HOME_STATE_DIR);
    while cursor.starts_with(&stop) && cursor != stop {
        if let Ok(m) = fs::symlink_metadata(cursor) {
            if m.file_type().is_symlink() {
                return Ok(None);
            }
        }
        cursor = match cursor.parent() {
            Some(p) => p,
            None => break,
        };
    }
    match fs::symlink_metadata(&path) {
        Ok(m) if m.is_file() && m.len() <= FILE_LIMIT => {
            let bytes = fs::read(&path).map_err(|_| "known-good read failed")?;
            Ok((sha256_hex(&bytes) == sha).then_some(bytes))
        }
        _ => Ok(None),
    }
}

/// True when any component from the projection root down to `target` is a symlink.
fn symlink_on_path(root: &Path, target: &Path) -> bool {
    let mut cursor = target;
    loop {
        if let Ok(m) = fs::symlink_metadata(cursor) {
            if m.file_type().is_symlink() {
                return true;
            }
        }
        if cursor == root {
            return false;
        }
        cursor = match cursor.parent() {
            Some(p) if p.starts_with(root) => p,
            _ => return false,
        };
    }
}

fn classify_file(
    home: &Path,
    install_id: &str,
    host: &str,
    root: &Path,
    entry: &crate::update::HostReceiptEntry,
) -> Result<RecoveryFile> {
    let mut file = RecoveryFile {
        path: entry.path.clone(),
        class: "conflict".into(),
        reason: None,
        action: "none".into(),
        before_sha256: entry.before_sha256.clone(),
        after_sha256: entry.after_sha256.clone(),
        current_sha256: None,
    };
    if !relative_ok(&entry.path) {
        return Err("host receipt path is not a bounded relative path; refused".into());
    }
    let target = root.join(&entry.path);
    if symlink_on_path(root, &target) {
        file.reason = Some("symlink".into());
        return Ok(file);
    }
    let current = match read_opt(&target) {
        Ok(c) => c,
        Err(_) => {
            file.reason = Some("not_a_regular_file".into());
            return Ok(file);
        }
    };
    file.current_sha256 = current.as_deref().map(sha256_hex);
    let current_sha = file.current_sha256.as_deref();
    if current_sha.is_some() && current_sha == entry.after_sha256.as_deref() {
        match entry.before_sha256.as_deref() {
            None => {
                file.class = "matches_after".into();
                file.action = "remove".into();
            }
            Some(before) => {
                if known_good(home, install_id, host, before)?.is_some() {
                    file.class = "matches_after".into();
                    file.action = "restore".into();
                } else {
                    file.reason = Some("no_known_good".into());
                }
            }
        }
    } else if current_sha == entry.before_sha256.as_deref() {
        file.class = "matches_before".into();
    } else if current_sha.is_none() {
        file.class = "missing".into();
    } else {
        file.reason = Some("user_changed".into());
    }
    Ok(file)
}

/// REQ-04C-01: read-only classification of every host. Writes nothing.
pub fn recovery_plan(home: &Path) -> Result<RecoveryPlan> {
    let canonical_home = fs::canonicalize(home).map_err(|_| "home directory unavailable")?;
    let install_id = current_install_id(&canonical_home)?;
    let mut hosts = Vec::new();
    for host in HOSTS {
        let path = host_receipt_path(&canonical_home, &install_id, host, false)?;
        let mut h = RecoveryHost {
            host: host.to_string(),
            receipt_status: "none".into(),
            blocked_reason: None,
            package_version: None,
            version_before: None,
            files: Vec::new(),
        };
        let receipt = match load_host_receipt(&path) {
            Ok(r) => r,
            Err(e) => {
                // A damaged or substituted receipt: nothing about this host can be trusted.
                h.receipt_status = "blocked".into();
                h.blocked_reason = Some(e);
                hosts.push(h);
                continue;
            }
        };
        let Some(receipt) = receipt else {
            hosts.push(h);
            continue;
        };
        h.package_version = Some(receipt.package_version.clone());
        h.version_before = receipt.version_before.clone();
        h.receipt_status = receipt.status.clone();
        // REQ-3 (#2268): a FIRST apply (`version_before` none) into a projection root
        // that already existed (`top_skills_existed_before`) landed created files
        // inside a previously unmanaged folder — list them so the operator sees what
        // an apply added there. Fresh installs into an empty folder (the normal path)
        // never trigger this.
        if receipt.version_before.is_none() && receipt.top_skills_existed_before {
            for entry in &receipt.entries {
                if entry.before_sha256.is_none() && entry.published {
                    h.files.push(crate::recovery::RecoveryFile {
                        path: entry.path.clone(),
                        class: "added_into_pre_existing_root".into(),
                        reason: Some(
                            "first apply landed this file in a folder that already existed \
                             (unmanaged root at apply time, #2268)"
                                .into(),
                        ),
                        action: "none".into(),
                        before_sha256: None,
                        after_sha256: entry.after_sha256.clone(),
                        current_sha256: None,
                    });
                }
            }
        }
        if receipt.status == "pending" {
            let root = projection_root(&canonical_home, host);
            if fs::symlink_metadata(&root).is_ok_and(|m| m.file_type().is_symlink()) {
                h.receipt_status = "blocked".into();
                h.blocked_reason = Some("projection path is a symlink; refused".into());
            } else {
                for entry in &receipt.entries {
                    h.files.push(classify_file(
                        &canonical_home,
                        &install_id,
                        host,
                        &root,
                        entry,
                    )?);
                }
            }
        }
        hosts.push(h);
    }
    let mut plan = RecoveryPlan {
        schema_version: RECOVERY_SCHEMA_VERSION,
        protocol_version: PROTOCOL_VERSION,
        home: canonical_home
            .to_str()
            .ok_or("non UTF-8 home path")?
            .to_string(),
        install_id,
        hosts,
        plan_digest: String::new(),
    };
    plan.plan_digest = crate::digest(&serde_json::to_vec(&plan).map_err(|_| "encode failed")?);
    Ok(plan)
}

/// What one recovery did on one host, saved beside its receipt (REQ-04C-07).
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RecoveryRecord {
    pub schema_version: u32,
    pub host: String,
    pub plan_digest: String,
    pub started_at: String,
    pub finished_at: String,
    /// recovered | pending (conflicts remain) | failed (stopped part way; no retry)
    pub status: String,
    pub reverted: Vec<String>,
    pub conflicts: Vec<Value>,
    pub failed: Option<Value>,
    pub not_attempted: Vec<String>,
}

fn save_record(home: &Path, install_id: &str, record: &RecoveryRecord) -> Result<()> {
    let receipt = host_receipt_path(home, install_id, &record.host, true)?;
    let path = receipt.with_file_name(format!("{}.recovery.json", record.host));
    if fs::symlink_metadata(&path).is_ok_and(|m| m.file_type().is_symlink()) {
        return Err("recovery record is a symlink; refused".into());
    }
    let bytes = serde_json::to_vec_pretty(record).map_err(|_| "encode failed".to_string())?;
    let before = read_opt(&path)?;
    publish_replace(&path, before.as_deref(), &bytes)
}

fn validate_permission(permission: &str) -> Result<()> {
    if ["", "null", "placeholder"].contains(&permission.trim())
        || permission.len() > 128
        || permission.chars().any(char::is_control)
    {
        return Err("permission reference required".into());
    }
    Ok(())
}

fn conflict_json(f: &RecoveryFile) -> Value {
    json!({"path": f.path, "class": f.class, "reason": f.reason,
           "current_sha256": f.current_sha256})
}

/// REQ-04C-02..07: reverts only `matches_after` files of pending hosts.
pub fn recovery_apply(
    home: &Path,
    plan: &RecoveryPlan,
    plan_digest: &str,
    permission_reference: &str,
) -> Result<Value> {
    validate_permission(permission_reference)?;
    let fresh = recovery_plan(home)?;
    if *plan != fresh || fresh.plan_digest != plan_digest {
        return Err("stale or altered plan; re-preview required".into());
    }
    let home = PathBuf::from(&fresh.home);
    let install_id = fresh.install_id.as_str();
    let mut reports = Vec::new();
    let mut reverted_anywhere: Vec<String> = Vec::new();
    let mut conflicts_remain = false;

    for h in &fresh.hosts {
        let applied: Vec<&str> = h
            .files
            .iter()
            .filter(|f| f.class != "matches_before")
            .map(|f| f.path.as_str())
            .collect();
        if h.receipt_status != "pending" {
            // Committed, recovered, absent or blocked: never written (REQ-04C-05).
            conflicts_remain |= h.receipt_status == "blocked";
            reports.push(json!({"host": h.host, "receipt_status": h.receipt_status,
                "blocked_reason": h.blocked_reason, "version_before": h.version_before,
                "version_before_basis": version_before_basis(h),
                "version_after": h.package_version, "applied": [], "failed": [],
                "recovered": [], "conflicts": [], "written": false}));
            continue;
        }
        let root = projection_root(&home, &h.host);
        let started = now_rfc3339();
        let conflicts: Vec<Value> = h
            .files
            .iter()
            .filter(|f| f.class == "conflict" || f.class == "missing")
            .map(conflict_json)
            .collect();
        let todo: Vec<&crate::recovery::RecoveryFile> =
            h.files.iter().filter(|f| f.action != "none").collect();
        let mut reverted: Vec<String> = Vec::new();
        for (i, f) in todo.iter().enumerate() {
            let target = root.join(&f.path);
            let step = || -> Result<()> {
                // Re-verify right before the write: still exactly this request's bytes.
                if symlink_on_path(&root, &target) {
                    return Err("target became a symlink; refused".into());
                }
                let current = read_opt(&target)?;
                if current.as_deref().map(sha256_hex).as_deref() != f.after_sha256.as_deref() {
                    return Err("target changed since recovery-plan".into());
                }
                match (f.action.as_str(), f.before_sha256.as_deref()) {
                    ("remove", None) => {
                        fs::remove_file(&target).map_err(|_| "target remove failed".to_string())
                    }
                    ("restore", Some(before)) => {
                        let bytes = known_good(&home, install_id, &h.host, before)?
                            .ok_or("known-good copy changed since recovery-plan")?;
                        publish_replace(&target, current.as_deref(), &bytes)
                    }
                    _ => Err("invalid recovery action".into()),
                }
            };
            if let Err(e) = step() {
                let rest: Vec<String> = todo[i + 1..].iter().map(|f| f.path.clone()).collect();
                let record = RecoveryRecord {
                    schema_version: RECOVERY_SCHEMA_VERSION,
                    host: h.host.clone(),
                    plan_digest: plan_digest.to_string(),
                    started_at: started.clone(),
                    finished_at: now_rfc3339(),
                    status: "failed".into(),
                    reverted: reverted.clone(),
                    conflicts: conflicts.clone(),
                    failed: Some(json!({"path": f.path, "reason": e})),
                    not_attempted: rest.clone(),
                };
                save_record(&home, install_id, &record)?;
                reverted_anywhere.extend(reverted.iter().cloned());
                if reverted_anywhere.is_empty() {
                    return Err(format!(
                        "conflict in recovery: {} {} could not be reverted ({e}); nothing reverted; the receipt stays pending, no retry",
                        h.host, f.path
                    ));
                }
                return Err(format!(
                    "partial apply: recovery {} reverted [{}]; failed at {}: {e}; conflicts [{}]; not attempted [{}]",
                    h.host,
                    reverted_anywhere.join(", "),
                    f.path,
                    conflicts
                        .iter()
                        .filter_map(|c| c["path"].as_str())
                        .collect::<Vec<_>>()
                        .join(", "),
                    rest.join(", "),
                ));
            }
            reverted.push(f.path.clone());
        }
        let status = if conflicts.is_empty() {
            "recovered"
        } else {
            "pending"
        };
        conflicts_remain |= !conflicts.is_empty();
        if !reverted.is_empty() || status == "recovered" {
            let path = host_receipt_path(&home, install_id, &h.host, false)?;
            let mut receipt: HostReceipt =
                load_host_receipt(&path)?.ok_or("host receipt disappeared")?;
            if receipt.status != "pending" {
                return Err("host receipt changed since recovery-plan".into());
            }
            receipt.status = status.into();
            receipt.finished_at = Some(now_rfc3339());
            save_host_receipt(&home, install_id, &receipt)?;
        }
        save_record(
            &home,
            install_id,
            &RecoveryRecord {
                schema_version: RECOVERY_SCHEMA_VERSION,
                host: h.host.clone(),
                plan_digest: plan_digest.to_string(),
                started_at: started,
                finished_at: now_rfc3339(),
                status: status.into(),
                reverted: reverted.clone(),
                conflicts: conflicts.clone(),
                failed: None,
                not_attempted: Vec::new(),
            },
        )?;
        reverted_anywhere.extend(reverted.iter().cloned());
        reports.push(json!({"host": h.host, "receipt_status": status,
            "blocked_reason": null,
            "version_before": h.version_before,
            "version_before_basis": version_before_basis(h),
            "version_after": h.package_version, "applied": applied, "failed": [],
            "recovered": reverted, "conflicts": conflicts, "written": true}));
    }
    Ok(json!({
        "status": if conflicts_remain { "partial" } else { "success" },
        "plan_digest": plan_digest,
        "hosts": reports,
        "retry": "none: a failure is reported, never retried",
        "host_loaded": false,
    }))
}

src/redact.rs.content:
//! Shared secret-shape detection and message redaction (Issue #1996, 03-B owns the
//! module; scope decision 2026-11-08).
//!
//! The shape list itself stays `crate::SECRET_SHAPES` in lib.rs — forge::promote and
//! the profile filter already consume it, and moving the constant would touch files
//! outside this Issue's scope. This module is the shared read side: one predicate and
//! one redacting formatter so callers refuse or mask the same shapes instead of
//! restating the list. It is a conservative shape filter, not a secret detector; the
//! common redaction policy (what may be logged at all) belongs to the caller.

/// True when `s` carries a credential-shaped substring (lower-cased match).
pub fn contains_secret_shape(s: &str) -> bool {
    let lower = s.to_ascii_lowercase();
    crate::SECRET_SHAPES
        .iter()
        .any(|shape| lower.contains(shape))
}

/// Replaces every credential-shaped key and the value that follows it (up to the
/// next whitespace or the end of the string) with `[redacted]`, so diagnostics can
/// quote the surrounding context without carrying the secret value.
pub fn redact_secret_shapes(s: &str) -> String {
    let mut out = s.to_string();
    for shape in crate::SECRET_SHAPES {
        loop {
            let lower = out.to_ascii_lowercase();
            let Some(start) = lower.find(shape) else {
                break;
            };
            let value_end = out[start..]
                .find(char::is_whitespace)
                .map(|i| start + i)
                .unwrap_or(out.len());
            out.replace_range(start..value_end, "[redacted]");
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_the_shared_shapes_without_echoing() {
        assert!(contains_secret_shape("token=abc123"));
        assert!(contains_secret_shape("see PASSWORD=topsecret"));
        assert!(!contains_secret_shape("plain value"));
        let line = "failed at token=abc123 near the end";
        let redacted = redact_secret_shapes(line);
        assert!(!redacted.contains("abc123"), "{redacted}");
        assert!(redacted.contains("[redacted]"));
        assert!(redacted.contains("near the end"));
    }
}

src/run.rs.content:
//! RUN methodology and real VERIFY (Issue #2003, 05-C).
//!
//! A RUN request names a task admitted by 05-B, a change strategy and a domain-modelling
//! choice, and which of the approved snapshot's verification commands to run. `run` re-reads
//! the pinned contract first and runs nothing on a mismatch; otherwise it runs the commands
//! through the trusted runner (`crate::verify`) and returns a receipt. Receipts that arrive
//! as JSON from outside are self-reports and are never treated as runner receipts.

use crate::digest;
use crate::plan::{admit, AdmissionRequest, Decision};
use crate::verify::{self, CheckResult, CheckRun, FailureClass, Toolchain};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::path::Path;
use std::time::Duration;

pub type Result<T> = std::result::Result<T, String>;

/// Paths a tree digest leaves out: git metadata and build output (#2003 leader decision H1).
pub const TREE_EXCLUDES: [&str; 2] = [".git", "target"];

/// Required evidence per change strategy; the table, not the request, decides it.
const STRATEGIES: [(&str, &[&str]); 6] = [
    ("tdd", &["red", "green", "regression"]),
    ("bugfix", &["repro-fail", "fixed", "regression"]),
    ("preserve", &["baseline", "after", "intent-diff"]),
    ("contract", &["contract-tests", "migration", "rollback"]),
    ("eval", &["trials"]),
    ("docs", &["schema", "links", "smoke"]),
];
const DOMAIN_EVIDENCE: &str = "domain-invariants";

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Method {
    pub change_strategy: Option<String>,
    pub domain_modeling: Option<String>,
    /// The older single choice, `tdd` or `ddd`; mapped to the two fields above.
    pub legacy_mode: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ResolvedMethod {
    pub change_strategy: String,
    /// `not-required` or `required`.
    pub domain_modeling: String,
    /// Set when the request used the legacy single choice.
    pub legacy_mode: Option<String>,
}

/// Mirror of 05-B `plan::PinnedContract`, which has no `Deserialize`; compared field by field
/// with what `plan::admit` returns now.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PinnedRef {
    pub spec_ref: String,
    pub plan_digest: String,
    pub task_id: String,
    pub expected_revision: String,
    pub scope: Vec<String>,
    pub approval_ref: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct VerificationRequest {
    /// Indexes into the approved snapshot's `verification_commands`.
    pub commands_ref: Vec<usize>,
    /// Per command; required, no default (P11).
    pub timeout_ms: u64,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RunRequest {
    pub protocol_version: u32,
    /// Always `RUN`.
    pub intent: String,
    pub request_id: String,
    pub task_id: String,
    pub attempt_id: String,
    /// Opaque; owner and epoch belong to 06-A.
    pub owner: Option<String>,
    pub pinned: PinnedRef,
    pub admission: AdmissionRequest,
    pub method: Method,
    /// A step of the change strategy (`red`, `baseline`, …), when the run records one.
    pub phase: Option<String>,
    pub verification: VerificationRequest,
    /// A baseline receipt for `preserve`; arrives as JSON, so it is a self-report.
    pub baseline: Option<Value>,
    /// Paths the change touches, for the oracle-change check.
    #[serde(default)]
    pub diff_paths: Vec<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ProducerKind {
    RunnerReceipt,
    SelfReport,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Producer {
    pub kind: ProducerKind,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Summary {
    Passed,
    Failed,
    NotRun,
    Blocked,
    Unknown,
}

/// Shaped after an in-toto statement (subject: the tree digest; the rest: what ran), unsigned:
/// it claims no tamper resistance. `producer.kind` says how far it can be trusted.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Receipt {
    pub producer: Producer,
    pub task_id: String,
    pub attempt_id: String,
    pub spec_ref: String,
    pub spec_digest: String,
    pub plan_digest: String,
    pub base_revision: String,
    pub tree_digest: String,
    pub policy_digest: Option<String>,
    pub toolchain: Toolchain,
    pub method: ResolvedMethod,
    pub phase: Option<String>,
    pub required_evidence: Vec<String>,
    /// Every declared check, run or `not_run`.
    pub checks: Vec<CheckRun>,
    pub oracle_changes: Vec<String>,
    /// For the RED step of `tdd` / `bugfix` only.
    pub red_confirmed: Option<bool>,
    pub result: Summary,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct RunOutcome {
    /// `ready` when the commands ran; `stale` or `blocked` when nothing ran.
    pub decision: Decision,
    pub reasons: Vec<String>,
    pub receipt: Option<Receipt>,
}

pub fn resolve_method(m: &Method) -> Result<ResolvedMethod> {
    let explicit = m.change_strategy.is_some() || m.domain_modeling.is_some();
    let (strategy, domain, legacy) = match (&m.legacy_mode, explicit) {
        (Some(_), true) => {
            return Err(
                "invalid run request: give change_strategy and domain_modeling, or legacy_mode"
                    .into(),
            )
        }
        (Some(l), false) => match l.as_str() {
            "tdd" => ("tdd", "not-required", Some(l.clone())),
            "ddd" => ("preserve", "required", Some(l.clone())),
            _ => return Err("invalid run request: legacy_mode must be tdd or ddd".into()),
        },
        (None, _) => (
            m.change_strategy.as_deref().unwrap_or_default(),
            m.domain_modeling.as_deref().unwrap_or_default(),
            None,
        ),
    };
    if !STRATEGIES.iter().any(|(s, _)| *s == strategy) {
        return Err("invalid run request: unknown change_strategy".into());
    }
    if !matches!(domain, "not-required" | "required") {
        return Err("invalid run request: domain_modeling must be not-required or required".into());
    }
    Ok(ResolvedMethod {
        change_strategy: strategy.into(),
        domain_modeling: domain.into(),
        legacy_mode: legacy,
    })
}

pub fn required_evidence(m: &ResolvedMethod) -> Vec<String> {
    let mut out: Vec<String> = STRATEGIES
        .iter()
        .find(|(s, _)| *s == m.change_strategy)
        .map(|(_, e)| e.iter().map(|x| x.to_string()).collect())
        .unwrap_or_default();
    if m.domain_modeling == "required" {
        out.push(DOMAIN_EVIDENCE.into());
    }
    out
}

/// Test, fixture and golden paths among `paths`, sorted: changes to what judges the code.
pub fn oracle_changes(paths: &[String]) -> Vec<String> {
    let mut out: Vec<String> = paths
        .iter()
        .map(|p| p.trim().trim_start_matches("./").to_string())
        .filter(|p| {
            let parts: Vec<&str> = p.split('/').collect();
            parts.first() == Some(&"tests")
                || parts.iter().any(|s| matches!(*s, "fixtures" | "golden"))
                || p.ends_with("_test.py")
        })
        .collect();
    out.sort();
    out.dedup();
    out
}

/// RED is confirmed for the `red` / `repro-fail` step of `tdd` / `bugfix` when something failed
/// and every failure is an assertion failure.
pub fn red_confirmed(m: &ResolvedMethod, phase: Option<&str>, checks: &[CheckRun]) -> Option<bool> {
    let red_step = matches!(
        (m.change_strategy.as_str(), phase),
        ("tdd", Some("red")) | ("bugfix", Some("repro-fail"))
    );
    if !red_step {
        return None;
    }
    let failed: Vec<&CheckRun> = checks
        .iter()
        .filter(|c| c.result == CheckResult::Failed)
        .collect();
    Some(
        !failed.is_empty()
            && failed
                .iter()
                .all(|c| c.failure_class == Some(FailureClass::TestFailure)),
    )
}

/// Accepts agent-written receipt JSON as a self-report, whatever producer it claims.
pub fn ingest_self_report(value: Value) -> Result<Receipt> {
    let mut r: Receipt =
        serde_json::from_value(value).map_err(|_| "invalid typed JSON input".to_string())?;
    r.producer.kind = ProducerKind::SelfReport;
    Ok(r)
}

/// Only a receipt this runner produced counts as evidence for admission.
pub fn admissible_evidence(r: &Receipt) -> bool {
    r.producer.kind == ProducerKind::RunnerReceipt
}

/// Why a receipt no longer describes the current state; empty when it still does.
pub fn stale_reasons(
    r: &Receipt,
    tree_digest: &str,
    spec_digest: &str,
    policy_digest: Option<&str>,
) -> Vec<&'static str> {
    let mut out = Vec::new();
    if r.tree_digest != tree_digest {
        out.push("tree-changed");
    }
    if r.spec_digest != spec_digest {
        out.push("spec-changed");
    }
    if r.policy_digest.as_deref() != policy_digest {
        out.push("policy-changed");
    }
    out
}

/// Tasks whose receipts are stale and need verifying again, sorted.
pub fn revalidate(
    receipts: &[Receipt],
    tree_digest: &str,
    spec_digest: &str,
    policy_digest: Option<&str>,
) -> Vec<String> {
    let mut out: Vec<String> = receipts
        .iter()
        .filter(|r| !stale_reasons(r, tree_digest, spec_digest, policy_digest).is_empty())
        .map(|r| r.task_id.clone())
        .collect();
    out.sort();
    out.dedup();
    out
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Budget {
    /// Required when retries are wanted; there is no default (P11).
    pub max_attempts: u32,
}

/// REQ-05C-11: with a budget, stop once `max_attempts` attempts have run and the last ones all
/// failed on the same checks. Without a budget there is no retry decision (one result only).
/// The caller holds the attempt history: receipts are not stored anywhere yet (P09).
pub fn budget_exhausted(budget: Option<&Budget>, attempts: &[Receipt]) -> bool {
    let Some(b) = budget else {
        return false;
    };
    let n = b.max_attempts as usize;
    if n == 0 || attempts.len() < n {
        return false;
    }
    let failing = |r: &Receipt| -> Vec<usize> {
        r.checks
            .iter()
            .filter(|c| c.result == CheckResult::Failed)
            .map(|c| c.command_ref)
            .collect()
    };
    let last = &attempts[attempts.len() - n..];
    let first = failing(&last[0]);
    !first.is_empty() && last.iter().all(|r| failing(r) == first)
}

/// Required evidence the attempts have not produced yet: what is left to report at a stop.
pub fn remaining_evidence(required: &[String], attempts: &[Receipt]) -> Vec<String> {
    required
        .iter()
        .filter(|e| {
            !attempts
                .iter()
                .any(|r| r.phase.as_deref() == Some(e.as_str()) && r.result == Summary::Passed)
        })
        .cloned()
        .collect()
}

fn summarize(checks: &[CheckRun], oracle: &[String]) -> Summary {
    if checks.iter().any(|c| c.result == CheckResult::Failed) {
        Summary::Failed
    } else if checks.iter().any(|c| c.result == CheckResult::NotRun) {
        Summary::NotRun
    } else if !oracle.is_empty() {
        // Passing while the oracle itself changed needs a reader, not a summary.
        Summary::Unknown
    } else {
        Summary::Passed
    }
}

fn halt(decision: Decision, reasons: Vec<String>) -> RunOutcome {
    RunOutcome {
        decision,
        reasons,
        receipt: None,
    }
}

/// Re-reads the pinned contract, then runs the requested commands in `project`. Input errors
/// return `Err`; a mismatch returns `stale` or `blocked` without running anything.
pub fn run(project: &Path, req: &RunRequest, current_revision: &str) -> Result<RunOutcome> {
    if req.intent != "RUN" {
        return Err("invalid run request: intent must be RUN".into());
    }
    if req.verification.timeout_ms == 0 {
        return Err("invalid run request: timeout_ms must be positive".into());
    }
    let method = resolve_method(&req.method)?;
    let evidence = required_evidence(&method);
    if let Some(p) = &req.phase {
        if !evidence.iter().any(|e| e == p) || p == DOMAIN_EVIDENCE {
            return Err("invalid run request: phase is not a step of the change strategy".into());
        }
    }
    let commands = &req.admission.spec.verification_commands;
    if req
        .verification
        .commands_ref
        .iter()
        .any(|i| *i >= commands.len())
    {
        return Err("invalid run request: commands_ref out of range".into());
    }

    // REQ-05C-01: the pinned contract against what 05-B admits now.
    let admitted = admit(&req.admission, current_revision);
    if admitted.decision != Decision::Ready {
        return Ok(halt(
            admitted.decision,
            admitted.reasons.iter().map(|r| r.to_string()).collect(),
        ));
    }
    let Some(now) = admitted.pinned.iter().find(|p| p.task_id == req.task_id) else {
        return Ok(halt(Decision::Blocked, vec!["task-not-admitted".into()]));
    };
    let now = PinnedRef {
        spec_ref: now.spec_ref.clone(),
        plan_digest: now.plan_digest.clone(),
        task_id: now.task_id.clone(),
        expected_revision: now.expected_revision.clone(),
        scope: now.scope.clone(),
        approval_ref: now.approval_ref.clone(),
    };
    if now != req.pinned {
        return Ok(halt(
            Decision::Stale,
            vec!["pinned-contract-mismatch".into()],
        ));
    }

    // REQ-05C-04: improving under `preserve` needs a trusted baseline first.
    if method.change_strategy == "preserve"
        && !matches!(req.phase.as_deref(), None | Some("baseline"))
    {
        let reason = match &req.baseline {
            None => "baseline-missing",
            Some(v) => match ingest_self_report(v.clone()) {
                Ok(r) if admissible_evidence(&r) => "",
                _ => "baseline-untrusted",
            },
        };
        if !reason.is_empty() {
            return Ok(halt(Decision::Blocked, vec![reason.into()]));
        }
    }

    // Every requested command must be runnable before any of them starts.
    let mut wanted: Vec<usize> = req.verification.commands_ref.clone();
    wanted.sort_unstable();
    wanted.dedup();
    if wanted
        .iter()
        .any(|i| verify::parse_argv(&commands[*i]).is_err())
    {
        return Ok(halt(Decision::Blocked, vec!["command-not-runnable".into()]));
    }

    let tree_digest = crate::tree_digest(project, &TREE_EXCLUDES)?;
    let toolchain = verify::toolchain(project);
    let timeout = Duration::from_millis(req.verification.timeout_ms);
    let checks: Vec<CheckRun> = commands
        .iter()
        .enumerate()
        .map(|(i, c)| {
            if wanted.contains(&i) {
                verify::run_check(project, i, c, timeout)
            } else {
                verify::not_run(i, c)
            }
        })
        .collect();
    let oracle = oracle_changes(&req.diff_paths);
    let snapshot = req
        .admission
        .spec
        .snapshot
        .as_ref()
        .expect("admitted spec is approved");
    let receipt = Receipt {
        producer: Producer {
            kind: ProducerKind::RunnerReceipt,
        },
        task_id: req.task_id.clone(),
        attempt_id: req.attempt_id.clone(),
        spec_ref: snapshot.reference.clone(),
        spec_digest: snapshot.digest.clone(),
        plan_digest: admitted.plan.plan_digest.clone(),
        base_revision: current_revision.into(),
        tree_digest,
        policy_digest: req
            .admission
            .spec
            .policy_revision
            .as_ref()
            .map(|p| digest(p.as_bytes())),
        toolchain,
        red_confirmed: red_confirmed(&method, req.phase.as_deref(), &checks),
        result: summarize(&checks, &oracle),
        method,
        phase: req.phase.clone(),
        required_evidence: evidence,
        checks,
        oracle_changes: oracle,
    };
    Ok(RunOutcome {
        decision: Decision::Ready,
        reasons: Vec::new(),
        receipt: Some(receipt),
    })
}

/// Cost-request input (#2191, REQ-D5-01): an array of run/verify receipts to
/// aggregate. Receipts arrive as JSON in the exact `Receipt` schema — self-reports
/// are aggregated as what they claim, and the report's producer rows keep that
/// distinction visible.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CostRequest {
    pub protocol_version: u32,
    pub receipts: Vec<Receipt>,
}

/// `cost-report` (#2191): aggregates cost items across run/verify receipts —
/// check outcomes, per-command and total durations, wall spans, external backend
/// calls and tokens — separately per producer kind (REQ-D5-01: estimates and
/// measurements are distinguished). Only runner receipts carry numbers the runner
/// measured, so their group is `measured`; a self-report group carries what the
/// reporter claims and is tagged `self_reported`. External backend calls are
/// structurally zero only for runner receipts (the runner spawns local commands and
/// has no network path); for self-reports nothing establishes the count, so it is
/// `absent`. Token accounting has no source in any receipt and is `absent` rather
/// than estimated; the report contains no estimate rows.
pub fn cost_report(req: CostRequest) -> Result<Value> {
    if req.protocol_version != 1 {
        return Err("unsupported protocol_version; supported: 1".into());
    }
    let runner: Vec<&Receipt> = req
        .receipts
        .iter()
        .filter(|r| r.producer.kind == ProducerKind::RunnerReceipt)
        .collect();
    let self_report: Vec<&Receipt> = req
        .receipts
        .iter()
        .filter(|r| r.producer.kind == ProducerKind::SelfReport)
        .collect();
    let per_receipt: Vec<Value> = req.receipts.iter().map(receipt_row).collect();
    Ok(json!({
        "protocol_version": 1,
        "receipts": req.receipts.len(),
        "by_producer": {
            "runner-receipt": producer_group(&runner, ProducerKind::RunnerReceipt),
            "self-report": producer_group(&self_report, ProducerKind::SelfReport),
        },
        "per_receipt": per_receipt,
        "tokens": {
            "basis": "absent",
            "note": "receipts carry no token source; nothing is estimated"
        },
        "estimates": [],
        "network": "none",
        "writes": "none"
    }))
}

/// Evidence basis of a receipt's own numbers: measured by the runner, or claimed
/// by a self-report.
fn producer_basis(kind: ProducerKind) -> &'static str {
    match kind {
        ProducerKind::RunnerReceipt => "measured",
        ProducerKind::SelfReport => "self_reported",
    }
}

/// Sum of a receipt's check durations, with the count of checks that carry none.
fn receipt_duration(r: &Receipt) -> (u128, usize) {
    r.checks
        .iter()
        .fold((0, 0), |(sum, missing), c| match c.duration_ms {
            Some(ms) => (sum + ms as u128, missing),
            None => (sum, missing + 1),
        })
}

/// Earliest check start to latest check finish, when both exist and are ordered.
fn receipt_wall_span(r: &Receipt) -> Option<u64> {
    let start = r.checks.iter().filter_map(|c| c.started_unix_ms).min();
    let finish = r.checks.iter().filter_map(|c| c.finished_unix_ms).max();
    match (start, finish) {
        (Some(s), Some(f)) if f >= s => Some(f - s),
        _ => None,
    }
}

fn receipt_row(r: &Receipt) -> Value {
    let (duration, missing) = receipt_duration(r);
    json!({
        "task_id": r.task_id,
        "attempt_id": r.attempt_id,
        "producer_kind": r.producer.kind,
        "basis": producer_basis(r.producer.kind),
        "checks_total": r.checks.len(),
        "duration_ms": if missing == 0 { json!(duration as u64) } else { json!(null) },
        "duration_missing_samples": missing,
        "wall_span_ms": receipt_wall_span(r),
        "result": r.result,
    })
}

/// Aggregate of one producer kind's receipts; every row carries that kind's basis.
/// A kind with no receipts is `null`: an empty group asserts no basis at all.
fn producer_group(receipts: &[&Receipt], kind: ProducerKind) -> Value {
    if receipts.is_empty() {
        return Value::Null;
    }
    let basis = producer_basis(kind);
    let (mut total, mut passed, mut failed, mut not_run) = (0usize, 0usize, 0usize, 0usize);
    let (mut duration_total, mut duration_missing) = (0u128, 0usize);
    let mut wall_spans = Vec::new();
    for r in receipts {
        for c in &r.checks {
            total += 1;
            match c.result {
                CheckResult::Passed => passed += 1,
                CheckResult::Failed => failed += 1,
                CheckResult::NotRun => not_run += 1,
            }
        }
        let (d, m) = receipt_duration(r);
        duration_total += d;
        duration_missing += m;
        wall_spans.extend(receipt_wall_span(r));
    }
    wall_spans.sort_unstable();
    let p50 = wall_spans.get((wall_spans.len().max(1) - 1) / 2).copied();
    let p95 = wall_spans
        .get(((wall_spans.len() as f64 * 0.95).ceil() as usize).max(1) - 1)
        .copied();
    let external = match kind {
        ProducerKind::RunnerReceipt => json!({"count": 0, "basis": "structural"}),
        ProducerKind::SelfReport => json!({"count": null, "basis": "absent"}),
    };
    json!({
        "receipts": receipts.len(),
        "checks": {
            "total": total,
            "passed": passed,
            "failed": failed,
            "not_run": not_run,
            "basis": basis
        },
        "duration_ms": {
            "total": duration_total as u64,
            "samples_missing": duration_missing,
            "basis": basis
        },
        "wall_span_ms": {
            "p50": p50,
            "p95": p95,
            "samples": wall_spans.len(),
            "basis": basis
        },
        "external_backend_calls": external,
    })
}

