//! Host projection UPDATE (Issue #1999, 04-B).
//!
//! `update-plan` inventories every host projection (Claude `~/.claude/skills/moai/`,
//! Codex `~/.agents/skills/moai/` — the design-verified paths; project-level projections
//! are a P04 HOLD and are not included), compares each file three-way (baseline = the
//! ownership manifest of the latest host receipt, current = bytes on disk, new = the
//! staged package) and writes nothing. `update-apply` recomputes the plan and refuses
//! any other digest, then walks the host transaction (REQ-04B-04): pending receipt
//! (fsynced publish) → per-file unique temp + fsync + rename through the 01-B engine
//! (`apply::publish_replace` / `apply::publish_exclusive`, each re-verifying the target
//! and fsyncing the parent directory) → full re-verification → committed receipt. A
//! failed host keeps its `pending` receipt with the PRE-apply ownership manifest
//! (recovery is 04-C) and never touches a host that already committed. A crashed
//! apply therefore reads back as per-file `conflict` where the stage differs and
//! `unchanged` where the bytes already match — never as a silent overwrite.
//!
//! Host receipts live beside the 04-A install receipt:
//! `~/.moai-cli/installations/<install_id>/hosts/<host>.json`. The `install_id` is the
//! 04-A derivation, obtained through the public `install::plan_receipt` so this module
//! does not modify 04-A. Host config keys (Claude `settings.json`, Codex `config.toml`)
//! are out of scope (P04 HOLD — the REQs name projections only). Projections are
//! independent copies; a symlinked projection is `blocked`, never followed (REQ-04B-08),
//! and user files are never deleted or overwritten (REQ-04B-09).

use crate::apply::{decide, publish_exclusive, publish_replace, read_opt, relative_ok, Decision};
use crate::contract::PROTOCOL_VERSION;
use crate::install::{plan_receipt, InstallerOwner};
use serde::{Deserialize, Serialize};
use serde_json::json;
use sha2::{Digest, Sha256};
use std::{
    collections::BTreeMap,
    fs,
    path::{Path, PathBuf},
};

type Result<T> = std::result::Result<T, String>;

const UPDATE_SCHEMA_VERSION: u32 = 1;
/// Host projection roots under the home, in fixed plan order. 02-B/02-C expose explicit
/// target paths rather than constants, so the design-verified values stand in here
/// (Issue impl plan step 1).
pub(crate) const HOSTS: [&str; 2] = ["claude", "codex"];
/// Same bounded-file rule as every other state file.
pub(crate) const FILE_LIMIT: u64 = 262_144;
const WALK_DEPTH: usize = 32;
const WALK_ENTRIES: usize = 8192;
const WALK_FILES: usize = 4096;
const WALK_BYTES: usize = 16 * 1024 * 1024;

fn skills_dir(host: &str) -> &'static str {
    match host {
        "claude" => ".claude/skills",
        "codex" => ".agents/skills",
        other => unreachable!("unknown host {other}"),
    }
}

pub(crate) fn projection_root(home: &Path, host: &str) -> PathBuf {
    home.join(skills_dir(host)).join("moai")
}

/// UTC RFC3339 second precision; local copy of install.rs's private formatter.
pub(crate) fn now_rfc3339() -> String {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let days = (secs / 86400) as i64;
    let rem = secs % 86400;
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    format!(
        "{y:04}-{m:02}-{d:02}T{:02}:{:02}:{:02}Z",
        rem / 3600,
        (rem % 3600) / 60,
        rem % 60
    )
}

pub(crate) fn sha256_hex(bytes: &[u8]) -> String {
    format!("sha256:{:x}", Sha256::digest(bytes))
}

// --- staged package -----------------------------------------------------------------

/// The staged new package: `moai-package-tree-v1` digest plus every file's bytes.
pub struct StagedPackage {
    pub digest: String,
    pub files: BTreeMap<String, Vec<u8>>,
}

/// Stages the package directory. `package_digest` is the single source of the digest
/// (and of the SKILL.md/symlink/size rules); the walk below mirrors its limits to also
/// carry the bytes.
pub fn stage_package(src: &Path) -> Result<StagedPackage> {
    let digest = crate::package_digest(src)?;
    let mut files = BTreeMap::new();
    let mut entries = 0usize;
    let mut total = 0usize;
    walk_files(src, src, &mut files, &mut entries, &mut total, 0)?;
    Ok(StagedPackage { digest, files })
}

fn walk_files(
    root: &Path,
    dir: &Path,
    files: &mut BTreeMap<String, Vec<u8>>,
    entries: &mut usize,
    total: &mut usize,
    depth: usize,
) -> Result<()> {
    if depth > WALK_DEPTH {
        return Err("package nesting limit exceeded".into());
    }
    for entry in fs::read_dir(dir).map_err(|_| "package directory unavailable")? {
        *entries += 1;
        if *entries > WALK_ENTRIES {
            return Err("package entry limit exceeded".into());
        }
        let path = entry.map_err(|_| "package entry unavailable")?.path();
        let meta = fs::symlink_metadata(&path).map_err(|_| "package metadata unavailable")?;
        if meta.file_type().is_symlink() {
            return Err("package symlink refused".into());
        }
        if meta.is_dir() {
            walk_files(root, &path, files, entries, total, depth + 1)?;
        } else if meta.is_file() {
            if meta.len() > FILE_LIMIT {
                return Err("package file exceeds the size limit".into());
            }
            let rel = path
                .strip_prefix(root)
                .map_err(|_| "package path invalid")?
                .to_str()
                .ok_or("non UTF-8 package path")?
                .replace('\\', "/");
            if !relative_ok(&rel) {
                return Err("nonportable package path".into());
            }
            let bytes = fs::read(&path).map_err(|_| "package read failed")?;
            *total += bytes.len();
            if *total > WALK_BYTES {
                return Err("package too large".into());
            }
            files.insert(rel, bytes);
        } else {
            return Err("package special file refused".into());
        }
        if files.len() > WALK_FILES {
            return Err("package file limit exceeded".into());
        }
    }
    Ok(())
}

// --- plan types ---------------------------------------------------------------------

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct FilePlan {
    pub host: String,
    pub path: String,
    /// create | update | unchanged | conflict | preserved | remove_blocked
    pub action: String,
    pub baseline_sha256: Option<String>,
    pub current_sha256: Option<String>,
    pub new_sha256: Option<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct HostPlan {
    pub host: String,
    pub projection_root: String,
    /// ok | blocked (REQ-04B-02: one blocked host never stops the others)
    pub preflight: String,
    pub blocked_reason: Option<String>,
    pub files: Vec<FilePlan>,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct ProtocolRange {
    pub min: u32,
    pub max: u32,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct FileHash {
    pub host: String,
    pub path: String,
    pub sha256: String,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct UpdatePlan {
    pub schema_version: u32,
    pub protocol_version: u32,
    pub protocol_range: ProtocolRange,
    /// Canonical home; binds the plan so a replay under another HOME is refused.
    pub home: String,
    pub scope: Vec<String>,
    pub source_version: Option<String>,
    pub target_version: String,
    pub package_digest: String,
    pub hosts: Vec<HostPlan>,
    pub expected_file_hashes: Vec<FileHash>,
    pub rollback_manifest: Vec<FileHash>,
    pub plan_digest: String,
}

// --- host receipt -------------------------------------------------------------------

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct HostReceiptEntry {
    pub path: String,
    pub action: String,
    pub before_sha256: Option<String>,
    pub after_sha256: Option<String>,
    pub published: bool,
    pub error: Option<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct HostReceipt {
    pub schema_version: u32,
    pub install_id: String,
    pub host: String,
    pub operation: String,
    pub plan_digest: String,
    pub package_digest: String,
    pub package_version: String,
    /// The previous receipt's `package_version` — the version this apply replaces
    /// (REQ-04C-06 recovery input, #2089). Absent on a first apply. `default` keeps
    /// pre-#2089 receipts readable.
    #[serde(default)]
    pub version_before: Option<String>,
    /// pending | committed (REQ-04B-04/05: a failed apply stays pending) | recovered
    /// (04-C #2000: a pending host whose changes were all reverted; read like committed)
    pub status: String,
    pub started_at: String,
    pub finished_at: Option<String>,
    /// This apply's file actions (before/after per file).
    pub entries: Vec<HostReceiptEntry>,
    /// Ownership manifest: every file this host owns and its sha at this receipt's
    /// commit point. The plan's baseline comes from here (REQ-04B-01). A pending
    /// receipt keeps the PRE-apply manifest, so a crashed apply surfaces as per-file
    /// conflict instead of a silent overwrite (04-C recovers).
    pub owned: Vec<FileHash>,
    /// #2268 additive (REQ-3): whether the projection root already existed before this
    /// apply. On a first apply (`version_before` none) into a pre-existing root, the
    /// created entries landed inside a previously unmanaged folder — recovery lists
    /// them. serde-default keeps pre-#2268 receipts readable.
    #[serde(default)]
    pub top_skills_existed_before: bool,
}

/// Receipt path; `create` also creates the directory chain (apply only — the plan must
/// not write anything, so it passes `false`).
pub(crate) fn host_receipt_path(
    home: &Path,
    install_id: &str,
    host: &str,
    create: bool,
) -> Result<PathBuf> {
    let dir = home
        .join(crate::HOME_STATE_DIR)
        .join("installations")
        .join(install_id)
        .join("hosts");
    if create {
        // Refuse a symlink in any component below ~/.moai-cli before creating.
        let mut cursor = dir.as_path();
        let mut parts: Vec<PathBuf> = Vec::new();
        while let Some(parent) = cursor.parent() {
            parts.push(cursor.to_path_buf());
            cursor = parent;
            if cursor.file_name().map(|n| n == crate::HOME_STATE_DIR) == Some(true) {
                break;
            }
        }
        for part in parts.iter().rev() {
            if let Ok(m) = fs::symlink_metadata(part) {
                if m.file_type().is_symlink() {
                    return Err("installations receipt path is a symlink; refused".into());
                }
            }
        }
        fs::create_dir_all(&dir).map_err(|_| "host receipt directory unavailable")?;
    }
    Ok(dir.join(format!("{host}.json")))
}

pub(crate) fn load_host_receipt(path: &Path) -> Result<Option<HostReceipt>> {
    match fs::symlink_metadata(path) {
        Ok(m) if m.file_type().is_symlink() => Err("host receipt is a symlink; refused".into()),
        Ok(_) => {
            let meta = fs::metadata(path).map_err(|_| "host receipt metadata unavailable")?;
            if !meta.is_file() || meta.len() > FILE_LIMIT {
                return Err("host receipt is not a bounded regular file".into());
            }
            let bytes = fs::read(path).map_err(|_| "host receipt read failed")?;
            let receipt: HostReceipt = serde_json::from_slice(&bytes)
                .map_err(|_| "invalid host receipt; no values were logged".to_string())?;
            Ok(Some(receipt))
        }
        Err(_) => Ok(None),
    }
}

/// Writes the receipt through the 01-B publish engine (temp + fsync + rename + parent
/// directory fsync), REQ-04B-04(a).
pub(crate) fn save_host_receipt(
    home: &Path,
    install_id: &str,
    receipt: &HostReceipt,
) -> Result<()> {
    let path = host_receipt_path(home, install_id, &receipt.host, true)?;
    let bytes =
        serde_json::to_vec_pretty(receipt).map_err(|_| "receipt encode failed".to_string())?;
    let before = read_opt(&path)?;
    publish_replace(&path, before.as_deref(), &bytes)
}

/// REQ-04C-03 (#2089): preserve every file this host will overwrite as a known-good
/// copy BEFORE the apply transaction starts (the pending receipt included) — a copy
/// failure starts nothing for the host. Copies live at
/// `~/.moai-cli/installations/<id>/hosts/<host>/known-good/<hex>`, where `<hex>` is the
/// bare-hex sha256 of the exact before bytes — a filename-valid form like `install_id`;
/// the receipt's `before_sha256` carries the same digest with its `sha256:` prefix, so
/// recovery derives the path by stripping that prefix. `create` actions have no before
/// bytes and get no copy. Exclusive create: an existing regular file under the same
/// digest name is reused only after verifying it holds that digest's bytes — a
/// mismatched copy (a partial write from a failed save) is replaced with the true
/// bytes, and every fresh copy is read back and verified. No retention or GC: copies
/// accumulate for the life of the installation.
// @MX:DEBT: known-good copies accumulate with no retention or GC
// @MX:CEILING: RC1 fixture scale — a handful of hosts and files per installation
// @MX:UPGRADE: the real installer ships (P12 release matrix) — add retention/GC then
fn known_good_copies(
    home: &Path,
    install_id: &str,
    host: &str,
    root: &Path,
    writes: &[&FilePlan],
) -> Result<()> {
    for w in writes {
        if w.action != "update" {
            continue;
        }
        let target = root.join(&w.path);
        let bytes = read_opt(&target)?.ok_or("known-good: update target missing")?;
        let hex = format!("{:x}", Sha256::digest(&bytes));
        let dir = home
            .join(crate::HOME_STATE_DIR)
            .join("installations")
            .join(install_id)
            .join("hosts")
            .join(host)
            .join("known-good");
        // Refuse a symlink in any component below ~/.moai-cli before creating (same
        // hygiene as the receipt path).
        let mut cursor = dir.as_path();
        let mut parts: Vec<PathBuf> = Vec::new();
        while let Some(parent) = cursor.parent() {
            parts.push(cursor.to_path_buf());
            cursor = parent;
            if cursor.file_name().map(|n| n == crate::HOME_STATE_DIR) == Some(true) {
                break;
            }
        }
        for part in parts.iter().rev() {
            if let Ok(m) = fs::symlink_metadata(part) {
                if m.file_type().is_symlink() {
                    return Err("installations known-good path is a symlink; refused".into());
                }
            }
        }
        fs::create_dir_all(&dir).map_err(|_| "known-good directory unavailable")?;
        let path = dir.join(&hex);
        if fs::symlink_metadata(&path).is_ok() {
            // A file under this digest name already exists: reuse only a regular
            // file that actually holds its digest's bytes — a partial write from a
            // failed earlier save must not survive as a "known-good" copy. A
            // directory or symlink planted at the path is a refusal, not a reuse;
            // a mismatched regular file is replaced with the true bytes.
            let m = fs::symlink_metadata(&path).map_err(|_| "known-good copy state unavailable")?;
            if !m.is_file() {
                return Err("known-good digest path is not a regular file".into());
            }
            let existing = fs::read(&path).map_err(|_| "known-good copy read failed")?;
            if format!("{:x}", Sha256::digest(&existing)) == hex {
                continue;
            }
            // 01-B temp+rename (REQ-01B-03): stage() re-verifies the on-disk bytes
            // right before the rename, and the rename swaps the inode, so a hard
            // link sharing the corrupt copy keeps its own bytes — an in-place
            // truncate would corrupt every link (#2103).
            publish_replace(&path, Some(&existing), &bytes)?;
        } else {
            // Exclusive create through the same engine (REQ-01B-04): the temp file
            // is hard-linked into place and the publish fails explicitly if the
            // path appeared meanwhile.
            publish_exclusive(&path, &bytes)?;
        }
        // Read-back verification: what is on disk must be the digest the name
        // promises (save-time digest re-verification).
        let stored = fs::read(&path).map_err(|_| "known-good copy read failed")?;
        if format!("{:x}", Sha256::digest(&stored)) != hex {
            return Err("known-good copy does not hold its digest's bytes".into());
        }
    }
    Ok(())
}

fn owned_map(receipt: Option<&HostReceipt>) -> BTreeMap<String, String> {
    let mut map = BTreeMap::new();
    if let Some(r) = receipt {
        for f in &r.owned {
            map.insert(f.path.clone(), f.sha256.clone());
        }
    }
    map
}

fn owned_vec(host: &str, map: &BTreeMap<String, String>) -> Vec<FileHash> {
    map.iter()
        .map(|(p, s)| FileHash {
            host: host.to_string(),
            path: p.clone(),
            sha256: s.clone(),
        })
        .collect()
}

// --- inventory / preflight ----------------------------------------------------------

struct ProjectionScan {
    files: BTreeMap<String, String>, // rel -> sha256
}

/// Reads the projection tree (shas only). Only called on an existing root: any
/// structural hazard (symlink, special file, oversized/unreadable file) becomes an
/// `Err` that the caller turns into the host's `blocked` reason (REQ-04B-02).
fn scan_projection(root: &Path) -> std::result::Result<ProjectionScan, String> {
    let meta =
        fs::symlink_metadata(root).map_err(|_| "projection directory unavailable".to_string())?;
    if meta.file_type().is_symlink() {
        return Err("projection path is a symlink; refused".into());
    }
    if !meta.is_dir() {
        return Err("projection path is not a directory".into());
    }
    let mut files = BTreeMap::new();
    let mut entries = 0usize;
    let mut total = 0usize;
    scan_walk(root, root, &mut files, &mut entries, &mut total, 0)?;
    Ok(ProjectionScan { files })
}

fn scan_walk(
    root: &Path,
    dir: &Path,
    files: &mut BTreeMap<String, String>,
    entries: &mut usize,
    total: &mut usize,
    depth: usize,
) -> std::result::Result<(), String> {
    if depth > WALK_DEPTH {
        return Err("projection nesting limit exceeded".into());
    }
    for entry in fs::read_dir(dir).map_err(|_| "projection directory unavailable")? {
        *entries += 1;
        if *entries > WALK_ENTRIES {
            return Err("projection entry limit exceeded".into());
        }
        let path = entry.map_err(|_| "projection entry unavailable")?.path();
        let meta = fs::symlink_metadata(&path).map_err(|_| "projection metadata unavailable")?;
        if meta.file_type().is_symlink() {
            return Err("projection contains a symlink; refused".into());
        }
        if meta.is_dir() {
            scan_walk(root, &path, files, entries, total, depth + 1)?;
        } else if meta.is_file() {
            if meta.len() > FILE_LIMIT {
                return Err("projection file exceeds the size limit".into());
            }
            let rel = path
                .strip_prefix(root)
                .map_err(|_| "projection path invalid")?
                .to_str()
                .ok_or("non UTF-8 projection path")?
                .replace('\\', "/");
            let bytes = fs::read(&path).map_err(|_| "projection read failed")?;
            *total += bytes.len();
            if *total > WALK_BYTES {
                return Err("projection too large".into());
            }
            files.insert(rel, sha256_hex(&bytes));
        } else {
            return Err("projection special file refused".into());
        }
        if files.len() > WALK_FILES {
            return Err("projection file limit exceeded".into());
        }
    }
    Ok(())
}

/// Refuses a symlink in any existing component between the home and the projection root.
fn ancestor_symlinks(home: &Path, root: &Path) -> Result<()> {
    let mut cursor = root.to_path_buf();
    while cursor.starts_with(home) && cursor != home {
        match fs::symlink_metadata(&cursor) {
            Ok(m) if m.file_type().is_symlink() => {
                return Err("projection path is a symlink; refused".into())
            }
            Ok(_) => (),
            Err(_) => (), // missing components are created at apply time
        }
        cursor = cursor
            .parent()
            .ok_or("projection path invalid")?
            .to_path_buf();
    }
    Ok(())
}

/// Cross-filesystem projection (unix device ids): receipt and files would live on
/// different filesystems, weakening the crash ordering. Non-unix platforms skip the
/// check and make no claim.
#[cfg(unix)]
fn cross_filesystem(home: &Path, root: &Path) -> Result<bool> {
    use std::os::unix::fs::MetadataExt;
    let state = home.join(crate::HOME_STATE_DIR);
    match (fs::metadata(&state), fs::metadata(root)) {
        (Ok(a), Ok(b)) => Ok(a.dev() != b.dev()),
        _ => Ok(false),
    }
}

#[cfg(not(unix))]
fn cross_filesystem(_home: &Path, _root: &Path) -> Result<bool> {
    Ok(false)
}

fn writable(path: &Path) -> bool {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::metadata(path)
            .map(|m| m.permissions().mode() & 0o200 != 0)
            .unwrap_or(false)
    }
    #[cfg(not(unix))]
    {
        fs::metadata(path).is_ok()
    }
}

/// Runs the host preflight (REQ-04B-02) and, when safe, the projection scan in one
/// pass. Returns the `blocked` reason (if any) and the scan (an absent projection is
/// an empty scan, not a block). Every hazard becomes a reason; nothing escapes as a
/// global error.
fn preflight(home: &Path, host: &str) -> (Option<String>, Option<ProjectionScan>) {
    let root = projection_root(home, host);
    if let Err(e) = ancestor_symlinks(home, &root) {
        return (Some(e), None);
    }
    let meta = match fs::symlink_metadata(&root) {
        Err(_) => {
            // Absent projection: apply may create it, so the nearest existing ancestor
            // must be writable.
            let mut cursor = match root.parent() {
                Some(p) => p.to_path_buf(),
                None => return (Some("projection path invalid".into()), None),
            };
            loop {
                if fs::symlink_metadata(&cursor).is_ok() {
                    if !writable(&cursor) {
                        return (
                            Some("skills parent directory is not writable; refused".into()),
                            None,
                        );
                    }
                    break;
                }
                match cursor.parent() {
                    Some(p) => cursor = p.to_path_buf(),
                    None => break,
                }
            }
            return (
                None,
                Some(ProjectionScan {
                    files: BTreeMap::new(),
                }),
            );
        }
        Ok(m) => m,
    };
    if meta.file_type().is_symlink() {
        return (Some("projection path is a symlink; refused".into()), None);
    }
    let scan = match scan_projection(&root) {
        Ok(s) => s,
        Err(e) => return (Some(e), None),
    };
    if !writable(&root) {
        return (
            Some("projection directory is not writable; refused".into()),
            None,
        );
    }
    if cross_filesystem(home, &root).unwrap_or(false) {
        return (
            Some("cross-filesystem projection; receipt and files must share one filesystem".into()),
            None,
        );
    }
    (None, Some(scan))
}

// --- plan ---------------------------------------------------------------------------

/// Computes the current installation id through 04-A's public API (no 04-A changes).
pub(crate) fn current_install_id(home: &Path) -> Result<String> {
    let exe = std::env::current_exe().map_err(|_| "current executable unavailable".to_string())?;
    Ok(plan_receipt(&exe, home, InstallerOwner::Unknown)?.install_id)
}

/// Read-only three-way plan over every host (REQ-04B-01/02/03). Writes nothing.
pub fn plan_update(home: &Path, staged: &StagedPackage) -> Result<UpdatePlan> {
    let canonical_home = fs::canonicalize(home).map_err(|_| "home directory unavailable")?;
    let install_id = current_install_id(&canonical_home)?;
    let mut hosts = Vec::new();
    let mut expected = Vec::new();
    let mut rollback = Vec::new();
    let mut latest_version: Option<String> = None;

    for host in HOSTS {
        let root = projection_root(&canonical_home, host);
        let root_text = root
            .to_str()
            .ok_or("non UTF-8 projection path")?
            .to_string();
        let (blocked, scan) = preflight(&canonical_home, host);
        let receipt = if blocked.is_some() {
            None
        } else {
            let path = host_receipt_path(&canonical_home, &install_id, host, false)?;
            load_host_receipt(&path)?
        };
        // REQ-04C-04 (04-C #2000): a pending host takes no new apply until recovered; the
        // other hosts plan as usual.
        let (blocked, scan) = match &receipt {
            Some(r) if r.status == "pending" => (
                Some("host receipt is pending; run recovery-plan first".to_string()),
                None,
            ),
            _ => (blocked, scan),
        };
        if receipt.is_some() && latest_version.is_none() {
            latest_version = receipt.as_ref().map(|r| r.package_version.clone());
        }
        let owned = owned_map(receipt.as_ref());
        let mut files = Vec::new();

        // Package files vs disk, three-way per file (REQ-04B-01).
        for (rel, new_bytes) in &staged.files {
            let new_sha = sha256_hex(new_bytes);
            let baseline = owned.get(rel).cloned();
            let current = scan.as_ref().and_then(|s| s.files.get(rel).cloned());
            let action = match decide(
                baseline.as_deref(),
                current.as_deref(),
                Some(new_sha.as_str()),
            ) {
                Decision::KeepCurrent => {
                    if current.as_deref() == Some(new_sha.as_str()) {
                        "unchanged"
                    } else {
                        // desired == baseline: the template did not change; keep the
                        // user's edit (AC-04B-03).
                        "preserved"
                    }
                }
                Decision::Apply => {
                    if current.is_none() {
                        "create"
                    } else {
                        "update"
                    }
                }
                Decision::Conflict => "conflict",
            };
            if action == "create" || action == "update" {
                expected.push(FileHash {
                    host: (*host).to_string(),
                    path: rel.clone(),
                    sha256: new_sha.clone(),
                });
                if let Some(before) = &current {
                    rollback.push(FileHash {
                        host: (*host).to_string(),
                        path: rel.clone(),
                        sha256: before.clone(),
                    });
                }
            }
            files.push(FilePlan {
                host: (*host).to_string(),
                path: rel.clone(),
                action: action.to_string(),
                baseline_sha256: baseline,
                current_sha256: current,
                new_sha256: Some(new_sha),
            });
        }

        // Disk files the package does not carry (REQ-04B-09): never deleted, reported.
        if let Some(scan) = &scan {
            for (rel, current_sha) in &scan.files {
                if staged.files.contains_key(rel) {
                    continue;
                }
                let owned_here = owned.contains_key(rel);
                files.push(FilePlan {
                    host: (*host).to_string(),
                    path: rel.clone(),
                    action: if owned_here {
                        // We applied it before and the new package dropped it: removal
                        // would be needed, but RC1 never deletes (04-C decides).
                        "remove_blocked"
                    } else {
                        "preserved"
                    }
                    .to_string(),
                    baseline_sha256: owned.get(rel).cloned(),
                    current_sha256: Some(current_sha.clone()),
                    new_sha256: None,
                });
            }
        }

        files.sort_by(|a, b| a.path.cmp(&b.path));

        // REQ-1 (#2268, fail-closed): pre-existing content the install receipt does not
        // own means the projection root holds a foreign or previous-generation package
        // (the agent-9 repro: an old-generation SKILL.md with 12 pending RC1 creates
        // around it). The host is blocked — apply writes nothing for it. A managed
        // root (every staged file owned) keeps the normal three-way path (AC-2).
        // REQ-2: the reason names the condition ('unmanaged existing package') and the
        // safe alternatives — never an automatic overwrite.
        let unmanaged: Vec<&str> = files
            .iter()
            .filter(|f| {
                f.baseline_sha256.is_none()
                    && f.current_sha256.is_some()
                    && staged.files.contains_key(&f.path)
            })
            .map(|f| f.path.as_str())
            .collect();
        let (preflight, blocked) = if !unmanaged.is_empty() {
            (
                "blocked".to_string(),
                Some(format!(
                    "unmanaged existing package: {} file(s) present in the projection root \
                     that install receipt {install_id} does not own ({}); \
                     safe alternatives: install to a separate location, or a \
                     user-confirmed backup-then-replace — never automatic; \
                     per-file actions below are informational only",
                    unmanaged.len(),
                    unmanaged.join(", "),
                )),
            )
        } else {
            let reason = blocked.clone();
            (
                if reason.is_some() { "blocked" } else { "ok" }.into(),
                reason,
            )
        };
        hosts.push(HostPlan {
            host: (*host).to_string(),
            projection_root: root_text,
            preflight,
            blocked_reason: blocked,
            files,
        });
    }

    let plan = UpdatePlan {
        schema_version: UPDATE_SCHEMA_VERSION,
        protocol_version: PROTOCOL_VERSION,
        protocol_range: ProtocolRange {
            min: PROTOCOL_VERSION,
            max: PROTOCOL_VERSION,
        },
        home: canonical_home
            .to_str()
            .ok_or("non UTF-8 home path")?
            .to_string(),
        scope: HOSTS.iter().map(|h| (*h).to_string()).collect(),
        source_version: latest_version,
        target_version: env!("CARGO_PKG_VERSION").to_string(),
        package_digest: staged.digest.clone(),
        hosts,
        expected_file_hashes: expected,
        rollback_manifest: rollback,
        plan_digest: String::new(),
    };
    let mut core = plan.clone();
    core.plan_digest = String::new();
    let mut plan = plan;
    plan.plan_digest = crate::digest(&serde_json::to_vec(&core).map_err(|_| "encode failed")?);
    Ok(plan)
}

// --- apply --------------------------------------------------------------------------

fn validate_permission(permission: &str) -> Result<()> {
    if ["", "null", "placeholder"].contains(&permission.trim())
        || permission.len() > 128
        || permission.chars().any(char::is_control)
    {
        return Err("permission reference required".into());
    }
    Ok(())
}

/// One host's apply outcome.
struct HostOutcome {
    host: String,
    status: String, // applied | unchanged | conflict | blocked | failed
    files: Vec<serde_json::Value>,
    receipt_status: Option<String>,
    reload_required: String, // no | yes | unknown
    reload_basis: String,
    blocked_reason: Option<String>,
}

/// Applies the plan host by host (REQ-04B-03..06). Refuses anything but a freshly
/// recomputed identical digest before touching a single file.
pub fn apply_update(
    home: &Path,
    staged: &StagedPackage,
    plan: &UpdatePlan,
    plan_digest: &str,
    permission_reference: &str,
) -> Result<serde_json::Value> {
    validate_permission(permission_reference)?;
    let fresh = plan_update(home, staged)?;
    // The whole plan BODY must equal a fresh recompute (a tampered body with a stolen
    // digest field is still refused), and the caller's digest must bind both.
    if plan.schema_version != UPDATE_SCHEMA_VERSION
        || plan.protocol_version != PROTOCOL_VERSION
        || *plan != fresh
        || fresh.plan_digest != plan_digest
        || plan.plan_digest != plan_digest
    {
        return Err("stale or altered plan; re-preview required".into());
    }
    let canonical_home = fs::canonicalize(home).map_err(|_| "home directory unavailable")?;
    let install_id = current_install_id(&canonical_home)?;

    let mut outcomes: Vec<HostOutcome> = Vec::new();
    let mut published_anywhere = false;
    let mut any_failed = false;
    let mut any_conflict_only = false;

    for host_plan in &fresh.hosts {
        let host = host_plan.host.as_str();
        if host_plan.preflight == "blocked" {
            // REQ-04B-02: a blocked host is never written; the others go on.
            outcomes.push(HostOutcome {
                host: host.to_string(),
                status: "blocked".into(),
                files: Vec::new(),
                receipt_status: None,
                reload_required: "no".into(),
                reload_basis: "no files written".into(),
                blocked_reason: host_plan.blocked_reason.clone(),
            });
            continue;
        }

        let root = projection_root(&canonical_home, host);
        let writes: Vec<&FilePlan> = host_plan
            .files
            .iter()
            .filter(|f| f.action == "create" || f.action == "update")
            .collect();
        let conflict_only = host_plan.files.iter().any(|f| f.action == "conflict");

        if writes.is_empty() {
            // Nothing to write: report, never touch (REQ-04B-07 rerun; conflicts keep
            // the user bytes, REQ-04B-09).
            let status = if conflict_only {
                "conflict"
            } else {
                "unchanged"
            };
            any_conflict_only |= conflict_only;
            let files = host_plan
                .files
                .iter()
                .map(|f| file_result(f, false, None))
                .collect();
            outcomes.push(HostOutcome {
                host: host.to_string(),
                status: status.into(),
                files,
                receipt_status: None,
                reload_required: "no".into(),
                reload_basis: "no files written".into(),
                blocked_reason: None,
            });
            continue;
        }

        // REQ-04C-03 (#2089): known-good copies of every overwritten file, BEFORE the
        // transaction starts; a copy failure starts nothing for this host.
        if let Err(e) = known_good_copies(&canonical_home, &install_id, host, &root, &writes) {
            any_failed = true;
            outcomes.push(HostOutcome {
                host: host.to_string(),
                status: "failed".into(),
                files: Vec::new(),
                receipt_status: None,
                reload_required: "no".into(),
                reload_basis: format!("known-good copy failed; host not started: {e}"),
                blocked_reason: None,
            });
            continue;
        }

        // Transaction start: pending receipt BEFORE the first file write (REQ-04B-04a),
        // carrying the pre-apply ownership manifest.
        let receipt_path = host_receipt_path(&canonical_home, &install_id, host, true)?;
        let previous = load_host_receipt(&receipt_path)?;
        let pre_owned = owned_map(previous.as_ref());
        let top_skills_existed = fs::symlink_metadata(home.join(skills_dir(host))).is_ok();
        let mut receipt = HostReceipt {
            schema_version: crate::install::RECEIPT_SCHEMA_VERSION,
            install_id: install_id.clone(),
            host: host.to_string(),
            operation: "update.apply".into(),
            plan_digest: plan_digest.to_string(),
            package_digest: staged.digest.clone(),
            package_version: fresh.target_version.clone(),
            version_before: previous.as_ref().map(|p| p.package_version.clone()),
            top_skills_existed_before: top_skills_existed,
            status: "pending".into(),
            started_at: now_rfc3339(),
            finished_at: None,
            entries: writes
                .iter()
                .map(|f| HostReceiptEntry {
                    path: f.path.clone(),
                    action: f.action.clone(),
                    before_sha256: f.current_sha256.clone(),
                    after_sha256: f.new_sha256.clone(),
                    published: false,
                    error: None,
                })
                .collect(),
            owned: owned_vec(host, &pre_owned),
        };
        save_host_receipt(&canonical_home, &install_id, &receipt)?;

        // (b) per file: 01-B engine (unique temp + fsync + rename / exclusive create),
        // each re-verifying the target right before publish and fsyncing its directory.
        let mut owned_now = pre_owned.clone();
        let mut host_published = 0usize;
        let mut failed: Option<String> = None;
        for (idx, w) in writes.iter().enumerate() {
            let target = root.join(&w.path);
            let new_bytes = staged
                .files
                .get(&w.path)
                .ok_or_else(|| "package file disappeared".to_string())?;
            // Re-verify the current bytes still match the plan (REQ-04B-03); an
            // unreadable target is THIS host's failure, not a global error.
            let before = match read_opt(&target) {
                Ok(b) => b,
                Err(e) => {
                    failed = Some(e);
                    receipt.entries[idx].error = failed.clone();
                    break;
                }
            };
            let before_sha = before.as_deref().map(sha256_hex);
            if before_sha != w.current_sha256 {
                failed = Some("target changed during apply; temporary file discarded".into());
                receipt.entries[idx].error = failed.clone();
                break;
            }
            let result = if w.action == "create" {
                publish_exclusive(&target, new_bytes)
            } else {
                publish_replace(&target, before.as_deref(), new_bytes)
            };
            match result {
                Ok(()) => {
                    let written = read_opt(&target)?;
                    let written_sha = written.as_deref().map(sha256_hex);
                    if written_sha.as_deref() != w.new_sha256.as_deref() {
                        failed = Some("published bytes do not match the plan".into());
                        receipt.entries[idx].error = failed.clone();
                        break;
                    }
                    receipt.entries[idx].published = true;
                    owned_now.insert(w.path.clone(), written_sha.expect("sha of a written file"));
                    host_published += 1;
                }
                Err(e) => {
                    failed = Some(e);
                    receipt.entries[idx].error = failed.clone();
                    break;
                }
            }
        }
        published_anywhere |= host_published > 0;

        if let Some(_err) = failed {
            // REQ-04B-05: keep the receipt pending WITH THE PRE-APPLY OWNERSHIP
            // manifest, report failed, never roll back another host (04-C recovers).
            any_failed = true;
            receipt.finished_at = Some(now_rfc3339());
            save_host_receipt(&canonical_home, &install_id, &receipt)?;
            let files = writes
                .iter()
                .zip(&receipt.entries)
                .map(|(f, e)| file_result_with(f, e))
                .collect();
            outcomes.push(HostOutcome {
                host: host.to_string(),
                status: "failed".into(),
                files,
                receipt_status: Some("pending".into()),
                reload_required: "unknown".into(),
                reload_basis: "apply failed mid-transaction; host state is pending (04-C recovery)"
                    .into(),
                blocked_reason: None,
            });
            continue;
        }

        // (c) every touched directory was fsynced by publish_replace/publish_exclusive;
        // (d) full re-verification, then committed (ownership manifest moves forward).
        for w in &writes {
            let target = root.join(&w.path);
            let written = read_opt(&target)?;
            if written.as_deref().map(sha256_hex).as_deref() != w.new_sha256.as_deref() {
                return Err("published bytes do not match the plan".into());
            }
        }
        receipt.owned = owned_vec(host, &owned_now);
        receipt.status = "committed".into();
        receipt.finished_at = Some(now_rfc3339());
        save_host_receipt(&canonical_home, &install_id, &receipt)?;

        let (reload, basis) = reload_state(host, top_skills_existed, host_published > 0);
        let mut all: Vec<serde_json::Value> = writes
            .iter()
            .zip(&receipt.entries)
            .map(|(f, e)| file_result_with(f, e))
            .collect();
        for f in host_plan
            .files
            .iter()
            .filter(|f| f.action != "create" && f.action != "update")
        {
            all.push(file_result(f, false, None));
        }
        outcomes.push(HostOutcome {
            host: host.to_string(),
            status: "applied".into(),
            files: all,
            receipt_status: Some("committed".into()),
            reload_required: reload.into(),
            reload_basis: basis,
            blocked_reason: None,
        });
    }

    let overall = if any_failed {
        "partial"
    } else if !outcomes.is_empty() && outcomes.iter().all(|o| o.status == "blocked") {
        "blocked"
    } else if published_anywhere {
        "applied"
    } else if any_conflict_only {
        "conflict"
    } else {
        "unchanged"
    };
    Ok(json!({
        "status": overall,
        "plan_digest": plan_digest,
        "package_digest": staged.digest,
        "package_version": fresh.target_version,
        "hosts": outcomes.iter().map(host_outcome_json).collect::<Vec<_>>(),
        "host_loaded": false,
        "execution_verified": "not_run",
        "reload_note": "host loading is not measured here (08-C owns the live check)",
        "writes": false,
    }))
}

/// REQ-04B-06: reload state and its documented basis per host.
fn reload_state(
    host: &str,
    top_skills_existed_before: bool,
    wrote: bool,
) -> (&'static str, String) {
    match host {
        "claude" => {
            if wrote && !top_skills_existed_before {
                (
                    "yes",
                    "the top-level skills directory was created; running sessions need /reload-skills (code.claude.com/docs/en/skills, 2026-11-08)".into(),
                )
            } else if wrote {
                (
                    "no",
                    "Claude reflects skill file changes live (code.claude.com/docs/en/skills, 2026-11-08)".into(),
                )
            } else {
                ("no", "no files written".into())
            }
        }
        "codex" => {
            if wrote {
                (
                    "unknown",
                    "Codex detects skill changes automatically; restart if they are not shown (learn.chatgpt.com/docs/build-skills, 2026-11-08)".into(),
                )
            } else {
                ("no", "no files written".into())
            }
        }
        other => unreachable!("unknown host {other}"),
    }
}

fn file_result(f: &FilePlan, published: bool, error: Option<String>) -> serde_json::Value {
    json!({
        "path": f.path,
        "action": f.action,
        "before_sha256": f.current_sha256,
        "after_sha256": if published { f.new_sha256.clone() } else { None },
        "published": published,
        "error": error,
    })
}

fn file_result_with(f: &FilePlan, e: &HostReceiptEntry) -> serde_json::Value {
    json!({
        "path": f.path,
        "action": f.action,
        "before_sha256": e.before_sha256,
        "after_sha256": if e.published { e.after_sha256.clone() } else { None },
        "published": e.published,
        "error": e.error.clone(),
    })
}

fn host_outcome_json(o: &HostOutcome) -> serde_json::Value {
    json!({
        "host": o.host,
        "status": o.status,
        "files": o.files,
        "receipt_status": o.receipt_status,
        "reload_required": o.reload_required,
        "reload_basis": o.reload_basis,
        "blocked_reason": o.blocked_reason,
        "host_loaded": false,
        "execution_verified": "not_run",
    })
}

src/verify.rs.content:
//! Trusted runner for VERIFY (Issue #2003, 05-C).
//!
//! Runs one verification command as an argv array (never through a shell), with a timeout,
//! and records what happened: start and end, exit status, timeout, the sha256 of stdout and
//! stderr (the output itself is not kept), and a failure class. Nothing is written to disk.

use crate::digest;
use serde::{Deserialize, Serialize};
use std::io::Read;
use std::path::Path;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

pub type Result<T> = std::result::Result<T, String>;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum FailureClass {
    /// The check could not test anything: build failure, missing command, timeout, network.
    EnvironmentFailure,
    /// An assertion in the tests failed.
    TestFailure,
    /// Failed without a recognised sign either way; never counted as RED.
    Unclassified,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CheckResult {
    Passed,
    Failed,
    NotRun,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Toolchain {
    pub rustc: Option<String>,
    pub cargo: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CheckRun {
    /// Index into the approved snapshot's `verification_commands`.
    pub command_ref: usize,
    pub command: String,
    pub argv: Vec<String>,
    pub result: CheckResult,
    pub exit_code: Option<i32>,
    pub timed_out: bool,
    /// No cancellation path exists yet; recorded so a later one has a place.
    pub cancelled: bool,
    pub spawn_error: Option<String>,
    pub started_unix_ms: Option<u64>,
    pub finished_unix_ms: Option<u64>,
    pub duration_ms: Option<u64>,
    pub stdout_sha256: Option<String>,
    pub stderr_sha256: Option<String>,
    pub failure_class: Option<FailureClass>,
    /// Arguments after `--`: the test selection the command asked for.
    pub test_filters: Vec<String>,
    /// Sums of the `test result:` lines, when the output has any.
    pub tests_passed: Option<u64>,
    pub tests_failed: Option<u64>,
    /// False when stdout or stderr could not be read within the grace period after the command
    /// ended; their digests are null then. None when nothing was spawned.
    pub output_complete: Option<bool>,
}

/// Splits a snapshot command into argv. No shell: a leading `VAR=value`, an option before the
/// executable, and an executable with a path separator are refused (#2003 leader decision I1).
pub fn parse_argv(command: &str) -> Result<Vec<String>> {
    let argv: Vec<String> = command.split_ascii_whitespace().map(String::from).collect();
    let Some(exe) = argv.first() else {
        return Err("command not runnable: empty".into());
    };
    if exe.contains('=') {
        return Err("command not runnable: environment assignment before the executable".into());
    }
    if exe.starts_with('-') {
        return Err("command not runnable: option before the executable".into());
    }
    if exe.contains('/') || exe.contains('\\') {
        return Err("command not runnable: executable given as a path".into());
    }
    Ok(argv)
}

/// Words that mark a failure of the environment rather than of the code under test.
const ENVIRONMENT_SIGNS: [&str; 8] = [
    "could not compile",
    "error[e",
    "failed to download",
    "failed to get `",
    "could not resolve host",
    "spurious network error",
    "failed to load manifest",
    "no such command",
];
/// Words that mark an assertion failure in the tests.
const TEST_SIGNS: [&str; 2] = ["test result: failed", "panicked at"];

/// Failure class of a finished check; `None` when it passed. Environment signs win over test
/// signs, so a run that could not build is never counted as RED. Text-based (libtest JSON is
/// unstable), so a heuristic.
pub fn classify(
    spawn_error: Option<&str>,
    timed_out: bool,
    success: bool,
    output: &str,
) -> Option<FailureClass> {
    if spawn_error.is_some() || timed_out {
        return Some(FailureClass::EnvironmentFailure);
    }
    if success {
        return None;
    }
    let lower = output.to_ascii_lowercase();
    Some(if ENVIRONMENT_SIGNS.iter().any(|s| lower.contains(s)) {
        FailureClass::EnvironmentFailure
    } else if TEST_SIGNS.iter().any(|s| lower.contains(s)) {
        FailureClass::TestFailure
    } else {
        FailureClass::Unclassified
    })
}

/// Sums `test result: … N passed; M failed` lines.
fn test_counts(output: &str) -> (Option<u64>, Option<u64>) {
    let mut found = false;
    let (mut passed, mut failed) = (0, 0);
    for line in output
        .lines()
        .filter(|l| l.trim_start().starts_with("test result:"))
    {
        found = true;
        let words: Vec<&str> = line
            .split([' ', ';', '.'])
            .filter(|w| !w.is_empty())
            .collect();
        for pair in words.windows(2) {
            match (pair[0].parse::<u64>(), pair[1]) {
                (Ok(n), "passed") => passed += n,
                (Ok(n), "failed") => failed += n,
                _ => {}
            }
        }
    }
    if found {
        (Some(passed), Some(failed))
    } else {
        (None, None)
    }
}

fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |d| d.as_millis() as u64)
}

/// A declared check that this request did not run.
pub fn not_run(command_ref: usize, command: &str) -> CheckRun {
    CheckRun {
        command_ref,
        command: command.into(),
        argv: parse_argv(command).unwrap_or_default(),
        result: CheckResult::NotRun,
        exit_code: None,
        timed_out: false,
        cancelled: false,
        spawn_error: None,
        started_unix_ms: None,
        finished_unix_ms: None,
        duration_ms: None,
        stdout_sha256: None,
        stderr_sha256: None,
        failure_class: None,
        test_filters: Vec::new(),
        tests_passed: None,
        tests_failed: None,
        output_complete: None,
    }
}

/// How long the output readers may take after the command ended (or was ended).
const OUTPUT_GRACE: Duration = Duration::from_secs(2);

/// Ends every process left in the command's process group (unix: `kill -KILL -- -<pgid>`, as
/// argv). An empty group makes `kill` fail, which is fine. Without process groups, nothing.
fn end_group(pid: u32) {
    #[cfg(unix)]
    {
        let _ = Command::new("kill")
            .args(["-KILL", "--", &format!("-{pid}")])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();
    }
    #[cfg(not(unix))]
    let _ = pid;
}

// @MX:WARN: [AUTO] spawns a process group and two reader threads; the group is killed when the
// command ends or times out, and the readers are waited for at most OUTPUT_GRACE
// @MX:REASON: a grandchild holding the pipes kept an unbounded join waiting past the timeout
// (agent-2 FAIL on 5413e0221)
/// Runs one command in `dir` with the inherited environment and returns its record. A command
/// that does not parse is recorded as an environment failure without spawning anything.
pub fn run_check(dir: &Path, command_ref: usize, command: &str, timeout: Duration) -> CheckRun {
    let mut rec = not_run(command_ref, command);
    rec.result = CheckResult::Failed;
    let Ok(argv) = parse_argv(command) else {
        rec.spawn_error = Some("not-runnable".into());
        rec.failure_class = Some(FailureClass::EnvironmentFailure);
        return rec;
    };
    rec.test_filters = argv
        .iter()
        .position(|a| a == "--")
        .map(|i| argv[i + 1..].to_vec())
        .unwrap_or_default();
    rec.argv = argv.clone();
    let started = Instant::now();
    rec.started_unix_ms = Some(now_ms());
    let mut cmd = Command::new(&argv[0]);
    cmd.args(&argv[1..])
        .current_dir(dir)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    // Its own process group, so everything the command starts can be ended with it.
    #[cfg(unix)]
    std::os::unix::process::CommandExt::process_group(&mut cmd, 0);
    let spawned = cmd.spawn();
    let mut child = match spawned {
        Ok(c) => c,
        Err(e) => {
            rec.spawn_error = Some(
                match e.kind() {
                    std::io::ErrorKind::NotFound => "not-found",
                    std::io::ErrorKind::PermissionDenied => "permission-denied",
                    _ => "spawn-failed",
                }
                .into(),
            );
            rec.finished_unix_ms = Some(now_ms());
            rec.duration_ms = Some(started.elapsed().as_millis() as u64);
            rec.failure_class = Some(FailureClass::EnvironmentFailure);
            return rec;
        }
    };
    // Readers hand their bytes over a channel, so the wait for them can be bounded.
    let drain = |pipe: Option<Box<dyn Read + Send>>| {
        let (tx, rx) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let mut buf = Vec::new();
            if let Some(mut p) = pipe {
                let _ = p.read_to_end(&mut buf);
            }
            let _ = tx.send(buf);
        });
        rx
    };
    let out = drain(
        child
            .stdout
            .take()
            .map(|p| Box::new(p) as Box<dyn Read + Send>),
    );
    let err = drain(
        child
            .stderr
            .take()
            .map(|p| Box::new(p) as Box<dyn Read + Send>),
    );
    let status = loop {
        match child.try_wait() {
            Ok(Some(s)) => break Some(s),
            Ok(None) if started.elapsed() >= timeout => {
                let _ = child.kill();
                let _ = child.wait();
                rec.timed_out = true;
                break None;
            }
            Ok(None) => std::thread::sleep(Duration::from_millis(10)),
            Err(_) => break None,
        }
    };
    // Whatever the command left running (background children holding the pipes) ends with it.
    end_group(child.id());
    let stdout = out.recv_timeout(OUTPUT_GRACE).ok();
    let stderr = err.recv_timeout(OUTPUT_GRACE).ok();
    rec.output_complete = Some(stdout.is_some() && stderr.is_some());
    rec.finished_unix_ms = Some(now_ms());
    rec.duration_ms = Some(started.elapsed().as_millis() as u64);
    rec.exit_code = status.and_then(|s| s.code());
    rec.stdout_sha256 = stdout.as_deref().map(digest);
    rec.stderr_sha256 = stderr.as_deref().map(digest);
    let (stdout, stderr) = (stdout.unwrap_or_default(), stderr.unwrap_or_default());
    let text = format!(
        "{}\n{}",
        String::from_utf8_lossy(&stdout),
        String::from_utf8_lossy(&stderr)
    );
    (rec.tests_passed, rec.tests_failed) = test_counts(&text);
    let success = status.is_some_and(|s| s.success());
    rec.failure_class = classify(None, rec.timed_out, success, &text);
    rec.result = if success && !rec.timed_out {
        CheckResult::Passed
    } else {
        CheckResult::Failed
    };
    rec
}

/// `rustc -V` and `cargo -V` as seen from `dir` (a project toolchain file applies there).
pub fn toolchain(dir: &Path) -> Toolchain {
    let first_line = |program: &str| {
        Command::new(program)
            .arg("-V")
            .current_dir(dir)
            .stdin(Stdio::null())
            .output()
            .ok()
            .filter(|o| o.status.success())
            .and_then(|o| String::from_utf8(o.stdout).ok())
            .and_then(|s| s.lines().next().map(|l| l.trim().to_string()))
    };
    Toolchain {
        rustc: first_line("rustc"),
        cargo: first_line("cargo"),
    }
}

src/worktree.rs.content:
//! One worktree per claim (Issue #2007, 06-C; REQ-06C-01..04, 10, 12).
//!
//! `worktree-plan` computes the branch and path for a claim and writes nothing.
//! `worktree-apply` re-derives the plan, refuses on a digest mismatch, detects an existing
//! owner itself (branch already used by a worktree, branch ref present, path present, or a
//! worktree locked for the same task) and only then runs
//! `git worktree add --lock --reason "moai claim <task_key> e<epoch>" -b <branch> <path> <base>`.
//! It never forces the add, and the primary worktree's HEAD, branch and index are never
//! written: the only mutating git call in this file is that `worktree add`.
//!
//! Decided inputs (docs/decisions-2026-11-08.md): the default root is the user's lane location
//! `<primary>/.moai-cli/worktrees/<issue>-<logical_key>` (16:5x→17:0x); any other path is
//! accepted as given (REQ-06C-12). The branch prefix is an open HOLD, so it is a required
//! input with no default.
//!
//! Records: every 06-C command returns its record change as `record_update_request`. When
//! the record came from the local journal (`--task`), the change is also committed through
//! 06-B's public `Journal::commit` under the journal lock ([`commit_update`]): the worktree
//! identity, `blocked(reason=scope_conflict)`, an integration order, and `pr_ready` with the
//! `pr_create` effect intent. 06-A's acquire/release behaviour is unchanged; these are
//! additional events. A record can also come from a file (`--record`) for a claim that never
//! went through the local journal; such a file is the caller's input, not an authority, is
//! accepted only when it agrees with the Issue claim comment it names (`--claim-comment`),
//! and is never written back: the journal holds no record for it.
use crate::claim::{
    self, claim_token, is_key, parse_claim_line, ClaimRecord, Journal, WorktreeId, ACTIVE_STATES,
};
use crate::digest;
use crate::forge::policy::{format_utc, Clock};
use crate::spec::{Canonical, SortedKeys};
use serde_json::{json, Value};
use std::{
    collections::BTreeMap,
    fs,
    path::{Path, PathBuf},
    process::{Command, Stdio},
};

type Result<T> = std::result::Result<T, String>;

pub const RECORD_UPDATE_OWNER: &str =
    "06-C via 06-B Journal::commit when the record came from --task; not written for --record";

/// The journal of `project`, opened for writing and locked; a held lock is a conflict at
/// once (06-A busy-never-waits, REQ-06A-05).
pub fn open_locked_journal(project: &Path) -> Result<Journal> {
    let journal = Journal::open(&claim::journal_root(project)?)?;
    if !journal.try_lock()? {
        return Err("conflict in claim journal: another process holds the journal lock".into());
    }
    Ok(journal)
}

/// Applies `change` to the current record of `key` and commits it as one journal event.
/// The record must still be at `epoch` and active; a change that leaves the record as it
/// was writes nothing (`applied: false`), so a repeated command adds no event.
pub fn commit_update<C: Clock>(
    journal: &Journal,
    key: &str,
    epoch: u64,
    event: &str,
    clock: &C,
    change: impl FnOnce(&mut ClaimRecord),
) -> Result<Value> {
    if !is_key(key) {
        return Err("task must be a 16 hex character claim key".into());
    }
    let events = journal.read_events()?;
    let current = events
        .iter()
        .rev()
        .find(|e| e.record.task_key == key)
        .map(|e| e.record.clone())
        .ok_or("claim record not found for task")?;
    if current.epoch != epoch {
        return Err(format!(
            "conflict in claim journal: stale_epoch {epoch}; current record epoch is {}",
            current.epoch
        ));
    }
    if !ACTIVE_STATES.contains(&current.state.as_str()) {
        return Err(format!(
            "conflict in claim journal: the record is not active ({})",
            current.state
        ));
    }
    let mut next = current.clone();
    change(&mut next);
    if next == current {
        return Ok(json!({"applied": false, "event": event, "state": current.state}));
    }
    next.last_observed_at = format_utc(clock.now());
    journal.commit(event, &next)?;
    Ok(json!({"applied": true, "event": event, "state": next.state}))
}

/// `worktree-apply` plus the record write (REQ-06C-02): a created worktree's measured
/// identity becomes `record.worktree` when the record came from the journal.
#[allow(clippy::too_many_arguments)]
pub fn apply_and_record<C: Clock>(
    project: &Path,
    rec: &ClaimRecord,
    from_journal: bool,
    prefix: &str,
    path: Option<&Path>,
    plan_digest: &str,
    clock: &C,
) -> Result<Value> {
    let journal = if from_journal {
        Some(open_locked_journal(project)?)
    } else {
        None
    };
    let mut out = apply(project, rec, prefix, path, plan_digest)?;
    out["record_update"] = if out["decision"] != "created" {
        json!({"applied": false, "reason": "no worktree was created"})
    } else if let Some(journal) = &journal {
        let id: WorktreeId =
            serde_json::from_value(out["identity"].clone()).map_err(|_| "encode failed")?;
        commit_update(
            journal,
            &rec.task_key,
            rec.epoch,
            "worktree_recorded",
            clock,
            |r| r.worktree = id,
        )?
    } else {
        not_written()
    };
    Ok(out)
}

/// The `record_update` field for a record that came from a file: nothing is written.
pub fn not_written() -> Value {
    json!({"applied": false, "reason": "the record came from --record; the journal holds no record for it"})
}

fn git(dir: &Path, args: &[&str]) -> Result<String> {
    let out = Command::new("git")
        .args(args)
        .current_dir(dir)
        .output()
        .map_err(|_| "git unavailable".to_string())?;
    if !out.status.success() {
        let err = String::from_utf8_lossy(&out.stderr);
        return Err(format!(
            "git failed: {}",
            err.lines().next().unwrap_or("no message")
        ));
    }
    String::from_utf8(out.stdout).map_err(|_| "non UTF-8 git output".to_string())
}

fn git_ok(dir: &Path, args: &[&str]) -> Result<bool> {
    Command::new("git")
        .args(args)
        .current_dir(dir)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .map(|s| s.success())
        .map_err(|_| "git unavailable".to_string())
}

/// The 40-hex HEAD of `project` (the candidate SHA of a PR body).
pub fn head(project: &Path) -> Result<String> {
    Ok(git(project, &["rev-parse", "HEAD"])?.trim().to_string())
}

/// `(status, path)` of every path changed between the merge base of `base` and HEAD, and HEAD.
pub fn changes(project: &Path, base: &str) -> Result<Vec<(String, String)>> {
    let range = format!("{base}...HEAD");
    let out = git(project, &["diff", "--name-status", "--no-renames", &range])?;
    Ok(out
        .lines()
        .filter_map(|l| l.split_once('\t'))
        .map(|(s, p)| (s.to_string(), p.to_string()))
        .collect())
}

pub fn is_sha(s: &str) -> bool {
    s.len() == 40
        && s.bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

// ---- record input ----

fn read_json(path: &Path, what: &str) -> Result<Value> {
    let bytes = fs::read(path).map_err(|_| format!("{what} file not found"))?;
    serde_json::from_slice(&bytes).map_err(|_| format!("invalid {what} file"))
}

/// The record a command works on: from the local journal (`task`), or from a file checked
/// against the Issue claim comment (`record` + `comment`).
pub fn load_record(
    project: &Path,
    task: Option<&str>,
    record: Option<&Path>,
    comment: Option<&Path>,
) -> Result<ClaimRecord> {
    match (task, record) {
        (Some(key), None) => {
            let shown = claim::show(&claim::journal_root(project)?, key)?;
            serde_json::from_value(shown["record"].clone())
                .map_err(|_| "claim record not found for task".to_string())
        }
        (None, Some(path)) => {
            let rec: ClaimRecord = serde_json::from_value(read_json(path, "record")?)
                .map_err(|_| "invalid record file".to_string())?;
            let comment = comment.ok_or("--record requires --claim-comment")?;
            check_against_comment(&rec, &read_json(comment, "claim comment")?)?;
            Ok(rec)
        }
        _ => Err("exactly one of --task or --record is required".into()),
    }
}

/// A record file must agree with the Issue claim comment: comment id, session, epoch, lease
/// and (when present) the claim token. Any difference refuses the record.
pub fn check_against_comment(rec: &ClaimRecord, comment: &Value) -> Result<()> {
    let id = comment["id"]
        .as_i64()
        .ok_or("invalid claim comment file: id must be an integer")?;
    let line = comment["body"]
        .as_str()
        .and_then(parse_claim_line)
        .ok_or("invalid claim comment file: no moai-claim line in body")?;
    let mut diffs = Vec::new();
    if rec.comment_id != Some(id) {
        diffs.push("comment_id");
    }
    if rec.owner.id != line.session {
        diffs.push("session");
    }
    if rec.epoch != line.epoch {
        diffs.push("epoch");
    }
    if rec.lease_until.as_deref() != Some(line.lease_until.as_str()) {
        diffs.push("lease_until");
    }
    if let Some(token) = &rec.claim_token {
        if *token != claim_token(rec.task_ref.issue_number, id) {
            diffs.push("claim_token");
        }
    }
    if diffs.is_empty() {
        Ok(())
    } else {
        Err(format!(
            "conflict in record: {} differs from the Issue claim comment; record refused",
            diffs.join(", ")
        ))
    }
}

/// The latest record of every task in the local journal, active ones only.
pub fn active_records(project: &Path) -> Result<Vec<ClaimRecord>> {
    let events = Journal::open_read(&claim::journal_root(project)?)?.read_events()?;
    let mut latest: BTreeMap<String, ClaimRecord> = BTreeMap::new();
    for e in events {
        latest.insert(e.record.task_key.clone(), e.record);
    }
    Ok(latest
        .into_values()
        .filter(|r| ACTIVE_STATES.contains(&r.state.as_str()))
        .collect())
}

// ---- plan ----

struct Entry {
    path: String,
    head: String,
    branch: Option<String>,
    locked: Option<String>,
}

fn worktrees(project: &Path) -> Result<Vec<Entry>> {
    let text = git(project, &["worktree", "list", "--porcelain"])?;
    let mut out = Vec::new();
    for block in text.split("\n\n").filter(|b| !b.trim().is_empty()) {
        let mut e = Entry {
            path: String::new(),
            head: String::new(),
            branch: None,
            locked: None,
        };
        for line in block.lines() {
            if let Some(v) = line.strip_prefix("worktree ") {
                e.path = v.into();
            } else if let Some(v) = line.strip_prefix("HEAD ") {
                e.head = v.into();
            } else if let Some(v) = line.strip_prefix("branch ") {
                e.branch = Some(v.into());
            } else if line == "locked" {
                e.locked = Some(String::new());
            } else if let Some(v) = line.strip_prefix("locked ") {
                e.locked = Some(v.into());
            }
        }
        out.push(e);
    }
    Ok(out)
}

fn entry_json(e: &Entry) -> Value {
    json!({"path": e.path, "head": e.head, "branch": e.branch, "locked": e.locked})
}

fn valid_prefix(p: &str) -> bool {
    !p.is_empty()
        && !p.starts_with('/')
        && !p.ends_with('/')
        && !p.split('/').any(|s| s.is_empty() || s == "." || s == "..")
        && p.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"-_./".contains(&b))
}

// @MX:DEBT: [AUTO] the branch prefix is a required input with no default (HOLD, leader 2026-11-08)
// @MX:CEILING: REQ-06C-01 layout `<prefix>/<logical_key>-<issue>-e<epoch>`; it differs from the
//   lanes' `issue/<n>-<key>` and from 06-A's `claim_branch_suffix` (`c<issue>-<comment_id>`)
// @MX:UPGRADE: when the user decides the prefix and its relation to the 06-A suffix
/// The plan for a claim's worktree (REQ-06C-01): no git change, byte-identical for equal input.
pub fn plan(project: &Path, rec: &ClaimRecord, prefix: &str, path: Option<&Path>) -> Result<Value> {
    if !valid_prefix(prefix) {
        return Err("invalid --branch-prefix: segments of [A-Za-z0-9._-] separated by /".into());
    }
    if !is_sha(&rec.base_revision) {
        return Err("invalid record: base_revision must be 40 lowercase hex".into());
    }
    let issue = rec.task_ref.issue_number;
    let branch = format!("{prefix}/{}-{issue}-e{}", rec.logical_key, rec.epoch);
    if !git_ok(project, &["check-ref-format", "--branch", &branch])? {
        return Err(format!("invalid branch name {branch}"));
    }
    let primary = worktrees(project)?
        .into_iter()
        .next()
        .map(|e| PathBuf::from(e.path))
        .ok_or("project root unavailable")?;
    let path = match path {
        Some(p) if p.is_absolute() => p.to_path_buf(),
        Some(p) => primary.join(p),
        None => primary
            .join(".moai-cli")
            .join("worktrees")
            .join(format!("{issue}-{}", rec.logical_key)),
    };
    let content = json!({
        "task_key": rec.task_key,
        "logical_key": rec.logical_key,
        "issue_number": issue,
        "epoch": rec.epoch,
        "branch": branch,
        "path": path.to_string_lossy(),
        "base_sha": rec.base_revision,
        "primary": primary.to_string_lossy(),
        "lock_reason": format!("moai claim {} e{}", rec.task_key, rec.epoch),
    });
    let digest = digest(&SortedKeys.bytes(&content));
    let mut out = content;
    out["plan_digest"] = json!(digest);
    out["writes"] = json!(false);
    Ok(out)
}

// ---- apply ----

/// Measured identity of a worktree; never inferred from the `.git` shape or a basename (D42).
pub fn identity(path: &Path) -> Result<WorktreeId> {
    let out = git(
        path,
        &[
            "rev-parse",
            "--path-format=absolute",
            "--show-toplevel",
            "--git-common-dir",
            "--git-dir",
            "HEAD",
            "--abbrev-ref",
            "HEAD",
        ],
    )?;
    let lines: Vec<&str> = out.lines().collect();
    let [top, common, gitdir, head, abbrev] = lines[..] else {
        return Err("unexpected git rev-parse output".into());
    };
    let mut id = WorktreeId::new(common, gitdir, top, head);
    // #2131: the branch checked out at claim time, from the same rev-parse call.
    // A detached HEAD prints `HEAD` (git forbids a branch of that name), so it is None.
    id.branch = (abbrev != "HEAD").then(|| abbrev.to_string());
    Ok(id)
}

fn conflict(reason: &str, plan: &Value, existing: Vec<Value>) -> Value {
    json!({
        "decision": "conflict",
        "reason": reason,
        "branch": plan["branch"],
        "path": plan["path"],
        "existing": existing,
        "record_update_request": Value::Null,
    })
}

/// REQ-06C-02/03: create the worktree, or report the existing owner; the add is never forced.
pub fn apply(
    project: &Path,
    rec: &ClaimRecord,
    prefix: &str,
    path: Option<&Path>,
    plan_digest: &str,
) -> Result<Value> {
    let p = plan(project, rec, prefix, path)?;
    if p["plan_digest"] != plan_digest {
        return Err("stale or altered plan; re-preview required".into());
    }
    let branch = p["branch"].as_str().unwrap_or_default().to_string();
    let target = PathBuf::from(p["path"].as_str().unwrap_or_default());
    let reason = p["lock_reason"].as_str().unwrap_or_default().to_string();
    let task_lock = format!("moai claim {} ", rec.task_key);
    let entries = worktrees(project)?;
    let full_ref = format!("refs/heads/{branch}");
    let in_use: Vec<Value> = entries
        .iter()
        .filter(|e| e.branch.as_deref() == Some(full_ref.as_str()))
        .map(entry_json)
        .collect();
    if !in_use.is_empty() {
        return Ok(conflict("branch_in_use", &p, in_use));
    }
    let same_task: Vec<Value> = entries
        .iter()
        .filter(|e| {
            e.locked
                .as_deref()
                .is_some_and(|l| l.starts_with(&task_lock))
        })
        .map(entry_json)
        .collect();
    if !same_task.is_empty() {
        return Ok(conflict("task_has_worktree", &p, same_task));
    }
    if git_ok(project, &["show-ref", "--verify", "--quiet", &full_ref])? {
        let head = git(project, &["rev-parse", &full_ref])?;
        return Ok(conflict(
            "branch_exists",
            &p,
            vec![json!({"branch": full_ref, "head": head.trim()})],
        ));
    }
    if target.exists() {
        let at: Vec<Value> = entries
            .iter()
            .filter(|e| Path::new(&e.path) == target)
            .map(entry_json)
            .collect();
        return Ok(conflict("path_exists", &p, at));
    }
    let target_s = target.to_string_lossy().to_string();
    let base = p["base_sha"].as_str().unwrap_or_default().to_string();
    git(
        project,
        &[
            "worktree", "add", "--lock", "--reason", &reason, "-b", &branch, &target_s, &base,
        ],
    )?;
    let id = identity(&target)?;
    Ok(json!({
        "decision": "created",
        "plan_digest": plan_digest,
        "branch": branch,
        "path": target_s,
        "locked": reason,
        "identity": id,
        "record_update_request": {
            "task_key": rec.task_key,
            "epoch": rec.epoch,
            "worktree": id,
        },
        "record_update_owner": RECORD_UPDATE_OWNER,
    }))
}
